-- NEW CLEAN DEVELOPMENT ONLY. NOT A PRODUCTION MIGRATION.
DO $baseline_guard$ BEGIN
  IF current_setting('gan_batuach.development_baseline', true) IS DISTINCT FROM 'development-c0cf2de7-20260919-v1'
     OR current_database() <> 'postgres'
     OR EXISTS (SELECT 1 FROM pg_tables WHERE schemaname='public')
     OR EXISTS (SELECT 1 FROM auth.users)
  THEN RAISE EXCEPTION 'DEVELOPMENT baseline requires guarded fresh isolated database; Production use forbidden'; END IF;
END $baseline_guard$;
