CREATE FUNCTION public.accept_inspector_garden_invitation(p_invitation_id uuid, p_token_hash text, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor public.profiles%rowtype; invitation public.management_invitations%rowtype; garden public.gardens%rowtype;
  onboarding public.kindergarten_onboarding_records%rowtype; kind text; relationship text; now_at timestamptz:=now();
begin
  select * into actor from public.profiles where id=auth.uid() for update;
  if actor.id is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into invitation from public.management_invitations where id=p_invitation_id for update;
  if invitation.id is null or invitation.token_hash<>p_token_hash or invitation.invitation_type<>'garden_management'
    or invitation.payload->>'source'<>'inspector_preliminary' then raise exception 'invitation_invalid' using errcode='42501'; end if;
  if invitation.status='accepted' and invitation.accepted_by=actor.id and p_accept then
    return jsonb_build_object('garden_id',invitation.garden_id,'status','accepted','already_accepted',true);
  end if;
  if invitation.status not in ('pending','delivered') or invitation.expires_at<=now_at then raise exception 'invitation_unavailable' using errcode='42501'; end if;
  if invitation.target_profile_id is not null and invitation.target_profile_id<>actor.id then raise exception 'recipient_mismatch' using errcode='42501'; end if;
  if invitation.recipient_email is null or lower(invitation.recipient_email)<>lower(coalesce(actor.email,''))
    or actor.email_verified_at is null then raise exception 'verified_recipient_mismatch' using errcode='42501'; end if;
  select * into garden from public.gardens where id=invitation.garden_id for update;
  if garden.id is null or garden.bootstrap_inspector_id<>invitation.created_by or garden.bootstrap_cancelled_at is not null
    or garden.status::text<>'pending' then raise exception 'preliminary_garden_unavailable' using errcode='42501'; end if;
  if not p_accept then
    update public.management_invitations set status='rejected',rejected_at=now_at,rejected_by=actor.id,updated_at=now_at where id=invitation.id;
    insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action)
    values(actor.id,actor.role,garden.id,'management_invitations',invitation.id,'inspector_garden_invitation_rejected');
    return jsonb_build_object('garden_id',garden.id,'status','rejected');
  end if;
  kind:=invitation.payload->>'registrant_type';
  if kind not in ('owner_only','owner_teacher','teacher_operator') then raise exception 'invitation_role_invalid' using errcode='23514'; end if;
  relationship:=case when kind='teacher_operator' then 'manager' else 'owner' end;
  if invitation.intended_role<>(case when relationship='owner' then 'kindergarten_owner' else 'kindergarten_manager' end)
    then raise exception 'invitation_role_mismatch' using errcode='42501'; end if;
  if actor.role::text<>relationship then raise exception 'account_role_mismatch' using errcode='42501'; end if;
  select * into onboarding from public.kindergarten_onboarding_records where garden_id=garden.id for update;
  if onboarding.id is null or onboarding.manager_id is not null then raise exception 'onboarding_already_claimed' using errcode='23514'; end if;
  update public.gardens set manager_id=actor.id,owner_profile_id=case when relationship='owner' then actor.id else null end,
    owner_name=actor.full_name,ownership_type=case kind when 'owner_teacher' then 'teacher_is_owner' when 'owner_only' then 'owner_only' else 'teacher_only' end,
    updated_at=now_at where id=garden.id;
  -- The GB-M09 direct-column mirror may insert an active row; normalize it before commit.
  update public.garden_management_memberships set status='pending',activated_at=null,is_default=false,ended_at=null,updated_at=now_at
    where garden_id=garden.id and profile_id=actor.id;
  insert into public.garden_management_memberships(profile_id,garden_id,relationship_role,status,is_default,source,metadata)
  values(actor.id,garden.id,relationship,'pending',false,'self_service',jsonb_build_object('invitation_id',invitation.id,'source','inspector_invitation'))
  on conflict(profile_id,garden_id,relationship_role) do update set status='pending',activated_at=null,is_default=false,ended_at=null,updated_at=now_at;
  update public.kindergarten_onboarding_records set manager_id=actor.id,registrant_type=kind,
    profile_data=profile_data||jsonb_build_object('invitation_id',invitation.id,'registration_source','inspector_preliminary'),
    lifecycle_status='activation_in_progress',started_at=coalesce(started_at,now_at),updated_at=now_at where id=onboarding.id;
  update public.management_invitations set status='accepted',accepted_at=now_at,accepted_by=actor.id,target_profile_id=actor.id,updated_at=now_at
    where id=invitation.id;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(actor.id,actor.role,garden.id,'management_invitations',invitation.id,'inspector_garden_invitation_accepted',jsonb_build_object('registrant_type',kind));
  return jsonb_build_object('garden_id',garden.id,'status','accepted','already_accepted',false,'activation_key',onboarding.activation_key);
end $$;

CREATE FUNCTION public.activate_digital_observer_watch_rule(requested_observer_site_id uuid, requested_rule_id uuid, requested_original_text text, requested_structured_rule jsonb, requested_compiler_version text, requested_candidate_fingerprint text, requested_idempotency_key text, requested_title text, requested_watch_type text, requested_priority integer, requested_schedule jsonb, requested_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  rule_row public.observer_watch_requests;
  version_row public.digital_observer_watch_rule_versions;
  prior_version public.digital_observer_watch_rule_versions;
  camera_id_value uuid;
  zone_id_value uuid;
  next_version integer;
  action_value text;
begin
  if auth.uid() is null or not public.can_manage_observer_site(requested_observer_site_id) then
    raise exception 'WATCH_RULE_ACCESS_DENIED';
  end if;
  if length(trim(requested_original_text)) not between 3 and 1200
    or length(requested_candidate_fingerprint) <> 64
    or length(requested_idempotency_key) not between 8 and 160
    or requested_compiler_version <> 'do-watch-compiler-v1'
    or requested_structured_rule->>'schemaVersion' <> 'do-watch-rule-v1'
    or requested_structured_rule->>'observerSiteId' <> requested_observer_site_id::text
    or requested_structured_rule->>'environment' not in ('PRODUCTION','STAGING','TEST','DEMO')
    or coalesce((requested_structured_rule#>>'{safety,externalExecutionEnabled}')::boolean, true) <> false
    or coalesce((requested_structured_rule#>>'{safety,requiresUserConfirmation}')::boolean, false) <> true
    or coalesce((requested_structured_rule#>>'{safety,realCameraEventsOnly}')::boolean, false) <> true
    or requested_watch_type not in ('movement_in_area','restricted_area_entry','after_hours_activity')
    or requested_priority not between 1 and 10 then
    raise exception 'WATCH_RULE_CONTRACT_INVALID';
  end if;

  action_value := requested_structured_rule#>>'{policyIntent,minimumDecision}';
  if action_value not in ('LOG_ONLY','PRESERVE_EVIDENCE','VERIFY','NOTIFY_IN_APP') then
    raise exception 'WATCH_RULE_ACTION_UNSUPPORTED';
  end if;
  if jsonb_array_length(coalesce(requested_structured_rule#>'{target,cameraSourceIds}', '[]'::jsonb)) < 1 then
    raise exception 'WATCH_RULE_CAMERA_REQUIRED';
  end if;
  if exists (
    select 1
    from jsonb_array_elements_text(requested_structured_rule#>'{target,cameraSourceIds}') camera_ref
    left join public.digital_observer_camera_sources source
      on source.id = camera_ref::uuid and source.observer_site_id = requested_observer_site_id
    where source.id is null
  ) then
    raise exception 'WATCH_RULE_CAMERA_SCOPE_INVALID';
  end if;
  if exists (
    select 1
    from jsonb_array_elements_text(coalesce(requested_structured_rule#>'{target,zoneIds}', '[]'::jsonb)) zone_ref
    left join public.camera_zones zone
      on zone.id = zone_ref::uuid and zone.observer_site_id = requested_observer_site_id
    where zone.id is null
  ) then
    raise exception 'WATCH_RULE_ZONE_SCOPE_INVALID';
  end if;

  select * into version_row
  from public.digital_observer_watch_rule_versions
  where observer_site_id = requested_observer_site_id and idempotency_key = requested_idempotency_key;
  if found then
    select * into rule_row from public.observer_watch_requests where id = version_row.rule_id;
    return jsonb_build_object('rule_id', rule_row.id, 'version_id', version_row.id, 'version', version_row.version, 'idempotent', true, 'state', rule_row.rule_state);
  end if;

  select nullif(requested_structured_rule#>>'{target,cameraSourceIds,0}', '')::uuid into camera_id_value;
  select nullif(requested_structured_rule#>>'{target,zoneIds,0}', '')::uuid into zone_id_value;

  if requested_rule_id is null then
    insert into public.observer_watch_requests (
      observer_site_id, kindergarten_id, camera_id, camera_source_id, zone_id, created_by,
      title, description, watch_type, active, priority, schedule, notification_channels,
      requires_human_review, metadata, original_natural_language, structured_rule,
      validation_status, compiler_version, rule_version, rule_state, confirmed_by, confirmed_at
    ) values (
      requested_observer_site_id, null, null, camera_id_value, zone_id_value, auth.uid(),
      left(requested_title, 140), requested_original_text, requested_watch_type, true, requested_priority,
      requested_schedule,
      case when action_value = 'NOTIFY_IN_APP' then '["in_app"]'::jsonb else '[]'::jsonb end,
      true,
      coalesce(requested_metadata, '{}'::jsonb) || jsonb_build_object(
        'product', 'digital_observer',
        'canonical_compiled_rule', true,
        'compiler_version', requested_compiler_version,
        'rule_version', 1,
        'execution_state', 'production_real_event_policy',
        'no_external_action_execution', true,
        'risk_policy', jsonb_build_object(
          'event_types', requested_structured_rule#>'{conditions,eventTypes}',
          'minimum_decision', action_value,
          'minimum_risk_score', null,
          'contribution', coalesce((requested_structured_rule#>>'{policyIntent,riskContribution}')::integer, 0),
          'version', 'watch-rule-1',
          'reason', 'canonical_natural_language_watch_rule'
        )
      ),
      requested_original_text, requested_structured_rule, 'VALID', requested_compiler_version,
      1, 'ACTIVE', auth.uid(), now()
    ) returning * into rule_row;
    next_version := 1;
  else
    select * into rule_row from public.observer_watch_requests
    where id = requested_rule_id and observer_site_id = requested_observer_site_id for update;
    if not found or rule_row.compiler_version is null then raise exception 'WATCH_RULE_NOT_FOUND'; end if;
    next_version := rule_row.rule_version + 1;
    select * into prior_version from public.digital_observer_watch_rule_versions
      where rule_id = rule_row.id order by version desc limit 1;
    update public.observer_watch_requests set
      camera_source_id = camera_id_value,
      zone_id = zone_id_value,
      title = left(requested_title, 140),
      description = requested_original_text,
      watch_type = requested_watch_type,
      active = true,
      priority = requested_priority,
      schedule = requested_schedule,
      notification_channels = case when action_value = 'NOTIFY_IN_APP' then '["in_app"]'::jsonb else '[]'::jsonb end,
      metadata = coalesce(requested_metadata, '{}'::jsonb) || jsonb_build_object(
        'product', 'digital_observer',
        'canonical_compiled_rule', true,
        'compiler_version', requested_compiler_version,
        'rule_version', next_version,
        'execution_state', 'production_real_event_policy',
        'no_external_action_execution', true,
        'risk_policy', jsonb_build_object(
          'event_types', requested_structured_rule#>'{conditions,eventTypes}',
          'minimum_decision', action_value,
          'minimum_risk_score', null,
          'contribution', coalesce((requested_structured_rule#>>'{policyIntent,riskContribution}')::integer, 0),
          'version', 'watch-rule-' || next_version,
          'reason', 'canonical_natural_language_watch_rule'
        )
      ),
      original_natural_language = requested_original_text,
      structured_rule = requested_structured_rule,
      validation_status = 'VALID',
      compiler_version = requested_compiler_version,
      rule_version = next_version,
      rule_state = 'ACTIVE',
      confirmed_by = auth.uid(),
      confirmed_at = now(),
      archived_at = null,
      updated_at = now()
    where id = rule_row.id returning * into rule_row;
  end if;

  insert into public.digital_observer_watch_rule_versions (
    observer_site_id, rule_id, version, original_natural_language, structured_rule,
    validation_status, compiler_version, candidate_fingerprint, created_by, change_type,
    previous_version_id, environment, idempotency_key
  ) values (
    requested_observer_site_id, rule_row.id, next_version, requested_original_text, requested_structured_rule,
    'VALID', requested_compiler_version, requested_candidate_fingerprint, auth.uid(),
    case when requested_rule_id is null then 'CREATE' else 'EDIT' end,
    prior_version.id, requested_structured_rule->>'environment', requested_idempotency_key
  ) returning * into version_row;

  return jsonb_build_object('rule_id', rule_row.id, 'version_id', version_row.id, 'version', next_version, 'idempotent', false, 'state', rule_row.rule_state);
end;
$$;

CREATE FUNCTION public.activate_enrollment_from_evidence(target_request_id uuid, target_evidence_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  req public.kindergarten_enrollment_requests; evidence public.enrollment_payment_evidence;
  hold public.classroom_seat_reservations; room public.classrooms; file public.permanent_child_files;
  parent_profile public.profiles; parent_row public.parents; child_row public.children;
  enrollment public.child_kindergarten_enrollments; existing_active public.child_kindergarten_enrollments;
  other_request record; identity_value text; now_at timestamptz:=now();
begin
  perform pg_advisory_xact_lock(hashtextextended(target_request_id::text,0));
  select * into req from public.kindergarten_enrollment_requests where id=target_request_id for update;
  if req.id is null then raise exception 'enrollment_request_not_found' using errcode='P0002'; end if;
  if req.status='activated' and req.activated_enrollment_id is not null then
    select * into enrollment from public.child_kindergarten_enrollments where id=req.activated_enrollment_id;
    return jsonb_build_object('status','activated','enrollment_id',enrollment.id,'child_id',enrollment.child_id,'idempotent',true);
  end if;
  if req.status<>'awaiting_payment' then raise exception 'enrollment_not_awaiting_payment' using errcode='23514'; end if;
  select * into evidence from public.enrollment_payment_evidence where id=target_evidence_id and enrollment_request_id=req.id and garden_id=req.garden_id for update;
  if evidence.id is null or evidence.status<>'confirmed' then raise exception 'confirmed_payment_evidence_required' using errcode='23514'; end if;
  if evidence.evidence_kind='electronic' and evidence.provider_mode not in ('live','verified_test') then raise exception 'unverified_electronic_provider' using errcode='23514'; end if;
  select * into hold from public.classroom_seat_reservations where id=req.reservation_id and enrollment_request_id=req.id and garden_id=req.garden_id and classroom_id=req.requested_classroom_id for update;
  if hold.id is null or hold.status<>'active' or (hold.expires_at is not null and hold.expires_at<=now_at) then raise exception 'enrollment_reservation_not_active' using errcode='23514'; end if;
  select * into room from public.classrooms where id=hold.classroom_id and garden_id=req.garden_id and status='active' for update;
  if room.id is null then raise exception 'enrollment_classroom_not_active' using errcode='23514'; end if;
  perform pg_advisory_xact_lock(hashtextextended(req.child_profile_id::text,0));
  select * into existing_active from public.child_kindergarten_enrollments where permanent_child_file_id=req.child_profile_id and status='active' for update;
  if existing_active.id is not null and existing_active.garden_id<>req.garden_id then raise exception 'active_enrollment_conflict' using errcode='23505'; end if;
  select * into file from public.permanent_child_files where id=req.child_profile_id for update;
  select * into parent_profile from public.profiles where id=req.parent_id;
  if file.id is null or parent_profile.id is null or not exists(
    select 1 from public.child_guardian_links link where link.guardian_profile_id=req.parent_id and link.permanent_child_file_id=req.child_profile_id
      and link.status='active' and link.legal_authority=true and coalesce((link.access_scope->>'profile')::boolean,false)=true
      and (link.valid_until is null or link.valid_until>now_at)
  ) then raise exception 'enrollment_identity_invalid' using errcode='42501'; end if;
  if parent_profile.contact_verification_required and (parent_profile.email_verified_at is null or parent_profile.phone_verified_at is null) then raise exception 'enrollment_contact_verification_required' using errcode='23514'; end if;
  select * into parent_row from public.parents where profile_id=req.parent_id and garden_id=req.garden_id order by created_at desc limit 1 for update;
  if parent_row.id is null then
    insert into public.parents(profile_id,user_id,garden_id,full_name,phone,email,address,completed_profile,status,onboarding_status,invitation_status,activated_at,activated_by)
    values(req.parent_id,req.parent_id,req.garden_id,parent_profile.full_name,coalesce(parent_profile.phone,''),parent_profile.email,file.address,true,'active','active','active',now_at,evidence.recorded_by)
    returning * into parent_row;
  else
    update public.parents set status='active',onboarding_status='active',invitation_status='active',activated_at=coalesce(activated_at,now_at),activated_by=coalesce(activated_by,evidence.recorded_by),updated_at=now_at where id=parent_row.id returning * into parent_row;
  end if;
  select * into child_row from public.children where garden_id=req.garden_id and permanent_child_file_id=file.id for update;
  if child_row.id is null then
    identity_value:=coalesce(file.identity_number,file.mother_details->>'identity_number',file.father_details->>'identity_number');
    if identity_value is null then raise exception 'child_identity_required' using errcode='23514'; end if;
    insert into public.children(garden_id,primary_parent_id,permanent_child_file_id,full_name,birth_date,identity_number,hmo,address,photo_url,face_image_url,pickup_authorized,status,parent_completed,manager_approved_at,monthly_fee,payment_status)
    values(req.garden_id,parent_row.id,file.id,file.full_name,file.birth_date,identity_value,file.hmo,file.address,file.photo_url,coalesce(file.face_image_url,file.photo_url),coalesce(file.pickup_authorized,'[]'::jsonb),'active',true,now_at,coalesce(req.published_price_snapshot,evidence.amount),case when evidence.evidence_kind='manual_arrangement' then 'special_arrangement' else 'paid' end)
    returning * into child_row;
  else
    update public.children set status='active',parent_completed=true,manager_approved_at=coalesce(manager_approved_at,now_at),payment_status=case when evidence.evidence_kind='manual_arrangement' then 'special_arrangement' else 'paid' end,last_amount_paid=evidence.amount,last_payment_date=evidence.covered_from,valid_until=evidence.covered_until,updated_at=now_at where id=child_row.id returning * into child_row;
  end if;
  select * into enrollment from public.child_kindergarten_enrollments where child_id=child_row.id and garden_id=req.garden_id for update;
  if enrollment.id is null then
    insert into public.child_kindergarten_enrollments(child_id,permanent_child_file_id,garden_id,status,start_date,manager_approved_at,manager_approved_by,enrollment_request_id,activation_payment_evidence_id,classroom_id,activated_at,activation_source,updated_at)
    values(child_row.id,file.id,req.garden_id,'active',greatest(evidence.covered_from,current_date),now_at,evidence.recorded_by,req.id,evidence.id,room.id,now_at,evidence.evidence_kind,now_at)
    returning * into enrollment;
  else
    update public.child_kindergarten_enrollments set permanent_child_file_id=file.id,status='active',start_date=coalesce(start_date,greatest(evidence.covered_from,current_date)),manager_approved_at=coalesce(manager_approved_at,now_at),manager_approved_by=coalesce(manager_approved_by,evidence.recorded_by),enrollment_request_id=req.id,activation_payment_evidence_id=evidence.id,classroom_id=room.id,activated_at=coalesce(activated_at,now_at),activation_source=evidence.evidence_kind,updated_at=now_at where id=enrollment.id returning * into enrollment;
  end if;
  update public.classroom_seat_reservations set child_id=child_row.id,enrollment_id=enrollment.id,updated_at=now_at where id=hold.id;
  update public.child_classroom_assignments set is_current=false,ended_at=now_at,end_reason='enrollment_activation_move'
    where child_id=child_row.id and garden_id=req.garden_id and is_current and classroom_id<>room.id;
  if exists(select 1 from public.child_classroom_assignments where child_id=child_row.id and garden_id=req.garden_id and classroom_id=room.id and is_current) then
    update public.child_classroom_assignments set enrollment_id=enrollment.id where child_id=child_row.id and garden_id=req.garden_id and classroom_id=room.id and is_current;
  else
    insert into public.child_classroom_assignments(garden_id,child_id,enrollment_id,classroom_id,assigned_by)
    values(req.garden_id,child_row.id,enrollment.id,room.id,evidence.recorded_by);
  end if;
  update public.classroom_seat_reservations set status='consumed',consumed_at=now_at,updated_at=now_at where id=hold.id and status='active';
  select * into hold from public.classroom_seat_reservations where id=hold.id;
  if hold.status<>'consumed' then raise exception 'reservation_consumption_failed'; end if;
  update public.permanent_child_files set owner_status='submitted',updated_at=now_at where id=file.id;
  update public.kindergarten_enrollment_requests set status='activated',payment_status=case when evidence.evidence_kind='manual_arrangement' then 'arranged' else 'paid' end,activation_payment_evidence_id=evidence.id,activated_enrollment_id=enrollment.id,activated_at=now_at,activated_child_id=child_row.id,updated_at=now_at where id=req.id;

  for other_request in select id,reservation_id from public.kindergarten_enrollment_requests where child_profile_id=file.id and id<>req.id and status in ('draft','submitted','under_review','information_required','resubmitted','approved','awaiting_payment','waitlisted') for update loop
    update public.classroom_seat_reservations set status='released',released_at=now_at,updated_at=now_at where id=other_request.reservation_id and status='active';
    if exists(select 1 from public.enrollment_payment_evidence p where p.enrollment_request_id=other_request.id and p.status='confirmed') then
      update public.enrollment_payment_evidence set status='reconciliation_required',reconciliation_reason='another_garden_enrollment_activated',updated_at=now_at where enrollment_request_id=other_request.id and status='confirmed';
      update public.kindergarten_enrollment_requests set status='payment_reconciliation_required',updated_at=now_at where id=other_request.id;
    else
      update public.kindergarten_enrollment_requests set status='cancelled',cancelled_at=now_at,cancelled_by=evidence.recorded_by,updated_at=now_at where id=other_request.id;
    end if;
  end loop;
  insert into public.child_timeline_events(child_id,permanent_child_file_id,garden_id,actor_id,actor_role,event_type,title,description,metadata)
  values(child_row.id,file.id,req.garden_id,evidence.recorded_by,case when evidence.evidence_kind='manual_arrangement' then 'manager' else 'system' end,'kindergarten_enrollment_activated','ההרשמה לגן הופעלה','ההרשמה הופעלה לאחר אימות הסדר התשלום.',jsonb_build_object('enrollment_request_id',req.id,'payment_evidence_id',evidence.id,'classroom_id',room.id));
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(evidence.recorded_by,case when evidence.evidence_kind='manual_arrangement' then 'manager' else 'system' end,req.garden_id,'child_kindergarten_enrollments',enrollment.id,'enrollment_activation_succeeded',jsonb_build_object('request_id',req.id,'payment_evidence_id',evidence.id,'classroom_id',room.id));
  insert into public.notifications(garden_id,recipient_id,recipient_profile_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,kindergarten_id,child_id,created_by)
  values(req.garden_id,req.parent_id,req.parent_id,'parent','ההרשמה לגן הופעלה','ההרשמה הושלמה והילד/ה פעיל/ה בגן.','ההרשמה הושלמה והילד/ה פעיל/ה בגן.','child_kindergarten_enrollments',enrollment.id,'low','/dashboard/parent',req.garden_id,child_row.id,evidence.recorded_by);
  return jsonb_build_object('status','activated','enrollment_id',enrollment.id,'child_id',child_row.id,'classroom_id',room.id,'payment_evidence_id',evidence.id,'idempotent',false);
end $$;

CREATE FUNCTION public.activate_garden_onboarding(target_garden_id uuid, requested_activation_key uuid, accept_required_consents boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare record public.kindergarten_onboarding_records%rowtype; garden public.gardens%rowtype; status_state jsonb;
  actor public.profiles%rowtype; now_at timestamptz:=now(); trial_end timestamptz:=now()+interval '14 days'; relationship text; assignment_kind text;
begin
  perform pg_advisory_xact_lock(hashtextextended(target_garden_id::text,0));
  if not public.can_edit_garden_onboarding(target_garden_id) then raise exception 'onboarding_access_denied' using errcode='42501'; end if;
  select * into record from public.kindergarten_onboarding_records where garden_id=target_garden_id for update;
  select * into garden from public.gardens where id=target_garden_id for update;
  select * into actor from public.profiles where id=auth.uid() for update;
  if record.activation_key is distinct from requested_activation_key then raise exception 'activation_key_mismatch' using errcode='42501'; end if;
  if record.lifecycle_status='active' and garden.status::text='active' then return jsonb_build_object('garden_id',target_garden_id,'status','active','already_active',true); end if;
  if accept_required_consents then
    insert into public.kindergarten_legal_acceptances(garden_id,manager_profile_id,acceptance_type,accepted,version,accepted_at,metadata)
    select target_garden_id,actor.id,consent_type,true,'gb-m10-product-consent-v1',now_at,jsonb_build_object('source','garden_onboarding_activation')
    from unnest(array['platform_terms','privacy_terms']) consent_type
    where not exists(select 1 from public.kindergarten_legal_acceptances existing where existing.garden_id=target_garden_id
      and existing.manager_profile_id=actor.id and existing.acceptance_type=consent_type and existing.version='gb-m10-product-consent-v1');
  end if;
  status_state:=public.garden_onboarding_status(target_garden_id);
  if not coalesce((status_state->>'can_activate')::boolean,false) then
    update public.kindergarten_onboarding_records set activation_attempts=activation_attempts+1,last_activation_error='requirements_not_met',updated_at=now_at where id=record.id;
    raise exception 'onboarding_requirements_not_met:%',status_state->'blockers' using errcode='23514';
  end if;
  relationship:=case when record.registrant_type in ('owner_teacher','owner_only') then 'owner' else 'manager' end;
  update public.gardens set status='active',approval_flow_status='active',final_approval_status='active',onboarding_status='active',
    activation_progress_percent=100,activation_payment_status='payment_pending',onboarding_completed_at=now_at,
    profile_submitted_at=now_at,public_profile_enabled=true,updated_at=now_at where id=target_garden_id;
  update public.garden_management_memberships set status='active',activated_at=coalesce(activated_at,now_at),ended_at=null,updated_at=now_at
    where profile_id=actor.id and garden_id=target_garden_id and relationship_role=relationship;
  -- Activate the profile inside this transaction before the teaching-assignment guard runs.
  update public.profiles set garden_id=coalesce(garden_id,target_garden_id),active=true,self_service_status='active',self_service_approved_at=coalesce(self_service_approved_at,now_at),updated_at=now_at where id=actor.id;
  if record.registrant_type in ('owner_teacher','teacher_operator') then
    assignment_kind:=case when record.registrant_type='owner_teacher' then 'owner_teacher' else 'operator_teacher' end;
    insert into public.garden_teaching_assignments(garden_id,profile_id,staff_id,assignment_kind,title,status,granted_by,granted_at)
    values(target_garden_id,actor.id,null,assignment_kind,case when assignment_kind='owner_teacher' then 'בעלים וגננת' else 'גננת ומפעילת גן' end,'active',actor.id,now_at)
    on conflict(garden_id,profile_id) do update set assignment_kind=excluded.assignment_kind,status='active',revoked_at=null,updated_at=now_at;
  end if;
  if not exists(select 1 from public.kindergarten_subscriptions where garden_id=target_garden_id and status::text in ('active','trial','pending_payment','suspended')) then
    insert into public.kindergarten_subscriptions(garden_id,status,trial_status,plan_type,start_date,trial_started_at,trial_ends_at,expires_at,renewal_date,
      provider,billing_status,billing_cycle,current_period_start,current_period_end,trial_conversion_status,metadata,created_by,updated_by)
    values(target_garden_id,'trial','active','annual',current_date,now_at,trial_end,trial_end,trial_end::date,'manual','trial','annual',current_date,trial_end::date,
      'trial_active',jsonb_build_object('monthly_amount_nis',record.subscription_monthly_amount,'charge_today_nis',0,'payment_mode','manual_or_sandbox_until_provider_approval'),actor.id,actor.id);
  end if;
  update public.kindergarten_onboarding_records set lifecycle_status='active',progress_percent=100,current_step='activation',
    completed_steps=array(select distinct unnest(completed_steps||array['activation'])),activation_steps=array(select distinct unnest(activation_steps||array['activation_completed'])),
    payment_status='payment_pending',submitted_at=coalesce(submitted_at,now_at),activated_at=coalesce(activated_at,now_at),completed_at=coalesce(completed_at,now_at),
    activation_attempts=activation_attempts+1,last_activation_error=null,updated_at=now_at where id=record.id;
  update public.self_service_user_profiles set status='active',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('last_activated_garden_id',target_garden_id,'application_stage','trial_active'),updated_at=now_at where profile_id=actor.id;
  insert into public.kindergarten_activation_events(garden_id,actor_id,event_type,status,metadata) values(target_garden_id,actor.id,'activation_completed','recorded',jsonb_build_object('atomic',true,'admin_approval_required',false,'registrant_type',record.registrant_type)) on conflict do nothing;
  insert into public.audit_logs(actor_id,actor_role,performed_by_user,performed_by_role,garden_id,entity_type,entity_id,action,after_data)
  values(actor.id,actor.role,actor.id,actor.role,target_garden_id,'kindergarten_onboarding_records',record.id,'garden_onboarding_activated',jsonb_build_object('atomic',true,'registrant_type',record.registrant_type));
  return jsonb_build_object('garden_id',target_garden_id,'status','active','already_active',false);
end $$;

COMMENT ON FUNCTION public.activate_garden_onboarding(target_garden_id uuid, requested_activation_key uuid, accept_required_consents boolean) IS 'GB-M10 atomic and idempotent Garden activation. Locks one Garden and commits authority, teaching, subscription and lifecycle together.';

CREATE FUNCTION public.activate_staff_employment(target_application_id uuid, target_invitation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare application public.staff_job_applications; candidate public.staff_candidate_profiles; invitation public.management_invitations; actor_profile public.profiles; file public.staff_permanent_files; staff_row public.staff; employment public.staff_kindergarten_employments; room public.classrooms; now_at timestamptz:=now();
begin
  perform pg_advisory_xact_lock(hashtextextended(target_application_id::text,0));
  select * into application from public.staff_job_applications where id=target_application_id and staff_candidate_id=auth.uid() for update;
  if application.id is null then raise exception 'staff_application_not_found' using errcode='P0002'; end if;
  if application.status='employed' and application.employment_id is not null then return jsonb_build_object('application_id',application.id,'employment_id',application.employment_id,'staff_id',application.activated_staff_id,'idempotent',true); end if;
  if application.status<>'awaiting_candidate_acceptance' then raise exception 'staff_application_not_awaiting_acceptance' using errcode='23514'; end if;
  select * into actor_profile from public.profiles where id=auth.uid() for update;
  if actor_profile.id is null or (actor_profile.contact_verification_required and (actor_profile.email_verified_at is null or actor_profile.phone_verified_at is null)) then raise exception 'staff_contact_verification_required' using errcode='23514'; end if;
  select * into candidate from public.staff_candidate_profiles where profile_id=auth.uid() for update;
  if candidate.profile_id is null or coalesce((public.evaluate_staff_candidate_profile(auth.uid())->>'required_fields_complete')::boolean,false)<>true then raise exception 'candidate_profile_incomplete' using errcode='23514'; end if;
  if target_invitation_id is not null then
    select * into invitation from public.management_invitations where id=target_invitation_id and invitation_type='staff' and intended_role='staff' and garden_id=application.garden_id and staff_application_id=application.id and target_profile_id=auth.uid() and status in ('pending','delivered') and expires_at>now_at for update;
    if invitation.id is null then raise exception 'staff_invitation_invalid' using errcode='42501'; end if;
  end if;
  if application.classroom_id is not null then select * into room from public.classrooms where id=application.classroom_id and garden_id=application.garden_id and status='active'; if room.id is null then raise exception 'staff_application_classroom_invalid' using errcode='23514'; end if; end if;
  select * into file from public.staff_permanent_files where profile_id=auth.uid() order by created_at limit 1 for update;
  if file.id is null then insert into public.staff_permanent_files(profile_id,full_name,phone,email,profile_photo_url,document_summary,notes) values(auth.uid(),coalesce(candidate.full_name,'איש צוות'),candidate.phone,candidate.email,candidate.profile_photo_url,candidate.document_status,'נוצר בהפעלת העסקה קנונית GB-M18') returning * into file; end if;
  select * into staff_row from public.staff where profile_id=auth.uid() and garden_id=application.garden_id order by created_at limit 1 for update;
  if staff_row.id is null then insert into public.staff(profile_id,garden_id,full_name,role_title,phone,email,profile_photo_url,class_group,approved_to_work,onboarding_status,background_check_status,police_clearance_status,manager_approved_at,activated_at,activated_by) values(auth.uid(),application.garden_id,coalesce(candidate.full_name,'איש צוות'),coalesce(application.requested_role,'צוות'),candidate.phone,candidate.email,candidate.profile_photo_url,null,true,'active','pending_review','pending_review',application.reviewed_at,now_at,application.reviewed_by) returning * into staff_row;
  else update public.staff set approved_to_work=true,onboarding_status='active',role_title=coalesce(application.requested_role,role_title),activated_at=coalesce(activated_at,now_at),activated_by=coalesce(activated_by,application.reviewed_by),updated_at=now_at where id=staff_row.id returning * into staff_row; end if;
  select * into employment from public.staff_kindergarten_employments where profile_id=auth.uid() and garden_id=application.garden_id and status in ('pending_approval','active') order by created_at limit 1 for update;
  if employment.id is null then insert into public.staff_kindergarten_employments(staff_file_id,staff_id,profile_id,garden_id,status,role_title,start_date,approved_at,approved_by,notes) values(file.id,staff_row.id,auth.uid(),application.garden_id,'active',coalesce(application.requested_role,'צוות'),current_date,now_at,application.reviewed_by,'הופעל דרך GB-M18') returning * into employment;
  else update public.staff_kindergarten_employments set staff_id=staff_row.id,status='active',role_title=coalesce(application.requested_role,role_title),approved_at=coalesce(approved_at,now_at),approved_by=coalesce(approved_by,application.reviewed_by),updated_at=now_at where id=employment.id returning * into employment; end if;
  if room.id is not null and not exists(select 1 from public.staff_classroom_assignments where employment_id=employment.id and classroom_id=room.id and status='active') then insert into public.staff_classroom_assignments(garden_id,staff_id,employment_id,classroom_id,assigned_by,status) values(application.garden_id,staff_row.id,employment.id,room.id,application.reviewed_by,'active'); end if;
  update public.staff_job_applications set status='employed',accepted_at=now_at,activated_at=now_at,activated_staff_id=staff_row.id,employment_id=employment.id,updated_at=now_at where id=application.id;
  if invitation.id is not null then update public.management_invitations set status='accepted',accepted_at=now_at,accepted_by=auth.uid(),updated_at=now_at where id=invitation.id; end if;
  update public.profiles set active=true,garden_id=coalesce(garden_id,application.garden_id),self_service_status='active',self_service_approved_at=coalesce(self_service_approved_at,now_at),self_service_approved_by=coalesce(self_service_approved_by,application.reviewed_by) where id=auth.uid();
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data) values(auth.uid(),'staff',application.garden_id,'staff_kindergarten_employments',employment.id,'staff_employment_activated',jsonb_build_object('application_id',application.id,'invitation_id',invitation.id,'classroom_id',application.classroom_id));
  insert into public.notifications(garden_id,recipient_id,recipient_profile_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,kindergarten_id,created_by) values(application.garden_id,auth.uid(),auth.uid(),'staff','ההעסקה הופעלה','הגישה התפעולית לגן הופעלה בהתאם לתפקיד.','הגישה התפעולית לגן הופעלה בהתאם לתפקיד.','staff_kindergarten_employments',employment.id,'low','/dashboard/staff',application.garden_id,application.reviewed_by);
  return jsonb_build_object('application_id',application.id,'employment_id',employment.id,'staff_id',staff_row.id,'classroom_id',application.classroom_id,'idempotent',false);
end $$;

CREATE TABLE public.staffing_policy_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    policy_set_id uuid NOT NULL,
    version integer NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    effective_from date,
    effective_until date,
    source_title text,
    source_reference text,
    provenance_status text DEFAULT 'unverified'::text NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    activated_by uuid,
    activated_at timestamp with time zone,
    retired_by uuid,
    retired_at timestamp with time zone,
    notes text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staffing_policy_approval_truth_check CHECK (((status <> ALL (ARRAY['approved'::text, 'active'::text])) OR ((approved_at IS NOT NULL) AND (approved_by IS NOT NULL) AND (provenance_status = 'approved'::text)))),
    CONSTRAINT staffing_policy_dates_check CHECK (((effective_until IS NULL) OR (effective_from IS NULL) OR (effective_until >= effective_from))),
    CONSTRAINT staffing_policy_provenance_check CHECK ((provenance_status = ANY (ARRAY['unverified'::text, 'source_recorded'::text, 'reviewed'::text, 'approved'::text]))),
    CONSTRAINT staffing_policy_version_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'under_review'::text, 'approved'::text, 'active'::text, 'retired'::text])))
);

COMMENT ON TABLE public.staffing_policy_versions IS 'Versioned staffing policy with explicit provenance and review; no version is authoritative until approved and active.';

CREATE FUNCTION public.activate_staffing_policy_version(target_version_id uuid) RETURNS public.staffing_policy_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.staffing_policy_versions; conflict_count integer;
begin
  if not public.is_admin() then raise exception 'staffing_policy_admin_required' using errcode='42501'; end if;
  select * into target from public.staffing_policy_versions where id=target_version_id for update;
  if target.id is null then raise exception 'staffing_policy_version_not_found' using errcode='P0002'; end if;
  if target.status<>'approved' or target.provenance_status<>'approved' or target.approved_at is null then raise exception 'staffing_policy_approval_required' using errcode='23514'; end if;
  if target.effective_from is null or not exists(select 1 from public.staffing_policy_rules where policy_version_id=target.id) then raise exception 'staffing_policy_effective_rules_required' using errcode='23514'; end if;
  select count(*) into conflict_count from public.staffing_policy_versions v
  where v.policy_set_id=target.policy_set_id and v.id<>target.id and v.status='active'
    and daterange(v.effective_from,coalesce(v.effective_until,'infinity'::date),'[]') && daterange(target.effective_from,coalesce(target.effective_until,'infinity'::date),'[]');
  if conflict_count>0 then raise exception 'staffing_policy_effective_date_conflict' using errcode='23P01'; end if;
  update public.staffing_policy_versions set status='active',activated_by=auth.uid(),activated_at=now(),updated_at=now() where id=target.id returning * into target;
  return target;
end $$;

CREATE FUNCTION public.admin_adopt_platform_plan(target_subscription_id uuid, target_plan_id uuid, action_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.kindergarten_subscriptions%rowtype; p public.subscription_plans%rowtype; agreed_price numeric;
begin
  if public.is_admin() is distinct from true then raise exception 'admin_required' using errcode='42501'; end if;
  if action_reason is null or length(trim(action_reason))<5 then raise exception 'plan_adoption_reason_required'; end if;
  select * into s from public.kindergarten_subscriptions where id=target_subscription_id for update;
  if s.id is null then raise exception 'subscription_not_found'; end if;
  if s.status::text not in ('trial','pending_payment','payment_failed','past_due','grace_period','suspended') then
    raise exception 'plan_change_requires_new_contract';
  end if;
  select * into p from public.subscription_plans where id=target_plan_id and active;
  if p.id is null then raise exception 'active_plan_not_found'; end if;
  agreed_price:=case when p.billing_interval='monthly' then coalesce(p.monthly_price,p.price_amount)
    else coalesce(p.annual_price,p.price_amount) end;
  if s.plan_id=p.id and s.unit_price_snapshot=agreed_price and s.billing_interval=p.billing_interval then
    return jsonb_build_object('id',s.id,'plan_id',p.id,'idempotent',true);
  end if;
  update public.kindergarten_subscriptions set plan_id=p.id,plan_type=p.plan_type,
    plan_code_snapshot=p.code,plan_version_snapshot=p.version,unit_price_snapshot=agreed_price,
    currency_snapshot=p.currency,billing_interval=p.billing_interval,billing_cycle=p.billing_interval,
    commitment_months=p.commitment_months,updated_by=auth.uid(),updated_at=now()
    where id=s.id;
  insert into public.platform_subscription_events(subscription_id,garden_id,action,previous_status,next_status,actor_id,source,reason)
    values(s.id,s.garden_id,'plan_adopted',s.status::text,s.status::text,auth.uid(),'manual_admin',left(action_reason,500));
  return jsonb_build_object('id',s.id,'plan_id',p.id,'idempotent',false,'unit_price',agreed_price);
end $$;

CREATE FUNCTION public.admin_transition_platform_subscription(target_subscription_id uuid, requested_action text, action_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.kindergarten_subscriptions%rowtype; next_status public.kindergarten_subscription_status;
  next_billing text; next_start date; next_end date; source_kind text;
begin
  if public.is_admin() is distinct from true then raise exception 'admin_required' using errcode='42501'; end if;
  select * into s from public.kindergarten_subscriptions where id=target_subscription_id for update;
  if s.id is null then raise exception 'subscription_not_found'; end if;
  if s.status::text in ('cancelled','expired') and requested_action <> 'cancel' then
    raise exception 'terminal_subscription_requires_new_contract';
  end if;
  if requested_action in ('manual_activate','reactivate') then
    if action_reason is null or length(trim(action_reason))<5 then raise exception 'manual_reason_required'; end if;
    if s.status::text='active' then return jsonb_build_object('id',s.id,'status','active','idempotent',true); end if;
    if s.status::text='cancelled' then raise exception 'cancelled_subscription_requires_new_contract'; end if;
    if s.plan_id is null or s.unit_price_snapshot is null or s.billing_interval is null then
      raise exception 'subscription_terms_not_snapshotted';
    end if;
    next_status:='active'; next_billing:='active'; source_kind:='manual_admin';
    next_start:=current_date;
    next_end:=(next_start+case when coalesce(s.billing_interval,'monthly')='monthly' then interval '1 month' else interval '1 year' end)::date;
  elsif requested_action='suspend' then
    if s.status::text='suspended' then return jsonb_build_object('id',s.id,'status','suspended','idempotent',true); end if;
    next_status:='suspended';next_billing:='suspended';source_kind:='admin';
  elsif requested_action='mark_past_due' then
    if s.status::text='past_due' then return jsonb_build_object('id',s.id,'status','past_due','idempotent',true); end if;
    next_status:='past_due';next_billing:='past_due';source_kind:='admin';
  elsif requested_action='enter_grace' then
    if s.status::text='grace_period' then return jsonb_build_object('id',s.id,'status','grace_period','idempotent',true); end if;
    if s.status::text not in ('past_due','payment_failed') then raise exception 'invalid_transition'; end if;
    if s.plan_id is null or (select grace_days from public.subscription_plans where id=s.plan_id) is null then raise exception 'grace_not_configured'; end if;
    next_status:='grace_period';next_billing:='grace_period';source_kind:='admin';
  elsif requested_action='cancel' then
    if s.status::text='cancelled' then return jsonb_build_object('id',s.id,'status','cancelled','idempotent',true); end if;
    if action_reason is null or length(trim(action_reason))<5 then raise exception 'admin_cancellation_reason_required'; end if;
    next_status:='cancelled';next_billing:='cancelled';source_kind:='admin';
  elsif requested_action='renew' then
    if s.status::text not in ('active','past_due','grace_period') then raise exception 'invalid_transition'; end if;
    if s.current_period_end is null then raise exception 'period_missing'; end if;
    if s.current_period_end>current_date then return jsonb_build_object('id',s.id,'status',s.status,'idempotent',true); end if;
    next_status:='pending_payment';next_billing:='pending_payment';source_kind:='system_readiness';
    next_start:=s.current_period_end;
    next_end:=(next_start+case when coalesce(s.billing_interval,'monthly')='monthly' then interval '1 month' else interval '1 year' end)::date;
  else raise exception 'unsupported_subscription_action'; end if;
  update public.kindergarten_subscriptions set status=next_status,billing_status=next_billing,
    current_period_start=coalesce(next_start,current_period_start),
    current_period_end=coalesce(next_end,current_period_end),
    commitment_start=case when requested_action in ('manual_activate','reactivate') then coalesce(commitment_start,next_start) else commitment_start end,
    commitment_end=case when requested_action in ('manual_activate','reactivate') then
      coalesce(commitment_end,(coalesce(commitment_start,next_start)+(coalesce(commitment_months,12)||' months')::interval)::date) else commitment_end end,
    renewal_date=case when next_end is null then renewal_date else next_end end,
    activation_source=case when requested_action in ('manual_activate','reactivate') then source_kind else activation_source end,
    grace_until=case when requested_action='enter_grace' then now()+((select grace_days from public.subscription_plans where id=s.plan_id)||' days')::interval else grace_until end,
    suspended_at=case when requested_action='suspend' then now() else suspended_at end,
    cancelled_at=case when requested_action='cancel' then now() else cancelled_at end,
    updated_at=now(),updated_by=auth.uid() where id=s.id;
  insert into public.platform_subscription_events(subscription_id,garden_id,action,previous_status,next_status,actor_id,source,reason,period_start,period_end)
    values(s.id,s.garden_id,requested_action,s.status::text,next_status::text,auth.uid(),source_kind,left(action_reason,500),next_start,next_end);
  return jsonb_build_object('id',s.id,'status',next_status,'idempotent',false,'source',source_kind);
end $$;

CREATE FUNCTION public.admin_version_platform_plan(target_plan_id uuid, proposed_name text, proposed_price numeric, proposed_currency text DEFAULT 'ILS'::text, proposed_billing_interval text DEFAULT 'monthly'::text, proposed_grace_days integer DEFAULT NULL::integer, make_default boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare old_plan public.subscription_plans%rowtype; new_plan public.subscription_plans%rowtype; next_version integer;
begin
  if public.is_admin() is distinct from true then raise exception 'admin_required' using errcode='42501'; end if;
  if proposed_price < 0 or proposed_currency is null or length(proposed_currency) <> 3 or
     proposed_billing_interval not in ('monthly','annual') or
     proposed_grace_days < 0 or length(trim(proposed_name)) < 2 then raise exception 'invalid_plan_terms'; end if;
  select * into old_plan from public.subscription_plans where id=target_plan_id for update;
  if old_plan.id is null then raise exception 'plan_not_found'; end if;
  perform pg_advisory_xact_lock(hashtext(coalesce(old_plan.code,old_plan.id::text)));
  select coalesce(max(version),0)+1 into next_version from public.subscription_plans
    where code=coalesce(old_plan.code,old_plan.id::text);
  update public.subscription_plans set active=false,active_status='inactive',is_default=false,
    public_purchase_enabled=false,effective_until=current_date,updated_by=auth.uid(),updated_at=now()
    where id=old_plan.id;
  if make_default or old_plan.is_default then update public.subscription_plans set is_default=false,updated_at=now() where is_default; end if;
  insert into public.subscription_plans(name,description,plan_type,price_amount,monthly_price,annual_price,currency,
    duration_days,trial_days,enabled_features,features,limits,active,active_status,plan_category,
    billing_cycle_options,public_purchase_enabled,enterprise_contact_required,sort_order,
    code,version,effective_from,is_default,billing_interval,commitment_months,grace_days,created_by,updated_by)
  values(trim(proposed_name),old_plan.description,old_plan.plan_type,proposed_price,
    case when proposed_billing_interval='monthly' then proposed_price else null end,
    case when proposed_billing_interval='monthly' then proposed_price*12 else proposed_price end,
    upper(proposed_currency),old_plan.duration_days,old_plan.trial_days,
    old_plan.enabled_features,old_plan.features,old_plan.limits,true,'active',old_plan.plan_category,
    array[proposed_billing_interval]::text[],true,old_plan.enterprise_contact_required,old_plan.sort_order,
    coalesce(old_plan.code,old_plan.id::text),next_version,current_date,(make_default or old_plan.is_default),proposed_billing_interval,
    coalesce(old_plan.commitment_months,12),proposed_grace_days,auth.uid(),auth.uid())
  returning * into new_plan;
  return jsonb_build_object('id',new_plan.id,'code',new_plan.code,'version',new_plan.version,
    'unit_price',new_plan.price_amount,'currency',new_plan.currency,'is_default',new_plan.is_default);
end $$;

CREATE FUNCTION public.apply_manual_tuition_entry(target_period_id uuid, requested_kind text, requested_amount numeric, requested_method text, requested_reference text, requested_reason text, requested_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p public.tuition_billing_periods; existing public.tuition_ledger_entries; applied numeric(12,2); excess numeric(12,2); due numeric(12,2);
begin
  select * into p from public.tuition_billing_periods where id=target_period_id for update;
  if p.id is null or public.can_manage_garden(p.garden_id) is distinct from true then raise exception 'tuition_period_denied' using errcode='42501'; end if;
  if requested_key is null or length(requested_key)<8 then raise exception 'tuition_idempotency_key_required' using errcode='23514'; end if;
  select * into existing from public.tuition_ledger_entries where garden_id=p.garden_id and source_key=requested_key;
  if existing.id is not null then
    if existing.period_id<>p.id or existing.entry_kind<>requested_kind or existing.amount<>requested_amount then raise exception 'tuition_idempotency_conflict' using errcode='23505'; end if;
    return public.tuition_period_projection(p);
  end if;
  if p.status='cancelled' then raise exception 'tuition_period_cancelled' using errcode='23514'; end if;
  if requested_kind not in ('manual_settlement','adjustment') or requested_amount=0 then raise exception 'tuition_entry_invalid' using errcode='23514'; end if;
  if requested_kind='adjustment' then
    if requested_reason is null or length(trim(requested_reason))<3 or p.base_amount+p.adjustment_total+requested_amount<p.settled_total then raise exception 'tuition_adjustment_requires_credit_review' using errcode='23514'; end if;
    insert into public.tuition_ledger_entries(garden_id,period_id,entry_kind,amount,source_key,reason,actor_id)
    values(p.garden_id,p.id,'adjustment',requested_amount,requested_key,requested_reason,auth.uid());
    update public.tuition_billing_periods set adjustment_total=adjustment_total+requested_amount,updated_at=now() where id=p.id returning * into p;
  else
    if requested_amount<0 or requested_method not in ('bank_transfer','standing_order','checks','cash','external_other') then raise exception 'tuition_manual_method_invalid' using errcode='23514'; end if;
    due:=greatest(0,p.base_amount+p.adjustment_total-p.settled_total);
    applied:=least(requested_amount,due); excess:=requested_amount-applied;
    insert into public.tuition_ledger_entries(garden_id,period_id,entry_kind,amount,method,evidence_reference,source_key,reason,actor_id)
    values(p.garden_id,p.id,'manual_settlement',requested_amount,requested_method,requested_reference,requested_key,requested_reason,auth.uid());
    if excess>0 then
      insert into public.tuition_ledger_entries(garden_id,period_id,entry_kind,amount,method,evidence_reference,source_key,reason,actor_id)
      values(p.garden_id,p.id,'unapplied_credit',excess,requested_method,requested_reference,requested_key||':excess','overpayment_unapplied',auth.uid());
    end if;
    update public.tuition_billing_periods set settled_total=settled_total+applied,unapplied_credit_total=unapplied_credit_total+excess,updated_at=now() where id=p.id returning * into p;
  end if;
  update public.tuition_billing_periods set status=case when unapplied_credit_total>0 then 'reconciliation_required'
    when base_amount+adjustment_total=0 then 'waived'
    when settled_total>=base_amount+adjustment_total then 'paid'
    when p.status='reconciliation_required' then 'reconciliation_required'
    when settled_total>0 then 'partially_paid' else 'pending' end,
    reconciliation_reason=case when unapplied_credit_total>0 then 'unapplied_credit_pending_allocation'
      when settled_total>=base_amount+adjustment_total then null else reconciliation_reason end,
    updated_at=now() where id=p.id returning * into p;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(auth.uid(),public.current_role()::text,p.garden_id,'tuition_billing_periods',p.id,'tuition_ledger_entry_recorded',
    jsonb_build_object('kind',requested_kind,'amount',requested_amount,'source_key',requested_key,'excess',coalesce(excess,0)));
  return public.tuition_period_projection(p);
end $$;

CREATE FUNCTION public.apply_stream_health_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  new_status public.camera_status;
  severity public.severity_level;
  event_type text;
begin
  if new.offline then
    new_status := 'offline';
    severity := 'high';
    event_type := 'camera_disconnected';
  elsif new.covered then
    new_status := 'covered';
    severity := 'high';
    event_type := 'camera_covered';
  elsif new.frozen then
    new_status := 'frozen';
    severity := 'medium';
    event_type := 'camera_frozen';
  elsif new.black_screen then
    new_status := 'black_frame';
    severity := 'medium';
    event_type := 'camera_black_screen';
  else
    new_status := 'online';
    severity := null;
    event_type := null;
  end if;

  update public.camera_streams
  set status = new_status, last_health_check_at = new.checked_at, updated_at = now()
  where id = new.camera_stream_id;

  if event_type is not null then
    insert into public.ai_events (garden_id, camera_stream_id, event_type, severity, confidence, metadata, notes)
    values (
      new.garden_id,
      new.camera_stream_id,
      event_type,
      severity,
      1,
      jsonb_build_object('health_check_id', new.id, 'latency_ms', new.latency_ms, 'frame_loss_percent', new.frame_loss_percent),
      'Stream health check detected ' || event_type
    );
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.approve_observer_managed_device_enrollment(p_enrollment uuid, p_site uuid, p_gateway uuid, p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare request public.video_gateway_device_enrollments%rowtype;
declare organization uuid;
declare public_key text;
declare profile text;
begin
  select * into request from public.video_gateway_device_enrollments where id = p_enrollment for update;
  if not found or request.status <> 'pending' or request.expires_at <= now() then
    raise exception 'MANAGED_DEVICE_ENROLLMENT_UNAVAILABLE';
  end if;
  select coalesce(digital_observer_organization_id, id) into organization from public.observer_sites where id = p_site;
  if not found then raise exception 'MANAGED_DEVICE_SITE_UNAVAILABLE'; end if;
  public_key := request.metadata->>'credential_public_key_spki';
  profile := request.metadata->>'device_type';
  if length(public_key) not between 40 and 256 or public_key !~ '^[A-Za-z0-9_-]+$' or request.metadata->>'credential_algorithm' <> 'Ed25519'
    or profile not in ('SOFTWARE_CONNECTOR','PHYSICAL_GATEWAY','ENTERPRISE_EDGE') then
    raise exception 'MANAGED_DEVICE_KEY_OR_PROFILE_INVALID';
  end if;
  insert into public.observer_managed_device_credentials(id,enrollment_id,credential_version,algorithm,public_key_spki,credential_state,activated_at)
    values(gen_random_uuid(),request.id,1,'Ed25519',public_key,'ACTIVE',now());
  update public.video_gateway_device_enrollments set status = 'approved', observer_site_id = p_site,
    gateway_id = p_gateway, created_by_profile_id = p_actor, approved_at = now(),
    identity_scheme = 'ED25519_V1', deployment_profile = profile, tenant_id = organization,
    credential_version = 1, lifecycle_state = 'ACTIVE', hardened_at = now(), refresh_token_hash = null,
    runtime_version = nullif(request.metadata->>'software_version',''), config_version = 1,
    metadata = request.metadata - 'credential_public_key_spki' where id = request.id;
  return true;
end $_$;

CREATE FUNCTION public.assign_bootstrap_inspector_on_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.bootstrap_inspector_id is null or new.bootstrap_cancelled_at is not null or new.status::text<>'active'
    or new.onboarding_status<>'active' or (old.status::text='active' and old.onboarding_status='active') then return new; end if;
  if new.inspector_id is not null then
    update public.gardens set bootstrap_assignment_status='assigned' where id=new.id;
  elsif public.is_approved_inspector(new.bootstrap_inspector_id) then
    update public.gardens set inspector_id=new.bootstrap_inspector_id,bootstrap_assignment_status='assigned' where id=new.id;
    insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action)
    values(new.bootstrap_inspector_id,'inspector',new.id,'gardens',new.id,'bootstrap_inspector_assigned');
  else
    update public.gardens set bootstrap_assignment_status='admin_reassignment_required' where id=new.id;
    insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action)
    values(new.manager_id,'manager',new.id,'gardens',new.id,'bootstrap_inspector_reassignment_required');
  end if;
  return new;
end $$;

CREATE TABLE public.child_classroom_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid NOT NULL,
    child_id uuid NOT NULL,
    enrollment_id uuid,
    classroom_id uuid NOT NULL,
    is_current boolean DEFAULT true NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    assigned_by uuid,
    end_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT child_classroom_period_check CHECK (((is_current AND (ended_at IS NULL)) OR (NOT is_current)))
);

COMMENT ON TABLE public.child_classroom_assignments IS 'Time-preserving child Classroom assignment history within a Garden enrollment.';

CREATE FUNCTION public.assign_child_to_classroom(target_child_id uuid, target_classroom_id uuid, target_enrollment_id uuid DEFAULT NULL::uuid) RETURNS public.child_classroom_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare room public.classrooms; child_garden uuid; result public.child_classroom_assignments; capacity jsonb; own_reservation integer;
begin
  select * into room from public.classrooms where id=target_classroom_id and status='active' for update;
  select garden_id into child_garden from public.children where id=target_child_id;
  if room.id is null or child_garden is distinct from room.garden_id then raise exception 'cross_garden_classroom_assignment' using errcode='42501'; end if;
  if not public.can_manage_garden(room.garden_id) then raise exception 'classroom_assignment_denied' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(target_child_id::text,0));
  select * into result from public.child_classroom_assignments where child_id=target_child_id and garden_id=room.garden_id and classroom_id=room.id and is_current limit 1;
  if result.id is not null then return result; end if;
  perform public.expire_classroom_reservations(room.id);
  capacity:=public.classroom_capacity_status(room.id);
  select count(*)::integer into own_reservation from public.classroom_seat_reservations where classroom_id=room.id and child_id=target_child_id and status='active' and (expires_at is null or expires_at>now());
  if room.capacity_limit is not null and (capacity->>'available')::integer+least(own_reservation,1)<=0 then raise exception 'classroom_capacity_unavailable' using errcode='P0001'; end if;
  update public.child_classroom_assignments set is_current=false,ended_at=now(),end_reason='moved' where child_id=target_child_id and garden_id=room.garden_id and is_current;
  insert into public.child_classroom_assignments(garden_id,child_id,enrollment_id,classroom_id,assigned_by) values(room.garden_id,target_child_id,target_enrollment_id,room.id,auth.uid()) returning * into result;
  update public.classroom_seat_reservations set status='consumed',consumed_at=now(),updated_at=now() where classroom_id=room.id and child_id=target_child_id and status='active';
  return result;
end $$;

CREATE TABLE public.staff_classroom_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid NOT NULL,
    staff_id uuid NOT NULL,
    employment_id uuid,
    classroom_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    responsibility text DEFAULT 'staff'::text NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    assigned_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_classroom_responsibility_check CHECK ((responsibility = ANY (ARRAY['staff'::text, 'lead_teacher'::text, 'assistant'::text, 'support'::text]))),
    CONSTRAINT staff_classroom_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'revoked'::text])))
);

COMMENT ON TABLE public.staff_classroom_assignments IS 'Operational Classroom scope; employment authorization remains separate.';

CREATE FUNCTION public.assign_staff_to_classroom(target_staff_id uuid, target_classroom_id uuid, target_employment_id uuid DEFAULT NULL::uuid, target_responsibility text DEFAULT 'staff'::text) RETURNS public.staff_classroom_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare room public.classrooms; staff_row public.staff; employment uuid; result public.staff_classroom_assignments;
begin
  select * into room from public.classrooms where id=target_classroom_id and status='active';
  select * into staff_row from public.staff where id=target_staff_id;
  if room.id is null or staff_row.id is null or staff_row.garden_id is distinct from room.garden_id then raise exception 'cross_garden_classroom_assignment' using errcode='42501'; end if;
  if not public.can_manage_garden(room.garden_id) then raise exception 'classroom_assignment_denied' using errcode='42501'; end if;
  select id into employment from public.staff_kindergarten_employments where id=target_employment_id and staff_id=target_staff_id and garden_id=room.garden_id and status='active';
  if target_employment_id is not null and employment is null then raise exception 'active_employment_required' using errcode='23514'; end if;
  if not coalesce(staff_row.approved_to_work,false) then raise exception 'active_staff_required' using errcode='23514'; end if;
  insert into public.staff_classroom_assignments(garden_id,staff_id,employment_id,classroom_id,responsibility,assigned_by,status,ended_at)
  values(room.garden_id,target_staff_id,target_employment_id,room.id,target_responsibility,auth.uid(),'active',null)
  on conflict(staff_id,classroom_id) do update set employment_id=excluded.employment_id,responsibility=excluded.responsibility,status='active',ended_at=null,assigned_by=auth.uid(),updated_at=now()
  returning * into result;
  return result;
end $$;

