CREATE FUNCTION public.camera_physical_payload_valid(action_name text, value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  item text;
  allowed text[];
begin
  if jsonb_typeof(value) <> 'object' then return false; end if;
  if action_name = 'lighting' then
    allowed := array['enabled','level','duration_ms'];
    if jsonb_typeof(value -> 'enabled') <> 'boolean' then return false; end if;
    if value ? 'level' and (jsonb_typeof(value -> 'level') <> 'number' or (value ->> 'level')::integer not between 0 and 100) then return false; end if;
    if value ? 'duration_ms' and (value ->> 'enabled')::boolean is not true then return false; end if;
    if value ? 'duration_ms' and (jsonb_typeof(value -> 'duration_ms') <> 'number'
      or (value ->> 'duration_ms')::integer not between 1000 and 30000) then return false; end if;
  elsif action_name = 'siren' then
    allowed := array['enabled','duration_ms','volume'];
    if jsonb_typeof(value -> 'enabled') <> 'boolean' or jsonb_typeof(value -> 'duration_ms') <> 'number'
      or (value ->> 'duration_ms')::integer not between 250 and 5000 then return false; end if;
    if value ? 'volume' and (jsonb_typeof(value -> 'volume') <> 'number' or (value ->> 'volume')::integer not between 0 and 100) then return false; end if;
  elsif action_name = 'ptz' then
    allowed := array['command','duration_ms','speed'];
    if value ->> 'command' not in ('Ptz_Cmd_Up','Ptz_Cmd_Down','Ptz_Cmd_Left','Ptz_Cmd_Right',
      'Ptz_Cmd_UpLeft','Ptz_Cmd_UpRight','Ptz_Cmd_DownLeft','Ptz_Cmd_DownRight',
      'Ptz_Cmd_ZoomMinus','Ptz_Cmd_ZoomAdd','Ptz_Cmd_FocusMinus','Ptz_Cmd_FocusAdd')
      or jsonb_typeof(value -> 'duration_ms') <> 'number' or (value ->> 'duration_ms')::integer not between 50 and 500
      or jsonb_typeof(value -> 'speed') <> 'number' or (value ->> 'speed')::integer not between 0 and 100 then return false; end if;
  else return false;
  end if;
  for item in select jsonb_object_keys(value) loop
    if not item = any(allowed) then return false; end if;
  end loop;
  return true;
exception when others then return false;
end;
$$;

CREATE FUNCTION public.can_access_child_record(target_child_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_child_id is not null
    and exists (
      select 1
      from public.children c
      where c.id = target_child_id
        and (
          public.can_access_garden(c.garden_id)
          or public.can_parent_access_child(c.id)
        )
    )
$$;

CREATE FUNCTION public.can_access_document(target_document_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_document_id is not null
    and exists (
      select 1
      from public.documents d
      left join public.staff s on s.id = d.staff_id
      where d.id = target_document_id
        and (
          public.is_admin()
          or d.uploaded_by = auth.uid()
          or (d.child_id is not null and public.can_access_child_record(d.child_id))
          or (d.staff_id is not null and s.profile_id = auth.uid())
          or (d.garden_id is not null and public.can_manage_garden(d.garden_id))
        )
    )
$$;

COMMENT ON FUNCTION public.can_access_document(target_document_id uuid) IS 'Document access helper; checks uploader, child ownership, staff self-document, manager/admin garden access.';

CREATE FUNCTION public.can_access_garden(target_garden_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_garden_id is not null and (
    public.can_manage_garden(target_garden_id)
    or public.can_staff_access_garden(target_garden_id)
    or public.can_inspector_access_garden(target_garden_id)
  )
$$;

COMMENT ON FUNCTION public.can_access_garden(target_garden_id uuid) IS 'Operational garden access only. Does not grant parent whole-kindergarten access.';

CREATE FUNCTION public.can_access_network(target_network_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    public.is_admin()
    or exists (
      select 1
      from public.network_manager_assignments nma
      where nma.network_id = target_network_id
        and nma.profile_id = auth.uid()
        and nma.active = true
        and (nma.ends_at is null or nma.ends_at > now())
    )
$$;

CREATE FUNCTION public.can_access_observer_site(target_site_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  select target_site_id is not null and (
    public.is_admin()
    or exists (
      select 1
      from public.observer_sites s
      where s.id = target_site_id
        and (
          s.owner_profile_id = auth.uid()
          or (s.garden_id is not null and public.can_access_garden(s.garden_id))
        )
    )
    or exists (
      select 1
      from public.observer_site_memberships m
      where m.observer_site_id = target_site_id
        and m.profile_id = auth.uid()
        and m.active = true
    )
  )
$$;

CREATE FUNCTION public.can_access_payment_record(target_payment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_payment_id is not null
    and exists (
      select 1
      from public.subscription_payments p
      where p.id = target_payment_id
        and (
          public.is_admin()
          or public.can_manage_garden(p.garden_id)
        )
    )
$$;

CREATE FUNCTION public.can_access_sensitive_child_data(target_child_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.can_access_child_record(target_child_id)
$$;

COMMENT ON FUNCTION public.can_access_sensitive_child_data(target_child_id uuid) IS 'Sensitive child data helper; parent access is child-specific, operational roles remain garden-scoped.';

CREATE FUNCTION public.can_edit_garden_onboarding(target_garden_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select auth.uid() is not null and (
    public.is_admin() or public.can_manage_garden(target_garden_id) or exists (
      select 1 from public.kindergarten_onboarding_records onboarding
      join public.garden_management_memberships membership
        on membership.garden_id=onboarding.garden_id and membership.profile_id=onboarding.manager_id
      join public.profiles profile on profile.id=onboarding.manager_id
      where onboarding.garden_id=target_garden_id and onboarding.manager_id=auth.uid()
        and onboarding.lifecycle_status in ('registration_pending','credentials_sent','activation_in_progress','onboarding_in_progress','correction_required')
        and membership.profile_id=auth.uid() and membership.status='pending'
        and membership.relationship_role in ('owner','manager')
    )
  )
$$;

CREATE FUNCTION public.can_guardian_access_child(target_child_file_id uuid, required_scope text DEFAULT 'profile'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_child_file_id is not null and exists (
    select 1 from public.child_guardian_links link
    join public.profiles profile on profile.id = link.guardian_profile_id
    where link.permanent_child_file_id = target_child_file_id
      and link.guardian_profile_id = auth.uid()
      and profile.role = 'parent'
      and link.status = 'active'
      and link.legal_authority = true
      and (link.valid_until is null or link.valid_until > now())
      and coalesce(link.access_scope ->> required_scope, 'false') = 'true'
  );
$$;

CREATE FUNCTION public.can_inspector_access_garden(target_garden_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_garden_id is not null and (
    public.is_admin() or (
      public.is_approved_inspector(auth.uid())
      and exists (select 1 from public.gardens g where g.id=target_garden_id and g.inspector_id=auth.uid())
    )
  );
$$;

CREATE FUNCTION public.can_label_digital_observer_site(target_site_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  select auth.uid() is not null and target_site_id is not null and (
    public.is_admin()
    or coalesce((auth.jwt()->'app_metadata'->>'digital_observer_admin')::boolean, false)
    or exists (
      select 1 from public.observer_sites site
      where site.id = target_site_id and site.owner_profile_id = auth.uid()
    )
    or exists (
      select 1 from public.observer_site_memberships membership
      where membership.observer_site_id = target_site_id
        and membership.profile_id = auth.uid()
        and membership.active = true
        and membership.member_role in ('owner','admin','operator','reviewer')
    )
  )
$$;

CREATE FUNCTION public.can_manage_garden(target_garden_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_garden_id is not null and (
    public.is_admin()
    or exists (
      select 1
      from public.garden_management_memberships membership
      join public.profiles profile on profile.id = membership.profile_id
      join public.gardens garden on garden.id = membership.garden_id
      where membership.profile_id = auth.uid()
        and membership.garden_id = target_garden_id
        and membership.status = 'active'
        and membership.relationship_role in ('owner', 'manager')
        and profile.active is true
        and profile.role::text in ('owner', 'manager')
        and coalesce(garden.status::text, 'active') not in ('inactive', 'suspended', 'closed', 'rejected')
    )
    or exists (
      select 1 from public.profiles profile
      join public.gardens garden on garden.id = target_garden_id
      join public.network_manager_assignments assignment
        on assignment.network_id = garden.network_id and assignment.profile_id = profile.id
      where profile.id = auth.uid() and profile.active is true and profile.role::text = 'network_manager'
        and assignment.active is true and (assignment.ends_at is null or assignment.ends_at > now())
    )
  )
$$;

CREATE FUNCTION public.can_manage_observer_site(target_site_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  select target_site_id is not null and (
    public.is_admin()
    or exists (
      select 1
      from public.observer_sites s
      where s.id = target_site_id
        and s.owner_profile_id = auth.uid()
    )
    or exists (
      select 1
      from public.observer_site_memberships m
      where m.observer_site_id = target_site_id
        and m.profile_id = auth.uid()
        and m.active = true
        and m.member_role in ('owner', 'admin')
    )
  )
$$;

CREATE FUNCTION public.can_parent_access_child(target_child_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_child_id is not null
    and exists (
      select 1
      from public.children c
      left join public.parents p on p.id = c.primary_parent_id
      left join public.permanent_child_files f on f.id = c.permanent_child_file_id
      where c.id = target_child_id
        and (
          p.profile_id = auth.uid()
          or p.user_id = auth.uid()
          or f.primary_parent_profile_id = auth.uid()
        )
    )
$$;

COMMENT ON FUNCTION public.can_parent_access_child(target_child_id uuid) IS 'Parent child-specific access helper. Use for parent access to child-scoped sensitive records.';

CREATE FUNCTION public.can_parent_access_child_file(target_child_file_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_child_file_id is not null
    and exists (
      select 1
      from public.permanent_child_files f
      where f.id = target_child_file_id
        and f.primary_parent_profile_id = auth.uid()
    )
$$;

CREATE FUNCTION public.can_parent_access_enrollment_request(target_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_request_id is not null
    and exists (
      select 1
      from public.kindergarten_enrollment_requests r
      left join public.permanent_child_files f on f.id = r.child_profile_id
      where r.id = target_request_id
        and (
          r.parent_id = auth.uid()
          or f.primary_parent_profile_id = auth.uid()
        )
    )
$$;

CREATE FUNCTION public.can_parent_access_garden(target_garden_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_garden_id is not null and exists (
    select 1 from public.profiles profile
    where profile.id = auth.uid()
      and profile.active = true
      and profile.role = 'parent'
      and (
        exists (
          select 1 from public.parent_kindergarten_links link
          where link.parent_profile_id = profile.id
            and link.garden_id = target_garden_id
            and link.status in ('pending', 'active')
        )
        or exists (
          select 1 from public.child_guardian_links guardian
          join public.child_kindergarten_enrollments enrollment
            on enrollment.permanent_child_file_id = guardian.permanent_child_file_id
          where guardian.guardian_profile_id = profile.id
            and guardian.status = 'active'
            and guardian.legal_authority = true
            and (guardian.valid_until is null or guardian.valid_until > now())
            and enrollment.garden_id = target_garden_id
            and enrollment.status in ('pending_parent_completion','pending_manager_approval','active')
        )
      )
  );
$$;

CREATE FUNCTION public.can_parent_view_camera(p_parent_id uuid, p_camera_stream_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.parent_camera_permissions pcp
    join public.camera_streams cs on cs.id = pcp.camera_stream_id
    where pcp.parent_id = p_parent_id
      and pcp.camera_stream_id = p_camera_stream_id
      and pcp.allowed = true
      and cs.active = true
      and cs.parent_view_allowed = true
      and (pcp.valid_until is null or pcp.valid_until > now())
  )
$$;

CREATE FUNCTION public.can_report_complaint(p_garden_id uuid, p_child_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select auth.uid() is not null and exists(select 1 from public.gardens g where g.id=p_garden_id and g.status='active')
    and case when p_child_id is not null then
      (public.can_parent_access_child(p_child_id) or exists(
        select 1 from public.children c where c.id=p_child_id
          and public.can_guardian_access_child(c.permanent_child_file_id,'profile')))
      and exists(
        select 1 from public.child_kindergarten_enrollments e
        where e.child_id=p_child_id and e.garden_id=p_garden_id and e.status='active'
      )
    else exists(
      select 1 from public.parent_kindergarten_links l
      where l.garden_id=p_garden_id and l.status='active'
        and (l.parent_profile_id=auth.uid() or exists(select 1 from public.parents p where p.id=l.parent_id
          and (p.profile_id=auth.uid() or p.user_id=auth.uid())))
    ) or exists(
      select 1 from public.child_kindergarten_enrollments e
      join public.children c on c.id=e.child_id
      where e.garden_id=p_garden_id and e.status='active' and public.can_parent_access_child(c.id)
    ) end;
$$;

CREATE FUNCTION public.can_review_digital_observer_site(target_site_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  select auth.uid() is not null and target_site_id is not null and (
    public.is_admin()
    or coalesce((auth.jwt()->'app_metadata'->>'digital_observer_admin')::boolean, false)
    or exists (
      select 1 from public.observer_site_memberships membership
      where membership.observer_site_id = target_site_id
        and membership.profile_id = auth.uid()
        and membership.active = true
        and membership.member_role in ('admin','reviewer')
    )
  )
$$;

CREATE FUNCTION public.can_staff_access_garden(target_garden_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select target_garden_id is not null and (
    public.can_manage_garden(target_garden_id)
    or exists (
      select 1 from public.staff_kindergarten_employments e
      join public.staff s on s.id = e.staff_id and s.profile_id = e.profile_id and s.garden_id = e.garden_id
      join public.profiles p on p.id = e.profile_id
      join public.gardens g on g.id = e.garden_id
      where e.profile_id = auth.uid() and e.garden_id = target_garden_id
        and p.active and p.role::text = 'staff' and e.status = 'active'
        and (e.start_date is null or e.start_date <= current_date)
        and (e.end_date is null or e.end_date >= current_date)
        and s.approved_to_work and s.onboarding_status = 'active'
        and g.status::text = 'active'
    )
  )
$$;

CREATE FUNCTION public.can_teach_in_garden(target_garden_id uuid, required_scope text DEFAULT 'children'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select auth.uid() is not null and required_scope in ('children','attendance','journal','communication')
    and exists (
      select 1 from public.garden_teaching_assignments a
      join public.profiles p on p.id=a.profile_id and p.active
      join public.gardens g on g.id=a.garden_id and g.status::text='active'
      left join public.staff s on s.id=a.staff_id and s.profile_id=a.profile_id and s.garden_id=a.garden_id
      where a.profile_id=auth.uid() and a.garden_id=target_garden_id and a.status='active'
        and coalesce((a.access_scope ->> required_scope)::boolean,false)
        and ((a.assignment_kind='owner_teacher' and p.role::text='owner'
              and g.owner_profile_id=p.id and g.ownership_type='teacher_is_owner')
          or (a.assignment_kind='delegated_teacher' and p.role::text='staff'
              and s.approved_to_work and s.onboarding_status='active'
              and exists(select 1 from public.staff_kindergarten_employments e
                where e.staff_id=s.id and e.profile_id=p.id and e.garden_id=a.garden_id
                  and e.status='active' and (e.start_date is null or e.start_date<=current_date)
                  and (e.end_date is null or e.end_date>=current_date))))
    )
$$;

COMMENT ON FUNCTION public.can_teach_in_garden(target_garden_id uuid, required_scope text) IS 'Checks a narrow teaching capability independently of can_manage_garden.';

CREATE FUNCTION public.can_view_management_task(p_garden_id uuid, p_assigned_to uuid, p_assigned_role text, p_source_type text, p_source_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select auth.uid() is not null and
    (case when p_garden_id is null then public.is_admin()
      else public.is_admin() or public.can_manage_garden(p_garden_id)
        or (public.can_staff_access_garden(p_garden_id) and
            (p_assigned_to=auth.uid() or (p_assigned_to is null and p_assigned_role='staff')))
        or (public.can_inspector_access_garden(p_garden_id) and
            (p_assigned_to=auth.uid() or (p_assigned_to is null and p_assigned_role='inspector')))
      end)
    and (p_source_type not in ('corrective_action','complaint','incident') or p_source_id is null
      or public.is_admin() or public.can_manage_garden(p_garden_id)
      or public.can_inspector_access_garden(p_garden_id))
    and (p_source_type is distinct from 'complaint' or p_source_id is null or public.is_admin()
      or public.can_inspector_access_garden(p_garden_id)
      or exists(select 1 from public.complaints c where c.id=p_source_id and c.garden_id=p_garden_id
        and c.visibility='garden' and public.can_manage_garden(p_garden_id)));
$$;

CREATE FUNCTION public.cancel_inspector_preliminary_garden(p_garden_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor_id uuid:=auth.uid(); garden public.gardens%rowtype; onboarding public.kindergarten_onboarding_records%rowtype;
begin
  if actor_id is null or not public.is_approved_inspector(actor_id) then raise exception 'approved_inspector_required' using errcode='42501'; end if;
  select * into garden from public.gardens where id=p_garden_id for update;
  if garden.id is null or garden.bootstrap_inspector_id<>actor_id then raise exception 'preliminary_garden_not_found' using errcode='42501'; end if;
  if garden.bootstrap_cancelled_at is not null then return jsonb_build_object('status','cancelled','already_cancelled',true); end if;
  select * into onboarding from public.kindergarten_onboarding_records where garden_id=p_garden_id for update;
  if garden.status::text<>'pending' or onboarding.manager_id is not null then raise exception 'recipient_onboarding_started' using errcode='23514'; end if;
  update public.gardens set bootstrap_cancelled_at=now(),updated_at=now() where id=p_garden_id;
  update public.management_invitations set status='revoked',revoked_at=now(),updated_at=now()
    where garden_id=p_garden_id and invitation_type='garden_management' and status in ('pending','delivered');
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action)
    values(actor_id,'inspector',p_garden_id,'gardens',p_garden_id,'inspector_preliminary_garden_cancelled');
  return jsonb_build_object('status','cancelled','already_cancelled',false);
end $$;

CREATE FUNCTION public.cancel_parent_enrollment_request(target_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare req public.kindergarten_enrollment_requests;
begin
  select * into req from public.kindergarten_enrollment_requests where id=target_request_id for update;
  if req.id is null or req.parent_id<>auth.uid() or not public.can_guardian_access_child(req.child_profile_id,'profile') then raise exception 'enrollment_request_denied' using errcode='42501'; end if;
  if req.status not in ('draft','submitted','under_review','information_required','resubmitted','approved','awaiting_payment','waitlisted') then raise exception 'invalid_enrollment_transition' using errcode='23514'; end if;
  if req.reservation_id is not null then
    update public.classroom_seat_reservations set status='released',released_at=now(),updated_at=now()
    where id=req.reservation_id and enrollment_request_id=req.id and status='active';
  end if;
  update public.kindergarten_enrollment_requests set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),updated_at=now() where id=req.id returning * into req;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data) values(auth.uid(),'parent',req.garden_id,'kindergarten_enrollment_requests',req.id,'enrollment_request_cancelled',jsonb_build_object('status','cancelled'));
  return jsonb_build_object('request',to_jsonb(req));
end $$;

CREATE FUNCTION public.check_tuition_entry_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists(select 1 from public.tuition_billing_periods p where p.id=new.period_id and p.garden_id=new.garden_id) then
    raise exception 'tuition_entry_scope_mismatch' using errcode='23514';
  end if;
  return new;
end $$;

CREATE FUNCTION public.check_tuition_period_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists(select 1 from public.child_kindergarten_enrollments e where e.id=new.enrollment_id
    and e.garden_id=new.garden_id and e.child_id=new.child_id) then
    raise exception 'tuition_period_scope_mismatch' using errcode='23514';
  end if;
  return new;
end $$;

CREATE FUNCTION public.claim_digital_observer_profile(requested_name text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return public.ensure_digital_observer_account(requested_name, 'home');
end;
$$;

CREATE FUNCTION public.claim_observer_connector_install_intent(p_id uuid, p_secret_hash text, p_site uuid, p_enrollment uuid, p_poll_hash text, p_installation text, p_platform text, p_version text, p_build text, p_credential_algorithm text, p_credential_public_key_spki text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
declare intent public.observer_connector_install_intents%rowtype;
begin
  if p_installation !~ '^edge-[a-f0-9]{32}$' or p_poll_hash !~ '^[a-f0-9]{64}$'
    or p_platform not in ('macos-arm64','macos-x64','windows-x64')
    or length(p_version) not between 1 and 80 or length(p_build) not between 1 and 80
    or p_credential_algorithm <> 'Ed25519'
    or length(p_credential_public_key_spki) not between 40 and 256
    or p_credential_public_key_spki !~ '^[A-Za-z0-9_-]+$' then
    raise exception 'INSTALL_INPUT_INVALID';
  end if;
  select * into intent from public.observer_connector_install_intents where id = p_id for update;
  if not found or intent.state <> 'ISSUED' or intent.expires_at <= now()
    or intent.secret_hash is distinct from p_secret_hash or intent.observer_site_id is distinct from p_site then
    raise exception 'INSTALL_INTENT_UNAVAILABLE';
  end if;
  if not exists (select 1 from public.observer_sites s where s.id = intent.observer_site_id and s.owner_profile_id = intent.actor_profile_id)
    and not exists (select 1 from public.observer_site_memberships m where m.observer_site_id = intent.observer_site_id
      and m.profile_id = intent.actor_profile_id and m.active and m.member_role in ('owner','admin')) then
    raise exception 'INSTALL_AUTHORIZATION_REVOKED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_installation, 0));
  if exists (select 1 from public.video_gateway_device_enrollments e where e.metadata->>'installation_id' = p_installation
    and e.status in ('pending','approved','delivered') and (e.status <> 'pending' or e.expires_at > now())) then
    raise exception 'INSTALLATION_ALREADY_ENROLLED';
  end if;
  insert into public.video_gateway_device_enrollments(id, status, device_name, device_platform,
    poll_token_hash, observer_site_id, created_by_profile_id, expires_at, metadata)
  values(p_enrollment, 'pending', 'Digital Observer', p_platform, p_poll_hash, intent.observer_site_id,
    intent.actor_profile_id, intent.expires_at, jsonb_build_object('protocol_version',3,
    'device_type','SOFTWARE_CONNECTOR','installation_id',p_installation,'install_intent_id',intent.id,
    'software_version',p_version,'build_sha',p_build,'connector_config_version',1,
    'credential_algorithm',p_credential_algorithm,'credential_public_key_spki',p_credential_public_key_spki,
    'outbound_only',true,'arbitrary_shell_commands',false));
  update public.observer_connector_install_intents set state = 'CLAIMED', enrollment_id = p_enrollment,
    secret_hash = repeat('0',64) where id = intent.id;
  return p_enrollment;
end $_$;

CREATE TABLE public.observer_edge_fleet_commands (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    tenant_id uuid NOT NULL,
    observer_site_id uuid NOT NULL,
    enrollment_id uuid NOT NULL,
    command text NOT NULL,
    state text DEFAULT 'REQUESTED'::text NOT NULL,
    safe_parameters jsonb DEFAULT '{}'::jsonb NOT NULL,
    requested_by uuid NOT NULL,
    support_access_id uuid,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    delivered_at timestamp with time zone,
    acknowledged_at timestamp with time zone,
    completed_at timestamp with time zone,
    result_category text,
    CONSTRAINT observer_edge_fleet_command_ttl CHECK (((expires_at > requested_at) AND (expires_at <= (requested_at + '00:30:00'::interval)))),
    CONSTRAINT observer_edge_fleet_commands_command_check CHECK ((command = ANY (ARRAY['REFRESH_CONFIGURATION'::text, 'HEALTH_PROBE'::text, 'REDISCOVER_CAMERAS'::text, 'RECONNECT_CAMERAS'::text, 'RESTART_SERVICE'::text, 'ASSIGN_UPDATE_CHANNEL'::text, 'INITIATE_APPROVED_UPDATE'::text, 'PAUSE_ROLLOUT'::text]))),
    CONSTRAINT observer_edge_fleet_commands_idempotency_key_check CHECK (((length(idempotency_key) >= 16) AND (length(idempotency_key) <= 160))),
    CONSTRAINT observer_edge_fleet_commands_state_check CHECK ((state = ANY (ARRAY['REQUESTED'::text, 'TARGETED'::text, 'DELIVERED'::text, 'ACKNOWLEDGED'::text, 'COMPLETED'::text, 'FAILED'::text, 'EXPIRED'::text])))
);

CREATE FUNCTION public.claim_observer_edge_fleet_commands(p_enrollment uuid, p_limit integer DEFAULT 20) RETURNS SETOF public.observer_edge_fleet_commands
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.observer_edge_fleet_commands set state='EXPIRED', result_category='COMMAND_TTL_EXPIRED'
    where enrollment_id=p_enrollment and state in ('REQUESTED','TARGETED') and expires_at <= now();
  return query
    update public.observer_edge_fleet_commands c set state='DELIVERED', delivered_at=now()
    where c.id in (select id from public.observer_edge_fleet_commands where enrollment_id=p_enrollment
      and state in ('REQUESTED','TARGETED') and expires_at > now() order by requested_at limit least(greatest(p_limit,1),20) for update skip locked)
    returning c.*;
end $$;

CREATE FUNCTION public.classroom_capacity_status(target_classroom_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare room public.classrooms; occupied_count integer; reserved_count integer; available_count integer;
begin
  select * into room from public.classrooms where id=target_classroom_id;
  if room.id is null then raise exception 'classroom_not_found' using errcode='P0002'; end if;
  if not (public.can_access_garden(room.garden_id) or auth.role()='anon') then raise exception 'classroom_capacity_denied' using errcode='42501'; end if;
  select count(*)::integer into occupied_count
  from public.child_classroom_assignments a
  left join public.child_kindergarten_enrollments e on e.id=a.enrollment_id
  where a.classroom_id=room.id and a.is_current and (a.enrollment_id is null or e.status='active');
  select count(*)::integer into reserved_count from public.classroom_seat_reservations r
  where r.classroom_id=room.id and r.status='active' and (r.expires_at is null or r.expires_at>now())
    and not exists (select 1 from public.child_classroom_assignments a where a.classroom_id=room.id and a.child_id=r.child_id and a.is_current);
  available_count:=case when room.capacity_limit is null then null else greatest(room.capacity_limit-occupied_count-reserved_count,0) end;
  return jsonb_build_object('classroom_id',room.id,'garden_id',room.garden_id,'capacity_limit',room.capacity_limit,
    'occupied',occupied_count,'reserved',reserved_count,'available',available_count,
    'over_capacity',room.capacity_limit is not null and occupied_count+reserved_count>room.capacity_limit);
end $$;

CREATE FUNCTION public.complaint_sla_state(p_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS TABLE(acknowledgement_overdue boolean, response_overdue boolean, resolution_overdue boolean, sla_configured boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.sla_policy_id is not null and c.acknowledgement_due_at<p_at and c.acknowledged_at is null,
    c.sla_policy_id is not null and c.response_due_at<p_at and c.last_response_at is null and c.status::text not in ('resolved','closed'),
    c.sla_policy_id is not null and c.resolution_due_at<p_at and c.status::text not in ('resolved','closed'),c.sla_policy_id is not null
  from public.complaints c where c.id=p_id and (public.is_admin() or c.reporter_user_id=auth.uid()
    or public.can_inspector_access_garden(c.garden_id) or (c.visibility='garden' and public.can_manage_garden(c.garden_id)));
$$;

CREATE FUNCTION public.complete_monthly_inspection(p_inspection_id uuid, p_answers jsonb, p_gps_lat numeric, p_gps_lng numeric, p_gps_radius_meters numeric, p_signature_image text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare i public.inspections%rowtype; g public.gardens%rowtype; result jsonb; signed_time timestamptz:=now();
declare document_number text; distance numeric;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into i from public.inspections where id=p_inspection_id for update;
  if i.id is null or i.inspector_id<>auth.uid() or not public.can_inspector_access_garden(i.garden_id) then
    raise exception 'inspection_not_authorized' using errcode='42501';
  end if;
  if i.status::text='done' and i.report_snapshot is not null then return i.report_snapshot; end if;
  if i.status::text not in ('open','in_progress') or i.completed_at is not null then
    raise exception 'inspection_locked' using errcode='23514';
  end if;
  select * into g from public.gardens where id=i.garden_id;
  if g.status::text<>'active' then raise exception 'garden_not_active' using errcode='23514'; end if;
  if i.period_month is null or i.period_month<>date_trunc('month',i.period_month)::date then
    raise exception 'inspection_period_invalid' using errcode='23514';
  end if;
  if p_signature_image is null or length(p_signature_image)>1000000 or
     p_signature_image !~ '^data:image/png;base64,[A-Za-z0-9+/=]+$' then
    raise exception 'signature_png_required' using errcode='23514';
  end if;
  if p_gps_lat not between -90 and 90 or p_gps_lng not between -180 and 180 then raise exception 'gps_invalid' using errcode='23514'; end if;
  if p_answers is null or jsonb_typeof(p_answers)<>'array' then raise exception 'answers_must_be_array' using errcode='23514'; end if;
  if exists(select 1 from jsonb_array_elements(p_answers) a where
    (a ? 'photo_url' and coalesce(a->>'photo_url','') !~ '^inspection-reports/[A-Za-z0-9/_\\.-]+$') or
    (a ? 'document_url' and coalesce(a->>'document_url','') !~ '^inspection-reports/[A-Za-z0-9/_\\.-]+$')) then
    raise exception 'inspection_evidence_must_be_private' using errcode='23514';
  end if;
  -- The legacy scorer writes answers, findings, task and score in this same transaction.
  result:=public.submit_inspection_with_answers(p_inspection_id,p_answers,p_gps_lat,p_gps_lng,p_gps_radius_meters);
  document_number:='GB-INS-'||to_char(i.period_month,'YYYYMM')||'-'||upper(left(i.id::text,8));
  distance:=case when g.gps_lat is not null and g.gps_lng is not null then
    public.distance_meters(g.gps_lat,g.gps_lng,p_gps_lat,p_gps_lng) else null end;
  insert into public.inspection_signatures(inspection_id,signature_image,signed_by,gps_lat,gps_lng,gps_distance_meters,
    inspector_details,kindergarten_details,result_snapshot)
  values(i.id,p_signature_image,auth.uid(),p_gps_lat,p_gps_lng,distance,
    jsonb_build_object('id',auth.uid()),jsonb_build_object('id',g.id,'name',g.name),result);
  insert into public.inspection_gps_validations(inspection_id,garden_id,inspector_id,arrived_at,departed_at,
    gps_lat,gps_lng,garden_lat,garden_lng,distance_meters,validation_result,consistency_status,metadata)
  values(i.id,g.id,auth.uid(),coalesce(i.started_at,i.created_at),signed_time,p_gps_lat,p_gps_lng,g.gps_lat,g.gps_lng,distance,
    case when distance is null then 'pending' when distance<=p_gps_radius_meters then 'valid' else 'suspicious' end,
    case when distance is null then 'requires_review' when distance<=p_gps_radius_meters then 'consistent' else 'inconsistent' end,
    jsonb_build_object('source','browser_capture','not_independent_proof',true));
  update public.inspections set signature_image=p_signature_image,signed_at=signed_time,signed_by=auth.uid(),
    performed_by_user=auth.uid(),performed_by_role='inspector',regulatory_document_number=document_number,
    regulatory_locked_at=signed_time,regulatory_locked_by=auth.uid(),
    template_snapshot=coalesce(template_snapshot,(select jsonb_build_object('form_id',i.form_id,'questions',coalesce(jsonb_agg(to_jsonb(q) order by q.sort_order),'[]'::jsonb)) from public.inspection_form_questions q where q.form_id=i.form_id)),
    report_snapshot=result||jsonb_build_object('document_number',document_number,'period_month',i.period_month),updated_at=now()
  where id=i.id;
  update public.monthly_inspection_cycles set completion_status='completed',completed_inspection_id=i.id,
    completed_at=signed_time,updated_at=signed_time where garden_id=i.garden_id and cycle_month=i.period_month;
  update public.required_inspections set status='done',inspection_id=i.id,readiness_status='ready',updated_at=signed_time
    where garden_id=i.garden_id and monthly_cycle_date=i.period_month and status<>'done';
  delete from public.inspection_drafts where inspection_id=i.id;
  insert into public.regulatory_audit_events(actor_profile_id,actor_role,garden_id,inspection_id,event_type,event_title,event_details)
  values(auth.uid(),'inspector',g.id,i.id,'inspection_submitted_and_locked','דוח ביקורת נחתם וננעל',
    jsonb_build_object('document_number',document_number,'gps_captured',true));
  return result||jsonb_build_object('document_number',document_number,'period_month',i.period_month);
end $_$;

CREATE TABLE public.digital_observer_camera_action_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
    camera_source_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    confirmed_by uuid,
    action_type text NOT NULL,
    request_origin text DEFAULT 'dashboard'::text NOT NULL,
    action_status text DEFAULT 'awaiting_confirmation'::text NOT NULL,
    parameters jsonb DEFAULT '{}'::jsonb NOT NULL,
    capability_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    idempotency_key text NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '00:02:00'::interval) NOT NULL,
    confirmed_at timestamp with time zone,
    delivered_at timestamp with time zone,
    completed_at timestamp with time zone,
    result jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    task_kind text DEFAULT 'legacy_command'::text NOT NULL,
    gateway_id text,
    stream_id text,
    channel integer,
    requested_at timestamp with time zone,
    payload_digest text,
    result_digest text,
    confirmation_id uuid,
    confirmation_nonce_hash text,
    confirmation_expires_at timestamp with time zone,
    dispatch_intent_digest text,
    source_generation text,
    binding_generation text,
    non_retryable boolean DEFAULT false NOT NULL,
    result_phase jsonb,
    authorization_kind text DEFAULT 'human_confirmation'::text NOT NULL,
    automation_policy_id uuid,
    automation_event_id uuid,
    CONSTRAINT camera_queue_automation_scope_check CHECK (((authorization_kind = ANY (ARRAY['human_confirmation'::text, 'digital_guard_policy'::text])) AND (((authorization_kind = 'human_confirmation'::text) AND (automation_policy_id IS NULL) AND (automation_event_id IS NULL)) OR ((authorization_kind = 'digital_guard_policy'::text) AND (task_kind = 'physical_command'::text) AND (request_origin = 'digital_guard'::text) AND (action_type = ANY (ARRAY['lighting'::text, 'siren'::text])) AND (automation_policy_id IS NOT NULL) AND (automation_event_id IS NOT NULL))))),
    CONSTRAINT camera_queue_binding_check CHECK (((task_kind = 'legacy_command'::text) OR (((gateway_id ~ '^[A-Za-z0-9_-]{1,160}$'::text) AND (stream_id ~ '^[A-Za-z0-9_-]{1,160}$'::text) AND ((channel >= 1) AND (channel <= 64))) IS TRUE))),
    CONSTRAINT camera_queue_no_physical_success_check CHECK ((((task_kind = 'legacy_command'::text) AND (action_status <> 'completed'::text)) OR (task_kind <> 'legacy_command'::text))),
    CONSTRAINT camera_queue_payload_check CHECK (((task_kind = 'legacy_command'::text) OR ((((task_kind = 'capability_snapshot'::text) AND (parameters = '{}'::jsonb) AND (payload_digest IS NULL)) OR ((task_kind = 'command_preflight'::text) AND (parameters = '{}'::jsonb) AND (payload_digest ~ '^[a-f0-9]{64}$'::text)) OR ((task_kind = 'physical_command'::text) AND public.camera_physical_payload_valid(action_type, parameters) AND (payload_digest ~ '^[a-f0-9]{64}$'::text))) IS TRUE))),
    CONSTRAINT camera_queue_physical_confirmation_check CHECK (((task_kind <> 'physical_command'::text) OR ((confirmation_expires_at = expires_at) AND (((authorization_kind = 'human_confirmation'::text) AND (confirmation_nonce_hash ~ '^[a-f0-9]{64}$'::text) AND (automation_policy_id IS NULL) AND (automation_event_id IS NULL) AND (((action_status = 'awaiting_confirmation'::text) AND (confirmation_id IS NULL) AND (confirmed_by IS NULL) AND (confirmed_at IS NULL) AND (dispatch_intent_digest IS NULL)) OR ((action_status = ANY (ARRAY['approved'::text, 'delivered'::text, 'completed'::text, 'failed'::text, 'reconciliation_required'::text, 'unknown'::text])) AND (confirmation_id IS NOT NULL) AND (confirmed_by IS NOT NULL) AND (confirmed_at IS NOT NULL) AND (confirmed_at <= confirmation_expires_at) AND (dispatch_intent_digest ~ '^[a-f0-9]{64}$'::text)) OR (action_status = ANY (ARRAY['blocked'::text, 'expired'::text, 'cancelled'::text])))) OR ((authorization_kind = 'digital_guard_policy'::text) AND (request_origin = 'digital_guard'::text) AND (confirmation_nonce_hash IS NULL) AND (automation_policy_id IS NOT NULL) AND (automation_event_id IS NOT NULL) AND (confirmation_id IS NOT NULL) AND (confirmed_by IS NOT NULL) AND (confirmed_at IS NOT NULL) AND (confirmed_at <= confirmation_expires_at) AND (dispatch_intent_digest ~ '^[a-f0-9]{64}$'::text) AND (action_status = ANY (ARRAY['approved'::text, 'delivered'::text, 'completed'::text, 'failed'::text, 'reconciliation_required'::text, 'unknown'::text, 'blocked'::text, 'expired'::text, 'cancelled'::text]))))))),
    CONSTRAINT camera_queue_physical_evidence_check CHECK (((task_kind <> 'physical_command'::text) OR ((((capability_evidence ->> 'adapter'::text) = 'private_nvr_http_api_v1'::text) AND ((capability_evidence ->> 'executor_installed'::text) = 'true'::text) AND ((capability_evidence ->> 'supported'::text) = 'true'::text) AND ((capability_evidence ->> 'action'::text) = action_type) AND ((capability_evidence ->> 'evidence_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND ((capability_evidence ->> 'site_id'::text) = (observer_site_id)::text) AND ((capability_evidence ->> 'camera_id'::text) = (camera_source_id)::text) AND ((capability_evidence ->> 'gateway_id'::text) = gateway_id) AND ((capability_evidence ->> 'stream_id'::text) = stream_id) AND ((capability_evidence -> 'channel'::text) = to_jsonb(channel)) AND ((capability_evidence ->> 'source_generation'::text) = source_generation) AND ((capability_evidence ->> 'binding_generation'::text) = binding_generation) AND (source_generation ~ '^[A-Za-z0-9._:-]{1,128}$'::text) AND (binding_generation ~ '^[A-Za-z0-9._:-]{1,128}$'::text) AND ((capability_evidence #>> '{live,tested}'::text[]) = 'true'::text) AND ((capability_evidence #>> '{live,media_progressing}'::text[]) = 'true'::text) AND (COALESCE((capability_evidence #>> '{live,verified_at}'::text[]), ''::text) <> ''::text)) IS TRUE))),
    CONSTRAINT camera_queue_result_check CHECK (((task_kind = 'legacy_command'::text) OR (action_status <> ALL (ARRAY['completed'::text, 'reconciliation_required'::text, 'unknown'::text])) OR (((completed_at IS NOT NULL) AND (delivered_at IS NOT NULL) AND (result_digest ~ '^[a-f0-9]{64}$'::text) AND ((result ->> 'request_id'::text) = (id)::text) AND (((action_status = 'completed'::text) AND (task_kind = ANY (ARRAY['capability_snapshot'::text, 'command_preflight'::text])) AND ((result ->> 'outcome'::text) = task_kind) AND ((result #>> '{outcome_payload,camera_id}'::text[]) = (camera_source_id)::text) AND ((result #>> '{outcome_payload,site_id}'::text[]) = (observer_site_id)::text) AND ((result #>> '{outcome_payload,stream_id}'::text[]) = stream_id) AND ((result #> '{outcome_payload,channel}'::text[]) = to_jsonb(channel)) AND ((result #> '{outcome_payload,executed}'::text[]) = 'false'::jsonb)) OR ((action_status = 'completed'::text) AND (task_kind = 'physical_command'::text) AND ((result ->> 'outcome'::text) = 'physical_command'::text) AND ((result #>> '{outcome_payload,request_id}'::text[]) = (id)::text) AND ((result #>> '{outcome_payload,camera_id}'::text[]) = (camera_source_id)::text) AND ((result #>> '{outcome_payload,site_id}'::text[]) = (observer_site_id)::text) AND ((result #>> '{outcome_payload,stream_id}'::text[]) = stream_id) AND ((result #> '{outcome_payload,channel}'::text[]) = to_jsonb(channel)) AND ((result #>> '{outcome_payload,gateway_id}'::text[]) = gateway_id) AND ((result #>> '{outcome_payload,source_generation}'::text[]) = source_generation) AND ((result #>> '{outcome_payload,binding_generation}'::text[]) = binding_generation) AND ((result #>> '{outcome_payload,action}'::text[]) = action_type) AND ((result #> '{outcome_payload,executor_installed}'::text[]) = 'true'::jsonb) AND ((result #> '{outcome_payload,executed}'::text[]) = 'true'::jsonb) AND ((result #>> '{outcome_payload,audit_digest}'::text[]) ~ '^[a-f0-9]{64}$'::text)) OR ((action_status = ANY (ARRAY['reconciliation_required'::text, 'unknown'::text])) AND (task_kind = 'physical_command'::text) AND ((result ->> 'outcome'::text) =
CASE
    WHEN (action_status = 'reconciliation_required'::text) THEN 'acknowledged_needs_reconciliation'::text
    ELSE 'unknown_non_retryable'::text
END) AND ((result ->> 'result_code'::text) = (result ->> 'outcome'::text)) AND ((result #>> '{outcome_payload,request_id}'::text[]) = (id)::text) AND ((result #>> '{outcome_payload,camera_id}'::text[]) = (camera_source_id)::text) AND ((result #>> '{outcome_payload,site_id}'::text[]) = (observer_site_id)::text) AND ((result #>> '{outcome_payload,gateway_id}'::text[]) = gateway_id) AND ((result #>> '{outcome_payload,stream_id}'::text[]) = stream_id) AND ((result #> '{outcome_payload,channel}'::text[]) = to_jsonb(channel)) AND ((result #>> '{outcome_payload,source_generation}'::text[]) = source_generation) AND ((result #>> '{outcome_payload,binding_generation}'::text[]) = binding_generation) AND ((result #>> '{outcome_payload,action}'::text[]) = action_type) AND ((result #> '{outcome_payload,executor_installed}'::text[]) = 'true'::jsonb) AND ((result #> '{outcome_payload,executed}'::text[]) = 'null'::jsonb) AND ((result #> '{outcome_payload,non_retryable}'::text[]) = 'true'::jsonb) AND ((result #> '{outcome_payload,phase,write_attempted}'::text[]) = 'true'::jsonb) AND ((result #>> '{outcome_payload,audit_digest}'::text[]) ~ '^[a-f0-9]{64}$'::text) AND ((result #>> '{outcome_payload,reported_at}'::text[]) <> ''::text)))) IS TRUE))),
    CONSTRAINT camera_queue_task_kind_check CHECK ((task_kind = ANY (ARRAY['legacy_command'::text, 'capability_snapshot'::text, 'command_preflight'::text, 'physical_command'::text]))),
    CONSTRAINT camera_queue_terminal_facts_check CHECK ((((task_kind <> 'physical_command'::text) AND (non_retryable = false) AND (result_phase IS NULL)) OR ((task_kind = 'physical_command'::text) AND (((action_status = ANY (ARRAY['awaiting_confirmation'::text, 'approved'::text, 'delivered'::text, 'failed'::text, 'blocked'::text, 'expired'::text, 'cancelled'::text])) AND (non_retryable = false) AND (result_phase IS NULL)) OR ((action_status = 'completed'::text) AND (non_retryable = true) AND (result_phase IS NULL)) OR ((action_status = 'reconciliation_required'::text) AND (non_retryable = true) AND (result_phase = (result #> '{outcome_payload,phase}'::text[])) AND ((result_phase -> 'write_attempted'::text) = 'true'::jsonb) AND ((result_phase -> 'ack_observed'::text) = 'true'::jsonb)) OR ((action_status = 'unknown'::text) AND (non_retryable = true) AND (result_phase = (result #> '{outcome_payload,phase}'::text[])) AND (result_phase = '{"ack_observed": false, "state_verified": false, "write_attempted": true}'::jsonb)))))),
    CONSTRAINT camera_queue_ttl_check CHECK (((task_kind = 'legacy_command'::text) OR (((requested_at IS NOT NULL) AND (expires_at > requested_at) AND (expires_at <= (requested_at +
CASE
    WHEN (task_kind = 'physical_command'::text) THEN '00:00:30'::interval
    ELSE '00:02:00'::interval
END))) IS TRUE))),
    CONSTRAINT digital_observer_camera_action_confirmation_check CHECK (((task_kind <> ALL (ARRAY['legacy_command'::text, 'physical_command'::text])) OR (action_status = ANY (ARRAY['awaiting_confirmation'::text, 'blocked'::text, 'expired'::text, 'cancelled'::text])) OR ((confirmed_by IS NOT NULL) AND (confirmed_at IS NOT NULL)))),
    CONSTRAINT digital_observer_camera_action_evidence_check CHECK (((task_kind <> 'legacy_command'::text) OR (((capability_evidence ->> 'supported'::text) = 'true'::text) AND (COALESCE((capability_evidence ->> 'method'::text), ''::text) <> ''::text) AND (COALESCE((capability_evidence ->> 'tested_at'::text), ''::text) <> ''::text)))),
    CONSTRAINT digital_observer_camera_action_origin_check CHECK (((request_origin = ANY (ARRAY['dashboard'::text, 'observer_chat'::text, 'digital_guard'::text])) AND ((task_kind <> 'physical_command'::text) OR ((request_origin = 'dashboard'::text) AND (authorization_kind = 'human_confirmation'::text)) OR ((request_origin = 'digital_guard'::text) AND (authorization_kind = 'digital_guard_policy'::text))))),
    CONSTRAINT digital_observer_camera_action_status_check CHECK ((action_status = ANY (ARRAY['awaiting_confirmation'::text, 'approved'::text, 'delivered'::text, 'succeeded'::text, 'failed'::text, 'completed'::text, 'reconciliation_required'::text, 'unknown'::text, 'blocked'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT digital_observer_camera_action_type_check CHECK ((((task_kind = 'legacy_command'::text) AND (action_type = ANY (ARRAY['talkback'::text, 'ptz_pan'::text, 'ptz_tilt'::text, 'ptz_zoom'::text, 'light_on'::text, 'light_off'::text, 'siren_on'::text, 'siren_off'::text, 'relay_on'::text, 'relay_off'::text]))) OR ((task_kind = 'capability_snapshot'::text) AND (action_type = 'capability_snapshot'::text)) OR ((task_kind = 'command_preflight'::text) AND (action_type = ANY (ARRAY['ptz'::text, 'talk'::text, 'siren'::text, 'lighting'::text]))) OR ((task_kind = 'physical_command'::text) AND (action_type = ANY (ARRAY['ptz'::text, 'siren'::text, 'lighting'::text])))))
);

COMMENT ON COLUMN public.digital_observer_camera_action_requests.task_kind IS 'Legacy physical approvals are preserved but never reclassified. Snapshot/preflight are read-only diagnostics.';

CREATE FUNCTION public.confirm_camera_physical_command(requested_action_id uuid, confirming_actor_id uuid, confirmation_value uuid, confirmation_nonce text) RETURNS public.digital_observer_camera_action_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  queued public.digital_observer_camera_action_requests%rowtype;
  intent_digest text;
begin
  select * into strict queued from public.digital_observer_camera_action_requests
  where id = requested_action_id for update;
  if queued.task_kind <> 'physical_command' or queued.action_status <> 'awaiting_confirmation'
    or queued.requested_by <> confirming_actor_id or queued.request_origin <> 'dashboard'
    or queued.authorization_kind <> 'human_confirmation' then
    raise exception 'camera_physical_confirmation_scope_invalid' using errcode = '23514';
  end if;
  if queued.expires_at <= clock_timestamp() or queued.confirmation_expires_at <= clock_timestamp()
    or queued.confirmation_nonce_hash <> encode(extensions.digest(confirmation_nonce, 'sha256'::text), 'hex') then
    raise exception 'camera_physical_confirmation_expired_or_invalid' using errcode = '23514';
  end if;
  if exists (select 1 from public.digital_observer_camera_action_requests where confirmation_id = confirmation_value) then
    raise exception 'camera_physical_confirmation_replayed' using errcode = '23505';
  end if;
  intent_digest := encode(extensions.digest(concat_ws('|', queued.id::text, confirmation_value::text,
    queued.observer_site_id::text, queued.camera_source_id::text, queued.gateway_id, queued.stream_id,
    queued.channel::text, queued.source_generation, queued.binding_generation, queued.action_type, queued.payload_digest,
    confirming_actor_id::text, queued.confirmation_expires_at::text), 'sha256'::text), 'hex');
  update public.digital_observer_camera_action_requests set
    confirmation_id = confirmation_value, confirmed_by = confirming_actor_id, confirmed_at = clock_timestamp(),
    dispatch_intent_digest = intent_digest, action_status = 'approved', updated_at = clock_timestamp()
  where id = queued.id returning * into queued;
  insert into public.immutable_audit_events (
    event_type,event_category,actor_profile_id,actor_role,target_type,target_id,camera_id,request_id,metadata,risk_level
  ) values (
    'digital_guard_command_dispatch_intent_v12','camera',confirming_actor_id,'observer_user',
    'digital_observer_camera_source',queued.camera_source_id,queued.camera_source_id,queued.id::text,
    jsonb_build_object('schema','camera_dispatch_intent_v12','site_id',queued.observer_site_id,
      'camera_id',queued.camera_source_id,'stream_id',queued.stream_id,'channel',queued.channel,'action',queued.action_type,
      'gateway_id',queued.gateway_id,'source_generation',queued.source_generation,'binding_generation',queued.binding_generation,
      'payload_digest',queued.payload_digest,'confirmation_id',queued.confirmation_id,
      'confirmation_expires_at',queued.confirmation_expires_at,'dispatch_intent_digest',intent_digest),'critical'
  );
  return queued;
exception when no_data_found then
  raise exception 'camera_physical_request_not_found' using errcode = 'P0002';
end;
$$;

COMMENT ON FUNCTION public.confirm_camera_physical_command(requested_action_id uuid, confirming_actor_id uuid, confirmation_value uuid, confirmation_nonce text) IS 'Atomically consumes one 30-second dashboard confirmation, approves one exact camera command, and appends immutable dispatch intent.';

CREATE FUNCTION public.confirm_electronic_enrollment_payment(target_request_id uuid, target_provider_mode text, target_provider_event_id text, target_amount numeric, target_covered_from date, target_covered_until date, target_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare req public.kindergarten_enrollment_requests; evidence public.enrollment_payment_evidence; activation jsonb; reason text;
begin
  if auth.role()<>'service_role' then raise exception 'electronic_payment_system_only' using errcode='42501'; end if;
  if target_provider_mode not in ('live','verified_test') or target_provider_event_id is null or length(btrim(target_provider_event_id))<8 then raise exception 'verified_provider_event_required' using errcode='23514'; end if;
  select * into req from public.kindergarten_enrollment_requests where id=target_request_id for update;
  if req.id is null then raise exception 'enrollment_request_not_found' using errcode='P0002'; end if;
  if target_provider_mode='verified_test' and coalesce((req.metadata->>'qa')::boolean,false)<>true then raise exception 'verified_test_requires_qa_request' using errcode='23514'; end if;
  insert into public.enrollment_payment_evidence(garden_id,enrollment_request_id,evidence_kind,provider_mode,provider_event_id,idempotency_key,status,amount,covered_from,covered_until,confirmed_at,recorded_by,metadata)
  values(req.garden_id,req.id,'electronic',target_provider_mode,btrim(target_provider_event_id),'provider-event:'||btrim(target_provider_event_id),'confirmed',target_amount,target_covered_from,target_covered_until,now(),auth.uid(),coalesce(target_metadata,'{}'::jsonb))
  on conflict(provider_mode,provider_event_id) do update set updated_at=now()
  returning * into evidence;
  if evidence.enrollment_request_id<>req.id then raise exception 'provider_event_request_conflict' using errcode='23505'; end if;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(auth.uid(),'system',req.garden_id,'enrollment_payment_evidence',evidence.id,'electronic_payment_confirmed',jsonb_build_object('request_id',req.id,'provider_mode',target_provider_mode));
  begin
    activation:=public.activate_enrollment_from_evidence(req.id,evidence.id);
    return activation;
  exception when others then
    reason:=sqlstate||':'||sqlerrm;
    update public.enrollment_payment_evidence set status='reconciliation_required',reconciliation_reason=left(reason,500),updated_at=now() where id=evidence.id;
    update public.kindergarten_enrollment_requests set status='payment_reconciliation_required',payment_status='reconciliation_required',updated_at=now() where id=req.id and status<>'activated';
    insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
    values(auth.uid(),'system',req.garden_id,'enrollment_payment_evidence',evidence.id,'enrollment_activation_reconciliation_required',jsonb_build_object('request_id',req.id,'reason_code',sqlstate));
    return jsonb_build_object('status','payment_reconciliation_required','payment_evidence_id',evidence.id,'reason_code',sqlstate,'idempotent',false);
  end;
end $$;

COMMENT ON FUNCTION public.confirm_electronic_enrollment_payment(target_request_id uuid, target_provider_mode text, target_provider_event_id text, target_amount numeric, target_covered_from date, target_covered_until date, target_metadata jsonb) IS 'Service-role provider adapter contract. Mock/not-configured providers cannot confirm enrollment payment.';

CREATE FUNCTION public.confirm_observer_managed_device_rotation(p_rotation uuid, p_enrollment uuid, p_new_version integer, p_challenge_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare rotation public.observer_managed_device_rotations%rowtype;
begin
  select * into rotation from public.observer_managed_device_rotations where id = p_rotation and enrollment_id = p_enrollment for update;
  if not found or rotation.state <> 'PENDING' or rotation.expires_at <= now()
    or rotation.new_credential_version <> p_new_version or rotation.challenge_hash is distinct from p_challenge_hash then
    raise exception 'MANAGED_DEVICE_ROTATION_INVALID';
  end if;
  if not exists (select 1 from public.observer_managed_device_credentials where enrollment_id = p_enrollment
    and credential_version = p_new_version and credential_state = 'PENDING') then
    raise exception 'MANAGED_DEVICE_ROTATION_KEY_MISSING';
  end if;
  update public.observer_managed_device_credentials set credential_state = 'RETIRED', retired_at = now()
    where enrollment_id = p_enrollment and credential_state = 'ACTIVE';
  update public.observer_managed_device_credentials set credential_state = 'ACTIVE', activated_at = now()
    where enrollment_id = p_enrollment and credential_version = p_new_version and credential_state = 'PENDING';
  update public.video_gateway_device_enrollments set credential_version = p_new_version,
    identity_scheme = 'ED25519_V1', hardened_at = coalesce(hardened_at, now()), refresh_token_hash = null,
    active_runtime_instance_id = null, active_runtime_sequence = null, updated_at = now() where id = p_enrollment;
  update public.observer_managed_device_rotations set state = 'CONFIRMED', confirmed_at = now(),
    challenge_hash = repeat('0',64) where id = p_rotation;
  return true;
end $$;

CREATE TABLE public.classroom_seat_reservations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid NOT NULL,
    classroom_id uuid NOT NULL,
    child_id uuid,
    enrollment_id uuid,
    enrollment_request_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    idempotency_key text NOT NULL,
    expires_at timestamp with time zone,
    released_at timestamp with time zone,
    consumed_at timestamp with time zone,
    created_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT classroom_seat_reservation_key_check CHECK (((length(btrim(idempotency_key)) >= 8) AND (length(btrim(idempotency_key)) <= 160))),
    CONSTRAINT classroom_seat_reservation_lifecycle_check CHECK ((((status = 'active'::text) AND (released_at IS NULL) AND (consumed_at IS NULL)) OR ((status = ANY (ARRAY['released'::text, 'expired'::text])) AND (released_at IS NOT NULL) AND (consumed_at IS NULL)) OR ((status = 'consumed'::text) AND (consumed_at IS NOT NULL)))),
    CONSTRAINT classroom_seat_reservation_status_check CHECK ((status = ANY (ARRAY['active'::text, 'released'::text, 'consumed'::text, 'expired'::text])))
);

COMMENT ON TABLE public.classroom_seat_reservations IS 'Canonical temporary or workflow-backed Classroom seat holds; occupied seats remain derived from active assignments.';

CREATE FUNCTION public.consume_classroom_seat_reservation(target_reservation_id uuid) RETURNS public.classroom_seat_reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.classroom_seat_reservations;
begin
  select * into result from public.classroom_seat_reservations where id=target_reservation_id for update;
  if result.id is null then raise exception 'reservation_not_found' using errcode='P0002'; end if;
  perform 1 from public.classrooms where id=result.classroom_id for update;
  if not public.can_manage_garden(result.garden_id) then raise exception 'classroom_capacity_denied' using errcode='42501'; end if;
  if result.status='consumed' then return result; end if;
  if result.status<>'active' or (result.expires_at is not null and result.expires_at<=now()) then raise exception 'reservation_not_active' using errcode='P0001'; end if;
  update public.classroom_seat_reservations set status='consumed',consumed_at=now(),updated_at=now() where id=result.id returning * into result;
  return result;
end $$;

CREATE FUNCTION public.consume_rate_limit(requested_identifier text, requested_route text, requested_limit integer, requested_window_start timestamp with time zone) RETURNS TABLE(hits integer, blocked boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  result_hits integer;
  result_blocked boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'RATE_LIMIT_SERVICE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  if requested_identifier is null or length(requested_identifier) < 16 or length(requested_identifier) > 180
     or requested_route is null or length(requested_route) < 2 or length(requested_route) > 120
     or requested_limit is null or requested_limit < 1 or requested_limit > 10000
     or requested_window_start is null then
    raise exception 'RATE_LIMIT_ARGUMENT_INVALID' using errcode = '22023';
  end if;

  insert into public.rate_limit_events(identifier, route, window_start, hits, blocked)
  values (requested_identifier, requested_route, requested_window_start, 1, false)
  on conflict (identifier, route, window_start) do update
    set hits = public.rate_limit_events.hits + 1,
        blocked = public.rate_limit_events.hits + 1 > requested_limit
  returning public.rate_limit_events.hits, public.rate_limit_events.blocked
  into result_hits, result_blocked;

  return query select result_hits, result_blocked;
end;
$$;

CREATE FUNCTION public.correlate_digital_observer_signal(p_signal_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  signal_row public.observer_intelligence_signals%rowtype;
  incident_id uuid;
  event_type text;
  camera_source_id uuid;
  track_id text;
  camera_name text;
  timeline_item jsonb;
  incident_status text;
  incident_title text;
  incident_summary text;
begin
  select * into signal_row from public.observer_intelligence_signals where id = p_signal_id for update;
  if not found then return null; end if;

  event_type := signal_row.metadata->>'event_type';
  camera_source_id := nullif(signal_row.metadata->>'camera_source_id','')::uuid;
  track_id := nullif(signal_row.metadata->>'track_id','');
  camera_name := nullif(signal_row.metadata->>'camera_name','');
  if signal_row.observer_site_id is null
    or signal_row.signal_type <> 'ai_camera'
    or signal_row.source_type <> 'system'
    or signal_row.metadata->>'observation_provenance' <> 'REAL_CAMERA_AI'
    or signal_row.metadata->>'validated_event' <> 'true'
    or event_type not in ('person_entered','person_exited')
    or camera_source_id is null or track_id is null then
    return null;
  end if;

  -- Serialise only this site/camera/track tuple. No cross-camera identity is inferred.
  perform pg_advisory_xact_lock(hashtextextended(signal_row.observer_site_id::text || ':' || camera_source_id::text || ':' || track_id, 0));

  select correlated_event_id into incident_id
  from public.observer_correlated_event_links
  where source_type = 'observer_intelligence_signal' and source_id = signal_row.id;
  if incident_id is not null then return incident_id; end if;

  select id into incident_id
  from public.observer_correlated_events
  where observer_site_id = signal_row.observer_site_id
    and primary_camera_source_id = camera_source_id
    and correlation_version = 'do-track-v1'
    and involved_track_ids @> array[track_id]
    and status in ('open','acknowledged')
    and opened_at <= signal_row.created_at
    and last_activity_at >= signal_row.created_at - interval '10 minutes'
  order by last_activity_at desc limit 1 for update;

  -- An exit cannot create an incident without a prior correlated entry state.
  if incident_id is null and event_type = 'person_exited' then return null; end if;

  if incident_id is null then
    insert into public.observer_correlated_events (
      observer_site_id, correlation_type, severity, confidence, status, start_time,
      title, summary, opened_at, last_activity_at, primary_camera_source_id,
      involved_camera_ids, involved_track_ids, related_event_ids, provenance,
      correlation_version, created_by_origin, timeline_summary, confidence_factors, metadata
    ) values (
      signal_row.observer_site_id, 'safety_event_correlation', signal_row.severity,
      coalesce(signal_row.confidence, 0), 'open', signal_row.created_at,
      'תנועה באזור הכניסה', 'אדם נכנס לאזור המצולם; האירוע עדיין פתוח לבדיקה.',
      signal_row.created_at, signal_row.created_at, camera_source_id,
      array[camera_source_id], array[track_id], '{}'::uuid[], 'REAL_CAMERA_AI',
      'do-track-v1', 'system', '[]'::jsonb,
      jsonb_build_object('rule','same_site_camera_track','version','do-track-v1'),
      jsonb_build_object('canonical_incident',true,'correlation_reason','same site + camera + track ID + compatible entry/exit sequence')
    ) returning id into incident_id;
  end if;

  timeline_item := jsonb_build_object(
    'event_id', signal_row.id, 'event_type', event_type, 'timestamp', signal_row.created_at,
    'camera_source_id', camera_source_id, 'camera_name', camera_name, 'track_id', track_id,
    'provenance', 'REAL_CAMERA_AI', 'confidence', signal_row.confidence,
    'evidence_kind', signal_row.metadata->>'evidence_kind'
  );
  incident_status := case when event_type = 'person_exited' then 'closed' else 'open' end;
  incident_title := 'תנועה באזור הכניסה';
  incident_summary := case when event_type = 'person_exited'
    then 'אדם נכנס לאזור המצולם ולאחר מכן יצא.'
    else 'אדם נכנס לאזור המצולם; האירוע עדיין פתוח לבדיקה.' end;

  insert into public.observer_correlated_event_links (
    correlated_event_id, source_type, source_id, observer_site_id, event_time,
    confidence, sequence_order, metadata
  ) values (
    incident_id, 'observer_intelligence_signal', signal_row.id, signal_row.observer_site_id,
    signal_row.created_at, signal_row.confidence,
    coalesce((select max(sequence_order) + 1 from public.observer_correlated_event_links where correlated_event_id = incident_id), 0),
    jsonb_build_object('event_type',event_type,'camera_source_id',camera_source_id,'track_id',track_id,
      'provenance','REAL_CAMERA_AI','evidence_reference',signal_row.id)
  ) on conflict do nothing;

  update public.observer_correlated_events set
    status = incident_status,
    severity = case
      when severity in ('critical','urgent') then severity
      when signal_row.severity in ('critical','urgent') then signal_row.severity
      when severity = 'high' or signal_row.severity = 'high' then 'high'
      when severity = 'medium' or signal_row.severity = 'medium' then 'medium'
      else severity end,
    confidence = greatest(confidence, coalesce(signal_row.confidence, 0)),
    title = incident_title,
    summary = incident_summary,
    last_activity_at = greatest(last_activity_at, signal_row.created_at),
    end_time = case when event_type = 'person_exited' then signal_row.created_at else end_time end,
    closed_at = case when event_type = 'person_exited' then signal_row.created_at else closed_at end,
    involved_camera_ids = (select array_agg(distinct value) from unnest(involved_camera_ids || camera_source_id) value),
    involved_track_ids = (select array_agg(distinct value) from unnest(involved_track_ids || track_id) value),
    related_event_ids = (select array_agg(distinct value) from unnest(related_event_ids || signal_row.id) value),
    timeline_summary = coalesce(timeline_summary,'[]'::jsonb) || timeline_item,
    updated_at = now()
  where id = incident_id
    and not (related_event_ids @> array[signal_row.id]);

  return incident_id;
end;
$$;

COMMENT ON FUNCTION public.correlate_digital_observer_signal(p_signal_id uuid) IS 'Deterministically correlates validated REAL_CAMERA_AI entry/exit Events into one same-site/camera/track Incident.';

CREATE FUNCTION public.correlate_digital_observer_signal_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.correlate_digital_observer_signal(new.id);
  return new;
end;
$$;

CREATE TABLE public.complaint_sla_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version integer NOT NULL,
    category text,
    severity public.severity_level,
    acknowledgement_minutes integer,
    response_minutes integer,
    resolution_minutes integer,
    effective_from timestamp with time zone NOT NULL,
    effective_until timestamp with time zone,
    status text NOT NULL,
    source_note text,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT complaint_sla_policies_acknowledgement_minutes_check CHECK ((acknowledgement_minutes > 0)),
    CONSTRAINT complaint_sla_policies_check CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT complaint_sla_policies_check1 CHECK (((status <> 'active'::text) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT complaint_sla_policies_resolution_minutes_check CHECK ((resolution_minutes > 0)),
    CONSTRAINT complaint_sla_policies_response_minutes_check CHECK ((response_minutes > 0)),
    CONSTRAINT complaint_sla_policies_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'retired'::text]))),
    CONSTRAINT complaint_sla_policies_version_check CHECK ((version > 0))
);

CREATE FUNCTION public.create_complaint_sla_draft(p_category text, p_severity public.severity_level, p_acknowledgement_minutes integer, p_response_minutes integer, p_resolution_minutes integer, p_effective_from timestamp with time zone, p_effective_until timestamp with time zone, p_source_note text) RETURNS public.complaint_sla_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.complaint_sla_policies%rowtype; new_version integer;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'admin_required' using errcode='42501'; end if;
  if p_acknowledgement_minutes is null or p_response_minutes is null or p_resolution_minutes is null
    or p_source_note is null or length(btrim(p_source_note))<3 then raise exception 'policy_incomplete' using errcode='23514'; end if;
  perform pg_advisory_xact_lock(hashtext('complaint_sla_policy'),0);
  select coalesce(max(version),0)+1 into new_version from public.complaint_sla_policies;
  insert into public.complaint_sla_policies(version,category,severity,acknowledgement_minutes,response_minutes,
    resolution_minutes,effective_from,effective_until,status,source_note)
  values(new_version,p_category,p_severity,p_acknowledgement_minutes,p_response_minutes,p_resolution_minutes,
    p_effective_from,p_effective_until,'draft',btrim(p_source_note)) returning * into result;
  insert into public.audit_logs(actor_id,garden_id,entity_type,entity_id,action,after_data)
    values(auth.uid(),null,'complaint_sla_policies',result.id,'sla_draft_created',jsonb_build_object('version',result.version));
  return result;
end; $$;

CREATE FUNCTION public.create_inspector_preliminary_garden(p_name text, p_city text, p_address text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor_id uuid:=auth.uid(); existing public.gardens%rowtype; new_id uuid;
begin
  if actor_id is null or not public.is_approved_inspector(actor_id) then raise exception 'approved_inspector_required' using errcode='42501'; end if;
  if length(trim(coalesce(p_name,'')))<2 or length(trim(coalesce(p_city,'')))<2 then raise exception 'garden_details_required' using errcode='23514'; end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(trim(p_name))||'|'||lower(trim(p_city)),21));
  select * into existing from public.gardens g
    where lower(trim(g.name))=lower(trim(p_name)) and lower(trim(g.city))=lower(trim(p_city))
      and g.status::text<>'archived' order by g.created_at limit 1;
  if existing.id is not null then
    if existing.bootstrap_inspector_id=actor_id and existing.status::text='pending' and existing.bootstrap_cancelled_at is null then
      return jsonb_build_object('garden_id',existing.id,'already_exists',true,'status','preliminary');
    end if;
    return jsonb_build_object('status','duplicate_review_required');
  end if;
  insert into public.gardens(name,city,address,status,approval_flow_status,final_approval_status,onboarding_status,
    activation_payment_status,public_profile_enabled,eligible_for_safe_status,safe_status,ages,bootstrap_inspector_id,bootstrap_assignment_status)
  values(trim(p_name),trim(p_city),nullif(trim(coalesce(p_address,'')),''),'pending','activation_in_progress',
    'activation_in_progress','activation_in_progress','not_started',false,false,'pending_review','{}'::text[],actor_id,'pending')
  returning id into new_id;
  insert into public.kindergarten_onboarding_records(garden_id,lifecycle_status,progress_percent,completed_steps,missing_fields,
    profile_data,activation_steps,payment_status,subscription_monthly_amount,started_at,current_step,registrant_type)
  values(new_id,'activation_in_progress',0,'{}'::text[],array['owner_invitation','garden_details','identity','documents','consents'],
    jsonb_build_object('registration_source','inspector_preliminary','bootstrap_inspector_id',actor_id),
    '{}'::text[],'not_started',700,now(),'garden_details','owner_only');
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(actor_id,'inspector',new_id,'gardens',new_id,'inspector_preliminary_garden_created',jsonb_build_object('city',trim(p_city)));
  return jsonb_build_object('garden_id',new_id,'already_exists',false,'status','preliminary');
end $$;

CREATE TABLE public.tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid,
    title text NOT NULL,
    description text,
    assigned_to uuid,
    created_by uuid,
    due_at timestamp with time zone,
    status public.task_status DEFAULT 'open'::public.task_status NOT NULL,
    files jsonb DEFAULT '[]'::jsonb NOT NULL,
    viewed_at timestamp with time zone,
    completed_at timestamp with time zone,
    completed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    task_type text DEFAULT 'general'::text NOT NULL,
    period_month date,
    source_entity_type text,
    source_entity_id uuid,
    escalated_at timestamp with time zone,
    escalated_by uuid,
    escalation_reason text,
    priority public.severity_level DEFAULT 'medium'::public.severity_level NOT NULL,
    assigned_role text,
    assigned_group text,
    repeat_rule text,
    rejection_reason text,
    completed_notes text,
    performed_by_user uuid,
    performed_by_role text,
    requires_proof boolean DEFAULT false NOT NULL,
    proof_files jsonb DEFAULT '[]'::jsonb NOT NULL,
    completion_comment text,
    waiting_approval_at timestamp with time zone,
    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text,
    workflow_id uuid,
    workflow_task_id uuid,
    response_target_at timestamp with time zone,
    completion_target_at timestamp with time zone,
    escalation_target_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    blocked_reason text
);

CREATE FUNCTION public.create_management_task(p_garden_id uuid, p_title text, p_description text DEFAULT NULL::text, p_assigned_to uuid DEFAULT NULL::uuid, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_priority text DEFAULT 'medium'::text) RETURNS public.tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor public.profiles%rowtype; result public.tasks%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into actor from public.profiles where id=auth.uid() and active=true;
  if actor.id is null or not (public.is_admin() or (p_garden_id is not null and public.can_manage_garden(p_garden_id))) then
    raise exception 'task_manager_required' using errcode='42501'; end if;
  if nullif(btrim(p_title),'') is null or length(p_title)>200 or p_priority not in ('low','medium','high','critical') then
    raise exception 'invalid_task' using errcode='23514'; end if;
  if p_assigned_to is not null and not (
    (p_garden_id is null and exists(select 1 from public.profiles p where p.id=p_assigned_to and p.active and p.role::text='admin'))
    or (p_garden_id is not null and (
      exists(select 1 from public.garden_management_memberships m join public.profiles p on p.id=m.profile_id and p.active where m.profile_id=p_assigned_to and m.garden_id=p_garden_id and m.status='active' and m.relationship_role in ('owner','manager'))
      or exists(select 1 from public.staff_kindergarten_employments e join public.staff s on s.id=e.staff_id and s.profile_id=e.profile_id and s.garden_id=e.garden_id join public.profiles p on p.id=e.profile_id and p.active where e.profile_id=p_assigned_to and e.garden_id=p_garden_id and e.status='active' and (e.start_date is null or e.start_date<=current_date) and (e.end_date is null or e.end_date>=current_date) and s.approved_to_work and s.onboarding_status='active')
      or (public.is_approved_inspector(p_assigned_to) and exists(select 1 from public.gardens g where g.id=p_garden_id and g.inspector_id=p_assigned_to))
    ))
  ) then raise exception 'ineligible_task_assignee' using errcode='42501'; end if;
  insert into public.tasks(garden_id,title,description,assigned_to,created_by,due_at,priority,status,task_type)
  values(p_garden_id,btrim(p_title),p_description,p_assigned_to,actor.id,p_due_at,p_priority::public.severity_level,'open','general') returning * into result;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(actor.id,actor.role,p_garden_id,'tasks',result.id,'task_created',jsonb_build_object('assigned_to',p_assigned_to,'due_at',p_due_at));
  if p_assigned_to is not null then
    insert into public.notifications(garden_id,recipient_id,title,body,entity_type,entity_id,channel,status)
    values(p_garden_id,p_assigned_to,'משימה חדשה',result.title,'task',result.id,'in_app','pending');
  end if;
  return result;
end; $$;

CREATE FUNCTION public.create_monthly_inspection_tasks(p_month date DEFAULT (date_trunc('month'::text, now()))::date) RETURNS TABLE(task_id uuid, inspection_id uuid, garden_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  g record;
  active_form_id uuid;
  new_task_id uuid;
  new_inspection_id uuid;
  due_date timestamptz;
begin
  select id into active_form_id
  from public.inspection_forms
  where active = true
  order by created_at desc
  limit 1;

  if active_form_id is null then
    raise exception 'No active inspection form exists';
  end if;

  due_date := (p_month + interval '1 month' - interval '1 day')::timestamptz;

  for g in
    select id, name, address, inspector_id
    from public.gardens
    where status = 'active' and inspector_id is not null
  loop
    insert into public.tasks (
      garden_id, title, description, assigned_to, due_at, task_type, period_month, status
    )
    values (
      g.id,
      'ביקורת חודשית - ' || to_char(p_month, 'MM/YYYY'),
      'משימת ביקורת חודשית אוטומטית לגן ' || g.name || coalesce(' בכתובת ' || g.address, ''),
      g.inspector_id,
      due_date,
      'monthly_inspection',
      p_month,
      'open'
    )
    on conflict (garden_id, task_type, period_month) where task_type = 'monthly_inspection'
    do update set due_at = excluded.due_at, assigned_to = excluded.assigned_to, updated_at = now()
    returning id into new_task_id;

    insert into public.inspections (
      garden_id, inspector_id, form_id, task_id, period_month, due_at, status
    )
    values (
      g.id, g.inspector_id, active_form_id, new_task_id, p_month, due_date, 'open'
    )
    on conflict (garden_id, period_month) where period_month is not null
    do update set task_id = excluded.task_id, inspector_id = excluded.inspector_id, updated_at = now()
    returning id into new_inspection_id;

    update public.tasks
    set source_entity_type = 'inspection', source_entity_id = new_inspection_id
    where id = new_task_id;

    task_id := new_task_id;
    inspection_id := new_inspection_id;
    garden_id := g.id;
    return next;
  end loop;
end;
$$;

CREATE FUNCTION public.create_skeleton_motion_signal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  mapped_status text;
  mapped_risk integer;
begin
  if new.event_type in ('pose_sample','motion_sample') then
    return new;
  end if;

  mapped_status := case
    when new.review_status in ('confirmed','dismissed','escalated','resolved') then new.review_status
    when new.review_status = 'closed' then 'resolved'
    else 'needs_review'
  end;

  mapped_risk := case new.severity
    when 'critical' then 95
    when 'urgent' then 88
    when 'high' then 76
    when 'medium' then 55
    when 'low' then 30
    else 15
  end;

  insert into public.observer_intelligence_signals (
    signal_type,
    source_type,
    source_id,
    kindergarten_id,
    observer_site_id,
    camera_id,
    severity,
    confidence,
    review_status,
    recommended_action,
    risk_score,
    pattern_key,
    human_review_required,
    parent_visible,
    metadata
  )
  values (
    'skeleton_motion',
    'skeleton_motion',
    new.id,
    new.garden_id,
    new.observer_site_id,
    new.camera_id,
    new.severity,
    new.confidence,
    mapped_status,
    coalesce(new.recommended_action, 'Review motion signal and camera zone context'),
    mapped_risk,
    concat('skeleton_motion:', new.event_type, ':', coalesce(new.zone_id::text, 'no_zone')),
    true,
    false,
    jsonb_build_object(
      'skeleton_event_type', new.event_type,
      'zone_id', new.zone_id,
      'anonymous_only', true,
      'no_face_recognition', true,
      'no_audio_processing', true,
      'no_raw_frame_stored', true,
      'review_required', true
    ) || coalesce(new.metadata, '{}'::jsonb)
  )
  on conflict (source_type, source_id) do update set
    severity = excluded.severity,
    confidence = excluded.confidence,
    review_status = excluded.review_status,
    recommended_action = excluded.recommended_action,
    risk_score = excluded.risk_score,
    metadata = excluded.metadata,
    updated_at = now();

  return new;
end;
$$;

COMMENT ON FUNCTION public.create_skeleton_motion_signal() IS 'Creates review-required observer intelligence signals from skeleton motion events. No parent visibility and no automatic action.';

CREATE FUNCTION public.create_task_from_source(p_source_type text, p_source_id uuid, p_assigned_to uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS public.tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.tasks%rowtype; target_garden uuid; source_title text; source_description text; source_priority text;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'admin_required' using errcode='42501'; end if;
  if p_source_type not in ('complaint','incident') then raise exception 'unsupported_task_source' using errcode='23514'; end if;
  perform pg_advisory_xact_lock(hashtext('management_task_source'),hashtext(p_source_type||p_source_id::text));
  select * into result from public.tasks where source_entity_type=p_source_type and source_entity_id=p_source_id limit 1;
  if result.id is not null then return result; end if;
  if p_source_type='complaint' then
    select garden_id,subject,description,severity::text into target_garden,source_title,source_description,source_priority
      from public.complaints where id=p_source_id;
  else
    select garden_id,title,description,severity into target_garden,source_title,source_description,source_priority
      from public.incident_reports where id=p_source_id;
  end if;
  if target_garden is null then raise exception 'task_source_not_found' using errcode='P0002'; end if;
  if p_assigned_to is not null and not (
    exists(select 1 from public.garden_management_memberships m join public.profiles p on p.id=m.profile_id and p.active
      where m.profile_id=p_assigned_to and m.garden_id=target_garden and m.status='active' and m.relationship_role in ('owner','manager'))
    or (public.is_approved_inspector(p_assigned_to) and exists(select 1 from public.gardens g where g.id=target_garden and g.inspector_id=p_assigned_to))
  ) then raise exception 'source_task_reviewer_required' using errcode='42501'; end if;
  result:=public.create_management_task(target_garden,'טיפול בדיווח: '||source_title,
    coalesce(p_note,source_description),p_assigned_to,null,
    case when source_priority in ('low','medium','high','critical') then source_priority else 'medium' end);
  update public.tasks set source_entity_type=p_source_type,source_entity_id=p_source_id,task_type='report_followup'
    where id=result.id returning * into result;
  return result;
end; $$;

CREATE FUNCTION public.current_garden_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select garden_id from public.profiles where id = auth.uid() and active = true
$$;

CREATE FUNCTION public.current_inspector_approved() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_approved_inspector(auth.uid());
$$;

CREATE FUNCTION public."current_role"() RETURNS public.app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select role from public.profiles where id = auth.uid() and active = true
$$;

CREATE FUNCTION public.current_user_role() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(public.current_role()::text, 'public');
$$;

CREATE FUNCTION public.decide_enrollment_request(target_request_id uuid, target_action text, target_classroom_id uuid DEFAULT NULL::uuid, target_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare req public.kindergarten_enrollment_requests; room public.classrooms; reservation public.classroom_seat_reservations;
  next_status text; staffing jsonb; child_birth date; child_months integer;
begin
  select * into req from public.kindergarten_enrollment_requests where id=target_request_id for update;
  if req.id is null then raise exception 'enrollment_request_not_found' using errcode='P0002'; end if;
  if not public.can_manage_garden(req.garden_id) then raise exception 'enrollment_decision_denied' using errcode='42501'; end if;
  if target_action='review' and req.status in ('submitted','resubmitted') then next_status:='under_review';
  elsif target_action='request_information' and req.status in ('submitted','resubmitted','under_review') then next_status:='information_required';
  elsif target_action='reject' and req.status in ('submitted','resubmitted','under_review','information_required') then next_status:='rejected';
  elsif target_action='waitlist' and req.status in ('submitted','resubmitted','under_review') then next_status:='waitlisted';
  elsif target_action='approve' and req.status in ('submitted','resubmitted','under_review') then next_status:='awaiting_payment';
  elsif target_action='cancel' and req.status in ('submitted','resubmitted','under_review','information_required','approved','awaiting_payment','waitlisted') then next_status:='cancelled';
  elsif target_action='approve' and req.status='awaiting_payment' and req.reservation_id is not null then
    return jsonb_build_object('request',to_jsonb(req),'staffing_readiness',public.evaluate_classroom_staffing(req.requested_classroom_id,current_date,1),'idempotent',true);
  else raise exception 'invalid_enrollment_transition' using errcode='23514'; end if;

  if target_action='approve' then
    select birth_date into child_birth from public.permanent_child_files where id=req.child_profile_id;
    child_months:=extract(year from age(current_date,child_birth))::integer*12+extract(month from age(current_date,child_birth))::integer;
    select * into room from public.classrooms where id=coalesce(target_classroom_id,req.requested_classroom_id) and garden_id=req.garden_id and status='active' for update;
    if room.id is null or room.min_age_months is null or room.max_age_months is null or child_months not between room.min_age_months and room.max_age_months then raise exception 'invalid_enrollment_classroom' using errcode='23514'; end if;
    reservation:=public.reserve_classroom_seat(room.id,'enrollment-request:'||req.id::text,null,null,req.id,null);
    staffing:=public.evaluate_classroom_staffing(room.id,current_date,1);
  end if;
  if next_status='cancelled' and req.reservation_id is not null then perform public.release_classroom_seat_reservation(req.reservation_id); end if;
  update public.kindergarten_enrollment_requests set status=next_status,reviewed_at=now(),reviewed_by=auth.uid(),
    manager_decision=target_action,decision_reason=case when target_action in ('reject','waitlist') then nullif(btrim(target_reason),'') else decision_reason end,
    information_request=case when target_action='request_information' then nullif(btrim(target_reason),'') else information_request end,
    information_requested_at=case when target_action='request_information' then now() else information_requested_at end,
    requested_classroom_id=coalesce(room.id,requested_classroom_id),reservation_id=coalesce(reservation.id,reservation_id),
    payment_status=case when next_status='awaiting_payment' then 'pending' else payment_status end,
    decided_at=case when next_status in ('awaiting_payment','waitlisted','rejected','cancelled') then now() else decided_at end,
    cancelled_at=case when next_status='cancelled' then now() else cancelled_at end,cancelled_by=case when next_status='cancelled' then auth.uid() else cancelled_by end,updated_at=now()
  where id=req.id returning * into req;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,before_data,after_data)
  values(auth.uid(),public.current_role()::text,req.garden_id,'kindergarten_enrollment_requests',req.id,'enrollment_request_'||target_action,null,jsonb_build_object('status',next_status,'reservation_id',req.reservation_id));
  insert into public.notifications(garden_id,recipient_id,recipient_profile_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,kindergarten_id,created_by)
  values(req.garden_id,req.parent_id,req.parent_id,'parent','בקשת ההצטרפות עודכנה',coalesce(nullif(btrim(target_reason),''),'סטטוס בקשת ההצטרפות עודכן.'),coalesce(nullif(btrim(target_reason),''),'סטטוס בקשת ההצטרפות עודכן.'),'kindergarten_enrollment_requests',req.id,case when next_status='rejected' then 'medium' else 'low' end,'/dashboard/parent',req.garden_id,auth.uid());
  return jsonb_build_object('request',to_jsonb(req),'staffing_readiness',staffing,'idempotent',false);
end $$;

CREATE FUNCTION public.decide_inspector_application(p_application_id uuid, p_action text, p_reason text DEFAULT NULL::text, p_regions text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare application public.inspector_applications%rowtype; applicant public.profiles%rowtype; saved public.inspector_applications%rowtype;
declare next_status text; now_at timestamptz:=now();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'admin_required' using errcode='42501'; end if;
  select * into application from public.inspector_applications where id=p_application_id for update;
  if application.id is null then raise exception 'application_not_found' using errcode='P0002'; end if;
  if p_action not in ('under_review','request_more_information','approve','reject','suspend') then raise exception 'invalid_inspector_action' using errcode='23514'; end if;
  next_status:=case p_action when 'request_more_information' then 'more_information_requested' when 'approve' then 'approved' when 'reject' then 'rejected' else p_action end;
  if application.status=next_status then return to_jsonb(application); end if;
  if not (
    (application.status in ('submitted','under_review','approved_pending_assignment') and p_action in ('under_review','request_more_information','approve','reject')) or
    (application.status='approved' and p_action='suspend') or
    (application.status='suspended' and p_action='approve')
  ) then raise exception 'invalid_inspector_transition' using errcode='23514'; end if;
  select * into applicant from public.profiles where id=application.profile_id for update;
  if applicant.id is null or applicant.role::text<>'inspector' then raise exception 'inspector_profile_invalid' using errcode='23514'; end if;
  if p_action='approve' then
    if applicant.contact_verification_required and (applicant.email_verified_at is null or applicant.phone_verified_at is null) then
      raise exception 'inspector_contact_unverified' using errcode='23514';
    end if;
    if nullif(trim(application.full_name),'') is null or nullif(trim(application.city),'') is null then
      raise exception 'inspector_application_incomplete' using errcode='23514'; end if;
    insert into public.inspectors(id,service_cities,certification_notes)
    values(applicant.id,coalesce(p_regions,application.preferred_regions),application.experience_summary)
    on conflict(id) do update set service_cities=excluded.service_cities,certification_notes=excluded.certification_notes;
    update public.profiles set active=true,self_service_status='active',self_service_approved_at=now_at,self_service_approved_by=auth.uid() where id=applicant.id;
  elsif p_action='suspend' then
    update public.profiles set self_service_status='suspended' where id=applicant.id;
  elsif p_action='reject' then
    update public.profiles set self_service_status='rejected' where id=applicant.id;
  end if;
  update public.inspector_applications set status=next_status,admin_decision=p_action,decision_reason=p_reason,
    decided_at=case when p_action in ('approve','reject','suspend') then now_at else decided_at end,
    activated_at=case when p_action='approve' then now_at else activated_at end,updated_at=now_at
  where id=application.id returning * into saved;
  insert into public.audit_logs(actor_id,actor_role,entity_type,entity_id,action,before_data,after_data)
  values(auth.uid(),'admin','inspector_applications',application.id,'inspector_application_'||p_action,
    jsonb_build_object('status',application.status),jsonb_build_object('status',next_status));
  insert into public.notifications(recipient_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,recipient_profile_id,created_by)
  values(application.profile_id,'inspector','בקשת המפקח עודכנה',coalesce(p_reason,'סטטוס הבקשה שלך עודכן.'),coalesce(p_reason,'סטטוס הבקשה שלך עודכן.'),
    'inspector_applications',application.id,'low','/dashboard/inspector/apply',application.profile_id,auth.uid());
  return to_jsonb(saved);
end;
$$;

CREATE FUNCTION public.decide_staff_job_application(target_application_id uuid, target_action text, target_reason text DEFAULT NULL::text, target_role text DEFAULT NULL::text, target_classroom_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare application public.staff_job_applications; room public.classrooms; next_status text; previous_status text; now_at timestamptz:=now();
begin
  select * into application from public.staff_job_applications where id=target_application_id for update;
  if application.id is null then raise exception 'staff_application_not_found' using errcode='P0002'; end if;
  previous_status:=application.status;
  if not public.can_manage_garden(application.garden_id) then raise exception 'staff_application_decision_denied' using errcode='42501'; end if;
  if target_action='review' and application.status in ('submitted','resubmitted') then next_status:='under_review';
  elsif target_action='request_information' and application.status in ('submitted','under_review','resubmitted') then next_status:='information_required';
  elsif target_action='reject' and application.status in ('submitted','under_review','resubmitted','approved','awaiting_candidate_acceptance') then next_status:='rejected';
  elsif target_action='approve' and application.status in ('submitted','under_review','resubmitted') then next_status:='awaiting_candidate_acceptance';
  else raise exception 'staff_application_transition_invalid' using errcode='23514'; end if;
  if target_action='approve' then
    if target_classroom_id is not null then select * into room from public.classrooms where id=target_classroom_id and garden_id=application.garden_id and status='active'; if room.id is null then raise exception 'staff_application_classroom_invalid' using errcode='23514'; end if; end if;
    if not exists(select 1 from public.staff_candidate_profiles c where c.profile_id=application.staff_candidate_id and coalesce((c.profile_completeness->>'required_fields_complete')::boolean,false)) then raise exception 'candidate_profile_incomplete' using errcode='23514'; end if;
  end if;
  update public.staff_job_applications set status=next_status,reviewed_at=now_at,reviewed_by=auth.uid(),manager_decision=target_action,decision_reason=case when target_action='request_information' then null else nullif(btrim(target_reason),'') end,information_request=case when target_action='request_information' then nullif(btrim(target_reason),'') else information_request end,classroom_id=coalesce(target_classroom_id,classroom_id),requested_role=coalesce(nullif(btrim(target_role),''),requested_role),decided_at=case when target_action in ('approve','reject') then now_at else decided_at end,updated_at=now_at where id=application.id returning * into application;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,before_data,after_data) values(auth.uid(),public.current_role()::text,application.garden_id,'staff_job_applications',application.id,'staff_application_'||target_action,jsonb_build_object('status',previous_status),jsonb_build_object('status',next_status));
  insert into public.notifications(garden_id,recipient_id,recipient_profile_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,kindergarten_id,created_by)
  values(application.garden_id,application.staff_candidate_id,application.staff_candidate_id,'staff','המועמדות עודכנה',coalesce(nullif(btrim(target_reason),''),'סטטוס המועמדות שלך עודכן.'),coalesce(nullif(btrim(target_reason),''),'סטטוס המועמדות שלך עודכן.'),'staff_job_applications',application.id,'low','/dashboard/staff/job-market',application.garden_id,auth.uid());
  return to_jsonb(application);
end $$;

CREATE FUNCTION public.digital_guard_crossing_line_valid(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when jsonb_typeof(value) = 'object'
      and value ->> 'axis' in ('x','y')
      and value ->> 'inside' in ('positive','negative')
      and jsonb_typeof(value -> 'position') = 'number'
    then (value ->> 'position')::numeric between 0.05 and 0.95
    else false
  end;
$$;

CREATE FUNCTION public.distance_meters(lat1 numeric, lng1 numeric, lat2 numeric, lng2 numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  select 6371000 * 2 * asin(
    sqrt(
      power(sin(radians((lat2 - lat1) / 2)), 2) +
      cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians((lng2 - lng1) / 2)), 2)
    )
  )
$$;

CREATE FUNCTION public.enforce_digital_guard_siren_crossing_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  crossing_line jsonb;
begin
  if new.enabled and 'siren' = any(new.allowed_actions) then
    select metadata -> 'crossing_line' into crossing_line
    from public.digital_observer_camera_sources
    where id = new.camera_source_id and observer_site_id = new.observer_site_id;
    if not public.digital_guard_crossing_line_valid(crossing_line) then
      raise exception 'Siren automation requires a valid crossing line'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.enforce_digital_observer_device_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  active_count integer;
begin
  if new.active is not true then
    return new;
  end if;

  select count(*)
  into active_count
  from public.digital_observer_device_slots d
  where d.observer_site_id = new.observer_site_id
    and d.active = true
    and d.id <> coalesce(new.id, gen_random_uuid());

  if active_count >= 2 then
    raise exception 'DIGITAL_OBSERVER_DEVICE_LIMIT_REACHED';
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.enforce_digital_observer_incident_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.correlation_version = 'do-track-v1' and new.status is distinct from old.status
    and not (
      (old.status = 'open' and new.status in ('acknowledged','resolved','closed'))
      or (old.status = 'acknowledged' and new.status in ('resolved','closed'))
      or (old.status = 'resolved' and new.status = 'closed')
    ) then
    raise exception 'INVALID_INCIDENT_STATE_TRANSITION';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.enforce_first_pilot_activation_gates() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.pilot_status = 'active_pilot' then
    if not exists (
      select 1
      from public.pilot_approval_gates gate
      where gate.pilot_profile_id = new.id
        and gate.required = true
        and gate.blocks_activation = true
    ) then
      raise exception 'Pilot activation blocked: approval gates have not been created';
    end if;

    if exists (
      select 1
      from public.pilot_approval_gates gate
      where gate.pilot_profile_id = new.id
        and gate.required = true
        and gate.blocks_activation = true
        and gate.status <> 'approved'
    ) then
      raise exception 'Pilot activation blocked: required approval gates are not approved';
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.enforce_observer_engine_boundary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  site_engine text;
begin
  select engine_mode into site_engine
  from public.observer_sites
  where id = new.observer_site_id;

  if site_engine is null then
    raise exception 'OBSERVER_SITE_ENGINE_MISSING';
  end if;

  if new.engine_mode is null then
    new.engine_mode := site_engine;
  elsif new.engine_mode <> site_engine then
    raise exception 'OBSERVER_ENGINE_BOUNDARY_VIOLATION';
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.enqueue_digital_guard_camera_command_v1(signal_id uuid, requested_action text, requested_payload jsonb, requested_payload_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  policy public.digital_observer_camera_automation_policies%rowtype;
  signal public.observer_intelligence_signals%rowtype;
  source public.digital_observer_camera_sources%rowtype;
  site public.observer_sites%rowtype;
  snapshot public.digital_observer_camera_action_requests%rowtype;
  existing public.digital_observer_camera_action_requests%rowtype;
  request_id uuid := gen_random_uuid();
  authorization_id uuid := gen_random_uuid();
  requested_at timestamptz := clock_timestamp();
  expires_at timestamptz := requested_at + interval '30 seconds';
  observed_at timestamptz;
  local_time time;
  event_type text;
  evidence_kind text;
  expected_digest text;
  intent_digest text;
  capability jsonb;
  recent_count integer;
begin
  if requested_action not in ('lighting','siren') or not public.camera_physical_payload_valid(requested_action, requested_payload) then
    return jsonb_build_object('status','blocked','reason','invalid_action_payload','action',requested_action);
  end if;
  if requested_action = 'lighting' and requested_payload <> '{"duration_ms":20000,"enabled":true}'::jsonb then
    return jsonb_build_object('status','blocked','reason','lighting_requires_twenty_second_pulse','action',requested_action);
  end if;
  if requested_action = 'siren' and requested_payload <> '{"enabled":true,"duration_ms":1000}'::jsonb then
    return jsonb_build_object('status','blocked','reason','siren_must_be_one_second','action',requested_action);
  end if;
  expected_digest := encode(extensions.digest(case when requested_action = 'lighting'
    then '{"duration_ms":20000,"enabled":true}' else '{"duration_ms":1000,"enabled":true}' end, 'sha256'::text), 'hex');
  if requested_payload_digest is distinct from expected_digest then
    return jsonb_build_object('status','blocked','reason','payload_digest_mismatch','action',requested_action);
  end if;

  select * into signal from public.observer_intelligence_signals where id = signal_id;
  if not found then return jsonb_build_object('status','blocked','reason','event_not_found','action',requested_action); end if;
  event_type := signal.metadata ->> 'event_type';
  evidence_kind := signal.metadata ->> 'evidence_kind';
  begin observed_at := (signal.metadata ->> 'first_seen')::timestamptz;
  exception when others then return jsonb_build_object('status','blocked','reason','event_time_invalid','action',requested_action); end;
  if signal.metadata ->> 'validated_event' <> 'true' or observed_at > requested_at + interval '5 seconds'
    or observed_at < requested_at - interval '20 seconds' then
    return jsonb_build_object('status','blocked','reason','event_not_fresh_and_verified','action',requested_action);
  end if;

  select * into policy from public.digital_observer_camera_automation_policies
  where observer_site_id = signal.observer_site_id
    and camera_source_id = (signal.metadata ->> 'camera_source_id')::uuid
    and enabled = true for update;
  if not found then return jsonb_build_object('status','blocked','reason','policy_disabled','action',requested_action); end if;
  if not requested_action = any(policy.allowed_actions) then
    return jsonb_build_object('status','blocked','reason','action_not_allowed','action',requested_action);
  end if;
  if signal.confidence < (case when requested_action = 'siren' then policy.siren_minimum_confidence else policy.minimum_confidence end) then
    return jsonb_build_object('status','blocked','reason','confidence_too_low','action',requested_action);
  end if;
  if requested_action = 'lighting' and not event_type = any(policy.lighting_event_types) then
    return jsonb_build_object('status','blocked','reason','event_not_allowed','action',requested_action);
  end if;
  if requested_action = 'siren' and (not event_type = any(policy.siren_event_types)
    or evidence_kind <> 'line_crossing' or signal.severity <> 'critical') then
    return jsonb_build_object('status','blocked','reason','siren_requires_critical_line_crossing','action',requested_action);
  end if;

  select * into site from public.observer_sites where id = policy.observer_site_id;
  select * into source from public.digital_observer_camera_sources
  where id = policy.camera_source_id and observer_site_id = policy.observer_site_id;
  if site.id is null or source.id is null or site.monitoring_enabled is not true
    or site.metadata ->> 'observer_monitoring_consent' <> 'true'
    or source.status not in ('connected','online','active','ready')
    or source.health_status not in ('healthy','online','connected','ok')
    or source.metadata ->> 'monitoring_enabled' = 'false' then
    return jsonb_build_object('status','blocked','reason','camera_or_monitoring_offline','action',requested_action);
  end if;
  local_time := (requested_at at time zone coalesce(site.timezone, 'Asia/Jerusalem'))::time;
  if policy.active_from < policy.active_until then
    if local_time < policy.active_from or local_time >= policy.active_until then
      return jsonb_build_object('status','blocked','reason','outside_active_schedule','action',requested_action);
    end if;
  elsif local_time < policy.active_from and local_time >= policy.active_until then
    return jsonb_build_object('status','blocked','reason','outside_active_schedule','action',requested_action);
  end if;

  select * into existing from public.digital_observer_camera_action_requests
  where automation_event_id = signal_id and action_type = requested_action
    and authorization_kind = 'digital_guard_policy' limit 1;
  if found then
    return jsonb_build_object('status','duplicate','request_id',existing.id,'action',requested_action,'action_status',existing.action_status);
  end if;
  if exists (
    select 1 from public.digital_observer_camera_action_requests
    where camera_source_id = source.id and task_kind = 'physical_command'
      and action_status in ('reconciliation_required','unknown')
  ) then return jsonb_build_object('status','blocked','reason','operator_reconciliation_required','action',requested_action); end if;

  select * into snapshot from public.digital_observer_camera_action_requests
  where observer_site_id = site.id and camera_source_id = source.id
    and task_kind = 'capability_snapshot' and action_status = 'completed'
    and result ->> 'reported_by_gateway' = 'true'
    and result #>> '{outcome_payload,executor_installed}' = 'true'
    and result #>> array['outcome_payload','capabilities',requested_action] = 'true'
    and (result #>> '{outcome_payload,verified_at}')::timestamptz >= requested_at - interval '5 minutes'
    and (result #>> '{outcome_payload,live,verified_at}')::timestamptz >= requested_at - interval '30 seconds'
    and result #>> '{outcome_payload,gateway_id}' = source.metadata ->> 'gateway_id'
    and result #>> '{outcome_payload,stream_id}' = source.metadata ->> 'gateway_stream_id'
    and result #> '{outcome_payload,channel}' = source.metadata -> 'dvr_channel'
  order by completed_at desc limit 1;
  if not found then return jsonb_build_object('status','blocked','reason','fresh_capability_evidence_required','action',requested_action); end if;

  if requested_action = 'lighting' then
    if exists (
      select 1 from public.digital_observer_camera_action_requests
      where camera_source_id = source.id and action_type = 'lighting'
        and authorization_kind = 'digital_guard_policy'
        and created_at >= requested_at - make_interval(secs => policy.lighting_cooldown_seconds)
    ) then return jsonb_build_object('status','blocked','reason','lighting_cooldown','action',requested_action); end if;
  else
    if exists (
      select 1 from public.digital_observer_camera_action_requests
      where camera_source_id = source.id and action_type = 'siren'
        and authorization_kind = 'digital_guard_policy'
        and created_at >= requested_at - make_interval(secs => policy.siren_cooldown_seconds)
    ) then return jsonb_build_object('status','blocked','reason','siren_cooldown','action',requested_action); end if;
    select count(*) into recent_count from public.digital_observer_camera_action_requests
    where camera_source_id = source.id and action_type = 'siren'
      and authorization_kind = 'digital_guard_policy' and created_at >= requested_at - interval '1 hour';
    if recent_count >= policy.siren_hourly_limit then
      return jsonb_build_object('status','blocked','reason','siren_hourly_limit','action',requested_action);
    end if;
  end if;

  capability := jsonb_build_object(
    'adapter', snapshot.result #>> '{outcome_payload,driver}', 'action', requested_action,
    'supported', true, 'executor_installed', true,
    'evidence_id', snapshot.result #>> '{outcome_payload,evidence_id}',
    'verified_at', snapshot.result #>> '{outcome_payload,verified_at}',
    'site_id', site.id, 'camera_id', source.id,
    'gateway_id', snapshot.result #>> '{outcome_payload,gateway_id}',
    'stream_id', snapshot.result #>> '{outcome_payload,stream_id}',
    'channel', snapshot.result #> '{outcome_payload,channel}',
    'source_generation', snapshot.result #>> '{outcome_payload,source_generation}',
    'binding_generation', snapshot.result #>> '{outcome_payload,binding_generation}',
    'live', snapshot.result #> '{outcome_payload,live}'
  );
  intent_digest := encode(extensions.digest(concat_ws('|', request_id::text, authorization_id::text,
    site.id::text, source.id::text, capability ->> 'gateway_id', capability ->> 'stream_id',
    capability ->> 'channel', capability ->> 'source_generation', capability ->> 'binding_generation',
    requested_action, requested_payload_digest, policy.id::text, signal.id::text, policy.approved_by::text,
    expires_at::text), 'sha256'::text), 'hex');

  insert into public.digital_observer_camera_action_requests (
    id,observer_site_id,camera_source_id,requested_by,confirmed_by,action_type,request_origin,action_status,
    parameters,capability_evidence,idempotency_key,expires_at,confirmed_at,task_kind,gateway_id,stream_id,channel,
    requested_at,payload_digest,confirmation_id,confirmation_expires_at,dispatch_intent_digest,
    source_generation,binding_generation,authorization_kind,automation_policy_id,automation_event_id
  ) values (
    request_id,site.id,source.id,policy.approved_by,policy.approved_by,requested_action,'digital_guard','approved',
    requested_payload,capability,concat('digital_guard:',signal.id,':',requested_action),expires_at,requested_at,
    'physical_command',capability ->> 'gateway_id',capability ->> 'stream_id',(capability ->> 'channel')::integer,
    requested_at,requested_payload_digest,authorization_id,expires_at,intent_digest,
    capability ->> 'source_generation',capability ->> 'binding_generation','digital_guard_policy',policy.id,signal.id
  );
  insert into public.immutable_audit_events (
    event_type,event_category,actor_profile_id,actor_role,target_type,target_id,camera_id,request_id,metadata,risk_level
  ) values (
    'digital_guard_autonomous_dispatch_intent_v1','camera',policy.approved_by,'digital_guard_policy',
    'digital_observer_camera_source',source.id,source.id,request_id::text,
    jsonb_build_object('schema','digital_guard_autonomous_dispatch_v1','site_id',site.id,'camera_id',source.id,
      'policy_id',policy.id,'event_id',signal.id,'event_type',event_type,'evidence_kind',evidence_kind,
      'action',requested_action,'payload_digest',requested_payload_digest,'authorization_id',authorization_id,
      'authorization_kind','digital_guard_policy','dispatch_intent_digest',intent_digest,
      'expires_at',expires_at,'siren_duration_ms',case when requested_action = 'siren' then 1000 else null end,
      'lighting_duration_ms',case when requested_action = 'lighting' then 20000 else null end),
    'critical'
  );
  return jsonb_build_object('status','queued','request_id',request_id,'action',requested_action,'action_status','approved');
end;
$$;

CREATE FUNCTION public.enqueue_digital_guard_capability_refresh_v1(signal_id uuid, requested_action text, requested_gateway_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  policy public.digital_observer_camera_automation_policies%rowtype;
  signal public.observer_intelligence_signals%rowtype;
  source public.digital_observer_camera_sources%rowtype;
  site public.observer_sites%rowtype;
  existing public.digital_observer_camera_action_requests%rowtype;
  request_id uuid := gen_random_uuid();
  requested_at timestamptz := clock_timestamp();
  expires_at timestamptz := requested_at + interval '119 seconds';
  observed_at timestamptz;
  local_time time;
  event_type text;
  evidence_kind text;
begin
  if requested_action not in ('lighting','siren')
    or requested_gateway_id !~ '^[A-Za-z0-9_-]{1,160}$' then
    return jsonb_build_object('status','blocked','reason','invalid_refresh_scope');
  end if;

  select * into signal from public.observer_intelligence_signals where id = signal_id;
  if not found then return jsonb_build_object('status','blocked','reason','event_not_found'); end if;
  event_type := signal.metadata ->> 'event_type';
  evidence_kind := signal.metadata ->> 'evidence_kind';
  begin observed_at := (signal.metadata ->> 'first_seen')::timestamptz;
  exception when others then return jsonb_build_object('status','blocked','reason','event_time_invalid'); end;
  if signal.metadata ->> 'validated_event' <> 'true'
    or observed_at > requested_at + interval '5 seconds'
    or observed_at < requested_at - interval '20 seconds' then
    return jsonb_build_object('status','blocked','reason','event_not_fresh_and_verified');
  end if;

  select * into policy from public.digital_observer_camera_automation_policies
  where observer_site_id = signal.observer_site_id
    and camera_source_id = (signal.metadata ->> 'camera_source_id')::uuid
    and enabled = true
  for update;
  if not found then return jsonb_build_object('status','blocked','reason','policy_disabled'); end if;
  if not requested_action = any(policy.allowed_actions) then
    return jsonb_build_object('status','blocked','reason','action_not_allowed');
  end if;
  if signal.confidence < (case when requested_action = 'siren'
      then policy.siren_minimum_confidence else policy.minimum_confidence end) then
    return jsonb_build_object('status','blocked','reason','confidence_too_low');
  end if;
  if requested_action = 'lighting' and not event_type = any(policy.lighting_event_types) then
    return jsonb_build_object('status','blocked','reason','event_not_allowed');
  end if;
  if requested_action = 'siren' and (not event_type = any(policy.siren_event_types)
      or evidence_kind <> 'line_crossing' or signal.severity <> 'critical') then
    return jsonb_build_object('status','blocked','reason','siren_requires_critical_line_crossing');
  end if;

  select * into site from public.observer_sites where id = policy.observer_site_id;
  select * into source from public.digital_observer_camera_sources
  where id = policy.camera_source_id and observer_site_id = policy.observer_site_id;
  if site.id is null or source.id is null or site.monitoring_enabled is not true
    or site.metadata ->> 'observer_monitoring_consent' <> 'true'
    or source.status not in ('connected','online','active','ready')
    or source.health_status not in ('healthy','online','connected','ok')
    or source.metadata ->> 'monitoring_enabled' = 'false'
    or source.metadata ->> 'gateway_id' <> requested_gateway_id
    or source.metadata ->> 'gateway_stream_id' is null
    or jsonb_typeof(source.metadata -> 'dvr_channel') <> 'number' then
    return jsonb_build_object('status','blocked','reason','camera_or_monitoring_offline');
  end if;
  local_time := (requested_at at time zone coalesce(site.timezone, 'Asia/Jerusalem'))::time;
  if policy.active_from < policy.active_until then
    if local_time < policy.active_from or local_time >= policy.active_until then
      return jsonb_build_object('status','blocked','reason','outside_active_schedule');
    end if;
  elsif local_time < policy.active_from and local_time >= policy.active_until then
    return jsonb_build_object('status','blocked','reason','outside_active_schedule');
  end if;

  select * into existing from public.digital_observer_camera_action_requests
  where observer_site_id = site.id and camera_source_id = source.id
    and task_kind = 'capability_snapshot' and action_status = 'completed'
    and result ->> 'reported_by_gateway' = 'true'
    and result #>> '{outcome_payload,executor_installed}' = 'true'
    and result #>> array['outcome_payload','capabilities',requested_action] = 'true'
    and (result #>> '{outcome_payload,verified_at}')::timestamptz >= requested_at - interval '5 minutes'
    and (result #>> '{outcome_payload,live,verified_at}')::timestamptz >= requested_at - interval '30 seconds'
    and result #>> '{outcome_payload,gateway_id}' = source.metadata ->> 'gateway_id'
    and result #>> '{outcome_payload,stream_id}' = source.metadata ->> 'gateway_stream_id'
    and result #> '{outcome_payload,channel}' = source.metadata -> 'dvr_channel'
  order by completed_at desc limit 1;
  if found then
    return jsonb_build_object('status','fresh','request_id',existing.id,'action',requested_action);
  end if;

  select * into existing from public.digital_observer_camera_action_requests
  where observer_site_id = site.id and camera_source_id = source.id
    and task_kind = 'capability_snapshot' and request_origin = 'digital_guard'
    and action_status in ('approved','delivered') and expires_at > requested_at
  order by created_at desc limit 1;
  if found then
    return jsonb_build_object('status','pending','request_id',existing.id,'action',requested_action);
  end if;

  insert into public.immutable_audit_events (
    id,event_type,event_category,actor_profile_id,actor_role,target_type,target_id,
    camera_id,request_id,metadata,risk_level
  ) values (
    request_id,'digital_guard_capability_refresh_request_v1','camera',policy.approved_by,
    'digital_guard_policy','digital_observer_camera_source',source.id,source.id,request_id::text,
    jsonb_build_object('schema','digital_guard_capability_refresh_v1','observer_site_id',site.id,
      'camera_id',source.id,'gateway_id',requested_gateway_id,'event_id',signal.id,
      'action',requested_action,'requested_at',requested_at,'expires_at',expires_at,
      'executed',false,'physical_confirmation',false),
    'low'
  );

  insert into public.digital_observer_camera_action_requests (
    id,observer_site_id,camera_source_id,requested_by,action_type,request_origin,action_status,
    parameters,capability_evidence,idempotency_key,expires_at,task_kind,gateway_id,stream_id,
    channel,requested_at,payload_digest,authorization_kind
  ) values (
    request_id,site.id,source.id,policy.approved_by,'capability_snapshot','digital_guard','approved',
    '{}'::jsonb,'{}'::jsonb,concat('digital_guard-capability:',signal.id),expires_at,
    'capability_snapshot',requested_gateway_id,source.metadata ->> 'gateway_stream_id',
    (source.metadata ->> 'dvr_channel')::integer,requested_at,null,'human_confirmation'
  );
  return jsonb_build_object('status','queued','request_id',request_id,'action',requested_action);
exception
  when unique_violation then
    select * into existing from public.digital_observer_camera_action_requests
    where idempotency_key = concat('digital_guard-capability:',signal_id)
    order by created_at desc limit 1;
    if found then return jsonb_build_object('status','pending','request_id',existing.id,'action',requested_action); end if;
    raise;
end;
$_$;

CREATE FUNCTION public.ensure_digital_observer_account(requested_name text DEFAULT NULL::text, requested_account_type text DEFAULT 'home'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  safe_type text := case when requested_account_type = 'business' then 'business' else 'home' end;
  auth_identity auth.users%rowtype;
begin
  if auth.uid() is null then return false; end if;

  select * into auth_identity
  from auth.users
  where id = auth.uid();

  if auth_identity.id is null or auth_identity.email_confirmed_at is null then
    return false;
  end if;

  insert into public.profiles (id, role, full_name, phone, must_change_password)
  values (
    auth_identity.id,
    'parent'::public.app_role,
    coalesce(
      nullif(btrim(requested_name), ''),
      nullif(btrim(auth_identity.raw_user_meta_data ->> 'full_name'), ''),
      auth_identity.email,
      'Digital Observer user'
    ),
    auth_identity.raw_user_meta_data ->> 'phone',
    false
  )
  on conflict (id) do update set
    full_name = coalesce(
      nullif(btrim(requested_name), ''),
      nullif(btrim(public.profiles.full_name), ''),
      nullif(btrim(auth_identity.raw_user_meta_data ->> 'full_name'), ''),
      auth_identity.email
    ),
    must_change_password = false,
    updated_at = now();

  insert into public.digital_observer_accounts (
    profile_id, account_type, status, onboarding_step, email_verified_at, metadata
  ) values (
    auth_identity.id,
    safe_type,
    'onboarding',
    'site',
    auth_identity.email_confirmed_at,
    jsonb_build_object(
      'product', 'digital_observer',
      'identity_separated_from_gan_batuach_role', true,
      'recovered_from_verified_identity', true
    )
  )
  on conflict (profile_id) do update set
    account_type = case
      when public.digital_observer_accounts.primary_site_id is null then excluded.account_type
      else public.digital_observer_accounts.account_type
    end,
    email_verified_at = coalesce(public.digital_observer_accounts.email_verified_at, excluded.email_verified_at),
    metadata = public.digital_observer_accounts.metadata || excluded.metadata,
    updated_at = now();

  return true;
end;
$$;

COMMENT ON FUNCTION public.ensure_digital_observer_account(requested_name text, requested_account_type text) IS 'Creates or repairs only the authenticated user own standalone Digital Observer account after email verification; preserves existing Gan Batuach roles and assignments.';

CREATE FUNCTION public.ensure_platform_subscription(target_garden_id uuid, requested_plan_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.kindergarten_subscriptions%rowtype; p public.subscription_plans%rowtype; today date:=current_date;
begin
  if public.can_manage_garden(target_garden_id) is distinct from true then raise exception 'garden_forbidden' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtext(target_garden_id::text));
  select * into s from public.kindergarten_subscriptions where garden_id=target_garden_id
    and status not in ('cancelled','expired') order by created_at desc limit 1 for update;
  if s.id is not null then return jsonb_build_object('id',s.id,'status',s.status,'existing',true); end if;
  select * into p from public.subscription_plans where id=coalesce(requested_plan_id,
    (select id from public.subscription_plans where is_default and active order by created_at desc limit 1))
    and active and (effective_from is null or effective_from<=today)
    and (effective_until is null or effective_until>today);
  if p.id is null then raise exception 'active_plan_not_found'; end if;
  insert into public.kindergarten_subscriptions(garden_id,plan_id,status,plan_type,start_date,
    billing_status,billing_cycle,provider,plan_code_snapshot,plan_version_snapshot,
    unit_price_snapshot,currency_snapshot,billing_interval,commitment_months,commitment_start,
    commitment_end,current_period_start,current_period_end,renewal_date,activation_source,created_by,updated_by)
  values(target_garden_id,p.id,'pending_payment',p.plan_type,today,'pending_payment',p.billing_interval,
    'manual',p.code,p.version,case when p.billing_interval='monthly' then coalesce(p.monthly_price,p.price_amount)
      else coalesce(p.annual_price,p.price_amount) end,p.currency,p.billing_interval,p.commitment_months,
    null,null,today,
    (today+case when p.billing_interval='monthly' then interval '1 month' else interval '1 year' end)::date,
    (today+case when p.billing_interval='monthly' then interval '1 month' else interval '1 year' end)::date,
    'pending_provider',auth.uid(),auth.uid()) returning * into s;
  insert into public.platform_subscription_events(subscription_id,garden_id,action,next_status,actor_id,source,period_start,period_end)
    values(s.id,target_garden_id,'created','pending_payment',auth.uid(),'garden',s.current_period_start,s.current_period_end);
  return jsonb_build_object('id',s.id,'status',s.status,'existing',false);
end $$;

CREATE FUNCTION public.ensure_tuition_billing_period(target_enrollment_id uuid, target_month date, agreed_partial_amount numeric DEFAULT NULL::numeric, partial_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e public.child_kindergarten_enrollments; p public.tuition_billing_periods; c public.children; g public.gardens;
  activation_evidence public.enrollment_payment_evidence;
  request_price numeric(12,2); group_price numeric(12,2); chosen_price numeric(12,2); chosen_source text;
  month_start date:=date_trunc('month',target_month)::date; month_end date:=(date_trunc('month',target_month)+interval '1 month - 1 day')::date;
  partial_period boolean; period_amount numeric(12,2);
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(target_enrollment_id::text,0));
  select * into e from public.child_kindergarten_enrollments where id=target_enrollment_id for update;
  if e.id is null or public.can_manage_garden(e.garden_id) is distinct from true then raise exception 'tuition_enrollment_denied' using errcode='42501'; end if;
  select * into p from public.tuition_billing_periods where enrollment_id=e.id and period_start=month_start;
  if p.id is not null then return public.tuition_period_projection(p); end if;
  if e.status<>'active' or e.start_date is null or month_end<e.start_date or (e.end_date is not null and month_start>e.end_date) then
    raise exception 'tuition_period_not_eligible' using errcode='23514';
  end if;
  partial_period:=e.start_date>month_start or (e.end_date is not null and e.end_date<month_end);
  if partial_period and (agreed_partial_amount is null or agreed_partial_amount<0 or partial_reason is null or length(trim(partial_reason))<3) then
    raise exception 'tuition_partial_period_review_required' using errcode='23514';
  end if;
  if not partial_period and agreed_partial_amount is not null then raise exception 'tuition_full_period_override_denied' using errcode='23514'; end if;
  select * into c from public.children where id=e.child_id and garden_id=e.garden_id;
  select * into g from public.gardens where id=e.garden_id;
  select * into activation_evidence from public.enrollment_payment_evidence where id=e.activation_payment_evidence_id and garden_id=e.garden_id;
  select r.published_price_snapshot into request_price from public.kindergarten_enrollment_requests r where r.id=e.enrollment_request_id;
  select fg.monthly_fee into group_price from public.kindergarten_fee_groups fg where fg.id=coalesce(c.payment_group_id,e.age_group_id) and fg.garden_id=e.garden_id;
  if e.tuition_unit_price_snapshot is null and request_price is null and month_start<date_trunc('month',current_date)::date then
    raise exception 'historical_tuition_price_requires_review' using errcode='23514';
  end if;
  if e.tuition_unit_price_snapshot is not null then chosen_price:=e.tuition_unit_price_snapshot; chosen_source:=e.tuition_price_source;
  elsif request_price is not null then chosen_price:=request_price; chosen_source:='enrollment_request_snapshot';
  elsif c.custom_monthly_fee is not null and (c.arrangement_valid_until is null or c.arrangement_valid_until>=month_start) then chosen_price:=c.custom_monthly_fee; chosen_source:='child_agreement';
  elsif group_price is not null and group_price>0 then chosen_price:=group_price; chosen_source:='garden_fee_group';
  elsif c.monthly_fee>0 then chosen_price:=c.monthly_fee; chosen_source:='child_legacy_fee';
  else raise exception 'tuition_price_not_configured' using errcode='23514'; end if;
  if e.tuition_unit_price_snapshot is null then
    update public.child_kindergarten_enrollments set tuition_unit_price_snapshot=chosen_price,tuition_price_source=chosen_source where id=e.id;
  end if;
  period_amount:=case when partial_period then agreed_partial_amount else chosen_price end;
  insert into public.tuition_billing_periods(garden_id,enrollment_id,child_id,period_start,period_end,due_at,base_amount,price_source,status,reconciliation_reason)
  values(e.garden_id,e.id,e.child_id,month_start,month_end,
    case when g.tuition_due_day is null then null else make_date(extract(year from month_start)::int,extract(month from month_start)::int,
      least(g.tuition_due_day,extract(day from month_end)::int)) end,period_amount,
    case when partial_period then 'manager_agreed_partial_period' else chosen_source end,
    case when period_amount=0 then 'waived'
      when partial_period or (activation_evidence.id is not null and activation_evidence.covered_from<=month_end and activation_evidence.covered_until>=month_start) then 'reconciliation_required' else 'pending' end,
    case when period_amount=0 then null
      when partial_period then 'partial_period_amount_requires_review'
      when activation_evidence.id is not null and activation_evidence.covered_from<=month_end and activation_evidence.covered_until>=month_start then 'activation_evidence_requires_period_allocation' else null end)
  returning * into p;
  if partial_period then
    insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
    values(auth.uid(),public.current_role()::text,e.garden_id,'tuition_billing_periods',p.id,'tuition_partial_period_agreed',
      jsonb_build_object('agreed_amount',agreed_partial_amount,'reason',left(partial_reason,500)));
  end if;
  return public.tuition_period_projection(p);
end $$;

CREATE FUNCTION public.escalate_overdue_complaints(p_at timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.complaints%rowtype; processed integer:=0; reason text; reviewer uuid;
begin
  if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then
    raise exception 'service_role_required' using errcode='42501';
  end if;
  if p_limit not between 1 and 500 then raise exception 'invalid_batch_size' using errcode='23514'; end if;
  -- Current Inspector authority wins over the historical assignee. Suspended/reassigned cases go to Admin.
  for c in select c.* from public.complaints c join public.gardens g on g.id=c.garden_id
    where c.status::text not in ('closed','resolved') and c.routing_state in ('inspector','admin_queue','unrouted') and
      (c.assigned_inspector_id is distinct from
        (case when public.is_approved_inspector(g.inspector_id) then g.inspector_id else null end)
       or c.routing_state is distinct from
        (case when public.is_approved_inspector(g.inspector_id) then 'inspector' else 'admin_queue' end))
    order by c.created_at,c.id for update of c skip locked limit p_limit
  loop
    select g.inspector_id into reviewer from public.gardens g where g.id=c.garden_id;
    if reviewer is not null and not public.is_approved_inspector(reviewer) then reviewer:=null; end if;
    if c.assigned_inspector_id is distinct from reviewer or c.routing_state is distinct from
      (case when reviewer is null then 'admin_queue' else 'inspector' end) then
      update public.complaints set assigned_inspector_id=reviewer,
        routing_state=case when reviewer is null then 'admin_queue' else 'inspector' end,revision=revision+1
        where id=c.id;
      update public.tasks set assigned_to=reviewer where source_entity_type='complaint' and source_entity_id=c.id
        and status::text not in ('done','cancelled');
      insert into public.complaint_events(complaint_id,garden_id,action,from_status,to_status)
        values(c.id,c.garden_id,case when reviewer is null then 'routed_admin_queue' else 'routed_inspector' end,c.status,c.status);
      insert into public.audit_logs(garden_id,entity_type,entity_id,action,after_data)
        values(c.garden_id,'complaints',c.id,'complaint_reassigned',jsonb_build_object('routing_state',case when reviewer is null then 'admin_queue' else 'inspector' end));
    end if;
  end loop;
  for c in select * from public.complaints
    where status::text not in ('closed','resolved','escalated') and sla_policy_id is not null
      and ((acknowledgement_due_at<p_at and acknowledged_at is null)
        or (response_due_at<p_at and last_response_at is null)
        or resolution_due_at<p_at)
    order by coalesce(acknowledgement_due_at,response_due_at,resolution_due_at),id
    for update skip locked limit p_limit
  loop
    reason:=case when c.acknowledgement_due_at<p_at and c.acknowledged_at is null then 'acknowledgement_overdue'
      when c.response_due_at<p_at and c.last_response_at is null then 'response_overdue' else 'resolution_overdue' end;
    update public.complaints set status='escalated',routing_state='admin_queue',escalated_at=p_at,revision=revision+1
      where id=c.id;
    update public.tasks set assigned_to=null,due_at=p_at where source_entity_type='complaint' and source_entity_id=c.id
      and status::text not in ('done','cancelled');
    insert into public.complaint_events(complaint_id,garden_id,action,from_status,to_status,internal_note)
      values(c.id,c.garden_id,'sla_escalated',c.status,'escalated',reason);
    insert into public.audit_logs(garden_id,entity_type,entity_id,action,after_data)
      values(c.garden_id,'complaints',c.id,'complaint_sla_escalated',jsonb_build_object('reason',reason));
    processed:=processed+1;
  end loop;
  return processed;
end; $$;

CREATE FUNCTION public.escalate_task(p_task_id uuid, p_reason text, p_actor_id uuid DEFAULT auth.uid()) RETURNS public.tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.tasks%rowtype; actor public.profiles%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into t from public.tasks where id=p_task_id for update;
  if t.id is null then raise exception 'task_not_found' using errcode='P0002'; end if;
  if not (public.is_admin() or (t.garden_id is not null and public.can_inspector_access_garden(t.garden_id))) then
    raise exception 'task_escalation_denied' using errcode='42501'; end if;
  if nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then
    raise exception 'reason_required' using errcode='23514'; end if;
  select * into actor from public.profiles where id=auth.uid() and active=true;
  if actor.id is null then raise exception 'active_actor_required' using errcode='42501'; end if;
  update public.tasks set escalated_at=now(),escalated_by=actor.id,escalation_reason=p_reason,
    priority='critical',updated_at=now() where id=t.id returning * into t;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(actor.id,actor.role,t.garden_id,'tasks',t.id,'task_escalated',jsonb_build_object('reason',p_reason));
  return t;
end; $$;

CREATE FUNCTION public.evaluate_classroom_staffing(target_classroom_id uuid, evaluation_date date DEFAULT CURRENT_DATE, projected_child_delta integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare room public.classrooms; child_count integer; projected_count integer; qualifying_count integer; shared_count integer;
declare version_count integer; unverified_count integer; rule_count integer; selected_version public.staffing_policy_versions; selected_rule public.staffing_policy_rules; required_count integer; state text;
begin
  select * into room from public.classrooms where id=target_classroom_id and status='active';
  if room.id is null then raise exception 'classroom_not_found' using errcode='P0002'; end if;
  if not public.can_access_garden(room.garden_id) then raise exception 'classroom_staffing_denied' using errcode='42501'; end if;
  select count(*)::integer into child_count from public.child_classroom_assignments a
    left join public.child_kindergarten_enrollments e on e.id=a.enrollment_id
    where a.classroom_id=room.id and a.is_current and (a.enrollment_id is null or e.status='active');
  projected_count:=greatest(child_count+projected_child_delta,0);
  select count(distinct a.staff_id)::integer into qualifying_count
    from public.staff_classroom_assignments a
    join public.staff s on s.id=a.staff_id and s.garden_id=room.garden_id and coalesce(s.approved_to_work,false)
    join public.staff_kindergarten_employments e on e.id=a.employment_id and e.staff_id=s.id and e.garden_id=room.garden_id and e.status='active'
    where a.classroom_id=room.id and a.garden_id=room.garden_id and a.status='active';
  select count(*)::integer into shared_count from (
    select a.staff_id from public.staff_classroom_assignments a
    where a.status='active' and a.staff_id in (select staff_id from public.staff_classroom_assignments where classroom_id=room.id and status='active')
    group by a.staff_id having count(distinct a.classroom_id)>1
  ) shared;
  select count(*)::integer into version_count from public.staffing_policy_versions v join public.staffing_policy_sets p on p.id=v.policy_set_id
    where v.status='active' and v.provenance_status='approved' and p.jurisdiction='IL'
      and (p.program_type is null or p.program_type=coalesce(room.metadata->>'program_type',p.program_type))
      and v.effective_from<=evaluation_date and (v.effective_until is null or v.effective_until>=evaluation_date);
  select count(*)::integer into unverified_count from public.staffing_policy_versions v join public.staffing_policy_sets p on p.id=v.policy_set_id
    where v.status<>'retired' and (v.provenance_status<>'approved' or v.status<>'active') and p.jurisdiction='IL'
      and (v.effective_from is null or v.effective_from<=evaluation_date) and (v.effective_until is null or v.effective_until>=evaluation_date);
  if version_count=0 then
    return jsonb_build_object('status',case when unverified_count>0 then 'policy_unverified' else 'policy_not_configured' end,'classroom_id',room.id,'garden_id',room.garden_id,'evaluation_date',evaluation_date,'child_count',child_count,'projected_child_count',projected_count,'required_staff',null,'qualifying_staff',qualifying_count,'deficit',null,'policy',null,'legal_compliance',null);
  elsif version_count>1 then
    return jsonb_build_object('status','policy_conflict','classroom_id',room.id,'garden_id',room.garden_id,'evaluation_date',evaluation_date,'child_count',child_count,'projected_child_count',projected_count,'required_staff',null,'qualifying_staff',qualifying_count,'deficit',null,'policy',null,'legal_compliance',null);
  end if;
  select v.* into selected_version from public.staffing_policy_versions v join public.staffing_policy_sets p on p.id=v.policy_set_id
    where v.status='active' and v.provenance_status='approved' and p.jurisdiction='IL'
      and (p.program_type is null or p.program_type=coalesce(room.metadata->>'program_type',p.program_type))
      and v.effective_from<=evaluation_date and (v.effective_until is null or v.effective_until>=evaluation_date);
  select count(*)::integer into rule_count from public.staffing_policy_rules r where r.policy_version_id=selected_version.id
    and (r.age_group_key is null or r.age_group_key=room.age_group_key)
    and (r.min_age_months is null or room.min_age_months is null or room.min_age_months>=r.min_age_months)
    and (r.max_age_months is null or room.max_age_months is null or room.max_age_months<=r.max_age_months)
    and projected_count>=r.child_count_from and (r.child_count_until is null or projected_count<=r.child_count_until);
  if rule_count=0 then state:='policy_not_configured';
  elsif rule_count>1 then state:='policy_conflict';
  else
    select * into selected_rule from public.staffing_policy_rules r where r.policy_version_id=selected_version.id
      and (r.age_group_key is null or r.age_group_key=room.age_group_key)
      and (r.min_age_months is null or room.min_age_months is null or room.min_age_months>=r.min_age_months)
      and (r.max_age_months is null or room.max_age_months is null or room.max_age_months<=r.max_age_months)
      and projected_count>=r.child_count_from and (r.child_count_until is null or projected_count<=r.child_count_until);
    required_count:=case when projected_count=0 then 0 else greatest(selected_rule.minimum_staff,ceil(projected_count/selected_rule.children_per_staff)::integer) end;
    state:=case when shared_count>0 then 'staffing_data_incomplete' when qualifying_count<required_count then 'deficit' when qualifying_count=required_count then 'compliant' else 'surplus' end;
  end if;
  return jsonb_build_object('status',state,'classroom_id',room.id,'garden_id',room.garden_id,'evaluation_date',evaluation_date,
    'child_count',child_count,'projected_child_count',projected_count,'required_staff',required_count,'qualifying_staff',qualifying_count,
    'deficit',case when required_count is null then null else greatest(required_count-qualifying_count,0) end,
    'needs_scheduling_validation',shared_count>0,'qualification_basis','active_employment_and_classroom_assignment',
    'policy',jsonb_build_object('policy_version_id',selected_version.id,'version',selected_version.version,'rule_id',selected_rule.id,'rule_key',selected_rule.rule_key,
      'source_title',selected_version.source_title,'source_reference',selected_version.source_reference,'provenance_status',selected_version.provenance_status),
    'legal_compliance',case when state in ('compliant','surplus') then true when state='deficit' then false else null end);
end $$;

COMMENT ON FUNCTION public.evaluate_classroom_staffing(target_classroom_id uuid, evaluation_date date, projected_child_delta integer) IS 'Non-mutating current/projected Classroom staffing evaluation with policy provenance and fail-closed conflict handling.';

CREATE FUNCTION public.evaluate_staff_candidate_profile(target_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare candidate public.staff_candidate_profiles; blockers text[] := '{}'; percent integer := 0; docs_ready boolean;
begin
  if target_profile_id <> auth.uid() and not public.is_admin() then
    raise exception 'staff_candidate_profile_denied' using errcode='42501';
  end if;
  select * into candidate from public.staff_candidate_profiles where profile_id=target_profile_id;
  if candidate.profile_id is null then
    blockers := array_append(blockers, 'professional_profile_missing');
  else
    if nullif(btrim(coalesce(candidate.full_name,'')),'') is null then blockers := array_append(blockers, 'full_name_missing'); else percent := percent + 15; end if;
    if nullif(btrim(coalesce(candidate.city,'')),'') is null then blockers := array_append(blockers, 'city_missing'); else percent := percent + 15; end if;
    if nullif(btrim(coalesce(candidate.professional_role,'')),'') is null then blockers := array_append(blockers, 'professional_role_missing'); else percent := percent + 20; end if;
    if coalesce(array_length(candidate.qualification_keys,1),0)=0 then blockers := array_append(blockers, 'qualification_missing'); else percent := percent + 20; end if;
    if candidate.availability='{}'::jsonb then blockers := array_append(blockers, 'availability_missing'); else percent := percent + 15; end if;
    docs_ready := coalesce((candidate.document_status->>'required_documents_ready')::boolean,false);
    if not docs_ready then blockers := array_append(blockers, 'required_documents_pending'); else percent := percent + 15; end if;
  end if;
  return jsonb_build_object('profile_id',target_profile_id,'percentage',percent,'blockers',to_jsonb(blockers),'required_fields_complete',cardinality(blockers)=0,'status',case when candidate.matching_paused then 'paused' when cardinality(blockers)=0 then 'ready_for_matching' else 'incomplete' end,'documents_ready',docs_ready);
end $$;

CREATE FUNCTION public.expire_classroom_reservations(target_classroom_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare changed integer;
begin
  update public.classroom_seat_reservations set status='expired',released_at=now(),updated_at=now()
  where classroom_id=target_classroom_id and status='active' and expires_at is not null and expires_at<=now();
  get diagnostics changed=row_count;
  return changed;
end $$;

CREATE FUNCTION public.find_child_garden_matches(target_child_file_id uuid, target_city text DEFAULT NULL::text, target_query text DEFAULT NULL::text, evaluation_date date DEFAULT CURRENT_DATE) RETURNS TABLE(garden_id uuid, garden_name text, city text, public_address text, image_url text, enrollment_availability text, match_status text, reason_code text, matching_classrooms jsonb, available_seats integer, price_status text, monthly_price numeric, pending_request_status text, active_enrollment boolean, distance_km numeric, distance_status text, staffing_readiness text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare child_birth_date date; child_months integer;
begin
  if auth.uid() is null then raise exception 'child_discovery_unauthenticated' using errcode='42501'; end if;
  if not exists (
    select 1 from public.child_guardian_links link
    where link.guardian_profile_id=auth.uid() and link.permanent_child_file_id=target_child_file_id
      and link.status='active' and link.legal_authority=true
      and coalesce((link.access_scope->>'profile')::boolean,false)=true
      and (link.valid_until is null or link.valid_until>now())
  ) then raise exception 'child_discovery_denied' using errcode='42501'; end if;

  select birth_date into child_birth_date from public.permanent_child_files where id=target_child_file_id;
  if child_birth_date is null then raise exception 'child_discovery_birth_date_required' using errcode='22023'; end if;
  child_months := extract(year from age(evaluation_date, child_birth_date))::integer * 12
    + extract(month from age(evaluation_date, child_birth_date))::integer;

  return query
  with eligible_gardens as (
    select g.id,g.name,g.city,g.address,g.image_url,g.enrollment_availability
    from public.gardens g
    where g.status='active' and coalesce(g.public_profile_enabled,false)
      and coalesce(g.enrollment_availability,'accepting') in ('accepting','waitlist_only')
      and (target_city is null or btrim(target_city)='' or g.city ilike '%'||btrim(target_city)||'%')
      and (target_query is null or btrim(target_query)='' or g.name ilike '%'||btrim(target_query)||'%')
  ), room_rows as (
    select eg.id as target_garden_id,c.id,c.name,c.age_group_key,c.age_group_label,c.capacity_limit,
      count(a.id) filter (where a.is_current and (a.enrollment_id is null or enrollment.status='active'))::integer as occupied,
      count(res.id) filter (where res.status='active' and (res.expires_at is null or res.expires_at>now())
        and not exists (select 1 from public.child_classroom_assignments own where own.classroom_id=c.id and own.child_id=res.child_id and own.is_current))::integer as reserved
    from eligible_gardens eg join public.classrooms c on c.garden_id=eg.id and c.status='active'
      left join public.child_classroom_assignments a on a.classroom_id=c.id
      left join public.child_kindergarten_enrollments enrollment on enrollment.id=a.enrollment_id
      left join public.classroom_seat_reservations res on res.classroom_id=c.id
    where c.min_age_months is not null and c.max_age_months is not null
      and child_months between c.min_age_months and c.max_age_months
    group by eg.id,c.id,c.name,c.age_group_key,c.age_group_label,c.capacity_limit
  ), matches as (
    select rr.target_garden_id,
      jsonb_agg(jsonb_build_object(
        'id',rr.id,'name',rr.name,'age_group_key',rr.age_group_key,'age_group_label',rr.age_group_label,
        'availability',case when rr.capacity_limit is null then 'not_configured' when greatest(rr.capacity_limit-rr.occupied-rr.reserved,0)=0 then 'full' when greatest(rr.capacity_limit-rr.occupied-rr.reserved,0)<=3 then 'limited' else 'available' end,
        'available_seats',case when rr.capacity_limit is null then null else greatest(rr.capacity_limit-rr.occupied-rr.reserved,0) end
      ) order by rr.name) as rooms,
      case when bool_or(rr.capacity_limit is null) then null else sum(greatest(rr.capacity_limit-rr.occupied-rr.reserved,0))::integer end as seats,
      bool_or(rr.capacity_limit is null or greatest(rr.capacity_limit-rr.occupied-rr.reserved,0)>0) as has_capacity
    from room_rows rr group by rr.target_garden_id
  ), fee as (
    select fg.garden_id,min(fg.monthly_fee) filter (where fg.show_price_public and fg.monthly_fee is not null) as public_price
    from public.kindergarten_fee_groups fg where fg.active=true group by fg.garden_id
  ), request_state as (
    select r.garden_id,max(r.status) as status
    from public.kindergarten_enrollment_requests r
    where r.parent_id=auth.uid() and r.child_profile_id=target_child_file_id
      and r.status in ('draft','submitted','under_review','information_required','resubmitted','waitlisted','payment_reconciliation_required','approved','awaiting_payment')
    group by r.garden_id
  ), active_state as (
    select e.garden_id,true as is_active from public.child_kindergarten_enrollments e
    where e.permanent_child_file_id=target_child_file_id and e.status='active'
  )
  select eg.id,eg.name,eg.city,eg.address,eg.image_url,eg.enrollment_availability,
    case when active_state.is_active then 'already_enrolled'
      when request_state.status is not null then 'pending_request'
      when eg.enrollment_availability='waitlist_only' then 'waitlist_only'
      when coalesce(matches.has_capacity,false) then 'eligible'
      else 'full' end,
    case when active_state.is_active then 'active_enrollment'
      when request_state.status is not null then 'pending_request'
      when eg.enrollment_availability='waitlist_only' then 'waitlist_only'
      when matches.target_garden_id is null then 'age_mismatch'
      when not coalesce(matches.has_capacity,false) then 'full' else 'eligible' end,
    coalesce(matches.rooms,'[]'::jsonb),matches.seats,
    case when fee.public_price is null then 'price_not_configured' else 'configured' end,fee.public_price,
    request_state.status,coalesce(active_state.is_active,false),null::numeric,'distance_unavailable',
    'policy_not_configured'
  from eligible_gardens eg
  left join matches on matches.target_garden_id=eg.id
  left join fee on fee.garden_id=eg.id
  left join request_state on request_state.garden_id=eg.id
  left join active_state on active_state.garden_id=eg.id
  order by case when active_state.is_active then 0 when request_state.status is not null then 1 when eg.enrollment_availability='accepting' and coalesce(matches.has_capacity,false) then 2 else 3 end,
    eg.city nulls last,eg.name;
end $$;

COMMENT ON FUNCTION public.find_child_garden_matches(target_child_file_id uuid, target_city text, target_query text, evaluation_date date) IS 'GB-M14 authorized Child-specific public Garden matching. It never reserves capacity and emits only whitelisted public fields.';

CREATE FUNCTION public.find_relevant_staff_jobs(target_city text DEFAULT NULL::text, target_role text DEFAULT NULL::text, target_age_group text DEFAULT NULL::text, target_query text DEFAULT NULL::text) RETURNS TABLE(id uuid, garden_id uuid, garden_name text, city text, role_needed text, qualification_keys text[], age_group text, employment_type text, description text, match_level text, match_reasons text[], application_status text, invitation_status text, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with candidate as (
    select * from public.staff_candidate_profiles where profile_id=auth.uid()
  ), openings as (
    select o.*, g.name as garden_name, g.city as garden_city
    from public.kindergarten_staff_openings o join public.gardens g on g.id=o.garden_id
    where o.active_status='published'
      and (target_city is null or g.city ilike '%' || target_city || '%')
      and (target_role is null or o.role_needed ilike '%' || target_role || '%')
      and (target_age_group is null or coalesce(o.age_group,'') ilike '%' || target_age_group || '%')
      and (target_query is null or concat_ws(' ',g.name,g.city,o.role_needed,o.description) ilike '%' || target_query || '%')
  )
  select o.id,o.garden_id,o.garden_name,o.garden_city,o.role_needed,o.qualification_keys,o.age_group,o.employment_type,o.description,
    case when coalesce(array_length(o.qualification_keys,1),0)=0 or o.qualification_keys <@ coalesce(c.qualification_keys,'{}') then 'exact_match' when coalesce(array_length(c.qualification_keys,1),0)=0 then 'profile_incomplete' else 'partial_match' end,
    array_remove(array[
      case when coalesce(c.professional_role,'')<>'' and lower(c.professional_role)=lower(o.role_needed) then 'profession_match' end,
      case when coalesce(array_length(o.qualification_keys,1),0)=0 or o.qualification_keys <@ coalesce(c.qualification_keys,'{}') then 'qualification_match' else 'missing_required_qualification' end,
      case when c.city is not null and lower(c.city)=lower(o.garden_city) then 'same_city' end,
      case when o.age_group is not null and o.age_group=any(coalesce(c.preferred_age_groups,'{}')) then 'preferred_age_group' end,
      case when c.city is null then 'location_unavailable' end
    ],null),
    app.status, null::text, o.created_at
  from openings o cross join candidate c
  left join public.staff_job_applications app on app.opening_id=o.id and app.staff_candidate_id=auth.uid() and app.status in ('draft','submitted','under_review','more_information_requested','approved_pending_completion','approved')
  where not c.matching_paused
  order by (coalesce(c.professional_role,'')=o.role_needed and (coalesce(array_length(o.qualification_keys,1),0)=0 or o.qualification_keys <@ coalesce(c.qualification_keys,'{}'))) desc, (c.city=o.garden_city) desc, o.created_at desc, o.id;
$$;

CREATE FUNCTION public.garden_onboarding_status(target_garden_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb; blockers text[] := '{}'; record public.kindergarten_onboarding_records%rowtype; garden public.gardens%rowtype; actor public.profiles%rowtype;
begin
  if not public.can_edit_garden_onboarding(target_garden_id) then raise exception 'onboarding_access_denied' using errcode='42501'; end if;
  select * into record from public.kindergarten_onboarding_records where garden_id=target_garden_id;
  select * into garden from public.gardens where id=target_garden_id;
  select * into actor from public.profiles where id=auth.uid();
  if record.id is null or garden.id is null then raise exception 'onboarding_not_found' using errcode='P0002'; end if;
  if coalesce(trim(garden.name),'')='' then blockers:=array_append(blockers,'garden_name'); end if;
  if coalesce(trim(garden.address),'')='' then blockers:=array_append(blockers,'address'); end if;
  if coalesce(trim(garden.phone),'')='' then blockers:=array_append(blockers,'phone'); end if;
  if actor.contact_verification_required and (actor.email_verified_at is null or actor.phone_verified_at is null) then blockers:=array_append(blockers,'identity_verification'); end if;
  if coalesce(jsonb_array_length(coalesce(record.profile_data->'selected_age_groups','[]'::jsonb)),0)=0 then blockers:=array_append(blockers,'age_groups'); end if;
  if coalesce(trim(record.profile_data->>'documents_summary'),'')='' then blockers:=array_append(blockers,'documents'); end if;
  if not exists(select 1 from public.kindergarten_legal_acceptances a where a.garden_id=target_garden_id and a.manager_profile_id=auth.uid() and a.accepted and a.acceptance_type='platform_terms') then blockers:=array_append(blockers,'platform_terms'); end if;
  if not exists(select 1 from public.kindergarten_legal_acceptances a where a.garden_id=target_garden_id and a.manager_profile_id=auth.uid() and a.accepted and a.acceptance_type='privacy_terms') then blockers:=array_append(blockers,'privacy_terms'); end if;
  result:=jsonb_build_object('garden_id',target_garden_id,'lifecycle_status',record.lifecycle_status,'current_step',record.current_step,
    'completed_stages',record.completed_steps,'progress_percent',record.progress_percent,'blockers',blockers,'can_activate',cardinality(blockers)=0,
    'registrant_type',record.registrant_type,'subscription',jsonb_build_object('provider','manual','status',record.payment_status,'live_collection',false));
  return result;
end $$;

CREATE FUNCTION public.get_monthly_inspection_draft(p_inspection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.inspections%rowtype; d jsonb;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into i from public.inspections where id=p_inspection_id;
  if i.id is null or i.inspector_id<>auth.uid() or not public.can_inspector_access_garden(i.garden_id) then
    raise exception 'inspection_not_authorized' using errcode='42501';
  end if;
  select answers into d from public.inspection_drafts where inspection_id=i.id;
  return jsonb_build_object('inspection_id',i.id,'answers',coalesce(d,'[]'::jsonb),'status',i.status);
end $$;

CREATE FUNCTION public.guard_camera_diagnostic_queue() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if old.task_kind <> new.task_kind then raise exception 'camera_queue_kind_immutable' using errcode = '23514'; end if;
    if old.task_kind <> 'legacy_command' then
      if row(old.id,old.observer_site_id,old.camera_source_id,old.gateway_id,old.stream_id,old.channel,old.source_generation,old.binding_generation,
             old.requested_by,old.action_type,old.requested_at,old.expires_at,old.parameters,old.capability_evidence,
             old.payload_digest,old.idempotency_key,old.request_origin,old.confirmation_nonce_hash,old.confirmation_expires_at,
             old.authorization_kind,old.automation_policy_id,old.automation_event_id)
         is distinct from
         row(new.id,new.observer_site_id,new.camera_source_id,new.gateway_id,new.stream_id,new.channel,new.source_generation,new.binding_generation,
             new.requested_by,new.action_type,new.requested_at,new.expires_at,new.parameters,new.capability_evidence,
             new.payload_digest,new.idempotency_key,new.request_origin,new.confirmation_nonce_hash,new.confirmation_expires_at,
             new.authorization_kind,new.automation_policy_id,new.automation_event_id) then
        raise exception 'camera_queue_request_immutable' using errcode = '23514';
      end if;
      if old.action_status <> 'awaiting_confirmation' and row(old.confirmation_id,old.confirmed_by,old.confirmed_at,old.dispatch_intent_digest)
        is distinct from row(new.confirmation_id,new.confirmed_by,new.confirmed_at,new.dispatch_intent_digest) then
        raise exception 'camera_queue_confirmation_immutable' using errcode = '23514';
      end if;
      if old.action_status in ('completed','reconciliation_required','unknown','failed','blocked','expired','cancelled') and old is distinct from new then
        raise exception 'camera_queue_result_immutable' using errcode = '23514';
      end if;
      if old.action_status is distinct from new.action_status and not (
        (old.action_status = 'awaiting_confirmation' and new.action_status in ('approved','blocked','expired','cancelled'))
        or (old.action_status = 'approved' and new.action_status in ('delivered','blocked','expired','cancelled'))
        or (old.action_status = 'delivered' and new.action_status in ('completed','reconciliation_required','unknown','failed','blocked','expired'))
      ) then raise exception 'camera_queue_transition_invalid' using errcode = '23514'; end if;
    end if;
  elsif new.task_kind <> 'legacy_command' then
    if new.result is not null or new.result_digest is not null then raise exception 'camera_queue_initial_state_invalid' using errcode = '23514'; end if;
    if new.task_kind = 'physical_command' and not (
      (new.authorization_kind = 'human_confirmation' and new.action_status = 'awaiting_confirmation')
      or (new.authorization_kind = 'digital_guard_policy' and new.action_status = 'approved')
    ) then raise exception 'camera_queue_initial_state_invalid' using errcode = '23514'; end if;
    if new.task_kind <> 'physical_command' and new.action_status not in ('approved','awaiting_confirmation') then
      raise exception 'camera_queue_initial_state_invalid' using errcode = '23514';
    end if;
    if new.requested_at > clock_timestamp() + interval '5 seconds' or new.expires_at <= clock_timestamp() then
      raise exception 'camera_queue_request_expired' using errcode = '23514';
    end if;
  end if;
  if new.task_kind <> 'legacy_command' and
     (tg_op = 'INSERT' or (new.action_status in ('approved','delivered','completed','reconciliation_required','unknown') and old.action_status is distinct from new.action_status)) then
    if (new.action_status not in ('completed','reconciliation_required','unknown') and new.expires_at <= clock_timestamp())
      or (new.action_status in ('completed','reconciliation_required','unknown')
        and new.expires_at + case when new.task_kind = 'physical_command' then interval '1 minute' else interval '0 seconds' end <= clock_timestamp()) then
      raise exception 'camera_queue_request_expired' using errcode = '23514';
    end if;
    if not exists (
      select 1 from public.digital_observer_camera_sources s
      where s.id = new.camera_source_id and s.observer_site_id = new.observer_site_id
        and s.metadata ->> 'gateway_id' = new.gateway_id
        and s.metadata ->> 'gateway_stream_id' = new.stream_id
        and s.metadata -> 'dvr_channel' = to_jsonb(new.channel)
    ) then raise exception 'camera_queue_binding_invalid' using errcode = '23514'; end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.guard_inspector_garden_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.inspector_id is not null and (tg_op='INSERT' or new.inspector_id is distinct from old.inspector_id)
    and not public.is_approved_inspector(new.inspector_id) then
    raise exception 'inspector_not_approved' using errcode='23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.guard_published_edge_release() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.release_state = 'PUBLISHED' and (
    new.release_id is distinct from old.release_id or new.version is distinct from old.version or
    new.build_sha is distinct from old.build_sha or new.signed_manifest is distinct from old.signed_manifest or
    new.artifact_sha256 is distinct from old.artifact_sha256 or new.signing_key_id is distinct from old.signing_key_id or
    new.platform is distinct from old.platform or new.architecture is distinct from old.architecture or
    new.deployment_profile is distinct from old.deployment_profile
  ) then raise exception 'PUBLISHED_EDGE_RELEASE_IMMUTABLE'; end if;
  new.updated_at = now(); return new;
end $$;

CREATE FUNCTION public.guard_used_inspection_form_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if exists(select 1 from public.inspections where form_id=new.form_id) then
    raise exception 'inspection_template_version_in_use' using errcode='23514';
  end if;
  return new;
end $$;

CREATE FUNCTION public.guard_used_inspection_question() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if exists(select 1 from public.inspections where form_id=old.form_id) then
    raise exception 'inspection_template_version_in_use' using errcode='23514';
  end if;
  return coalesce(new,old);
end $$;

CREATE FUNCTION public.handle_ai_event_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  manager_profile uuid;
  inspector_profile uuid;
  timeline_id uuid;
begin
  select manager_id, inspector_id into manager_profile, inspector_profile
  from public.gardens
  where id = new.garden_id;

  insert into public.incident_timeline (
    garden_id, entity_type, entity_id, event_type, title, body, severity, metadata
  )
  values (
    new.garden_id,
    'ai_event',
    new.id,
    'ai_event_detected',
    'אירוע AI: ' || new.event_type,
    coalesce(new.notes, 'אירוע תצפיתן AI זוהה ונדרש טיפול'),
    new.severity,
    new.metadata
  )
  returning id into timeline_id;

  update public.ai_events set incident_id = timeline_id where id = new.id;

  if manager_profile is not null then
    insert into public.ai_alerts (ai_event_id, garden_id, recipient_id, recipient_role, title, body)
    values (new.id, new.garden_id, manager_profile, 'manager', 'התראת תצפיתן AI', new.event_type);
  end if;

  if inspector_profile is not null and new.severity in ('high', 'critical') then
    insert into public.ai_alerts (ai_event_id, garden_id, recipient_id, recipient_role, title, body)
    values (new.id, new.garden_id, inspector_profile, 'inspector', 'אירוע AI חמור', new.event_type);
  end if;

  if new.severity = 'critical' then
    insert into public.tasks (garden_id, title, description, assigned_to, due_at, task_type, source_entity_type, source_entity_id, status)
    values (new.garden_id, 'טיפול מיידי באירוע AI', new.event_type, inspector_profile, now() + interval '2 hours', 'ai_incident', 'ai_event', new.id, 'open');
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.profiles (id, role, full_name, phone)
  values (
    new.id,
    coalesce((new.raw_app_meta_data->>'role')::public.app_role, 'parent'),
    coalesce(new.raw_user_meta_data->>'full_name', new.email, 'משתמש חדש'),
    new.raw_user_meta_data->>'phone'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

CREATE TABLE public.observer_site_learning_profiles (
    observer_site_id uuid NOT NULL,
    learning_status text DEFAULT 'collecting_baseline'::text NOT NULL,
    learning_maturity text DEFAULT 'new'::text NOT NULL,
    baseline_version text DEFAULT 'v0_mock'::text NOT NULL,
    confidence_level numeric(5,4) DEFAULT 0 NOT NULL,
    anomaly_readiness_score numeric(5,4) DEFAULT 0 NOT NULL,
    routine_confidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    confidence_trends jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT observer_site_learning_confidence_check CHECK ((((confidence_level >= (0)::numeric) AND (confidence_level <= (1)::numeric)) AND ((anomaly_readiness_score >= (0)::numeric) AND (anomaly_readiness_score <= (1)::numeric)))),
    CONSTRAINT observer_site_learning_maturity_check CHECK ((learning_maturity = ANY (ARRAY['new'::text, 'learning'::text, 'calibrated'::text, 'mature'::text]))),
    CONSTRAINT observer_site_learning_status_check CHECK ((learning_status = ANY (ARRAY['not_started'::text, 'collecting_baseline'::text, 'baseline_ready'::text, 'paused'::text, 'disabled'::text])))
);

CREATE FUNCTION public.initialize_digital_observer_learning(requested_site_id uuid) RETURNS public.observer_site_learning_profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  profile_row public.observer_site_learning_profiles;
begin
  if not public.can_manage_observer_site(requested_site_id) then
    raise exception 'OBSERVER_SITE_ACCESS_DENIED';
  end if;

  insert into public.observer_site_learning_profiles (
    observer_site_id,
    learning_status,
    learning_maturity,
    baseline_version,
    confidence_level,
    anomaly_readiness_score,
    routine_confidence,
    metadata
  ) values (
    requested_site_id,
    'collecting_baseline',
    'new',
    'v1_30_day_readiness',
    0,
    0,
    '{"status":"collecting","target_days":30}'::jsonb,
    '{"human_review_required":true,"no_raw_video_in_profile":true,"automatic_decisions":false}'::jsonb
  )
  on conflict (observer_site_id) do update set
    learning_status = case
      when public.observer_site_learning_profiles.learning_status in ('not_started', 'paused') then 'collecting_baseline'
      else public.observer_site_learning_profiles.learning_status
    end,
    updated_at = now()
  returning * into profile_row;

  insert into public.site_behavior_baselines (
    observer_site_id,
    baseline_type,
    baseline_value,
    confidence_level,
    learning_maturity,
    anomaly_readiness_score,
    source_summary,
    metadata
  )
  select
    requested_site_id,
    baseline_type,
    baseline_value,
    0,
    'new',
    0,
    '{"source":"camera_and_reviewed_events","minimum_learning_days":30}'::jsonb,
    '{"human_review_required":true,"no_identity_transfer_between_tenants":true}'::jsonb
  from (values
    ('normal_occupancy_patterns', '{"status":"collecting"}'::jsonb),
    ('normal_movement_patterns', '{"status":"collecting"}'::jsonb),
    ('normal_activity_levels', '{"status":"collecting"}'::jsonb),
    ('normal_active_hours', '{"status":"collecting"}'::jsonb),
    ('normal_camera_activity', '{"status":"collecting"}'::jsonb),
    ('normal_zone_usage', '{"status":"collecting"}'::jsonb)
  ) as baseline(baseline_type, baseline_value)
  on conflict (observer_site_id, baseline_type) where observer_site_id is not null do nothing;

  update public.observer_sites
  set learning_started_at = coalesce(learning_started_at, now()),
      learning_target_days = 30,
      observer_runtime_status = case
        when observer_runtime_status in ('active', 'suspended') then observer_runtime_status
        else 'learning_readiness'
      end,
      updated_at = now()
  where id = requested_site_id;

  return profile_row;
end;
$$;

CREATE FUNCTION public.inspection_attention_threshold() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select attention_score_below from public.inspection_product_settings where id=true
$$;

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.current_role() = 'admin'
$$;

CREATE FUNCTION public.is_approved_inspector(target_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.profiles p
    join public.inspector_applications a on a.profile_id=p.id
    join public.inspectors i on i.id=p.id
    where p.id=target_profile_id and p.role::text='inspector' and p.active=true
      and a.status='approved' and a.activated_at is not null
  );
$$;

CREATE FUNCTION public.iso_control_score(p_implementation text, p_evidence text, p_policy text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select round((
    case p_implementation when 'implemented' then 100 when 'partial' then 60 when 'not_applicable' then 100 when 'planned' then 25 else 0 end * 0.45
    + case p_evidence when 'approved' then 100 when 'collected' then 80 when 'partial' then 45 when 'expired' then 20 else 0 end * 0.35
    + case p_policy when 'approved' then 100 when 'draft' then 55 when 'needs_review' then 35 when 'not_required' then 100 else 0 end * 0.20
  ))::int
$$;

CREATE FUNCTION public.jwt_garden_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  select nullif(coalesce(auth.jwt() ->> 'kindergarten_id', auth.jwt() ->> 'garden_id'), '')::uuid
$$;

CREATE FUNCTION public.jwt_room_uuid() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  select nullif(auth.jwt() ->> 'room_uuid', '')::uuid
$$;

CREATE FUNCTION public.link_corrective_action_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.task_id is not null then
    update public.tasks set source_entity_type='corrective_action',source_entity_id=new.id
      where id=new.task_id and garden_id=new.garden_id;
    if not found then raise exception 'corrective_task_garden_mismatch' using errcode='23514'; end if;
  end if;
  return new;
end; $$;

CREATE FUNCTION public.management_gardens_for_current_user() RETURNS TABLE(garden_id uuid, garden_name text, relationship_role text, is_default boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with authorized as (
    select membership.garden_id, garden.name,
      case when bool_or(membership.relationship_role = 'owner') then 'owner' else 'manager' end as relationship_role,
      bool_or(membership.is_default) as is_default
    from public.garden_management_memberships membership
    join public.profiles profile on profile.id = membership.profile_id
    join public.gardens garden on garden.id = membership.garden_id
    where membership.profile_id = auth.uid()
      and membership.status = 'active'
      and profile.active is true
      and coalesce(garden.status::text, 'active') not in ('inactive', 'suspended', 'closed', 'rejected')
    group by membership.garden_id, garden.name
  )
  select authorized.garden_id, authorized.name, authorized.relationship_role, authorized.is_default
  from authorized
  order by authorized.is_default desc, authorized.garden_id
$$;

CREATE FUNCTION public.mark_observer_managed_device_unavailable(p_site uuid, p_gateway uuid, p_state text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare affected integer;
begin
  if p_state not in ('REVOKED','LOST','REPLACED','RETIRED') then raise exception 'MANAGED_DEVICE_STATE_INVALID'; end if;
  update public.digital_observer_camera_sources set status = 'readiness', health_status = 'offline',
    metadata = metadata || jsonb_build_object('active_monitoring',false,'managed_device_state',p_state,
      'managed_device_failure','DEVICE_CREDENTIAL_REVOKED'), updated_at = now()
  where observer_site_id = p_site and metadata->>'gateway_id' = p_gateway::text;
  get diagnostics affected = row_count;
  return affected;
end $$;

CREATE FUNCTION public.notify_role(p_garden_id uuid, p_role public.app_role, p_title text, p_body text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  inserted_count integer;
begin
  insert into public.notifications (garden_id, recipient_id, recipient_role, title, body, entity_type, entity_id)
  select p_garden_id, p.id, p.role, p_title, p_body, p_entity_type, p_entity_id
  from public.profiles p
  where p.active = true
    and p.role = p_role
    and (p_role = 'admin' or p.garden_id = p_garden_id or p.id in (
      select inspector_id from public.gardens where id = p_garden_id
    ));

  get diagnostics inserted_count = row_count;
  return inserted_count;
end;
$$;

CREATE FUNCTION public.observer_ai_job_ack_v1(p_worker_id text, p_job_id text, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare accepted integer;
begin
  if p_result->>'contract' <> 'observer-inference-result-v1' or p_result->>'job_id' <> p_job_id then raise exception 'observer_ai_result_invalid'; end if;
  if not exists(select 1 from public.observer_ai_jobs_shared where job_id=p_job_id and tenant_id=p_result->>'tenant_id' and site_id=p_result->>'site_id' and source_id=p_result->>'source_id') then raise exception 'observer_ai_result_scope_invalid'; end if;
  if exists(select 1 from public.observer_ai_results_shared where job_id=p_job_id) then return jsonb_build_object('acknowledged',true,'duplicate',true); end if;
  if not exists(select 1 from public.observer_ai_jobs_shared where job_id=p_job_id and state='CLAIMED' and lease_owner=p_worker_id and lease_expires_at>clock_timestamp()) then raise exception 'observer_ai_lease_invalid'; end if;
  insert into public.observer_ai_results_shared(result_id,job_id,payload) values(p_result->>'result_id',p_job_id,p_result) on conflict(job_id) do nothing;
  get diagnostics accepted = row_count;
  update public.observer_ai_jobs_shared set state='COMPLETED',completed_at=clock_timestamp(),lease_owner=null,lease_expires_at=null where job_id=p_job_id;
  return jsonb_build_object('acknowledged',true,'duplicate',accepted=0);
end $$;

CREATE FUNCTION public.observer_ai_job_claim_v1(p_worker_id text, p_tenant_ids text[], p_site_ids text[], p_capabilities text[], p_model_classes text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare claimed public.observer_ai_jobs_shared%rowtype;
begin
  update public.observer_ai_jobs_shared set state='PENDING',lease_owner=null,lease_expires_at=null where state='CLAIMED' and lease_expires_at <= clock_timestamp();
  update public.observer_ai_jobs_shared set state='EXPIRED',lease_owner=null,lease_expires_at=null,last_error='JOB_EXPIRED' where state in ('PENDING','RETRY_WAIT','CLAIMED') and expires_at <= clock_timestamp();
  select * into claimed from public.observer_ai_jobs_shared j
   where j.state in ('PENDING','RETRY_WAIT') and j.next_attempt_at <= clock_timestamp() and j.expires_at > clock_timestamp()
     and j.tenant_id = any(p_tenant_ids) and j.site_id = any(p_site_ids)
     and j.capability = any(p_capabilities) and j.model_class = any(p_model_classes)
     and not exists (select 1 from public.observer_ai_jobs_shared prior where prior.ordering_key=j.ordering_key and prior.observed_at<j.observed_at and prior.state in ('PENDING','RETRY_WAIT','CLAIMED'))
   order by case j.priority when 'CRITICAL' then 5 when 'HIGH' then 4 when 'NORMAL' then 3 when 'LOW' then 2 else 1 end desc, j.created_at
   for update skip locked limit 1;
  if claimed.job_id is null then return null; end if;
  update public.observer_ai_jobs_shared set state='CLAIMED',lease_owner=p_worker_id,lease_expires_at=clock_timestamp()+interval '30 seconds',attempts=attempts+1 where job_id=claimed.job_id;
  return jsonb_build_object('job',claimed.payload,'attempt',claimed.attempts+1,'lease_expires_at',clock_timestamp()+interval '30 seconds');
end $$;

CREATE FUNCTION public.observer_ai_job_enqueue_v1(p_job jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare inserted_count integer; canonical_job_id text;
begin
  if p_job->>'contract' <> 'observer-ai-job-v1' or p_job->>'canonical_event' <> 'false' then raise exception 'observer_ai_job_contract_invalid'; end if;
  insert into public.observer_ai_jobs_shared(job_id,idempotency_key,tenant_id,site_id,source_id,ordering_key,priority,capability,model_class,observed_at,expires_at,payload)
  values (p_job->>'job_id',p_job->>'idempotency_key',p_job->>'tenant_id',p_job->>'site_id',p_job->>'source_id',p_job->>'ordering_key',p_job->>'priority',p_job->>'requested_capability',p_job->>'model_class',(p_job->>'observation_timestamp')::timestamptz,(p_job->>'expires_at')::timestamptz,p_job)
  on conflict (idempotency_key) do nothing;
  get diagnostics inserted_count = row_count;
  select job_id into canonical_job_id from public.observer_ai_jobs_shared where idempotency_key=p_job->>'idempotency_key';
  return jsonb_build_object('inserted', inserted_count = 1, 'job_id', canonical_job_id);
end $$;

CREATE FUNCTION public.observer_ai_job_fail_v1(p_worker_id text, p_job_id text, p_classification text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare pending public.observer_ai_jobs_shared%rowtype; max_attempts integer;
begin
  select * into pending from public.observer_ai_jobs_shared where job_id=p_job_id and state='CLAIMED' and lease_owner=p_worker_id and lease_expires_at>clock_timestamp() for update;
  if pending.job_id is null then raise exception 'observer_ai_lease_invalid'; end if;
  max_attempts := greatest(1,least(10,coalesce((pending.payload#>>'{retry_policy,max_attempts}')::integer,3)));
  if p_classification <> 'RETRYABLE' or pending.attempts >= max_attempts then
    update public.observer_ai_jobs_shared set state='DEAD_LETTER',lease_owner=null,lease_expires_at=null,last_error=left(p_reason,96) where job_id=p_job_id;
    return jsonb_build_object('state','DEAD_LETTER');
  end if;
  update public.observer_ai_jobs_shared set state='RETRY_WAIT',next_attempt_at=clock_timestamp()+interval '1 second',lease_owner=null,lease_expires_at=null,last_error=left(p_reason,96) where job_id=p_job_id;
  return jsonb_build_object('state','RETRY_WAIT');
end $$;

CREATE FUNCTION public.observer_ai_job_result_v1(p_job_id text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select payload from public.observer_ai_results_shared where job_id=p_job_id $$;

CREATE FUNCTION public.observer_ai_queue_recover_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare recovered integer;
begin update public.observer_ai_jobs_shared set state='PENDING',lease_owner=null,lease_expires_at=null where state='CLAIMED' and lease_expires_at<=clock_timestamp(); get diagnostics recovered=row_count; return jsonb_build_object('recovered',recovered); end $$;

CREATE FUNCTION public.observer_ai_queue_snapshot_v1() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('backend','POSTGRES_SHARED_TRANSACTIONAL','queue_depth',coalesce(sum(n) filter(where state in ('PENDING','RETRY_WAIT','CLAIMED')),0),'states',coalesce(jsonb_object_agg(state,n),'{}'::jsonb))
  from (select state,count(*) n from public.observer_ai_jobs_shared group by state) q $$;

CREATE FUNCTION public.observer_control_effect_once_v1(p_resource_id text, p_tenant_id text, p_site_id text, p_owner_id text, p_epoch bigint, p_effect_key text, p_effect_type text, p_payload_digest text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare inserted_count integer; current_lease public.observer_control_leases%rowtype;
begin
  select * into current_lease from public.observer_control_leases where resource_id=p_resource_id for update;
  if current_lease.resource_id is null or current_lease.tenant_id<>p_tenant_id or current_lease.site_id<>p_site_id or current_lease.owner_id<>p_owner_id or current_lease.epoch<>p_epoch or current_lease.expires_at<=clock_timestamp() then raise exception 'observer_control_fence_rejected'; end if;
  insert into public.observer_control_effects(effect_key,resource_id,tenant_id,site_id,owner_id,epoch,effect_type,payload_digest) values(p_effect_key,p_resource_id,p_tenant_id,p_site_id,p_owner_id,p_epoch,p_effect_type,p_payload_digest) on conflict(effect_key) do nothing;
  get diagnostics inserted_count=row_count;
  return jsonb_build_object('accepted',inserted_count=1,'duplicate',inserted_count=0);
end $$;

CREATE FUNCTION public.observer_control_lease_acquire_v1(p_resource_id text, p_tenant_id text, p_site_id text, p_owner_id text, p_lease_seconds integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare current_lease public.observer_control_leases%rowtype;
begin
  select * into current_lease from public.observer_control_leases where resource_id=p_resource_id;
  if current_lease.resource_id is not null and (current_lease.tenant_id<>p_tenant_id or current_lease.site_id<>p_site_id) then raise exception 'observer_control_scope_mismatch'; end if;
  insert into public.observer_control_leases(resource_id,tenant_id,site_id,owner_id,epoch,expires_at,updated_at)
  values(p_resource_id,p_tenant_id,p_site_id,p_owner_id,1,clock_timestamp()+make_interval(secs=>greatest(1,least(300,p_lease_seconds))),clock_timestamp())
  on conflict(resource_id) do update set
    owner_id=excluded.owner_id,
    epoch=case when observer_control_leases.owner_id=excluded.owner_id and observer_control_leases.expires_at>clock_timestamp() then observer_control_leases.epoch else observer_control_leases.epoch+1 end,
    expires_at=excluded.expires_at,
    updated_at=excluded.updated_at
  where observer_control_leases.tenant_id=excluded.tenant_id and observer_control_leases.site_id=excluded.site_id
    and (observer_control_leases.expires_at<=clock_timestamp() or observer_control_leases.owner_id=excluded.owner_id)
  returning * into current_lease;
  if current_lease.resource_id is null then
    select * into current_lease from public.observer_control_leases where resource_id=p_resource_id;
    return jsonb_build_object('acquired',false,'owner_id',current_lease.owner_id,'epoch',current_lease.epoch);
  end if;
  return jsonb_build_object('acquired',true,'owner_id',current_lease.owner_id,'epoch',current_lease.epoch);
end $$;

CREATE FUNCTION public.parent_corrective_action_summary(p_garden_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  if auth.uid() is null or not public.can_parent_access_garden(p_garden_id) then
    raise exception 'parent_garden_not_authorized' using errcode='42501';
  end if;
  select jsonb_build_object(
    'garden_id',p_garden_id,
    'open_count',count(*) filter(where status<>'done'),
    'resolved_count',count(*) filter(where status='done'),
    'overdue_count',count(*) filter(where status<>'done' and correction_due_at<now()),
    'last_updated_at',max(updated_at)
  ) into result from public.violations where garden_id=p_garden_id and inspection_id is not null;
  return result;
end $$;

CREATE FUNCTION public.platform_subscription_entitlements(target_garden_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.kindergarten_subscriptions%rowtype; p public.subscription_plans%rowtype;
begin
  if public.is_admin() is distinct from true and public.can_manage_garden(target_garden_id) is distinct from true then
    raise exception 'garden_forbidden' using errcode='42501';
  end if;
  select * into s from public.kindergarten_subscriptions
    where garden_id=target_garden_id and status::text not in ('cancelled','expired')
    order by created_at desc limit 1;
  if s.id is null then
    return jsonb_build_object('status','not_configured','commercial_access','legacy_compatible','features','{}'::jsonb,'provider_readiness','not_configured');
  end if;
  select * into p from public.subscription_plans where id=s.plan_id;
  return jsonb_build_object(
    'status',s.status::text,'plan_id',s.plan_id,'plan_code',s.plan_code_snapshot,
    'commercial_access',case when s.admin_override or s.status::text in ('active','trial','demo_active','grace_period') then 'enabled'
      when s.status::text in ('pending_payment','payment_failed','past_due') then 'limited' else 'suspended' end,
    'features',coalesce(p.enabled_features,'{}'::jsonb),
    'provider_readiness',case when s.provider::text='manual' then 'manual_or_not_configured' else 'provider_not_verified' end,
    'billing_interval',s.billing_interval,'commitment_end',s.commitment_end,
    'current_period_end',s.current_period_end);
end $$;

CREATE FUNCTION public.prevent_benchmark_run_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  raise exception 'PUBLISHED_BENCHMARK_RUN_IMMUTABLE';
end;
$$;

CREATE FUNCTION public.prevent_sealed_benchmark_dataset_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.sealed_at is not null then
    raise exception 'SEALED_BENCHMARK_DATASET_IMMUTABLE';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

CREATE FUNCTION public.process_monthly_inspection_reminders(p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(task_id uuid, action text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  t record;
  reminder_key text;
begin
  for t in
    select *
    from public.tasks
    where task_type = 'monthly_inspection'
      and status in ('open', 'in_progress')
      and due_at is not null
  loop
    if t.due_at < p_now then
      update public.tasks set status = 'overdue', updated_at = now() where id = t.id;
      perform public.notify_role(t.garden_id, 'inspector', 'ביקורת חודשית באיחור', t.title, 'task', t.id);
      perform public.notify_role(t.garden_id, 'admin', 'ביקורת חודשית באיחור', t.title, 'task', t.id);
      task_id := t.id;
      action := 'marked_overdue';
      return next;
    elsif t.due_at - p_now <= interval '24 hours' then
      reminder_key := '24h';
    elsif t.due_at - p_now <= interval '3 days' then
      reminder_key := '3d';
    elsif t.due_at - p_now <= interval '7 days' then
      reminder_key := '7d';
    else
      reminder_key := null;
    end if;

    if reminder_key is not null and not exists (
      select 1 from public.notifications n
      where n.entity_type = 'task'
        and n.entity_id = t.id
        and n.metadata->>'reminder_key' = reminder_key
    ) then
      insert into public.notifications (garden_id, recipient_id, recipient_role, title, body, entity_type, entity_id, metadata)
      values (t.garden_id, t.assigned_to, 'inspector', 'תזכורת ביקורת חודשית', t.title, 'task', t.id, jsonb_build_object('reminder_key', reminder_key));
      task_id := t.id;
      action := 'reminder_' || reminder_key;
      return next;
    end if;
  end loop;
end;
$$;

CREATE FUNCTION public.public_age_group_availability(target_garden_id uuid) RETURNS TABLE(age_group_key text, age_group_label text, active_classrooms integer, available integer, availability text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select rows.age_group_key,max(rows.age_group_label),count(*)::integer,
    case when bool_or(rows.available is null) then null else sum(rows.available)::integer end,
    case when bool_or(rows.available is null) then 'not_configured' when sum(rows.available)=0 then 'full' when sum(rows.available)<=3 then 'limited' else 'available' end
  from public.public_classroom_availability(target_garden_id,null) rows
  group by rows.age_group_key order by rows.age_group_key
$$;

CREATE FUNCTION public.public_classroom_availability(target_garden_id uuid, target_age_group_key text DEFAULT NULL::text) RETURNS TABLE(classroom_id uuid, classroom_name text, age_group_key text, age_group_label text, availability text, available integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id,c.name,c.age_group_key,c.age_group_label,
    case when c.capacity_limit is null then 'not_configured' when (s->>'available')::integer=0 then 'full' when (s->>'available')::integer<=3 then 'limited' else 'available' end,
    case when c.capacity_limit is null then null else (s->>'available')::integer end
  from public.classrooms c join public.gardens g on g.id=c.garden_id
  cross join lateral public.classroom_capacity_status(c.id) s
  where c.garden_id=target_garden_id and c.status='active' and coalesce(g.public_profile_enabled,false)
    and (target_age_group_key is null or c.age_group_key=target_age_group_key)
  order by c.sort_order,c.name
$$;

CREATE FUNCTION public.rebind_video_gateway_enrollment(p_observer_site_id uuid, p_old_gateway_id uuid, p_new_gateway_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_source_count integer := 0;
  v_expired_request_count integer := 0;
  v_revoked_enrollment_count integer := 0;
  v_distinct_source_gateways integer := 0;
begin
  if p_old_gateway_id = p_new_gateway_id then
    raise exception 'gateway_rebind_identity_unchanged' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.video_gateway_device_enrollments enrollment
    where enrollment.observer_site_id = p_observer_site_id
      and enrollment.gateway_id = p_new_gateway_id
      and enrollment.status = 'delivered'
      and enrollment.refresh_token_hash is not null
  ) then
    raise exception 'gateway_rebind_new_enrollment_not_ready' using errcode = '23514';
  end if;

  select count(distinct source.metadata ->> 'gateway_id')
  into v_distinct_source_gateways
  from public.digital_observer_camera_sources source
  where source.observer_site_id = p_observer_site_id
    and coalesce(source.metadata ->> 'gateway_id', '') <> '';

  if v_distinct_source_gateways <> 1 or not exists (
    select 1
    from public.digital_observer_camera_sources source
    where source.observer_site_id = p_observer_site_id
      and source.metadata ->> 'gateway_id' = p_old_gateway_id::text
  ) then
    raise exception 'gateway_rebind_source_scope_ambiguous' using errcode = '23514';
  end if;

  update public.digital_observer_camera_sources source
  set metadata = jsonb_set(source.metadata, '{gateway_id}', to_jsonb(p_new_gateway_id::text), true),
      updated_at = now()
  where source.observer_site_id = p_observer_site_id
    and source.metadata ->> 'gateway_id' = p_old_gateway_id::text;
  get diagnostics v_source_count = row_count;

  if v_source_count = 0 then
    raise exception 'gateway_rebind_no_sources_updated' using errcode = '23514';
  end if;

  update public.digital_observer_camera_action_requests request
  set action_status = 'expired', updated_at = now()
  where request.observer_site_id = p_observer_site_id
    and request.gateway_id = p_old_gateway_id::text
    and request.action_status in ('approved', 'delivered');
  get diagnostics v_expired_request_count = row_count;

  update public.video_gateway_device_enrollments enrollment
  set status = 'revoked',
      refresh_token_hash = null,
      revoked_at = coalesce(enrollment.revoked_at, now()),
      updated_at = now()
  where enrollment.observer_site_id = p_observer_site_id
    and enrollment.gateway_id is distinct from p_new_gateway_id
    and enrollment.status in ('approved', 'delivered');
  get diagnostics v_revoked_enrollment_count = row_count;

  insert into public.immutable_audit_events (
    event_type,
    event_category,
    actor_profile_id,
    target_type,
    target_id,
    risk_level,
    metadata
  ) values (
    'video_gateway_reenrollment_rebound',
    'security',
    p_actor_profile_id,
    'observer_site',
    p_observer_site_id,
    'medium',
    jsonb_build_object(
      'old_gateway_id', p_old_gateway_id,
      'new_gateway_id', p_new_gateway_id,
      'source_count', v_source_count,
      'expired_request_count', v_expired_request_count,
      'revoked_enrollment_count', v_revoked_enrollment_count,
      'physical_actions_enabled', false,
      'physical_action_executed', false
    )
  );

  return jsonb_build_object(
    'source_count', v_source_count,
    'expired_request_count', v_expired_request_count,
    'revoked_enrollment_count', v_revoked_enrollment_count
  );
end;
$$;

COMMENT ON FUNCTION public.rebind_video_gateway_enrollment(p_observer_site_id uuid, p_old_gateway_id uuid, p_new_gateway_id uuid, p_actor_profile_id uuid) IS 'Atomically rebinds one unambiguous site Gateway, expires old queued work, revokes stale enrollments, and appends an immutable audit event.';

CREATE FUNCTION public.record_digital_observer_feedback(requested_signal_id uuid, requested_outcome text, requested_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  signal_row public.observer_intelligence_signals;
  learning_row public.observer_site_learning_profiles;
  feedback_id uuid;
  normalized_outcome text;
  confidence_change numeric(5,4);
begin
  select * into signal_row
  from public.observer_intelligence_signals
  where id = requested_signal_id;

  if signal_row.id is null or signal_row.observer_site_id is null then
    raise exception 'OBSERVER_SIGNAL_NOT_FOUND';
  end if;

  if not public.can_manage_observer_site(signal_row.observer_site_id) then
    raise exception 'OBSERVER_SITE_ACCESS_DENIED';
  end if;

  normalized_outcome := case requested_outcome
    when 'confirmed' then 'valid_detection'
    when 'dismissed' then 'false_positive'
    when 'resolved' then 'confirmed'
    when 'escalated' then 'escalated'
    else 'needs_more_data'
  end;

  confidence_change := case normalized_outcome
    when 'valid_detection' then 0.02
    when 'false_positive' then -0.03
    when 'escalated' then 0.01
    else 0
  end;

  select * into learning_row
  from public.observer_site_learning_profiles
  where observer_site_id = signal_row.observer_site_id;

  insert into public.learning_feedback_signals (
    observer_site_id,
    camera_id,
    source_type,
    source_id,
    event_type,
    review_outcome,
    confidence_delta,
    confidence_after,
    maturity_after,
    anomaly_readiness_after,
    metadata
  ) values (
    signal_row.observer_site_id,
    signal_row.camera_id,
    'observer_signal',
    signal_row.id,
    coalesce(signal_row.metadata->>'event_type', signal_row.signal_type, 'observer_event'),
    normalized_outcome,
    confidence_change,
    greatest(0, least(1, coalesce(learning_row.confidence_level, 0) + confidence_change)),
    coalesce(learning_row.learning_maturity, 'new'),
    coalesce(learning_row.anomaly_readiness_score, 0),
    jsonb_build_object(
      'reviewer_id', auth.uid(),
      'note', nullif(requested_note, ''),
      'scope', 'event_pattern_only',
      'does_not_whitelist_globally', true,
      'human_review_required', true
    )
  ) returning id into feedback_id;

  return feedback_id;
end;
$$;

COMMENT ON FUNCTION public.record_digital_observer_feedback(requested_signal_id uuid, requested_outcome text, requested_note text) IS 'Records site-scoped reviewed feedback. A dismissal never globally whitelists behavior and does not create an autonomous decision.';

CREATE FUNCTION public.record_digital_observer_incident_feedback(requested_incident_id uuid, requested_label text, requested_reason_code text DEFAULT NULL::text, requested_note text DEFAULT NULL::text, requested_source text DEFAULT 'PRODUCT_API'::text, requested_idempotency_key text DEFAULT NULL::text, requested_target_type text DEFAULT 'INCIDENT'::text, requested_target_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  incident_row public.observer_correlated_events;
  previous_id uuid;
  existing_id uuid;
  next_revision integer;
  feedback_id uuid;
  actor_role_value text;
  target_id_value uuid;
begin
  if auth.uid() is null then raise exception 'FEEDBACK_AUTH_REQUIRED'; end if;
  if requested_label not in (
    'TRUE_SECURITY_EVENT','TRUE_EXPECTED_ACTIVITY','FALSE_DETECTION','FALSE_CORRELATION',
    'FALSE_SPATIAL_EVENT','UNCERTAIN','OTHER'
  ) then raise exception 'FEEDBACK_LABEL_INVALID'; end if;
  if requested_source not in ('PRODUCT_UI','PRODUCT_API','INTERNAL_ADMIN') then raise exception 'FEEDBACK_SOURCE_INVALID'; end if;
  if requested_target_type not in ('INCIDENT','EVENT','VERIFICATION','DECISION','EVIDENCE') then raise exception 'FEEDBACK_TARGET_INVALID'; end if;
  if requested_idempotency_key is null or char_length(requested_idempotency_key) < 8 or char_length(requested_idempotency_key) > 120 then
    raise exception 'FEEDBACK_IDEMPOTENCY_INVALID';
  end if;
  if requested_note is not null and char_length(requested_note) > 500 then raise exception 'FEEDBACK_NOTE_TOO_LONG'; end if;
  if requested_reason_code is not null and char_length(requested_reason_code) > 80 then raise exception 'FEEDBACK_REASON_TOO_LONG'; end if;

  select * into incident_row from public.observer_correlated_events
  where id = requested_incident_id for update;
  if incident_row.id is null or incident_row.correlation_version <> 'do-track-v1' then
    raise exception 'CANONICAL_INCIDENT_NOT_FOUND';
  end if;
  if incident_row.provenance <> 'REAL_CAMERA_AI' then raise exception 'PRODUCTION_REAL_PROVENANCE_REQUIRED'; end if;
  if not public.can_label_digital_observer_site(incident_row.observer_site_id) then raise exception 'FEEDBACK_SITE_ACCESS_DENIED'; end if;

  target_id_value := coalesce(requested_target_id, incident_row.id);
  if (requested_target_type = 'INCIDENT' and target_id_value <> incident_row.id)
    or (requested_target_type = 'EVENT' and not (incident_row.related_event_ids @> array[target_id_value]))
    or (requested_target_type = 'VERIFICATION' and not exists (
      select 1 from public.digital_observer_incident_verifications item
      where item.id = target_id_value and item.incident_id = incident_row.id
    ))
    or (requested_target_type = 'DECISION' and not exists (
      select 1 from public.digital_observer_decision_intents item
      where item.id = target_id_value and item.incident_id = incident_row.id
    ))
    or (requested_target_type = 'EVIDENCE' and not exists (
      select 1 from public.digital_observer_event_clips item
      where item.id = target_id_value and item.observer_site_id = incident_row.observer_site_id
        and item.signal_id = any(incident_row.related_event_ids)
    )) then
    raise exception 'FEEDBACK_TARGET_SCOPE_MISMATCH';
  end if;

  select id into existing_id from public.digital_observer_feedback_revisions
  where actor_id = auth.uid() and idempotency_key = requested_idempotency_key;
  if existing_id is not null then return existing_id; end if;

  previous_id := incident_row.latest_feedback_revision_id;
  select coalesce(max(revision_number), 0) + 1 into next_revision
  from public.digital_observer_feedback_revisions where incident_id = incident_row.id;
  select coalesce(profile.role::text, 'observer_member') into actor_role_value
  from public.profiles profile where profile.id = auth.uid();

  insert into public.digital_observer_feedback_revisions (
    observer_site_id, incident_id, target_type, target_id, camera_source_id, label,
    actor_id, actor_role, reason_code, note, previous_feedback_id, revision_number,
    feedback_version, source, environment, incident_provenance, idempotency_key, metadata
  ) values (
    incident_row.observer_site_id, incident_row.id, requested_target_type, target_id_value,
    incident_row.primary_camera_source_id, requested_label, auth.uid(), coalesce(actor_role_value, 'observer_member'),
    nullif(requested_reason_code, ''), nullif(requested_note, ''), previous_id, next_revision,
    'do-feedback-v1', requested_source, 'PRODUCTION', incident_row.provenance,
    requested_idempotency_key,
    jsonb_build_object(
      'raw_feedback', true,
      'reviewed_ground_truth', false,
      'automatic_learning_applied', false,
      'model_mutated', false,
      'risk_mutated', false,
      'rules_mutated', false,
      'baseline_mutated', false
    )
  ) returning id into feedback_id;

  update public.observer_correlated_events set
    current_feedback_label = requested_label,
    latest_feedback_revision_id = feedback_id,
    feedback_updated_at = now(),
    updated_at = now()
  where id = incident_row.id;

  return feedback_id;
end;
$$;

COMMENT ON FUNCTION public.record_digital_observer_incident_feedback(requested_incident_id uuid, requested_label text, requested_reason_code text, requested_note text, requested_source text, requested_idempotency_key text, requested_target_type text, requested_target_id uuid) IS 'Records site-scoped raw Incident/Event/Verification/Decision/Evidence feedback without changing live model, Risk, rule, baseline, or Decision configuration.';

CREATE FUNCTION public.record_digital_observer_watch_rule_evaluation(requested_rule_id uuid, requested_rule_version integer, requested_event_id uuid, requested_incident_id uuid, requested_risk_evaluation_id uuid, requested_matched boolean, requested_matched_conditions jsonb, requested_non_match_reasons jsonb, requested_input_fingerprint text, requested_evaluated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  rule_row public.observer_watch_requests;
  event_row public.observer_intelligence_signals;
  incident_row public.observer_correlated_events;
  evaluation_id uuid;
begin
  if auth.role() <> 'service_role' then raise exception 'WATCH_RULE_EVALUATION_SERVICE_ONLY'; end if;
  select * into rule_row from public.observer_watch_requests where id = requested_rule_id;
  select * into event_row from public.observer_intelligence_signals where id = requested_event_id;
  if rule_row.id is null or event_row.id is null or rule_row.observer_site_id is null or event_row.observer_site_id is distinct from rule_row.observer_site_id
    or event_row.source_type <> 'system'
    or event_row.metadata->>'observation_provenance' <> 'REAL_CAMERA_AI'
    or coalesce((event_row.metadata->>'validated_event')::boolean, false) <> true then
    raise exception 'WATCH_RULE_EVALUATION_SCOPE_INVALID';
  end if;
  if requested_incident_id is not null then
    select * into incident_row from public.observer_correlated_events where id = requested_incident_id;
    if not found or incident_row.observer_site_id is distinct from rule_row.observer_site_id or incident_row.provenance <> 'REAL_CAMERA_AI' then
      raise exception 'WATCH_RULE_INCIDENT_SCOPE_INVALID';
    end if;
  end if;
  insert into public.digital_observer_watch_rule_evaluations (
    observer_site_id, rule_id, rule_version, event_id, incident_id, risk_evaluation_id,
    matched, matched_conditions, non_match_reasons, input_fingerprint,
    evaluation_version, event_provenance, evaluated_at, metadata
  ) values (
    rule_row.observer_site_id, rule_row.id, requested_rule_version, event_row.id,
    requested_incident_id, requested_risk_evaluation_id, requested_matched,
    coalesce(requested_matched_conditions, '[]'::jsonb), coalesce(requested_non_match_reasons, '[]'::jsonb),
    requested_input_fingerprint, 'do-watch-evaluator-v1', 'REAL_CAMERA_AI',
    coalesce(requested_evaluated_at, now()), jsonb_build_object('external_action_executed', false)
  ) on conflict (rule_id, rule_version, event_id) do nothing returning id into evaluation_id;
  if evaluation_id is not null and requested_matched then
    update public.observer_watch_requests set
      last_matched_at = coalesce(requested_evaluated_at, now()),
      match_count = match_count + 1,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('last_real_event_id', requested_event_id, 'last_real_incident_id', requested_incident_id)
    where id = rule_row.id and rule_version = requested_rule_version and active = true and rule_state = 'ACTIVE';
  end if;
  return jsonb_build_object('evaluation_id', evaluation_id, 'inserted', evaluation_id is not null, 'matched', requested_matched);
end;
$$;

CREATE FUNCTION public.record_manual_enrollment_arrangement(target_request_id uuid, target_method text, target_amount numeric, target_covered_from date, target_covered_until date, target_reference text DEFAULT NULL::text, target_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare req public.kindergarten_enrollment_requests; evidence public.enrollment_payment_evidence; key text; activation jsonb; reason text;
begin
  select * into req from public.kindergarten_enrollment_requests where id=target_request_id for update;
  if req.id is null then raise exception 'enrollment_request_not_found' using errcode='P0002'; end if;
  if not public.can_manage_garden(req.garden_id) then raise exception 'manual_payment_denied' using errcode='42501'; end if;
  if target_method not in ('bank_transfer','standing_order','checks') or target_amount<0 or target_covered_until<target_covered_from then raise exception 'invalid_manual_arrangement' using errcode='22023'; end if;
  key:='manual-enrollment:'||req.id::text;
  insert into public.enrollment_payment_evidence(garden_id,enrollment_request_id,evidence_kind,provider_mode,idempotency_key,status,manual_method,amount,covered_from,covered_until,reference,note,confirmed_at,recorded_by)
  values(req.garden_id,req.id,'manual_arrangement','manual',key,'confirmed',target_method,target_amount,target_covered_from,target_covered_until,nullif(btrim(target_reference),''),nullif(btrim(target_note),''),now(),auth.uid())
  on conflict(garden_id,idempotency_key) do update set updated_at=now()
  returning * into evidence;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(auth.uid(),public.current_role()::text,req.garden_id,'enrollment_payment_evidence',evidence.id,'manual_payment_arrangement_recorded',jsonb_build_object('request_id',req.id,'method',target_method,'covered_from',target_covered_from,'covered_until',target_covered_until));
  begin
    activation:=public.activate_enrollment_from_evidence(req.id,evidence.id);
    return activation;
  exception when others then
    reason:=sqlstate||':'||sqlerrm;
    update public.enrollment_payment_evidence set status='reconciliation_required',reconciliation_reason=left(reason,500),updated_at=now() where id=evidence.id;
    update public.kindergarten_enrollment_requests set status='payment_reconciliation_required',payment_status='reconciliation_required',updated_at=now() where id=req.id and status<>'activated';
    insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
    values(auth.uid(),public.current_role()::text,req.garden_id,'enrollment_payment_evidence',evidence.id,'enrollment_activation_reconciliation_required',jsonb_build_object('request_id',req.id,'reason_code',sqlstate));
    return jsonb_build_object('status','payment_reconciliation_required','payment_evidence_id',evidence.id,'reason_code',sqlstate,'idempotent',false);
  end;
end $$;

CREATE FUNCTION public.record_observer_managed_device_auth(p_enrollment uuid, p_credential_version integer, p_nonce_hash text, p_runtime_instance text, p_sequence bigint, p_observed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare device public.video_gateway_device_enrollments%rowtype;
declare session_class text;
begin
  if p_nonce_hash !~ '^[a-f0-9]{64}$' or p_runtime_instance !~ '^[A-Za-z0-9._:-]{8,160}$'
    or p_sequence < 0 or abs(extract(epoch from (now() - p_observed_at))) > 120 then
    raise exception 'MANAGED_DEVICE_AUTH_INPUT_INVALID';
  end if;
  select * into device from public.video_gateway_device_enrollments where id = p_enrollment for update;
  if not found or device.identity_scheme <> 'ED25519_V1' or device.status <> 'delivered'
    or device.lifecycle_state <> 'ACTIVE' or device.credential_version <> p_credential_version then
    raise exception 'MANAGED_DEVICE_NOT_ACTIVE';
  end if;
  insert into public.observer_managed_device_auth_nonces(enrollment_id, credential_version, nonce_hash, observed_at, expires_at)
    values(p_enrollment, p_credential_version, p_nonce_hash, p_observed_at, p_observed_at + interval '5 minutes');
  if device.active_runtime_instance_id is null then session_class := 'FIRST_SEEN';
  elsif device.active_runtime_instance_id = p_runtime_instance then
    if p_sequence <= coalesce(device.active_runtime_sequence, -1) then return 'MANAGED_DEVICE_STALE_SESSION'; end if;
    session_class := 'CONTINUATION';
  elsif device.last_seen_at is not null and p_observed_at - device.last_seen_at < interval '2 minutes' then
    update public.video_gateway_device_enrollments set clone_suspected_at = p_observed_at, updated_at = now() where id = p_enrollment;
    return 'MANAGED_DEVICE_CLONE_SUSPECTED';
  else session_class := 'RESTART';
  end if;
  update public.video_gateway_device_enrollments set active_runtime_instance_id = p_runtime_instance,
    active_runtime_sequence = p_sequence, last_seen_at = p_observed_at, updated_at = now()
  where id = p_enrollment;
  return session_class;
end $_$;

CREATE FUNCTION public.release_classroom_seat_reservation(target_reservation_id uuid) RETURNS public.classroom_seat_reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.classroom_seat_reservations;
begin
  select * into result from public.classroom_seat_reservations where id=target_reservation_id for update;
  if result.id is null then raise exception 'reservation_not_found' using errcode='P0002'; end if;
  if not public.can_manage_garden(result.garden_id) then raise exception 'classroom_capacity_denied' using errcode='42501'; end if;
  if result.status='active' then update public.classroom_seat_reservations set status='released',released_at=now(),updated_at=now() where id=result.id returning * into result; end if;
  return result;
end $$;

CREATE FUNCTION public.remove_digital_observer_demo_camera_bundle(requested_camera_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  source_row public.digital_observer_camera_sources;
  signal_ids uuid[] := '{}';
  deleted_signals integer := 0;
  deleted_clips integer := 0;
  deleted_rules integer := 0;
  deleted_candidates integer := 0;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;

  select * into source_row
  from public.digital_observer_camera_sources
  where id = requested_camera_source_id
  for update;

  if source_row.id is null then
    raise exception 'CAMERA_SOURCE_NOT_FOUND';
  end if;
  if not public.can_manage_observer_site(source_row.observer_site_id) then
    raise exception 'OBSERVER_SITE_ACCESS_DENIED';
  end if;
  if source_row.connector_type <> 'demo'
    or source_row.source_mode <> 'demo'
    or source_row.camera_stream_id is not null
    or source_row.secret_reference is not null
    or coalesce(source_row.metadata ->> 'gateway_stream_id', '') <> ''
    or coalesce(source_row.metadata ->> 'video_gateway_stream_id', '') <> ''
    or source_row.capabilities @> '{"live_view":true}'::jsonb then
    raise exception 'ONLY_SYNTHETIC_DEMO_CAMERA_CAN_BE_REMOVED';
  end if;

  if exists (
    select 1 from public.digital_observer_event_clips
    where camera_source_id = source_row.id
      and (storage_path is not null or snapshot_storage_path is not null)
  ) then
    raise exception 'DEMO_CAMERA_HAS_STORED_MEDIA';
  end if;

  select coalesce(array_agg(id), '{}') into signal_ids
  from public.observer_intelligence_signals
  where observer_site_id = source_row.observer_site_id
    and (
      metadata ->> 'camera_source_id' = source_row.id::text
      or (source_row.camera_stream_id is not null and camera_id = source_row.camera_stream_id)
    )
    and (
      metadata @> '{"qa_demo":true}'::jsonb
      or metadata @> '{"synthetic":true}'::jsonb
    );

  delete from public.digital_observer_notification_deliveries
  where signal_id = any(signal_ids)
    and metadata @> '{"qa_demo":true}'::jsonb;

  delete from public.digital_observer_event_clips
  where camera_source_id = source_row.id
    or signal_id = any(signal_ids);
  get diagnostics deleted_clips = row_count;

  delete from public.digital_observer_identity_candidates
  where camera_source_id = source_row.id
    and (
      metadata @> '{"qa_demo":true}'::jsonb
      or metadata @> '{"synthetic":true}'::jsonb
    );
  get diagnostics deleted_candidates = row_count;

  delete from public.observer_watch_requests
  where camera_source_id = source_row.id
    and (
      metadata @> '{"qa_demo":true}'::jsonb
      or metadata @> '{"synthetic":true}'::jsonb
    );
  get diagnostics deleted_rules = row_count;

  delete from public.observer_intelligence_signals
  where id = any(signal_ids);
  get diagnostics deleted_signals = row_count;

  delete from public.digital_observer_camera_sources
  where id = source_row.id;

  return jsonb_build_object(
    'camera_removed', true,
    'signals_removed', deleted_signals,
    'clips_removed', deleted_clips,
    'rules_removed', deleted_rules,
    'identity_candidates_removed', deleted_candidates
  );
end;
$$;

COMMENT ON FUNCTION public.remove_digital_observer_demo_camera_bundle(requested_camera_source_id uuid) IS 'Atomically removes one explicitly synthetic demo camera and only its synthetic dependent rows. Refuses Gateway/DVR sources and stored media.';

CREATE FUNCTION public.replace_observer_managed_device(p_site uuid, p_old_gateway uuid, p_new_gateway uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare old_device public.video_gateway_device_enrollments%rowtype;
declare new_device public.video_gateway_device_enrollments%rowtype;
declare affected integer;
begin
  if p_old_gateway = p_new_gateway then raise exception 'MANAGED_DEVICE_REPLACEMENT_UNCHANGED'; end if;
  select * into old_device from public.video_gateway_device_enrollments
    where observer_site_id = p_site and gateway_id = p_old_gateway and status = 'delivered' for update;
  select * into new_device from public.video_gateway_device_enrollments
    where observer_site_id = p_site and gateway_id = p_new_gateway and status = 'delivered'
      and identity_scheme = 'ED25519_V1' and lifecycle_state = 'ACTIVE' for update;
  if old_device.id is null or new_device.id is null or old_device.deployment_profile is distinct from new_device.deployment_profile then
    raise exception 'MANAGED_DEVICE_REPLACEMENT_SCOPE_INVALID';
  end if;
  update public.digital_observer_camera_sources set metadata = jsonb_set(metadata, '{gateway_id}', to_jsonb(p_new_gateway::text), true),
    updated_at = now() where observer_site_id = p_site and metadata->>'gateway_id' = p_old_gateway::text;
  get diagnostics affected = row_count;
  update public.video_gateway_device_enrollments set status = 'revoked', lifecycle_state = 'REPLACED',
    revocation_reason = 'AUTHORIZED_REPLACEMENT', revoked_at = now(), refresh_token_hash = null, updated_at = now()
    where id = old_device.id;
  update public.observer_managed_device_credentials set credential_state = 'REVOKED', revoked_at = now()
    where enrollment_id = old_device.id and credential_state in ('PENDING','ACTIVE');
  return jsonb_build_object('source_count',affected,'old_device_state','REPLACED','new_device_id',p_new_gateway);
end $$;

CREATE FUNCTION public.request_platform_subscription_cancellation(target_garden_id uuid, requested_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.kindergarten_subscriptions%rowtype; effective_at timestamptz;
begin
  if public.can_manage_garden(target_garden_id) is distinct from true then raise exception 'garden_forbidden' using errcode='42501'; end if;
  select * into s from public.kindergarten_subscriptions where garden_id=target_garden_id
    and status::text not in ('cancelled','expired') order by created_at desc limit 1 for update;
  if s.id is null then raise exception 'subscription_not_found'; end if;
  if s.cancellation_requested_at is not null then return jsonb_build_object('id',s.id,'status',s.status,'cancellation_effective_at',s.cancellation_effective_at); end if;
  effective_at := greatest(coalesce(s.current_period_end::timestamptz,s.expires_at,now()),
    coalesce(s.commitment_end::timestamptz,now()));
  update public.kindergarten_subscriptions set cancellation_requested_at=now(),
    cancellation_effective_at=effective_at,auto_renew=false,
    cancellation_reason=left(requested_reason,500),updated_at=now(),updated_by=auth.uid()
    where id=s.id;
  insert into public.platform_subscription_events(subscription_id,garden_id,action,previous_status,next_status,actor_id,source,reason)
    values(s.id,target_garden_id,'cancellation_requested',s.status::text,s.status::text,auth.uid(),'garden',left(requested_reason,500));
  return jsonb_build_object('id',s.id,'status',s.status,'cancellation_effective_at',effective_at);
end $$;

CREATE FUNCTION public.reserve_classroom_seat(target_classroom_id uuid, reservation_key text, target_child_id uuid DEFAULT NULL::uuid, target_enrollment_id uuid DEFAULT NULL::uuid, target_enrollment_request_id uuid DEFAULT NULL::uuid, target_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.classroom_seat_reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare room public.classrooms; existing public.classroom_seat_reservations; result public.classroom_seat_reservations; capacity jsonb;
begin
  if length(btrim(reservation_key))<8 then raise exception 'invalid_idempotency_key' using errcode='22023'; end if;
  select * into room from public.classrooms where id=target_classroom_id and status='active' for update;
  if room.id is null then raise exception 'classroom_not_found' using errcode='P0002'; end if;
  if not public.can_manage_garden(room.garden_id) then raise exception 'classroom_capacity_denied' using errcode='42501'; end if;
  select * into existing from public.classroom_seat_reservations where garden_id=room.garden_id and idempotency_key=reservation_key;
  if existing.id is not null then return existing; end if;
  perform public.expire_classroom_reservations(room.id);
  capacity:=public.classroom_capacity_status(room.id);
  if room.capacity_limit is not null and (capacity->>'available')::integer<=0 then raise exception 'classroom_capacity_unavailable' using errcode='P0001'; end if;
  insert into public.classroom_seat_reservations(garden_id,classroom_id,child_id,enrollment_id,enrollment_request_id,idempotency_key,expires_at,created_by)
  values(room.garden_id,room.id,target_child_id,target_enrollment_id,target_enrollment_request_id,btrim(reservation_key),target_expires_at,auth.uid()) returning * into result;
  return result;
end $$;

CREATE TABLE public.kindergarten_enrollment_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid NOT NULL,
    child_profile_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    requested_age_group text,
    requested_class_id uuid,
    published_price_snapshot numeric(10,2),
    parent_message text,
    status text DEFAULT 'submitted'::text NOT NULL,
    manager_decision text,
    decision_reason text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    payment_required boolean DEFAULT true NOT NULL,
    payment_status text DEFAULT 'not_requested'::text NOT NULL,
    activated_at timestamp with time zone,
    activated_child_id uuid,
    duplicate_flags jsonb DEFAULT '[]'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    requested_classroom_id uuid,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    information_request text,
    information_response text,
    information_requested_at timestamp with time zone,
    information_responded_at timestamp with time zone,
    reservation_id uuid,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    activation_payment_evidence_id uuid,
    activated_enrollment_id uuid,
    CONSTRAINT kindergarten_enrollment_requests_payment_status_check CHECK ((payment_status = ANY (ARRAY['not_requested'::text, 'pending'::text, 'paid'::text, 'arranged'::text, 'failed'::text, 'waived'::text, 'reconciliation_required'::text]))),
    CONSTRAINT kindergarten_enrollment_requests_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'under_review'::text, 'information_required'::text, 'resubmitted'::text, 'approved'::text, 'awaiting_payment'::text, 'waitlisted'::text, 'rejected'::text, 'cancelled'::text, 'expired'::text, 'activated'::text, 'payment_reconciliation_required'::text])))
);

COMMENT ON TABLE public.kindergarten_enrollment_requests IS 'Self-service parent enrollment requests. Does not grant kindergarten access until manager approval and activation.';

CREATE FUNCTION public.respond_enrollment_information(target_request_id uuid, target_response text) RETURNS public.kindergarten_enrollment_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare req public.kindergarten_enrollment_requests;
begin
  select * into req from public.kindergarten_enrollment_requests where id=target_request_id for update;
  if req.id is null or req.parent_id<>auth.uid() or not public.can_guardian_access_child(req.child_profile_id,'profile') then raise exception 'enrollment_request_denied' using errcode='42501'; end if;
  if req.status<>'information_required' then raise exception 'invalid_enrollment_transition' using errcode='23514'; end if;
  update public.kindergarten_enrollment_requests set status='resubmitted',information_response=nullif(btrim(target_response),''),information_responded_at=now(),updated_at=now() where id=req.id returning * into req;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data) values(auth.uid(),'parent',req.garden_id,'kindergarten_enrollment_requests',req.id,'enrollment_information_resubmitted',jsonb_build_object('status','resubmitted'));
  return req;
end $$;

CREATE FUNCTION public.respond_staff_job_application(target_application_id uuid, target_action text, target_response text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare application public.staff_job_applications; now_at timestamptz:=now();
begin
  select * into application from public.staff_job_applications where id=target_application_id and staff_candidate_id=auth.uid() for update;
  if application.id is null then raise exception 'staff_application_not_found' using errcode='P0002'; end if;
  if target_action='respond' and application.status='information_required' then update public.staff_job_applications set status='resubmitted',candidate_response=nullif(btrim(target_response),''),updated_at=now_at where id=application.id returning * into application;
  elsif target_action='withdraw' and application.status in ('draft','submitted','under_review','information_required','resubmitted','approved','awaiting_candidate_acceptance') then update public.staff_job_applications set status='withdrawn',withdrawn_at=now_at,updated_at=now_at where id=application.id returning * into application;
  else raise exception 'staff_application_transition_invalid' using errcode='23514'; end if;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data) values(auth.uid(),'staff',application.garden_id,'staff_job_applications',application.id,'staff_application_'||target_action,jsonb_build_object('status',application.status));
  return to_jsonb(application);
end $$;

CREATE FUNCTION public.retire_staffing_policy_version(target_version_id uuid) RETURNS public.staffing_policy_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.staffing_policy_versions;
begin
  if not public.is_admin() then raise exception 'staffing_policy_admin_required' using errcode='42501'; end if;
  update public.staffing_policy_versions set status='retired',retired_by=auth.uid(),retired_at=now(),updated_at=now()
  where id=target_version_id and status in ('approved','active') returning * into target;
  if target.id is null then raise exception 'staffing_policy_version_not_retirable' using errcode='P0001'; end if;
  return target;
end $$;

CREATE FUNCTION public.review_digital_observer_identity_candidate(requested_candidate_id uuid, requested_outcome text, requested_display_name text DEFAULT NULL::text, requested_relationship_label text DEFAULT NULL::text, requested_explicit_consent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  candidate_row public.digital_observer_identity_candidates;
  site_row public.observer_sites;
  person_id uuid;
  normalized_outcome text;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;

  normalized_outcome := lower(trim(coalesce(requested_outcome, '')));
  if normalized_outcome not in ('known','unknown','dismissed') then
    raise exception 'INVALID_IDENTITY_REVIEW_OUTCOME';
  end if;

  select * into candidate_row
  from public.digital_observer_identity_candidates
  where id = requested_candidate_id
  for update;

  if candidate_row.id is null then
    raise exception 'IDENTITY_CANDIDATE_NOT_FOUND';
  end if;

  if not public.can_manage_observer_site(candidate_row.observer_site_id) then
    raise exception 'OBSERVER_SITE_ACCESS_DENIED';
  end if;

  select * into site_row
  from public.observer_sites
  where id = candidate_row.observer_site_id;

  if site_row.business_handles_children = true or site_row.vision_privacy_mode = 'skeleton_only' then
    update public.digital_observer_identity_candidates
    set candidate_status = 'blocked', reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
    where id = candidate_row.id;
    raise exception 'BIOMETRIC_REVIEW_BLOCKED_FOR_CHILD_FOCUSED_SITE';
  end if;

  if normalized_outcome = 'known' then
    if length(trim(coalesce(requested_display_name, ''))) < 2 then
      raise exception 'KNOWN_PERSON_NAME_REQUIRED';
    end if;
    if requested_explicit_consent is not true then
      raise exception 'EXPLICIT_CONSENT_REQUIRED';
    end if;

    insert into public.digital_observer_known_people (
      observer_site_id,
      display_name,
      relationship_label,
      consent_status,
      recognition_status,
      camera_scope,
      notify_on_detection,
      confidence_threshold,
      last_confirmed_at,
      metadata,
      created_by
    ) values (
      candidate_row.observer_site_id,
      trim(requested_display_name),
      nullif(trim(coalesce(requested_relationship_label, '')), ''),
      'approved',
      'readiness',
      case when candidate_row.camera_source_id is null
        then '[]'::jsonb
        else jsonb_build_array(candidate_row.camera_source_id)
      end,
      true,
      greatest(0.5, least(0.99, coalesce(candidate_row.average_confidence, 0.8))),
      now(),
      jsonb_build_object(
        'source', 'camera_identity_candidate',
        'candidate_id', candidate_row.id,
        'biometric_processing_active', false,
        'explicit_consent_recorded', true,
        'requires_provider_activation', true
      ),
      auth.uid()
    ) returning id into person_id;
  end if;

  update public.digital_observer_identity_candidates
  set
    candidate_status = normalized_outcome,
    assigned_known_person_id = person_id,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'review_outcome', normalized_outcome,
      'reviewed_in_product', true,
      'does_not_enable_live_biometrics', true
    )
  where id = candidate_row.id;

  return jsonb_build_object(
    'candidate_id', candidate_row.id,
    'outcome', normalized_outcome,
    'known_person_id', person_id,
    'live_biometrics_enabled', false
  );
end;
$$;

COMMENT ON FUNCTION public.review_digital_observer_identity_candidate(requested_candidate_id uuid, requested_outcome text, requested_display_name text, requested_relationship_label text, requested_explicit_consent boolean) IS 'Reviews a site-scoped candidate. Known-person creation requires explicit consent and remains readiness-only.';

CREATE FUNCTION public.review_digital_observer_incident_feedback(requested_feedback_id uuid, requested_label text DEFAULT NULL::text, requested_reason_code text DEFAULT NULL::text, requested_note text DEFAULT NULL::text, requested_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  feedback_row public.digital_observer_feedback_revisions;
  incident_row public.observer_correlated_events;
  risk_row public.digital_observer_risk_evaluations;
  verification_row public.digital_observer_incident_verifications;
  decision_row public.digital_observer_decision_intents;
  previous_review uuid;
  existing_review uuid;
  next_review integer;
  canonical_label_value text;
  legacy_outcome text;
  review_id uuid;
  sample_id uuid;
  recommendation_id uuid;
  sample_count_value integer;
  event_types_value text[];
  model_provenance_value jsonb;
  detector_confidence_value numeric(5,4);
  evidence_references_value uuid[];
  decision_quality_value text;
  signal_type_value text;
  recommendation_type_value text;
  version_snapshot_value jsonb;
begin
  if auth.uid() is null then raise exception 'GROUND_TRUTH_AUTH_REQUIRED'; end if;
  if requested_idempotency_key is null or char_length(requested_idempotency_key) < 8 or char_length(requested_idempotency_key) > 120 then
    raise exception 'GROUND_TRUTH_IDEMPOTENCY_INVALID';
  end if;
  if requested_note is not null and char_length(requested_note) > 500 then raise exception 'GROUND_TRUTH_NOTE_TOO_LONG'; end if;

  select * into feedback_row from public.digital_observer_feedback_revisions
  where id = requested_feedback_id for update;
  if feedback_row.id is null then raise exception 'FEEDBACK_NOT_FOUND'; end if;
  if not public.can_review_digital_observer_site(feedback_row.observer_site_id) then raise exception 'GROUND_TRUTH_REVIEW_DENIED'; end if;

  select * into incident_row from public.observer_correlated_events
  where id = feedback_row.incident_id and observer_site_id = feedback_row.observer_site_id for update;
  if incident_row.id is null or incident_row.provenance <> 'REAL_CAMERA_AI' then raise exception 'CANONICAL_REAL_INCIDENT_REQUIRED'; end if;

  select id into existing_review from public.observer_ground_truth_reviews
  where reviewed_by = auth.uid() and review_idempotency_key = requested_idempotency_key;
  if existing_review is not null then
    return jsonb_build_object(
      'feedback_id', feedback_row.id,
      'ground_truth_review_id', existing_review,
      'calibration_sample_id', (select id from public.digital_observer_calibration_samples where ground_truth_review_id = existing_review),
      'recommendation_id', (select id from public.digital_observer_calibration_recommendations where ground_truth_review_id = existing_review),
      'idempotent', true
    );
  end if;

  canonical_label_value := coalesce(requested_label, feedback_row.label);
  if canonical_label_value not in (
    'TRUE_SECURITY_EVENT','TRUE_EXPECTED_ACTIVITY','FALSE_DETECTION','FALSE_CORRELATION',
    'FALSE_SPATIAL_EVENT','UNCERTAIN','OTHER'
  ) then raise exception 'GROUND_TRUTH_LABEL_INVALID'; end if;

  select * into risk_row from public.digital_observer_risk_evaluations
  where incident_id = incident_row.id order by evaluated_at desc limit 1;
  select * into verification_row from public.digital_observer_incident_verifications
  where incident_id = incident_row.id order by evaluated_at desc limit 1;
  select * into decision_row from public.digital_observer_decision_intents
  where incident_id = incident_row.id and metadata->>'decision_stage' = 'post_verification_final'
  order by created_at desc limit 1;

  select coalesce(array_agg(distinct coalesce(signal.metadata->>'event_type', signal.signal_type)), '{}'::text[]),
    coalesce(jsonb_agg(distinct signal.metadata->'model_provenance') filter (where signal.metadata ? 'model_provenance'), '[]'::jsonb),
    max(signal.confidence)
  into event_types_value, model_provenance_value, detector_confidence_value
  from public.observer_intelligence_signals signal
  where signal.id = any(incident_row.related_event_ids)
    and signal.observer_site_id = incident_row.observer_site_id;

  select coalesce(array_agg(clip.id), '{}'::uuid[]) into evidence_references_value
  from public.digital_observer_event_clips clip
  where clip.signal_id = any(incident_row.related_event_ids)
    and clip.observer_site_id = incident_row.observer_site_id;

  previous_review := incident_row.latest_ground_truth_review_id;
  select coalesce(max(review_number), 0) + 1 into next_review
  from public.observer_ground_truth_reviews where incident_id = incident_row.id and canonical_label is not null;
  legacy_outcome := case
    when canonical_label_value in ('TRUE_SECURITY_EVENT','TRUE_EXPECTED_ACTIVITY') then 'correct_detection'
    when canonical_label_value in ('FALSE_DETECTION','FALSE_CORRELATION','FALSE_SPATIAL_EVENT') then 'false_positive'
    else 'uncertain' end;

  version_snapshot_value := jsonb_build_object(
    'model', model_provenance_value,
    'risk_engine', risk_row.risk_engine_version,
    'risk_factors', risk_row.factor_version,
    'verification', verification_row.verification_version,
    'decision', verification_row.final_decision_version,
    'baseline', risk_row.baseline_context->>'version',
    'rules', coalesce(risk_row.matched_rules, '[]'::jsonb),
    'feedback', 'do-feedback-v1',
    'ground_truth', 'do-ground-truth-v1'
  );

  insert into public.observer_ground_truth_reviews (
    event_source, event_id, observer_site_id, reviewed_by, outcome,
    observer_recommendation, reviewer_note, confidence_at_review,
    updates_learning_profile, no_action_taken, metadata,
    feedback_revision_id, incident_id, target_type, target_id, camera_source_id,
    canonical_label, review_state, environment, reviewer_role, reason_code,
    previous_review_id, review_number, feedback_version, review_version,
    review_idempotency_key, version_snapshot, evidence_references
  ) values (
    'observer_correlated_event', incident_row.id, incident_row.observer_site_id, auth.uid(), legacy_outcome,
    'canonical_calibration_review', nullif(requested_note, ''), verification_row.verification_confidence,
    false, true,
    jsonb_build_object(
      'canonical_feedback', true,
      'automatic_learning_applied', false,
      'requires_versioned_release_approval', true,
      'historical_risk_rewritten', false
    ),
    feedback_row.id, incident_row.id, feedback_row.target_type, feedback_row.target_id,
    incident_row.primary_camera_source_id, canonical_label_value,
    case when previous_review is null then 'REVIEWED' else 'CORRECTED' end,
    'PRODUCTION', coalesce((select role::text from public.profiles where id = auth.uid()), 'reviewer'),
    nullif(requested_reason_code, ''), previous_review, next_review,
    feedback_row.feedback_version, 'do-ground-truth-v1', requested_idempotency_key,
    version_snapshot_value, evidence_references_value
  ) returning id into review_id;

  if previous_review is not null then
    update public.observer_ground_truth_reviews set review_state = 'SUPERSEDED'
    where id = previous_review;
  end if;

  decision_quality_value := case
    when canonical_label_value = 'TRUE_EXPECTED_ACTIVITY' and coalesce(verification_row.final_decision, risk_row.recommended_decision) in ('IGNORE','LOG_ONLY') then 'ALIGNED'
    when canonical_label_value = 'UNCERTAIN' and coalesce(verification_row.final_decision, risk_row.recommended_decision) = 'VERIFY' then 'ALIGNED'
    when canonical_label_value in ('FALSE_DETECTION','FALSE_CORRELATION','FALSE_SPATIAL_EVENT') and coalesce(verification_row.final_decision, risk_row.recommended_decision) in ('NOTIFY_IN_APP','ESCALATION_CANDIDATE') then 'POTENTIAL_OVER_ESCALATION'
    when canonical_label_value = 'TRUE_SECURITY_EVENT' and coalesce(verification_row.final_decision, risk_row.recommended_decision) in ('IGNORE','LOG_ONLY') then 'POTENTIAL_UNDER_RESPONSE'
    else 'REVIEW_REQUIRED' end;
  signal_type_value := case canonical_label_value
    when 'FALSE_DETECTION' then 'DETECTOR_REVIEW'
    when 'FALSE_SPATIAL_EVENT' then 'SPATIAL_GEOMETRY_REVIEW'
    when 'FALSE_CORRELATION' then 'INCIDENT_CORRELATION_REVIEW'
    when 'TRUE_EXPECTED_ACTIVITY' then 'CONTEXT_BASELINE_REVIEW'
    when 'TRUE_SECURITY_EVENT' then 'RISK_VERIFICATION_VALIDATION'
    when 'UNCERTAIN' then 'EVIDENCE_REVIEW'
    else 'MANUAL_CALIBRATION_REVIEW' end;

  insert into public.digital_observer_calibration_samples (
    observer_site_id, camera_source_id, incident_id, feedback_revision_id,
    ground_truth_review_id, canonical_label, environment, incident_provenance,
    event_ids, event_types, track_ids, evidence_references, model_provenance,
    detector_confidence, spatial_result, risk_snapshot, verification_snapshot,
    decision_snapshot, version_snapshot, decision_quality, calibration_signal_type,
    dataset_version, training_eligible, raw_media_copied, privacy_metadata
  ) values (
    incident_row.observer_site_id, incident_row.primary_camera_source_id, incident_row.id,
    feedback_row.id, review_id, canonical_label_value, 'PRODUCTION', incident_row.provenance,
    incident_row.related_event_ids, event_types_value, incident_row.involved_track_ids,
    evidence_references_value, model_provenance_value, detector_confidence_value,
    jsonb_build_object('event_types', event_types_value, 'track_ids', incident_row.involved_track_ids),
    jsonb_build_object('id', risk_row.id, 'score', risk_row.risk_score, 'band', risk_row.risk_band, 'confidence', risk_row.evaluation_confidence),
    jsonb_build_object('id', verification_row.id, 'status', verification_row.status, 'classification', verification_row.classification, 'confidence', verification_row.verification_confidence),
    jsonb_build_object('id', decision_row.id, 'decision', coalesce(verification_row.final_decision, risk_row.recommended_decision), 'confidence', verification_row.final_decision_confidence),
    version_snapshot_value, decision_quality_value, signal_type_value,
    'do-feedback-dataset-v1', false, false,
    jsonb_build_object(
      'structured_metadata_only', true,
      'media_access_by_reference', true,
      'raw_media_copied', false,
      'retention_policy_authoritative', true,
      'tenant_scope', incident_row.observer_site_id
    )
  ) returning id into sample_id;

  select count(*)::integer into sample_count_value
  from public.digital_observer_calibration_samples sample
  where sample.observer_site_id = incident_row.observer_site_id
    and sample.camera_source_id is not distinct from incident_row.primary_camera_source_id
    and sample.environment = 'PRODUCTION'
    and sample.incident_provenance = 'REAL_CAMERA_AI';

  recommendation_type_value := case canonical_label_value
    when 'FALSE_DETECTION' then 'REVIEW_PERSON_DETECTOR_FALSE_POSITIVES'
    when 'FALSE_SPATIAL_EVENT' then 'REVIEW_CAMERA_SPATIAL_GEOMETRY'
    when 'FALSE_CORRELATION' then 'REVIEW_INCIDENT_CORRELATION'
    when 'TRUE_EXPECTED_ACTIVITY' then 'REVIEW_EXPECTED_ACTIVITY_DECISION_ALIGNMENT'
    when 'TRUE_SECURITY_EVENT' then 'VALIDATE_RISK_AND_VERIFICATION_ALIGNMENT'
    when 'UNCERTAIN' then 'REVIEW_EVIDENCE_COVERAGE'
    else 'MANUAL_CALIBRATION_REVIEW' end;

  insert into public.digital_observer_calibration_recommendations (
    observer_site_id, camera_source_id, ground_truth_review_id, scope_type, scope_id,
    recommendation_type, status, sample_size, recommendation_confidence,
    evidence_summary, affected_versions, recommendation_version,
    requires_human_approval, production_change_applied
  ) values (
    incident_row.observer_site_id, incident_row.primary_camera_source_id, review_id,
    case when incident_row.primary_camera_source_id is null then 'SITE' else 'CAMERA' end,
    coalesce(incident_row.primary_camera_source_id::text, incident_row.observer_site_id::text),
    recommendation_type_value,
    case when sample_count_value < 10 then 'INSUFFICIENT_SAMPLE' else 'REVIEW_READY' end,
    sample_count_value, least(0.9000, sample_count_value::numeric / 20),
    jsonb_build_object(
      'canonical_label', canonical_label_value,
      'calibration_sample_id', sample_id,
      'decision_quality', decision_quality_value,
      'sample_size', sample_count_value,
      'no_accuracy_claim', sample_count_value < 10
    ),
    version_snapshot_value, 'do-calibration-recommendation-v1', true, false
  ) returning id into recommendation_id;

  update public.observer_correlated_events set
    current_ground_truth_label = canonical_label_value,
    latest_ground_truth_review_id = review_id,
    ground_truth_reviewed_at = now(),
    updated_at = now()
  where id = incident_row.id;

  return jsonb_build_object(
    'feedback_id', feedback_row.id,
    'ground_truth_review_id', review_id,
    'calibration_sample_id', sample_id,
    'recommendation_id', recommendation_id,
    'canonical_label', canonical_label_value,
    'sample_size', sample_count_value,
    'idempotent', false,
    'automatic_production_change', false
  );
end;
$$;

COMMENT ON FUNCTION public.review_digital_observer_incident_feedback(requested_feedback_id uuid, requested_label text, requested_reason_code text, requested_note text, requested_idempotency_key text) IS 'Promotes reviewed feedback into versioned Ground Truth and a structured calibration sample; never changes Production automatically.';

CREATE FUNCTION public.save_monthly_inspection_draft(p_inspection_id uuid, p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.inspections%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into i from public.inspections where id=p_inspection_id for update;
  if i.id is null or not public.can_inspector_access_garden(i.garden_id) or i.inspector_id<>auth.uid() then
    raise exception 'inspection_not_authorized' using errcode='42501';
  end if;
  if i.status::text not in ('open','in_progress') or i.completed_at is not null then
    raise exception 'inspection_locked' using errcode='23514';
  end if;
  if p_answers is null or jsonb_typeof(p_answers)<>'array' then raise exception 'answers_must_be_array' using errcode='23514'; end if;
  if exists(select 1 from jsonb_array_elements(p_answers) a where not exists(
    select 1 from public.inspection_form_questions q where q.id=(a->>'question_id')::uuid and q.form_id=i.form_id
  )) then raise exception 'question_not_in_template' using errcode='23514'; end if;
  insert into public.inspection_drafts(inspection_id,inspector_id,answers)
  values(i.id,auth.uid(),p_answers)
  on conflict(inspection_id) do update set answers=excluded.answers,updated_at=now();
  update public.inspections set status='in_progress',started_at=coalesce(started_at,now()),
    template_snapshot=coalesce(template_snapshot,(select jsonb_build_object('form_id',i.form_id,'questions',coalesce(jsonb_agg(to_jsonb(q) order by q.sort_order),'[]'::jsonb)) from public.inspection_form_questions q where q.form_id=i.form_id)),
    updated_at=now() where id=i.id;
  return jsonb_build_object('inspection_id',i.id,'status','in_progress');
end $$;

CREATE FUNCTION public.save_staff_candidate_profile(target_full_name text, target_city text, target_professional_role text, target_qualification_keys text[], target_availability jsonb, target_preferred_age_groups text[], target_employment_preference text, target_professional_summary text, target_matching_paused boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare saved public.staff_candidate_profiles; completeness jsonb;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  insert into public.staff_candidate_profiles(profile_id,full_name,phone,email,city,professional_role,qualification_keys,availability,preferred_age_groups,employment_preference,professional_summary,matching_paused,status)
  select auth.uid(),p.full_name,p.phone,p.email,nullif(btrim(target_city),''),nullif(btrim(target_professional_role),''),coalesce(target_qualification_keys,'{}'),coalesce(target_availability,'{}'::jsonb),coalesce(target_preferred_age_groups,'{}'),nullif(btrim(target_employment_preference),''),nullif(btrim(target_professional_summary),''),coalesce(target_matching_paused,false),'profile_incomplete'
  from public.profiles p where p.id=auth.uid()
  on conflict(profile_id) do update set full_name=excluded.full_name,phone=excluded.phone,email=excluded.email,city=excluded.city,professional_role=excluded.professional_role,qualification_keys=excluded.qualification_keys,availability=excluded.availability,preferred_age_groups=excluded.preferred_age_groups,employment_preference=excluded.employment_preference,professional_summary=excluded.professional_summary,matching_paused=excluded.matching_paused,updated_at=now()
  returning * into saved;
  completeness := public.evaluate_staff_candidate_profile(auth.uid());
  update public.staff_candidate_profiles set profile_completeness=completeness,status=case when completeness->>'status'='ready_for_matching' then 'active' when completeness->>'status'='paused' then 'pending_affiliation' else 'profile_incomplete' end,updated_at=now() where profile_id=auth.uid() returning * into saved;
  insert into public.audit_logs(actor_id,actor_role,entity_type,entity_id,action,after_data)
  values(auth.uid(),'staff','staff_candidate_profiles',auth.uid(),'staff_candidate_profile_updated',jsonb_build_object('percentage',completeness->>'percentage','status',completeness->>'status'));
  return jsonb_build_object('profile',to_jsonb(saved),'completeness',completeness);
end $$;

CREATE FUNCTION public.schedule_management_monthly_inspections(p_month date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare g record; v_form_id uuid; task_id uuid; inspection_id uuid; required_id uuid; period_start date;
declare due_date timestamptz; count_created integer:=0;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'scheduler_only' using errcode='42501'; end if;
  period_start:=date_trunc('month',coalesce(p_month,current_date))::date;
  due_date:=(period_start+interval '1 month'-interval '1 second')::timestamptz;
  select id into v_form_id from public.inspection_forms where active=true order by created_at desc,id desc limit 1;
  if v_form_id is null then raise exception 'inspection_template_missing' using errcode='23514'; end if;
  for g in select id,name,inspector_id from public.gardens
    where status::text='active' and inspector_id is not null and public.is_approved_inspector(inspector_id)
  loop
    perform pg_advisory_xact_lock(hashtextextended(g.id::text||period_start::text,0));
    select id into task_id from public.tasks where garden_id=g.id and task_type='monthly_inspection' and period_month=period_start
      order by created_at,id limit 1;
    if task_id is null then
      insert into public.tasks(garden_id,title,description,assigned_to,due_at,task_type,period_month,status)
      values(g.id,'ביקורת חודשית - '||to_char(period_start,'MM/YYYY'),'ביקורת חודשית לגן '||g.name,
        g.inspector_id,due_date,'monthly_inspection',period_start,'open') returning id into task_id;
    end if;
    insert into public.inspections(garden_id,inspector_id,form_id,task_id,period_month,due_at,status,template_snapshot)
    values(g.id,g.inspector_id,v_form_id,task_id,period_start,due_date,'open',
      (select jsonb_build_object('form_id',v_form_id,'questions',coalesce(jsonb_agg(to_jsonb(q) order by q.sort_order),'[]'::jsonb))
       from public.inspection_form_questions q where q.form_id=v_form_id))
    on conflict (garden_id,period_month) where period_month is not null do nothing;
    if found then count_created:=count_created+1; end if;
    select id into inspection_id from public.inspections where garden_id=g.id and period_month=period_start;
    update public.tasks set source_entity_type='inspection',source_entity_id=inspection_id where id=task_id and source_entity_id is null;
    select id into required_id from public.required_inspections where garden_id=g.id and monthly_cycle_date=period_start and inspection_type='monthly'
      order by created_at,id limit 1;
    if required_id is null then
      insert into public.required_inspections(garden_id,inspector_id,inspection_id,due_at,status,inspection_type,monthly_cycle_date,readiness_status)
      values(g.id,g.inspector_id,inspection_id,due_date,'required','monthly',period_start,'ready') returning id into required_id;
    end if;
    insert into public.monthly_inspection_cycles(garden_id,inspector_id,cycle_month,due_at,required_inspection_id,completed_inspection_id,completion_status,readiness_status)
    values(g.id,g.inspector_id,period_start,due_date::date,required_id,
      case when exists(select 1 from public.inspections where id=inspection_id and status::text='done') then inspection_id else null end,
      case when exists(select 1 from public.inspections where id=inspection_id and status::text='done') then 'completed' else 'pending' end,'ready')
    on conflict(garden_id,cycle_month) do nothing;
  end loop;
  return count_created;
end $$;

CREATE TABLE public.staff_shifts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    shift_date date NOT NULL,
    planned_start time without time zone,
    planned_end time without time zone,
    actual_start timestamp with time zone,
    actual_end timestamp with time zone,
    gps_start_lat numeric(10,7),
    gps_start_lng numeric(10,7),
    gps_end_lat numeric(10,7),
    gps_end_lng numeric(10,7),
    start_gps_verified boolean DEFAULT false NOT NULL,
    end_gps_verified boolean DEFAULT false NOT NULL,
    status text DEFAULT 'planned'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text,
    auto_attendance_enabled boolean DEFAULT true NOT NULL,
    auto_started boolean DEFAULT false NOT NULL,
    auto_closed boolean DEFAULT false NOT NULL,
    auto_start_detected_at timestamp with time zone,
    auto_end_detected_at timestamp with time zone,
    attendance_confidence text DEFAULT 'requires_review'::text NOT NULL,
    confidence_score integer DEFAULT 0 NOT NULL,
    total_minutes integer DEFAULT 0 NOT NULL,
    weekly_minutes integer DEFAULT 0 NOT NULL,
    monthly_minutes integer DEFAULT 0 NOT NULL,
    overtime_minutes integer DEFAULT 0 NOT NULL,
    review_reason text,
    employment_id uuid,
    CONSTRAINT staff_shifts_attendance_confidence_check CHECK ((attendance_confidence = ANY (ARRAY['verified'::text, 'probable'::text, 'requires_review'::text])))
);

COMMENT ON COLUMN public.staff_shifts.attendance_confidence IS 'verified, probable or requires_review based on GPS accuracy, duration and repeated confirmations.';

CREATE FUNCTION public.schedule_staff_employment_shift(target_staff_id uuid, target_garden_id uuid, target_shift_date date, target_start time without time zone, target_end time without time zone) RETURNS public.staff_shifts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare employee public.staff; employment public.staff_kindergarten_employments; result public.staff_shifts;
begin
  if not public.can_manage_garden(target_garden_id) then raise exception 'shift_management_denied' using errcode='42501'; end if;
  if target_shift_date is null or target_start is null or target_end is null or target_end<=target_start then
    raise exception 'shift_schedule_invalid' using errcode='23514';
  end if;
  select * into employee from public.staff where id=target_staff_id and garden_id=target_garden_id;
  if employee.id is null or employee.profile_id is null then raise exception 'shift_employment_denied' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(employee.profile_id::text,19));
  select * into employment from public.staff_kindergarten_employments
    where staff_id=employee.id and profile_id=employee.profile_id and garden_id=target_garden_id
      and status='active' and (start_date is null or start_date<=target_shift_date)
      and (end_date is null or end_date>=target_shift_date)
    order by created_at limit 1 for update;
  if employment.id is null or not employee.approved_to_work or employee.onboarding_status<>'active' then
    raise exception 'shift_employment_denied' using errcode='42501';
  end if;
  if exists(select 1 from public.staff_shifts sh join public.staff s on s.id=sh.staff_id
      where s.profile_id=employee.profile_id and sh.shift_date=target_shift_date
        and sh.planned_start is not null and sh.planned_end is not null
        and sh.status not in ('cancelled','canceled')
        and sh.planned_start<target_end and sh.planned_end>target_start) then
    raise exception 'staff_scheduling_conflict' using errcode='23505';
  end if;
  insert into public.staff_shifts(staff_id,garden_id,employment_id,shift_date,planned_start,planned_end,status)
  values(employee.id,target_garden_id,employment.id,target_shift_date,target_start,target_end,'planned')
  returning * into result;
  return result;
end $$;

CREATE FUNCTION public.set_digital_observer_watch_rule_state(requested_rule_id uuid, requested_state text, requested_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
declare
  rule_row public.observer_watch_requests;
  version_row public.digital_observer_watch_rule_versions;
  prior_version public.digital_observer_watch_rule_versions;
  next_version integer;
  next_active boolean;
  change_value text;
begin
  select * into rule_row from public.observer_watch_requests where id = requested_rule_id for update;
  if not found or rule_row.observer_site_id is null or rule_row.compiler_version is null then raise exception 'WATCH_RULE_NOT_FOUND'; end if;
  if auth.uid() is null or not public.can_manage_observer_site(rule_row.observer_site_id) then raise exception 'WATCH_RULE_ACCESS_DENIED'; end if;
  if requested_state not in ('ACTIVE','DISABLED','ARCHIVED') or length(requested_idempotency_key) not between 8 and 160 then raise exception 'WATCH_RULE_STATE_INVALID'; end if;
  select * into version_row from public.digital_observer_watch_rule_versions
    where observer_site_id = rule_row.observer_site_id and idempotency_key = requested_idempotency_key;
  if found then return jsonb_build_object('rule_id', rule_row.id, 'version_id', version_row.id, 'version', version_row.version, 'idempotent', true, 'state', rule_row.rule_state); end if;
  next_version := rule_row.rule_version + 1;
  next_active := requested_state = 'ACTIVE';
  change_value := case requested_state when 'ACTIVE' then 'ENABLE' when 'DISABLED' then 'DISABLE' else 'ARCHIVE' end;
  select * into prior_version from public.digital_observer_watch_rule_versions where rule_id = rule_row.id order by version desc limit 1;
  update public.observer_watch_requests set
    active = next_active,
    rule_state = requested_state,
    rule_version = next_version,
    archived_at = case when requested_state = 'ARCHIVED' then now() else null end,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('rule_version', next_version, 'state_changed_by', auth.uid()),
    updated_at = now()
  where id = rule_row.id returning * into rule_row;
  insert into public.digital_observer_watch_rule_versions (
    observer_site_id, rule_id, version, original_natural_language, structured_rule,
    validation_status, compiler_version, candidate_fingerprint, created_by, change_type,
    previous_version_id, environment, idempotency_key
  ) values (
    rule_row.observer_site_id, rule_row.id, next_version, rule_row.original_natural_language,
    rule_row.structured_rule, 'VALID', rule_row.compiler_version,
    encode(extensions.digest(rule_row.structured_rule::text, 'sha256'::text), 'hex'), auth.uid(), change_value,
    prior_version.id, coalesce(rule_row.structured_rule->>'environment', 'PRODUCTION'), requested_idempotency_key
  ) returning * into version_row;
  return jsonb_build_object('rule_id', rule_row.id, 'version_id', version_row.id, 'version', next_version, 'idempotent', false, 'state', rule_row.rule_state);
end;
$$;

CREATE FUNCTION public.set_garden_tuition_due_day(target_garden_id uuid, requested_day integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare prior_day integer;
begin
  if public.can_manage_garden(target_garden_id) is distinct from true then raise exception 'tuition_due_policy_denied' using errcode='42501'; end if;
  if requested_day is not null and (requested_day<1 or requested_day>31) then raise exception 'tuition_due_day_invalid' using errcode='23514'; end if;
  select tuition_due_day into prior_day from public.gardens where id=target_garden_id for update;
  if prior_day is not distinct from requested_day then return requested_day; end if;
  update public.gardens set tuition_due_day=requested_day where id=target_garden_id;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(auth.uid(),public.current_role()::text,target_garden_id,'gardens',target_garden_id,'tuition_due_day_changed',jsonb_build_object('day',requested_day));
  return requested_day;
end $$;

CREATE FUNCTION public.set_immutable_audit_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_previous text;
  v_metadata_hash text;
begin
  select event_hash
    into v_previous
    from public.immutable_audit_events
   where event_hash is not null
   order by created_at desc, id desc
   limit 1;

  if new.previous_event_hash is null then
    new.previous_event_hash := v_previous;
  end if;

  v_metadata_hash := encode(
    extensions.digest(coalesce(new.metadata::text, '{}'), 'sha256'::text),
    'hex'
  );
  new.event_hash := encode(
    extensions.digest(concat_ws('|',
      new.id::text,
      new.event_type,
      new.event_category,
      coalesce(new.actor_profile_id::text, ''),
      coalesce(new.target_type, ''),
      coalesce(new.target_id::text, ''),
      coalesce(new.garden_id::text, ''),
      coalesce(new.child_id::text, ''),
      coalesce(new.camera_id::text, ''),
      coalesce(new.document_id::text, ''),
      new.created_at::text,
      v_metadata_hash,
      coalesce(new.previous_event_hash, '')
    ), 'sha256'::text),
    'hex'
  );

  return new;
end;
$$;

COMMENT ON FUNCTION public.set_immutable_audit_hash() IS 'Builds the append-only audit hash chain with schema-qualified pgcrypto calls.';

CREATE FUNCTION public.snapshot_platform_subscription_terms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p public.subscription_plans%rowtype;
begin
  if new.plan_id is null then
    select * into p from public.subscription_plans where is_default and active
      and (effective_from is null or effective_from<=current_date)
      and (effective_until is null or effective_until>current_date) limit 1;
    if p.id is null then return new; end if;
    new.plan_id:=p.id;
  else
    select * into p from public.subscription_plans where id=new.plan_id;
  end if;
  if p.id is null then raise exception 'plan_not_found'; end if;
  new.plan_code_snapshot:=coalesce(new.plan_code_snapshot,p.code);
  new.plan_version_snapshot:=coalesce(new.plan_version_snapshot,p.version);
  new.unit_price_snapshot:=coalesce(new.unit_price_snapshot,
    case when p.billing_interval='monthly' then coalesce(p.monthly_price,p.price_amount)
      else coalesce(p.annual_price,p.price_amount) end);
  new.currency_snapshot:=coalesce(new.currency_snapshot,p.currency);
  new.billing_interval:=coalesce(new.billing_interval,p.billing_interval);
  new.billing_cycle:=new.billing_interval;
  new.commitment_months:=coalesce(new.commitment_months,p.commitment_months);
  if new.commitment_start is not null then
    new.commitment_end:=coalesce(new.commitment_end,(new.commitment_start+(new.commitment_months||' months')::interval)::date);
  end if;
  new.current_period_start:=coalesce(new.current_period_start,new.start_date);
  new.current_period_end:=coalesce(new.current_period_end,(new.current_period_start+
    case when new.billing_interval='monthly' then interval '1 month' else interval '1 year' end)::date);
  new.renewal_date:=coalesce(new.renewal_date,new.current_period_end);
  return new;
end $$;

CREATE FUNCTION public.staff_attendance_transition(target_garden_id uuid, target_action text, target_lat numeric DEFAULT NULL::numeric, target_lng numeric DEFAULT NULL::numeric) RETURNS public.staff_shifts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e public.staff_kindergarten_employments; existing public.staff_shifts;
        result public.staff_shifts; effective_at timestamptz; matching_samples integer;
        is_automatic boolean := target_action in ('auto_check_in','auto_check_out');
        is_check_in boolean := target_action in ('check_in','auto_check_in');
begin
  if target_action not in ('check_in','check_out','auto_check_in','auto_check_out') then
    raise exception 'attendance_action_invalid' using errcode='23514';
  end if;
  if not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role::text='staff' and p.active) then
    raise exception 'staff_employment_denied' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,19));
  select * into e from public.staff_kindergarten_employments
    where profile_id=auth.uid() and garden_id=target_garden_id and status='active'
      and (start_date is null or start_date<=current_date)
      and (end_date is null or end_date>=current_date)
    order by created_at limit 1 for update;
  if e.id is null or not public.can_staff_access_garden(target_garden_id) then
    raise exception 'staff_employment_denied' using errcode='42501';
  end if;

  effective_at := now();
  if is_automatic then
    select min(created_at),count(*) into effective_at,matching_samples
    from public.staff_location_samples
    where staff_id=e.staff_id and profile_id=auth.uid() and garden_id=target_garden_id
      and inside_geofence=is_check_in and created_at between now()-interval '36 minutes' and now();
    if matching_samples<2 or effective_at>now()-interval '30 minutes'
      or not exists(select 1 from public.staff_location_samples
          where staff_id=e.staff_id and profile_id=auth.uid() and garden_id=target_garden_id
            and inside_geofence=is_check_in and created_at>=now()-interval '2 minutes')
      or exists(select 1 from public.staff_location_samples
          where staff_id=e.staff_id and profile_id=auth.uid() and garden_id=target_garden_id
            and inside_geofence<>is_check_in and created_at between effective_at and now()) then
      raise exception 'attendance_observation_incomplete' using errcode='23514';
    end if;
  end if;

  select * into existing from public.staff_shifts
    where staff_id in (select id from public.staff where profile_id=auth.uid())
      and actual_start is not null and actual_end is null
    order by actual_start desc limit 1 for update;
  if is_check_in then
    if existing.id is not null then
      if existing.garden_id=target_garden_id and existing.employment_id=e.id then return existing; end if;
      raise exception 'staff_already_clocked_in' using errcode='23505';
    end if;
    select * into result from public.staff_shifts
      where staff_id=e.staff_id and garden_id=target_garden_id
        and shift_date=(effective_at at time zone 'Asia/Jerusalem')::date
      order by created_at desc limit 1 for update;
    if result.id is null then
      insert into public.staff_shifts(staff_id,garden_id,employment_id,shift_date,actual_start,status,
        gps_start_lat,gps_start_lng,auto_started,auto_start_detected_at)
      values(e.staff_id,target_garden_id,e.id,(effective_at at time zone 'Asia/Jerusalem')::date,
        effective_at,'started',target_lat,target_lng,is_automatic,
        case when is_automatic then now() else null end)
      returning * into result;
    else
      if result.actual_end is not null then raise exception 'staff_shift_already_completed' using errcode='23505'; end if;
      update public.staff_shifts set employment_id=e.id,actual_start=effective_at,status='started',
        gps_start_lat=target_lat,gps_start_lng=target_lng,auto_started=is_automatic,
        auto_start_detected_at=case when is_automatic then now() else null end
      where id=result.id returning * into result;
    end if;
  else
    if existing.id is null or existing.garden_id<>target_garden_id or existing.staff_id<>e.staff_id then
      raise exception 'staff_shift_not_open_in_garden' using errcode='23514';
    end if;
    if effective_at<existing.actual_start then raise exception 'attendance_time_invalid' using errcode='23514'; end if;
    update public.staff_shifts set employment_id=e.id,actual_end=effective_at,status='completed',
      total_minutes=greatest(0,round(extract(epoch from (effective_at-existing.actual_start))/60)::integer),
      gps_end_lat=target_lat,gps_end_lng=target_lng,auto_closed=is_automatic,
      auto_end_detected_at=case when is_automatic then now() else null end
    where id=existing.id returning * into result;
  end if;
  return result;
end $$;

CREATE FUNCTION public.staff_employments_for_current_user() RETURNS TABLE(employment_id uuid, staff_id uuid, garden_id uuid, garden_name text, role_title text, start_date date, classroom_names text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.id, e.staff_id, e.garden_id, g.name::text, e.role_title,
         e.start_date,
         array(select c.name::text from public.staff_classroom_assignments a
               join public.classrooms c on c.id = a.classroom_id and c.garden_id = e.garden_id
               where a.employment_id = e.id and a.staff_id = e.staff_id
                 and a.garden_id = e.garden_id and a.status = 'active'
                 and c.status = 'active' order by c.name)
  from public.staff_kindergarten_employments e
  join public.staff s on s.id = e.staff_id and s.profile_id = e.profile_id and s.garden_id = e.garden_id
  join public.gardens g on g.id = e.garden_id
  where e.profile_id = auth.uid() and public.can_staff_access_garden(e.garden_id)
    and e.status = 'active' and s.approved_to_work and s.onboarding_status = 'active'
  order by g.name, e.id
$$;

CREATE FUNCTION public.stamp_staff_location_sample_received_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op='INSERT' then new.created_at:=now();
  else new.created_at:=old.created_at; end if;
  return new;
end $$;

CREATE FUNCTION public.start_digital_observer_trial(requested_site_id uuid, requested_package_id uuid, requested_billing_cycle text DEFAULT 'monthly'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target_site public.observer_sites%rowtype;
  target_package public.observer_monitoring_packages%rowtype;
  current_subscription public.observer_site_subscriptions%rowtype;
  safe_cycle text := case when requested_billing_cycle = 'annual' then 'annual' else 'monthly' end;
  trial_started timestamptz := now();
  trial_ends timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;

  select * into target_site
  from public.observer_sites
  where id = requested_site_id
    and owner_profile_id = auth.uid()
    and garden_id is null
    and site_type <> 'kindergarten'
  for update;
  if target_site.id is null then raise exception 'observer_site_access_denied'; end if;

  select * into target_package
  from public.observer_monitoring_packages
  where id = requested_package_id and active = true;
  if target_package.id is null then raise exception 'observer_package_unavailable'; end if;
  if target_package.package_type not in (
    case when target_site.site_type = 'home' then 'home' else 'business' end,
    'enterprise'
  ) then raise exception 'observer_package_type_mismatch'; end if;

  trial_ends := trial_started + make_interval(days => least(greatest(coalesce(target_package.trial_days, 14), 1), 14));

  select * into current_subscription
  from public.observer_site_subscriptions
  where observer_site_id = target_site.id
    and status in ('trial','active','pending_payment','suspended')
  order by created_at desc
  limit 1
  for update;

  if current_subscription.id is null then
    insert into public.observer_site_subscriptions (
      observer_site_id, package_id, status, subscription_status, trial_start, trial_end,
      billing_cycle, monthly_price, annual_price, payment_provider,
      billing_separation_key, entitlement_status, purchase_channel, metadata
    ) values (
      target_site.id, target_package.id, 'trial', 'trial', trial_started, trial_ends,
      safe_cycle, target_package.monthly_price, target_package.annual_price, 'mock',
      'digital_observer', 'trial', 'mock',
      jsonb_build_object('product', 'digital_observer', 'real_charge_performed', false, 'payment_method_collected', false)
    )
    returning * into current_subscription;
  elsif current_subscription.status <> 'active' then
    update public.observer_site_subscriptions
    set package_id = target_package.id,
        status = 'trial',
        subscription_status = 'trial',
        trial_start = coalesce(trial_start, trial_started),
        trial_end = coalesce(trial_end, trial_ends),
        billing_cycle = safe_cycle,
        monthly_price = target_package.monthly_price,
        annual_price = target_package.annual_price,
        payment_provider = 'mock',
        billing_separation_key = 'digital_observer',
        entitlement_status = 'trial',
        purchase_channel = 'mock',
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'product', 'digital_observer',
          'real_charge_performed', false,
          'payment_method_collected', false
        ),
        updated_at = now()
    where id = current_subscription.id
    returning * into current_subscription;
  end if;

  update public.observer_sites
  set observer_package_id = target_package.id,
      observer_subscription_status = current_subscription.status,
      observer_trial_start = current_subscription.trial_start,
      observer_trial_end = current_subscription.trial_end,
      monitoring_enabled = false,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'product', 'digital_observer',
        'trial_connection_testing_allowed', true,
        'live_monitoring_requires_provider_activation', true
      ),
      updated_at = now()
  where id = target_site.id;

  update public.digital_observer_accounts
  set selected_package_id = target_package.id,
      primary_site_id = target_site.id,
      status = case when current_subscription.status = 'active' then 'active' else 'trial' end,
      onboarding_step = 'camera_setup',
      trial_start = current_subscription.trial_start,
      trial_end = current_subscription.trial_end,
      billing_status = case when current_subscription.status = 'active' then 'active' else 'trial' end,
      metadata = metadata || jsonb_build_object('real_charge_performed', false, 'payment_method_collected', false),
      updated_at = now()
  where profile_id = auth.uid();

  return jsonb_build_object(
    'subscription_id', current_subscription.id,
    'status', current_subscription.status,
    'trial_start', current_subscription.trial_start,
    'trial_end', current_subscription.trial_end,
    'charged', false
  );
end;
$$;

CREATE FUNCTION public.start_garden_onboarding(details jsonb, requested_registrant_type text DEFAULT 'teacher_operator'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor public.profiles%rowtype; existing_record public.kindergarten_onboarding_records%rowtype;
  new_garden_id uuid; relationship text; ownership text; now_at timestamptz := now();
begin
  select * into actor from public.profiles where id=auth.uid() for update;
  if actor.id is null or actor.role::text not in ('manager','owner') then raise exception 'onboarding_actor_not_allowed' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor.id::text,1));
  if requested_registrant_type not in ('teacher_operator','owner_teacher','owner_only') then raise exception 'invalid_registrant_type' using errcode='22023'; end if;
  if requested_registrant_type in ('owner_teacher','owner_only') and actor.role::text <> 'owner' then raise exception 'owner_role_required' using errcode='42501'; end if;
  select * into existing_record from public.kindergarten_onboarding_records
    where manager_id=actor.id and lifecycle_status in ('registration_pending','credentials_sent','activation_in_progress','onboarding_in_progress','correction_required')
    order by created_at desc limit 1 for update;
  if existing_record.id is not null then return jsonb_build_object('garden_id',existing_record.garden_id,'already_exists',true,'activation_key',existing_record.activation_key); end if;
  relationship := case when requested_registrant_type in ('owner_teacher','owner_only') then 'owner' else 'manager' end;
  ownership := case requested_registrant_type when 'owner_teacher' then 'teacher_is_owner' when 'owner_only' then 'owner_only' else 'teacher_only' end;
  insert into public.gardens(name,city,address,phone,email,manager_id,owner_profile_id,owner_name,status,
    ownership_type,approval_flow_status,final_approval_status,onboarding_status,activation_payment_status,
    public_profile_enabled,eligible_for_safe_status,safe_status,public_description,ages,created_at,updated_at)
  values (nullif(trim(details->>'name'),''),nullif(trim(details->>'city'),''),nullif(trim(details->>'address'),''),
    nullif(trim(details->>'phone'),''),nullif(trim(details->>'email'),''),actor.id,
    case when relationship='owner' then actor.id else null end,nullif(trim(details->>'manager_name'),''),'pending',ownership,
    'activation_in_progress','activation_in_progress','activation_in_progress','not_started',false,false,'pending_review',
    nullif(trim(details->>'public_description'),''),'{}'::text[],now_at,now_at) returning id into new_garden_id;
  -- The GB-M09 Garden trigger mirrors direct owner/manager columns as active.
  -- A draft must not grant operational access, so normalize every mirrored row
  -- inside this same transaction before it becomes externally visible.
  update public.garden_management_memberships set status='pending',is_default=false,activated_at=null,ended_at=null,updated_at=now_at
  where profile_id=actor.id and garden_id=new_garden_id;
  insert into public.garden_management_memberships(profile_id,garden_id,relationship_role,status,is_default,source,metadata,updated_at)
  values(actor.id,new_garden_id,relationship,'pending',false,'self_service',jsonb_build_object('purpose','onboarding'),now_at)
  on conflict(profile_id,garden_id,relationship_role) do update set status='pending',is_default=false,activated_at=null,ended_at=null,updated_at=now_at;
  insert into public.kindergarten_onboarding_records(garden_id,manager_id,lifecycle_status,progress_percent,completed_steps,missing_fields,
    profile_data,activation_steps,payment_status,subscription_monthly_amount,started_at,current_step,registrant_type,updated_at)
  values(new_garden_id,actor.id,'activation_in_progress',10,array['account'],array['garden_details','identity','documents','consents'],
    details || jsonb_build_object('registration_source','manager_self_service'),array['account'],'not_started',700,now_at,'garden_details',requested_registrant_type,now_at)
  returning * into existing_record;
  insert into public.kindergarten_activation_events(garden_id,actor_id,event_type,status,metadata)
  values(new_garden_id,actor.id,'registration_submitted','recorded',jsonb_build_object('admin_approval_required',false,'registrant_type',requested_registrant_type));
  insert into public.audit_logs(actor_id,actor_role,performed_by_user,performed_by_role,garden_id,entity_type,entity_id,action,after_data)
  values(actor.id,actor.role,actor.id,actor.role,new_garden_id,'kindergarten_onboarding_records',existing_record.id,
    'garden_onboarding_started',jsonb_build_object('registrant_type',requested_registrant_type));
  return jsonb_build_object('garden_id',new_garden_id,'already_exists',false,'activation_key',existing_record.activation_key);
end $$;

CREATE FUNCTION public.submit_enrollment_request(target_child_file_id uuid, target_garden_id uuid, target_classroom_id uuid DEFAULT NULL::uuid, target_age_group text DEFAULT NULL::text, target_parent_message text DEFAULT NULL::text) RETURNS public.kindergarten_enrollment_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare garden public.gardens; child_file public.permanent_child_files; room public.classrooms;
  existing public.kindergarten_enrollment_requests; result public.kindergarten_enrollment_requests; child_months integer;
begin
  if not public.can_guardian_access_child(target_child_file_id,'profile') then raise exception 'enrollment_child_denied' using errcode='42501'; end if;
  select * into child_file from public.permanent_child_files where id=target_child_file_id;
  if child_file.birth_date is null then raise exception 'enrollment_birth_date_required' using errcode='22023'; end if;
  if exists(select 1 from public.child_kindergarten_enrollments where permanent_child_file_id=target_child_file_id and status='active') then
    raise exception 'active_enrollment_conflict' using errcode='23505';
  end if;
  select * into garden from public.gardens where id=target_garden_id;
  if garden.id is null or garden.status<>'active' or not coalesce(garden.public_profile_enabled,false)
    or coalesce(garden.enrollment_availability,'accepting') not in ('accepting','waitlist_only') then
    raise exception 'garden_not_accepting_enrollment' using errcode='23514';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(target_child_file_id::text||':'||target_garden_id::text,0));
  select * into existing from public.kindergarten_enrollment_requests
    where child_profile_id=target_child_file_id and garden_id=target_garden_id
      and status in ('draft','submitted','under_review','information_required','resubmitted','approved','awaiting_payment','waitlisted')
    order by created_at desc limit 1;
  if existing.id is not null then return existing; end if;
  child_months:=extract(year from age(current_date,child_file.birth_date))::integer*12+extract(month from age(current_date,child_file.birth_date))::integer;
  if target_classroom_id is not null then
    select * into room from public.classrooms where id=target_classroom_id and garden_id=target_garden_id and status='active';
    if room.id is null or room.min_age_months is null or room.max_age_months is null or child_months not between room.min_age_months and room.max_age_months then
      raise exception 'invalid_enrollment_classroom' using errcode='23514';
    end if;
  elsif not exists(select 1 from public.classrooms c where c.garden_id=target_garden_id and c.status='active'
    and c.min_age_months is not null and c.max_age_months is not null and child_months between c.min_age_months and c.max_age_months) then
    raise exception 'no_matching_classroom' using errcode='23514';
  end if;
  insert into public.kindergarten_enrollment_requests(parent_id,child_profile_id,garden_id,requested_classroom_id,requested_age_group,parent_message,status,requested_at,payment_required,payment_status,metadata)
  values(auth.uid(),target_child_file_id,target_garden_id,target_classroom_id,target_age_group,nullif(btrim(target_parent_message),''),'submitted',now(),true,'not_requested',jsonb_build_object('source','canonical_parent_discovery')) returning * into result;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
  values(auth.uid(),'parent',target_garden_id,'kindergarten_enrollment_requests',result.id,'enrollment_request_submitted',jsonb_build_object('status','submitted'));
  insert into public.notifications(garden_id,recipient_id,recipient_profile_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,kindergarten_id,created_by)
  values(target_garden_id,garden.manager_id,garden.manager_id,'manager','בקשת הצטרפות חדשה','התקבלה בקשת הצטרפות חדשה לבדיקה.','התקבלה בקשת הצטרפות חדשה לבדיקה.','kindergarten_enrollment_requests',result.id,'medium','/dashboard/garden/enrollment-requests',target_garden_id,auth.uid());
  return result;
end $$;

CREATE FUNCTION public.submit_inspection_with_answers(p_inspection_id uuid, p_answers jsonb, p_gps_lat numeric, p_gps_lng numeric, p_gps_radius_meters numeric DEFAULT 120) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  inspection_record record;
  answer jsonb;
  question_record record;
  score_value integer;
  effective_score integer;
  bool_value boolean;
  total_weight numeric := 0;
  weighted_sum numeric := 0;
  weighted_average numeric := 0;
  violation_total integer := 0;
  critical_total integer := 0;
  distance numeric;
  task_id_created uuid;
  violation_id_created uuid;
begin
  select i.*, g.gps_lat as garden_lat, g.gps_lng as garden_lng, g.name as garden_name
  into inspection_record
  from public.inspections i
  join public.gardens g on g.id = i.garden_id
  where i.id = p_inspection_id
  for update;

  if inspection_record.id is null then
    raise exception 'Inspection not found';
  end if;

  if inspection_record.gps_exception_approved_by is null then
    if inspection_record.garden_lat is not null and inspection_record.garden_lng is not null then
      distance := public.distance_meters(inspection_record.garden_lat, inspection_record.garden_lng, p_gps_lat, p_gps_lng);
    end if;
    if distance > p_gps_radius_meters then
      raise exception 'GPS verification failed. Distance: % meters', round(distance, 2);
    end if;
  end if;

  if exists (
    select 1
    from public.inspection_form_questions q
    where q.form_id = inspection_record.form_id
      and q.required = true
      and not exists (
        select 1
        from jsonb_array_elements(p_answers) submitted
        where (submitted->>'question_id')::uuid = q.id
      )
  ) then
    raise exception 'All required inspection questions must be answered';
  end if;

  delete from public.inspection_answers where inspection_id = p_inspection_id;

  for answer in select * from jsonb_array_elements(p_answers)
  loop
    select *
    into question_record
    from public.inspection_form_questions
    where id = (answer->>'question_id')::uuid
      and form_id = inspection_record.form_id;

    if question_record.id is null then
      raise exception 'Question does not belong to inspection form';
    end if;

    score_value := nullif(answer->>'score', '')::integer;
    bool_value := case when answer ? 'boolean_value' then (answer->>'boolean_value')::boolean else null end;

    if question_record.question_type = 'score_1_10' then
      if score_value is null or score_value < question_record.min_score or score_value > question_record.max_score then
        raise exception 'Score must be between % and %', question_record.min_score, question_record.max_score;
      end if;
      effective_score := score_value;
    elsif question_record.question_type = 'boolean' then
      if bool_value is null then
        raise exception 'Boolean answer is required';
      end if;
      effective_score := case when bool_value then 10 else 1 end;
      score_value := effective_score;
    elsif question_record.question_type = 'photo_upload' then
      if question_record.required and coalesce(answer->>'photo_url', '') = '' then
        raise exception 'Photo upload is required';
      end if;
      effective_score := coalesce(score_value, 10);
    elsif question_record.question_type = 'document_upload' then
      if question_record.required and coalesce(answer->>'document_url', '') = '' then
        raise exception 'Document upload is required';
      end if;
      effective_score := coalesce(score_value, 10);
    else
      if question_record.required and coalesce(answer->>'note', answer->>'text_value', '') = '' then
        raise exception 'Text note is required';
      end if;
      effective_score := coalesce(score_value, 10);
    end if;

    if effective_score < 1 or effective_score > 10 then
      raise exception 'Effective score must be between 1 and 10';
    end if;

    if question_record.requires_note and coalesce(answer->>'note', answer->>'text_value', '') = '' then
      raise exception 'Question requires a note';
    end if;

    if question_record.requires_photo and coalesce(answer->>'photo_url', '') = '' then
      raise exception 'Question requires a photo';
    end if;

    if question_record.requires_document and coalesce(answer->>'document_url', '') = '' then
      raise exception 'Question requires a document';
    end if;

    insert into public.inspection_answers (
      inspection_id, question_id, score, note, photo_url, document_url, boolean_value, text_value, answer_payload
    )
    values (
      p_inspection_id,
      question_record.id,
      score_value,
      answer->>'note',
      answer->>'photo_url',
      answer->>'document_url',
      bool_value,
      answer->>'text_value',
      answer
    );

    total_weight := total_weight + question_record.weight;
    weighted_sum := weighted_sum + (effective_score * question_record.weight);

    if effective_score <= question_record.violation_threshold then
      violation_total := violation_total + 1;
      if question_record.critical then
        critical_total := critical_total + 1;
      end if;

      insert into public.tasks (
        garden_id, title, description, assigned_to, due_at, task_type, source_entity_type, status, priority
      )
      values (
        inspection_record.garden_id,
        'תיקון ליקוי: ' || question_record.category,
        question_record.question_text,
        inspection_record.inspector_id,
        now() + interval '7 days',
        'violation_correction',
        'inspection_answer',
        'open',
        case when question_record.critical then 'critical'::public.severity_level else 'high'::public.severity_level end
      )
      returning id into task_id_created;

      insert into public.violations (
        garden_id, inspection_id, question_id, task_id, title, description,
        category, severity, score, status, correction_due_at
      )
      values (
        inspection_record.garden_id,
        p_inspection_id,
        question_record.id,
        task_id_created,
        'ליקוי ביקורת: ' || question_record.category,
        question_record.question_text,
        question_record.category,
        case when question_record.critical then 'critical'::public.severity_level else 'high'::public.severity_level end,
        effective_score,
        'open',
        now() + interval '7 days'
      )
      returning id into violation_id_created;

      update public.tasks
      set source_entity_id = violation_id_created
      where id = task_id_created;

      insert into public.incident_timeline (
        garden_id, entity_type, entity_id, event_type, title, body, severity, metadata
      )
      values (
        inspection_record.garden_id,
        'violation',
        violation_id_created,
        'inspection_violation_created',
        'נוצר ליקוי אוטומטי',
        question_record.question_text,
        case when question_record.critical then 'critical'::public.severity_level else 'high'::public.severity_level end,
        jsonb_build_object('score', effective_score, 'inspection_id', p_inspection_id, 'question_type', question_record.question_type)
      );
    end if;
  end loop;

  if total_weight = 0 then
    raise exception 'Cannot submit inspection without weighted questions';
  end if;

  weighted_average := round(weighted_sum / total_weight, 2);

  update public.inspections
  set
    status = 'done',
    gps_lat = p_gps_lat,
    gps_lng = p_gps_lng,
    gps_verified = (distance is not null and distance <= p_gps_radius_meters),
    completed_at = now(),
    weighted_score = weighted_average,
    critical_failures = critical_total,
    violation_count = violation_total,
    submitted_payload = p_answers,
    updated_at = now()
  where id = p_inspection_id;

  update public.gardens
  set
    last_inspection_score = weighted_average,
    last_inspection_at = now(),
    next_inspection_at = coalesce(inspection_record.period_month,date_trunc('month',now())::date) + interval '2 months' - interval '1 second',
    safe_status = case
      when weighted_average < public.inspection_attention_threshold() or critical_total > 0 then 'requires_fix'::public.safe_status
      else 'safe'::public.safe_status
    end,
    eligible_for_safe_status = (weighted_average >= public.inspection_attention_threshold() and critical_total = 0),
    updated_at = now()
  where id = inspection_record.garden_id;

  update public.tasks
  set status = 'done', completed_at = now(), completed_by = inspection_record.inspector_id, updated_at = now()
  where id = inspection_record.task_id;

  insert into public.incident_timeline (
    garden_id, entity_type, entity_id, event_type, title, body, severity, metadata
  )
  values (
    inspection_record.garden_id,
    'inspection',
    p_inspection_id,
    'inspection_submitted',
    'ביקורת פקח הושלמה',
    'ציון משוקלל: ' || weighted_average || ', ליקויים: ' || violation_total,
    case when weighted_average < public.inspection_attention_threshold() or critical_total > 0 then 'high'::public.severity_level else 'low'::public.severity_level end,
    jsonb_build_object('weighted_score', weighted_average, 'violations', violation_total, 'critical_failures', critical_total)
  );

  if weighted_average < public.inspection_attention_threshold() or critical_total > 0 then
    insert into public.incident_timeline (
      garden_id, entity_type, entity_id, event_type, title, body, severity, metadata
    )
    values (
      inspection_record.garden_id,
      'garden',
      inspection_record.garden_id,
      'safe_badge_removed',
      'סטטוס גן בטוח הוסר',
      'הגן עבר לרשימת גנים הדורשים תיקון בעקבות ביקורת',
      'high',
      jsonb_build_object('weighted_score', weighted_average, 'critical_failures', critical_total)
    );
  end if;

  return jsonb_build_object(
    'inspection_id', p_inspection_id,
    'weighted_score', weighted_average,
    'violations_created', violation_total,
    'critical_failures', critical_total,
    'safe_status', case when weighted_average < public.inspection_attention_threshold() or critical_total > 0 then 'requires_fix' else 'safe' end
  );
end;
$$;

CREATE FUNCTION public.submit_inspector_application(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor public.profiles%rowtype; existing public.inspector_applications%rowtype; saved public.inspector_applications%rowtype;
declare submitted boolean := coalesce((p_payload->>'submit')::boolean,true);
declare next_status text;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into actor from public.profiles where id=auth.uid() for update;
  if actor.id is null or actor.role::text <> 'inspector' then raise exception 'inspector_role_required' using errcode='42501'; end if;
  if nullif(trim(p_payload->>'full_name'),'') is null then raise exception 'inspector_name_required' using errcode='23514'; end if;
  if submitted and (nullif(trim(p_payload->>'city'),'') is null or
      (actor.contact_verification_required and (actor.email_verified_at is null or actor.phone_verified_at is null))) then
    raise exception 'inspector_application_incomplete' using errcode='23514';
  end if;
  select * into existing from public.inspector_applications where profile_id=actor.id for update;
  if existing.id is not null and existing.status in ('approved','suspended') then
    raise exception 'inspector_application_locked' using errcode='23514';
  end if;
  if existing.id is not null and existing.status in ('submitted','under_review') then
    return to_jsonb(existing);
  end if;
  if existing.id is not null and existing.status='more_information_requested' and not submitted then
    raise exception 'inspector_response_requires_submission' using errcode='23514';
  end if;
  next_status:=case when submitted then 'submitted' else 'draft' end;
  insert into public.inspector_applications(profile_id,full_name,phone,email,city,preferred_regions,experience_summary,documents,status,submitted_at,metadata)
  values(actor.id,trim(p_payload->>'full_name'),coalesce(p_payload->>'phone',actor.phone),coalesce(p_payload->>'email',actor.email),p_payload->>'city',
    coalesce(array(select jsonb_array_elements_text(p_payload->'preferred_regions')),'{}'::text[]),p_payload->>'experience_summary',coalesce(p_payload->'documents','{}'::jsonb),next_status,
    case when submitted then now() else null end,coalesce(p_payload->'metadata','{}'::jsonb))
  on conflict(profile_id) do update set full_name=excluded.full_name,phone=excluded.phone,email=excluded.email,city=excluded.city,
    preferred_regions=excluded.preferred_regions,experience_summary=excluded.experience_summary,documents=excluded.documents,status=excluded.status,
    submitted_at=excluded.submitted_at,metadata=excluded.metadata,admin_decision=null,decision_reason=null,decided_at=null,updated_at=now()
  returning * into saved;
  insert into public.audit_logs(actor_id,actor_role,entity_type,entity_id,action,after_data)
  values(actor.id,'inspector','inspector_applications',saved.id,case when submitted then 'inspector_application_submitted' else 'inspector_application_saved' end,jsonb_build_object('status',next_status));
  if submitted then
    insert into public.notifications(recipient_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,recipient_profile_id,created_by)
    values(actor.id,'inspector','בקשת המפקח התקבלה','הבקשה הועברה לבדיקה.','הבקשה הועברה לבדיקה.',
      'inspector_applications',saved.id,'low','/dashboard/inspector/apply',actor.id,actor.id);
  end if;
  return to_jsonb(saved);
end;
$$;

CREATE FUNCTION public.submit_management_complaint(p_garden_id uuid, p_child_id uuid, p_subject text, p_description text, p_category text, p_reported_urgency public.severity_level, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.complaints%rowtype; actor public.profiles%rowtype; owner_parent uuid;
  reviewer uuid; manager_user uuid; task_assignee uuid; route_state text;
  policy public.complaint_sla_policies%rowtype; policy_ids uuid[]; policy_count integer; sensitive boolean;
begin
  select * into actor from public.profiles where id=auth.uid() and active=true and role='parent';
  if actor.id is null or not public.can_report_complaint(p_garden_id,p_child_id) then raise exception 'complaint_context_denied' using errcode='42501'; end if;
  if length(btrim(p_subject)) not between 2 and 200 or length(btrim(p_description)) not between 5 and 10000
     or p_idempotency_key is null then raise exception 'invalid_complaint' using errcode='23514'; end if;
  perform pg_advisory_xact_lock(hashtext(actor.id::text),hashtext(p_idempotency_key::text));
  select * into result from public.complaints where reporter_user_id=actor.id and idempotency_key=p_idempotency_key;
  if result.id is not null then return jsonb_build_object('id',result.id,'garden_id',result.garden_id,
    'child_id',result.child_id,'subject',result.subject,'category',result.category,'status',result.status,
    'created_at',result.created_at,'acknowledged_at',result.acknowledged_at,'resolution_public',result.resolution_public,'closed_at',result.closed_at); end if;
  select p.id into owner_parent from public.parents p where p.profile_id=actor.id or p.user_id=actor.id order by p.created_at limit 1;
  select g.inspector_id into reviewer from public.gardens g where g.id=p_garden_id;
  if reviewer is not null and not public.is_approved_inspector(reviewer) then reviewer:=null; end if;
  select m.profile_id into manager_user from public.garden_management_memberships m
    join public.profiles p on p.id=m.profile_id and p.active=true
    where m.garden_id=p_garden_id and m.status='active' and m.relationship_role in ('owner','manager')
    order by case when m.relationship_role='manager' then 0 else 1 end,m.profile_id limit 1;
  select array_agg(id) into policy_ids from public.complaint_sla_policies
    where status='active' and effective_from<=now() and (effective_until is null or effective_until>now())
      and (category is null or category=p_category) and (severity is null or severity=p_reported_urgency);
  policy_count:=coalesce(array_length(policy_ids,1),0);
  if policy_count>1 then raise exception 'sla_policy_conflict' using errcode='23505'; end if;
  if policy_count=1 then select * into policy from public.complaint_sla_policies where id=policy_ids[1];
  else policy.id:=null; end if;
  sensitive:=p_category in ('safety','violence','staff','medical','privacy','camera') or p_reported_urgency='critical';
  route_state:=case when not sensitive and manager_user is not null then 'garden'
    when reviewer is not null then 'inspector' else 'admin_queue' end;
  task_assignee:=case route_state when 'garden' then manager_user when 'inspector' then reviewer else null end;
  insert into public.complaints(garden_id,parent_id,child_id,reporter_user_id,idempotency_key,reported_urgency,subject,description,category,
    severity,urgent,status,visibility,routing_state,assigned_inspector_id,sla_policy_id,acknowledgement_due_at,response_due_at,resolution_due_at)
  values(p_garden_id,owner_parent,p_child_id,actor.id,p_idempotency_key,p_reported_urgency,btrim(p_subject),btrim(p_description),p_category,
    'medium',p_reported_urgency in ('high','critical'),'new',case when sensitive then 'restricted' else 'garden' end,
    route_state,case when route_state='inspector' then reviewer else null end,policy.id,
    case when policy.id is null then null else now()+make_interval(mins=>policy.acknowledgement_minutes) end,
    case when policy.id is null then null else now()+make_interval(mins=>policy.response_minutes) end,
    case when policy.id is null then null else now()+make_interval(mins=>policy.resolution_minutes) end)
  returning * into result;
  insert into public.complaint_events(complaint_id,garden_id,actor_id,action,to_status)
    values(result.id,p_garden_id,actor.id,'submitted','new');
  insert into public.tasks(garden_id,title,assigned_to,created_by,due_at,status,priority,task_type,source_entity_type,source_entity_id)
    values(p_garden_id,'בדיקת תלונה',task_assignee,actor.id,result.response_due_at,'open','medium','report_followup','complaint',result.id)
    on conflict do nothing;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data)
    values(actor.id,actor.role,p_garden_id,'complaints',result.id,'complaint_submitted',jsonb_build_object('routing_state',result.routing_state,'sla_policy_id',policy.id));
  insert into public.notifications(garden_id,recipient_id,title,body,entity_type,entity_id,channel,status)
    select p_garden_id,p.id,'תלונה חדשה','תלונה חדשה מחכה לבדיקה','complaints',result.id,'in_app','pending'
    from public.profiles p where p.id=task_assignee or (task_assignee is null and p.role='admin' and p.active=true);
  return jsonb_build_object('id',result.id,'garden_id',result.garden_id,'child_id',result.child_id,
    'subject',result.subject,'category',result.category,'status',result.status,'created_at',result.created_at,
    'acknowledged_at',result.acknowledged_at,'resolution_public',result.resolution_public,'closed_at',result.closed_at);
end; $$;

CREATE FUNCTION public.submit_staff_job_application(target_opening_id uuid, target_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare candidate public.staff_candidate_profiles; opening public.kindergarten_staff_openings; existing public.staff_job_applications; created public.staff_job_applications; completeness jsonb; now_at timestamptz:=now();
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||target_opening_id::text,0));
  select * into candidate from public.staff_candidate_profiles where profile_id=auth.uid() for update;
  if candidate.profile_id is null then raise exception 'candidate_profile_required' using errcode='23514'; end if;
  completeness:=public.evaluate_staff_candidate_profile(auth.uid());
  if coalesce((completeness->>'required_fields_complete')::boolean,false)<>true then raise exception 'candidate_profile_incomplete:%',completeness->'blockers' using errcode='23514'; end if;
  select o.* into opening from public.kindergarten_staff_openings o join public.gardens g on g.id=o.garden_id
    where o.id=target_opening_id and o.active_status='published' and g.status='active' for update of o;
  if opening.id is null then raise exception 'staff_opening_not_available' using errcode='P0002'; end if;
  if not (coalesce(opening.qualification_keys,'{}') <@ coalesce(candidate.qualification_keys,'{}')) then raise exception 'required_qualification_missing' using errcode='23514'; end if;
  if opening.classroom_id is not null and not exists(select 1 from public.classrooms c where c.id=opening.classroom_id and c.garden_id=opening.garden_id and c.status='active') then raise exception 'staff_opening_classroom_invalid' using errcode='23514'; end if;
  select * into existing from public.staff_job_applications where staff_candidate_id=auth.uid() and opening_id=opening.id and status in ('draft','submitted','under_review','information_required','resubmitted','approved','awaiting_candidate_acceptance','accepted','employed') order by created_at desc limit 1 for update;
  if existing.id is not null then return jsonb_build_object('application',to_jsonb(existing),'idempotent',true); end if;
  insert into public.staff_job_applications(staff_candidate_id,garden_id,opening_id,classroom_id,requested_role,status,submitted_at,requirement_snapshot,metadata)
  values(auth.uid(),opening.garden_id,opening.id,opening.classroom_id,opening.role_needed,'submitted',now_at,jsonb_build_object('role',opening.role_needed,'qualification_keys',opening.qualification_keys,'classroom_id',opening.classroom_id,'employment_type',opening.employment_type),jsonb_build_object('idempotency_key',coalesce(nullif(btrim(target_idempotency_key),''),'candidate-opening:'||auth.uid()::text||':'||opening.id::text))) returning * into created;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,after_data) values(auth.uid(),'staff',opening.garden_id,'staff_job_applications',created.id,'staff_application_submitted',jsonb_build_object('opening_id',opening.id,'status','submitted'));
  insert into public.notifications(garden_id,recipient_role,title,body,message,entity_type,entity_id,severity,action_url,kindergarten_id,created_by)
  values(opening.garden_id,'manager','מועמדות צוות חדשה','הוגשה מועמדות חדשה למשרה פתוחה.','הוגשה מועמדות חדשה למשרה פתוחה.','staff_job_applications',created.id,'low','/dashboard/garden/staff-applications',opening.garden_id,auth.uid());
  return jsonb_build_object('application',to_jsonb(created),'idempotent',false);
end $$;

CREATE FUNCTION public.sync_authorized_siren_policy_to_crossing_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.observer_site_id = 'cc1673b8-3eb0-4785-a12c-1fb88f425a41'::uuid
    and new.id in (
      '1de04a0a-d616-4072-ab53-a93d6d0366e2'::uuid,
      '3cf274ef-7b90-40c4-8cf9-b425ca04e035'::uuid,
      'd260f549-a14d-47f6-a8a2-969c0fff92fe'::uuid,
      'e9f8abf3-5895-494e-b1cf-ea8818602851'::uuid
    ) then
    update public.digital_observer_camera_automation_policies
    set enabled = public.digital_guard_crossing_line_valid(new.metadata -> 'crossing_line'),
        updated_at = clock_timestamp(),
        metadata = metadata || jsonb_build_object(
          'activation_state', case when public.digital_guard_crossing_line_valid(new.metadata -> 'crossing_line')
            then 'active' else 'authorized_waiting_for_crossing_line' end,
          'crossing_line_checked_at', clock_timestamp()
        )
    where observer_site_id = new.observer_site_id
      and camera_source_id = new.id
      and allowed_actions = array['siren']::text[]
      and metadata ->> 'approval_scope' = 'explicit_user_authorization_2026_09_02';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.sync_garden_management_memberships() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and old.owner_profile_id is not null and old.owner_profile_id is distinct from new.owner_profile_id then
    update public.garden_management_memberships set status = 'revoked', is_default = false, ended_at = now(), updated_at = now()
    where profile_id = old.owner_profile_id and garden_id = new.id and relationship_role = 'owner' and status = 'active';
  end if;
  if new.owner_profile_id is not null and (tg_op = 'INSERT' or new.owner_profile_id is distinct from old.owner_profile_id) then
    insert into public.garden_management_memberships(profile_id, garden_id, relationship_role, status, is_default, source, activated_at)
    values (new.owner_profile_id, new.id, 'owner', 'active', false, 'garden_owner', now())
    on conflict (profile_id, garden_id, relationship_role) do update
      set status = 'active', ended_at = null, activated_at = coalesce(garden_management_memberships.activated_at, now()), updated_at = now();
  end if;
  if tg_op = 'UPDATE' and old.manager_id is not null and old.manager_id is distinct from new.manager_id then
    update public.garden_management_memberships set status = 'revoked', is_default = false, ended_at = now(), updated_at = now()
    where profile_id = old.manager_id and garden_id = new.id and relationship_role = 'manager' and status = 'active';
  end if;
  if new.manager_id is not null and (tg_op = 'INSERT' or new.manager_id is distinct from old.manager_id) then
    insert into public.garden_management_memberships(profile_id, garden_id, relationship_role, status, is_default, source, activated_at)
    values (new.manager_id, new.id, 'manager', 'active', false, 'garden_manager', now())
    on conflict (profile_id, garden_id, relationship_role) do update
      set status = 'active', ended_at = null, activated_at = coalesce(garden_management_memberships.activated_at, now()), updated_at = now();
  end if;
  return new;
end $$;

CREATE FUNCTION public.sync_management_contact_verification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
  update public.profiles
  set email_verified_at = new.email_confirmed_at,
      phone_verified_at = new.phone_confirmed_at,
      updated_at = now()
  where id = new.id;

  update public.self_service_user_profiles
  set verification_status = jsonb_build_object(
        'email', case when new.email_confirmed_at is null then 'pending' else 'verified' end,
        'phone', case when new.phone_confirmed_at is null then 'pending' else 'verified' end,
        'mfa', coalesce(verification_status ->> 'mfa', 'not_required')
      ),
      updated_at = now()
  where profile_id = new.id;

  return new;
end;
$$;

CREATE FUNCTION public.sync_monthly_inspection_cycles(p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  inserted_count integer := 0;
begin
  insert into public.monthly_inspection_cycles (
    garden_id,
    inspector_id,
    cycle_month,
    due_at,
    required_inspection_id,
    completion_status,
    readiness_status,
    metadata
  )
  select
    g.id,
    g.inspector_id,
    date_trunc('month', p_month)::date,
    coalesce(g.next_inspection_at::date, (date_trunc('month', p_month)::date + interval '14 days')::date),
    r.id,
    case
      when i.id is not null then 'completed'
      when coalesce(g.next_inspection_at::date, (date_trunc('month', p_month)::date + interval '14 days')::date) < current_date then 'overdue'
      else 'pending'
    end,
    case
      when exists (
        select 1 from public.compliance_alerts ca
        where ca.garden_id = g.id and ca.alert_status not in ('resolved','verified','dismissed')
      ) then 'needs_attention'
      else 'ready'
    end,
    jsonb_build_object('source', 'phase_132_monthly_supervision')
  from public.gardens g
  left join lateral (
    select ri.id
    from public.required_inspections ri
    where ri.garden_id = g.id
      and coalesce(ri.monthly_cycle_date, date_trunc('month', ri.due_at)::date) = date_trunc('month', p_month)::date
    order by ri.due_at desc
    limit 1
  ) r on true
  left join lateral (
    select ins.id
    from public.inspections ins
    where ins.garden_id = g.id
      and date_trunc('month', coalesce(ins.completed_at, ins.created_at))::date = date_trunc('month', p_month)::date
      and ins.status::text in ('done','completed')
    order by coalesce(ins.completed_at, ins.created_at) desc
    limit 1
  ) i on true
  where g.inspector_id is not null
    and coalesce(g.status::text, '') not in ('archived','suspended','rejected')
  on conflict (garden_id, cycle_month)
  do update set
    inspector_id = excluded.inspector_id,
    due_at = excluded.due_at,
    required_inspection_id = coalesce(public.monthly_inspection_cycles.required_inspection_id, excluded.required_inspection_id),
    completed_inspection_id = coalesce(public.monthly_inspection_cycles.completed_inspection_id, excluded.completed_inspection_id),
    completion_status = case
      when public.monthly_inspection_cycles.completion_status = 'completed' then 'completed'
      else excluded.completion_status
    end,
    readiness_status = excluded.readiness_status,
    updated_at = now();

  get diagnostics inserted_count = row_count;
  return inserted_count;
end;
$$;

CREATE FUNCTION public.sync_primary_child_guardian_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.primary_parent_profile_id is not null then
    update public.child_guardian_links
    set is_primary = false, updated_at = now()
    where permanent_child_file_id = new.id
      and guardian_profile_id <> new.primary_parent_profile_id
      and is_primary = true;
    insert into public.child_guardian_links (
      permanent_child_file_id, guardian_profile_id, relationship_type, is_primary,
      legal_authority, status, verified_at, source
    ) values (
      new.id, new.primary_parent_profile_id, 'parent', true,
      true, 'active', now(), 'legacy_primary_parent_sync'
    )
    on conflict (permanent_child_file_id, guardian_profile_id) do update
    set is_primary = true, legal_authority = true, status = 'active', updated_at = now();
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.sync_verified_digital_observer_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  safe_type text := case
    when new.raw_user_meta_data ->> 'account_type' = 'business' then 'business'
    else 'home'
  end;
begin
  if new.email_confirmed_at is null
    or coalesce(new.raw_user_meta_data ->> 'product', '') <> 'digital_observer'
  then
    return new;
  end if;

  insert into public.profiles (id, role, full_name, phone, must_change_password)
  values (
    new.id,
    'parent'::public.app_role,
    coalesce(nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''), new.email, 'Digital Observer user'),
    new.raw_user_meta_data ->> 'phone',
    false
  )
  on conflict (id) do update set
    full_name = coalesce(nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''), public.profiles.full_name),
    must_change_password = false,
    updated_at = now();

  insert into public.digital_observer_accounts (
    profile_id,
    account_type,
    status,
    onboarding_step,
    email_verified_at,
    metadata
  ) values (
    new.id,
    safe_type,
    'onboarding',
    'site',
    new.email_confirmed_at,
    jsonb_build_object(
      'product', 'digital_observer',
      'identity_separated_from_gan_batuach_role', true,
      'created_from_verified_auth_identity', true
    )
  )
  on conflict (profile_id) do update set
    account_type = case
      when public.digital_observer_accounts.primary_site_id is null then excluded.account_type
      else public.digital_observer_accounts.account_type
    end,
    email_verified_at = coalesce(public.digital_observer_accounts.email_verified_at, excluded.email_verified_at),
    metadata = public.digital_observer_accounts.metadata || excluded.metadata,
    updated_at = now();

  return new;
end;
$$;

COMMENT ON FUNCTION public.sync_verified_digital_observer_account() IS 'Creates or repairs the standalone Digital Observer account after Supabase confirms an observer email; does not alter Gan Batuach role assignments.';

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

CREATE FUNCTION public.transition_complaint_sla_policy(p_id uuid, p_action text) RETURNS public.complaint_sla_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result public.complaint_sla_policies%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'admin_required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtext('complaint_sla_policy'),0);
  select * into result from public.complaint_sla_policies where id=p_id for update;
  if result.id is null then raise exception 'policy_not_found' using errcode='P0002'; end if;
  if p_action='activate' and result.status='draft' then
    if exists(select 1 from public.complaint_sla_policies p where p.status='active'
      and p.category is not distinct from result.category and p.severity is not distinct from result.severity
      and tstzrange(p.effective_from,p.effective_until,'[)') && tstzrange(result.effective_from,result.effective_until,'[)'))
    then raise exception 'policy_conflict' using errcode='23505'; end if;
    update public.complaint_sla_policies set status='active',approved_by=auth.uid(),approved_at=now()
      where id=p_id returning * into result;
  elsif p_action='retire' and result.status='active' then
    update public.complaint_sla_policies set status='retired' where id=p_id returning * into result;
  else raise exception 'policy_transition_denied' using errcode='42501'; end if;
  insert into public.audit_logs(actor_id,garden_id,entity_type,entity_id,action,after_data)
    values(auth.uid(),null,'complaint_sla_policies',p_id,'sla_'||p_action,jsonb_build_object('version',result.version,'status',result.status));
  return result;
end; $$;

CREATE FUNCTION public.transition_corrective_action(p_violation_id uuid, p_action text, p_note text DEFAULT NULL::text, p_evidence_paths jsonb DEFAULT '[]'::jsonb, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_responsible_profile_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v public.violations%rowtype; next_status public.task_status; manager_allowed boolean;
  inspector_allowed boolean; actor uuid := auth.uid(); evidence_item text;
begin
  if actor is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into v from public.violations where id=p_violation_id for update;
  if v.id is null then raise exception 'corrective_action_not_found' using errcode='P0002'; end if;
  manager_allowed := public.can_manage_garden(v.garden_id);
  inspector_allowed := public.can_inspector_access_garden(v.garden_id);
  if not (manager_allowed or inspector_allowed or public.is_admin()) then
    raise exception 'corrective_action_not_authorized' using errcode='42501';
  end if;
  if p_note is not null and length(p_note)>2000 then raise exception 'note_too_long' using errcode='23514'; end if;
  if p_evidence_paths is null or jsonb_typeof(p_evidence_paths)<>'array' or jsonb_array_length(p_evidence_paths)>12 then
    raise exception 'invalid_evidence' using errcode='23514';
  end if;
  for evidence_item in select jsonb_array_elements_text(p_evidence_paths) loop
    if evidence_item !~ ('^inspection-reports/corrective-actions/' || v.id::text || '/[a-zA-Z0-9._-]+$') then
      raise exception 'invalid_evidence_path' using errcode='23514';
    end if;
  end loop;
  if p_action in ('acknowledge','progress','submit') and not manager_allowed then
    raise exception 'garden_manager_required' using errcode='42501';
  end if;
  if p_action in ('accept','reject','reopen','extend') and not (inspector_allowed or public.is_admin()) then
    raise exception 'assigned_inspector_required' using errcode='42501';
  end if;
  case p_action
    when 'acknowledge' then
      if v.status<>'open' then raise exception 'invalid_transition' using errcode='23514'; end if;
      next_status := 'in_progress';
    when 'progress' then
      if v.status not in ('open','in_progress','rejected','overdue') then raise exception 'invalid_transition' using errcode='23514'; end if;
      next_status := 'in_progress';
    when 'submit' then
      if v.status not in ('in_progress','rejected','overdue') or nullif(btrim(coalesce(p_note,v.correction_note,'')),'') is null then
        raise exception 'remediation_note_required_or_invalid_transition' using errcode='23514';
      end if;
      next_status := 'waiting_approval';
    when 'accept' then
      if v.status='done' then return jsonb_build_object('id',v.id,'status',v.status,'idempotent',true); end if;
      if v.status<>'waiting_approval' then raise exception 'invalid_transition' using errcode='23514'; end if;
      next_status := 'done';
    when 'reject' then
      if v.status<>'waiting_approval' or nullif(btrim(coalesce(p_note,'')),'') is null then raise exception 'rejection_reason_required_or_invalid_transition' using errcode='23514'; end if;
      next_status := 'rejected';
    when 'reopen' then
      if v.status not in ('done','rejected') or nullif(btrim(coalesce(p_note,'')),'') is null then raise exception 'reopen_reason_required_or_invalid_transition' using errcode='23514'; end if;
      next_status := 'in_progress';
    when 'extend' then
      if v.status='done' or p_due_at is null or p_due_at<=now() then raise exception 'invalid_deadline_extension' using errcode='23514'; end if;
      next_status := v.status;
    else raise exception 'unsupported_action' using errcode='23514';
  end case;
  if p_responsible_profile_id is not null then
    if not manager_allowed or not exists(select 1 from public.profiles p where p.id=p_responsible_profile_id and p.active and
      (p.id=actor or exists(select 1 from public.staff_kindergarten_employments e
        join public.staff s on s.id=e.staff_id and s.profile_id=e.profile_id and s.garden_id=e.garden_id
        where e.profile_id=p.id and e.garden_id=v.garden_id and e.status='active'
          and (e.start_date is null or e.start_date<=current_date)
          and (e.end_date is null or e.end_date>=current_date)
          and s.approved_to_work and s.onboarding_status='active'))) then
      raise exception 'invalid_responsible_profile' using errcode='42501';
    end if;
  end if;
  update public.violations set status=next_status,
    acknowledged_at=case when p_action='acknowledge' then now() else acknowledged_at end,
    submitted_at=case when p_action='submit' then now() else submitted_at end,
    reopened_at=case when p_action='reopen' then now() else reopened_at end,
    correction_note=case when p_action in ('progress','submit') then coalesce(p_note,correction_note) else correction_note end,
    correction_files=case when p_action in ('progress','submit') and jsonb_array_length(p_evidence_paths)>0 then correction_files || p_evidence_paths else correction_files end,
    review_note=case when p_action in ('reject','reopen') then p_note when p_action='accept' then null else review_note end,
    approved_by=case when p_action='accept' then actor when p_action='reopen' then null else approved_by end,
    approved_at=case when p_action='accept' then now() when p_action='reopen' then null else approved_at end,
    correction_due_at=case when p_action='extend' then p_due_at else correction_due_at end,
    responsible_profile_id=coalesce(p_responsible_profile_id,responsible_profile_id)
  where id=v.id;
  insert into public.corrective_action_events(violation_id,garden_id,actor_id,action,from_status,to_status,note,evidence_paths,due_at)
  values(v.id,v.garden_id,actor,p_action,v.status,next_status,p_note,p_evidence_paths,case when p_action='extend' then p_due_at else v.correction_due_at end);
  return jsonb_build_object('id',v.id,'garden_id',v.garden_id,'status',next_status,'overdue',next_status<>'done' and coalesce(p_due_at,v.correction_due_at)<now());
end $_$;

CREATE FUNCTION public.transition_management_complaint(p_id uuid, p_action text, p_public_note text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.complaints%rowtype; old_status public.complaint_status; next_status public.complaint_status; is_reporter boolean;
  is_inspector boolean; is_manager boolean; is_platform_admin boolean;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into c from public.complaints where id=p_id for update;
  if c.id is null then raise exception 'complaint_not_found' using errcode='P0002'; end if;
  is_reporter:=c.reporter_user_id=auth.uid();
  is_inspector:=public.can_inspector_access_garden(c.garden_id);
  is_manager:=c.visibility='garden' and public.can_manage_garden(c.garden_id);
  is_platform_admin:=public.is_admin();
  if length(coalesce(p_public_note,''))>4000 or length(coalesce(p_internal_note,''))>4000 then raise exception 'note_too_long' using errcode='23514'; end if;
  if p_action in ('request_reporter','request_garden','reporter_reply','garden_reply','resolve','reopen')
    and nullif(btrim(coalesce(p_public_note,'')),'') is null then raise exception 'public_note_required' using errcode='23514'; end if;
  if p_action='note' and nullif(btrim(coalesce(p_internal_note,'')),'') is null then raise exception 'internal_note_required' using errcode='23514'; end if;
  if p_action='acknowledge' and (is_inspector or is_platform_admin or is_manager) and c.status='new' then next_status:='assigned';
  elsif p_action='review' and (is_inspector or is_platform_admin) and c.status in ('new','assigned','reopened') then next_status:='in_progress';
  elsif p_action='request_reporter' and (is_inspector or is_platform_admin) and c.status in ('assigned','in_progress','reopened') then next_status:='waiting_reporter';
  elsif p_action='request_garden' and (is_inspector or is_platform_admin) and c.visibility='garden'
    and c.status in ('assigned','in_progress','reopened') then next_status:='waiting_garden';
  elsif p_action='reporter_reply' and is_reporter and c.status='waiting_reporter' then next_status:='in_progress';
  elsif p_action='garden_reply' and is_manager and c.status in ('assigned','in_progress','waiting_garden') then next_status:='in_progress';
  elsif p_action='note' and (is_inspector or is_platform_admin) and c.status not in ('closed') then next_status:=c.status;
  elsif p_action='assign' and is_platform_admin and c.status not in ('closed') then next_status:='assigned';
  elsif p_action='mark_urgent' and (is_inspector or is_platform_admin) and c.status not in ('closed') then next_status:=c.status;
  elsif p_action='escalate' and (is_inspector or is_platform_admin) and c.status not in ('closed','resolved') then next_status:='escalated';
  elsif p_action='resolve' and (is_inspector or is_platform_admin) and c.status in ('in_progress','escalated','reopened') and nullif(btrim(p_public_note),'') is not null then next_status:='resolved';
  elsif p_action='close' and (is_inspector or is_platform_admin) and c.status='resolved' then next_status:='closed';
  elsif p_action='reopen' and (is_reporter or is_inspector or is_platform_admin) and c.status in ('resolved','closed') and nullif(btrim(p_public_note),'') is not null then next_status:='reopened';
  else raise exception 'complaint_transition_denied' using errcode='42501'; end if;
  if p_internal_note is not null and not (is_inspector or is_platform_admin) then raise exception 'internal_note_denied' using errcode='42501'; end if;
  old_status:=c.status;
  update public.complaints set status=next_status,revision=revision+1,
    acknowledged_at=case when p_action='acknowledge' then coalesce(acknowledged_at,now()) else acknowledged_at end,
    last_response_at=case when p_action='garden_reply' then now() else last_response_at end,
    resolved_at=case when p_action='resolve' then now() else resolved_at end,
    closed_at=case when p_action='close' then now() else closed_at end,
    escalated_at=case when p_action='escalate' then now() else escalated_at end,
    resolution_public=case when p_action='resolve' then p_public_note when p_action='reopen' then null else resolution_public end,
    resolution_due_at=case when p_action='reopen' and sla_policy_id is not null then now()+(select make_interval(mins=>resolution_minutes) from public.complaint_sla_policies where id=c.sla_policy_id) else resolution_due_at end
    where id=p_id returning * into c;
  if p_action='assign' then
    update public.complaints set assigned_to=auth.uid() where id=p_id returning * into c;
  end if;
  if p_action='mark_urgent' then
    update public.complaints set severity='critical',urgent=true where id=p_id returning * into c;
  end if;
  insert into public.complaint_events(complaint_id,garden_id,actor_id,action,from_status,to_status,public_note,internal_note)
    values(c.id,c.garden_id,auth.uid(),p_action,old_status,next_status,p_public_note,p_internal_note);
  if p_action='resolve' then
    update public.tasks set status='done',completed_at=now(),completed_by=auth.uid()
      where source_entity_type='complaint' and source_entity_id=c.id and status::text not in ('done','cancelled');
  elsif p_action='reopen' then
    update public.tasks set status='open',completed_at=null,completed_by=null,cancelled_at=null
      where source_entity_type='complaint' and source_entity_id=c.id and status::text in ('done','cancelled');
  end if;
  insert into public.audit_logs(actor_id,garden_id,entity_type,entity_id,action,after_data)
    values(auth.uid(),c.garden_id,'complaints',c.id,'complaint_'||p_action,jsonb_build_object('status',next_status));
  if c.reporter_user_id is not null and p_action not in ('reporter_reply','note','assign') then
    insert into public.notifications(garden_id,recipient_id,title,body,entity_type,entity_id,channel,status)
      values(c.garden_id,c.reporter_user_id,'עדכון תלונה','סטטוס התלונה עודכן','complaints',c.id,'in_app','pending');
  end if;
  return jsonb_build_object('id',c.id,'garden_id',c.garden_id,'child_id',c.child_id,
    'subject',c.subject,'status',c.status,'routing_state',c.routing_state,'reporter_user_id',c.reporter_user_id,
    'resolution_public',c.resolution_public,'acknowledged_at',c.acknowledged_at,
    'resolved_at',c.resolved_at,'closed_at',c.closed_at);
end; $$;

CREATE FUNCTION public.transition_management_task(p_task_id uuid, p_action text, p_note text DEFAULT NULL::text) RETURNS public.tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.tasks%rowtype; actor public.profiles%rowtype; manager_allowed boolean; assignee_allowed boolean;
  next_status public.task_status; old_status public.task_status;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into t from public.tasks where id=p_task_id for update;
  if t.id is null then raise exception 'task_not_found' using errcode='P0002'; end if;
  if not public.can_view_management_task(t.garden_id,t.assigned_to,t.assigned_role,t.source_entity_type,t.source_entity_id) then
    raise exception 'task_not_authorized' using errcode='42501'; end if;
  select * into actor from public.profiles where id=auth.uid() and active=true;
  if actor.id is null then raise exception 'active_actor_required' using errcode='42501'; end if;
  manager_allowed:=public.is_admin() or (t.garden_id is not null and public.can_manage_garden(t.garden_id));
  assignee_allowed:=t.assigned_to=auth.uid() and t.garden_id is not null and
    (public.can_staff_access_garden(t.garden_id) or public.can_inspector_access_garden(t.garden_id));
  if not (manager_allowed or assignee_allowed) then raise exception 'task_transition_denied' using errcode='42501'; end if;
  if p_note is not null and length(p_note)>2000 then raise exception 'note_too_long' using errcode='23514'; end if;
  old_status:=t.status;
  case p_action
    when 'start' then next_status:='in_progress';
    when 'submit' then next_status:='waiting_approval';
    when 'complete' then next_status:='done';
    when 'block' then next_status:='blocked';
    when 'reject' then next_status:='rejected';
    when 'reopen' then next_status:='open';
    when 'cancel' then next_status:='cancelled';
    else raise exception 'invalid_task_action' using errcode='23514';
  end case;
  if t.status=next_status then return t; end if;
  if p_action in ('complete','reject','reopen','cancel') and not manager_allowed then
    raise exception 'task_manager_required' using errcode='42501'; end if;
  if (p_action in ('start','submit','block') and t.status not in ('open','in_progress','rejected','blocked','overdue'))
    or (p_action='complete' and t.status not in ('open','in_progress','waiting_approval','blocked','overdue'))
    or (p_action='reject' and t.status<>'waiting_approval')
    or (p_action='reopen' and t.status not in ('done','cancelled','rejected'))
    or (p_action='cancel' and t.status in ('done','cancelled')) then
      raise exception 'invalid_task_transition' using errcode='23514'; end if;
  update public.tasks set status=next_status,updated_at=now(),
    completed_at=case when next_status='done' then now() else null end,
    completed_by=case when next_status='done' then actor.id else null end,
    cancelled_at=case when next_status='cancelled' then now() else null end,
    blocked_reason=case when next_status='blocked' then p_note else blocked_reason end,
    completion_comment=case when next_status='done' then p_note else completion_comment end,
    rejection_reason=case when next_status='rejected' then p_note else rejection_reason end,
    waiting_approval_at=case when next_status='waiting_approval' then now() else waiting_approval_at end
  where id=t.id returning * into t;
  if t.workflow_task_id is not null then
    update public.workflow_tasks set status=next_status::text,updated_at=now(),
      completed_at=t.completed_at,completed_by=t.completed_by,outcome_notes=p_note where id=t.workflow_task_id;
  end if;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,before_data,after_data)
  values(actor.id,actor.role,t.garden_id,'tasks',t.id,'task_'||p_action,
    jsonb_build_object('status',old_status),jsonb_build_object('status',next_status,'note',p_note));
  if t.created_by is not null and t.created_by<>actor.id and p_action in ('submit','complete','block','reopen') then
    insert into public.notifications(garden_id,recipient_id,title,body,entity_type,entity_id,channel,status)
    values(t.garden_id,t.created_by,'עדכון משימה',t.title||' · '||next_status::text,'task',t.id,'in_app','pending');
  end if;
  return t;
end; $$;

CREATE TABLE public.tuition_billing_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid NOT NULL,
    enrollment_id uuid NOT NULL,
    child_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    due_at date,
    base_amount numeric(12,2) NOT NULL,
    currency text DEFAULT 'ILS'::text NOT NULL,
    price_source text NOT NULL,
    adjustment_total numeric(12,2) DEFAULT 0 NOT NULL,
    settled_total numeric(12,2) DEFAULT 0 NOT NULL,
    unapplied_credit_total numeric(12,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reconciliation_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tuition_billing_periods_base_amount_check CHECK ((base_amount >= (0)::numeric)),
    CONSTRAINT tuition_billing_periods_check CHECK ((period_end = ((date_trunc('month'::text, (period_start)::timestamp with time zone) + '1 mon -1 days'::interval))::date)),
    CONSTRAINT tuition_billing_periods_check1 CHECK (((base_amount + adjustment_total) >= (0)::numeric)),
    CONSTRAINT tuition_billing_periods_check2 CHECK ((settled_total <= (base_amount + adjustment_total))),
    CONSTRAINT tuition_billing_periods_currency_check CHECK ((currency = 'ILS'::text)),
    CONSTRAINT tuition_billing_periods_period_start_check CHECK ((period_start = (date_trunc('month'::text, (period_start)::timestamp with time zone))::date)),
    CONSTRAINT tuition_billing_periods_settled_total_check CHECK ((settled_total >= (0)::numeric)),
    CONSTRAINT tuition_billing_periods_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partially_paid'::text, 'paid'::text, 'waived'::text, 'reconciliation_required'::text, 'cancelled'::text]))),
    CONSTRAINT tuition_billing_periods_unapplied_credit_total_check CHECK ((unapplied_credit_total >= (0)::numeric))
);

CREATE FUNCTION public.tuition_period_projection(p public.tuition_billing_periods, as_of date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'id',p.id,'garden_id',p.garden_id,'enrollment_id',p.enrollment_id,'child_id',p.child_id,
    'period_start',p.period_start,'period_end',p.period_end,'due_at',p.due_at,
    'base_amount',p.base_amount,'adjustment_total',p.adjustment_total,
    'amount_due',p.base_amount+p.adjustment_total,'amount_settled',p.settled_total,
    'unapplied_credit_total',p.unapplied_credit_total,
    'outstanding',greatest(0,p.base_amount+p.adjustment_total-p.settled_total),
    'currency',p.currency,'price_source',p.price_source,
    'status',case when p.status in ('pending','partially_paid') and p.due_at is not null and p.due_at<as_of and p.base_amount+p.adjustment_total>p.settled_total then 'overdue' else p.status end,
    'reconciliation_reason',p.reconciliation_reason
  );
$$;

CREATE FUNCTION public.update_management_task(p_task_id uuid, p_assigned_to uuid, p_due_at timestamp with time zone, p_priority text) RETURNS public.tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.tasks%rowtype; actor public.profiles%rowtype; prior_assignee uuid; prior_due timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into t from public.tasks where id=p_task_id for update;
  if t.id is null then raise exception 'task_not_found' using errcode='P0002'; end if;
  if not (public.is_admin() or (t.garden_id is not null and public.can_manage_garden(t.garden_id))) then
    raise exception 'task_manager_required' using errcode='42501'; end if;
  if t.status in ('done','cancelled') or p_priority not in ('low','medium','high','critical') then
    raise exception 'task_not_editable' using errcode='23514'; end if;
  if p_assigned_to is not null and not (
    (t.garden_id is null and exists(select 1 from public.profiles p where p.id=p_assigned_to and p.active and p.role::text='admin'))
    or (t.garden_id is not null and (
      exists(select 1 from public.garden_management_memberships m join public.profiles p on p.id=m.profile_id and p.active where m.profile_id=p_assigned_to and m.garden_id=t.garden_id and m.status='active' and m.relationship_role in ('owner','manager'))
      or exists(select 1 from public.staff_kindergarten_employments e join public.staff s on s.id=e.staff_id and s.profile_id=e.profile_id and s.garden_id=e.garden_id join public.profiles p on p.id=e.profile_id and p.active where e.profile_id=p_assigned_to and e.garden_id=t.garden_id and e.status='active' and (e.start_date is null or e.start_date<=current_date) and (e.end_date is null or e.end_date>=current_date) and s.approved_to_work and s.onboarding_status='active')
      or (public.is_approved_inspector(p_assigned_to) and exists(select 1 from public.gardens g where g.id=t.garden_id and g.inspector_id=p_assigned_to))
    ))
  ) then raise exception 'ineligible_task_assignee' using errcode='42501'; end if;
  if t.assigned_to is not distinct from p_assigned_to and t.due_at is not distinct from p_due_at and t.priority::text=p_priority then
    return t; end if;
  prior_assignee:=t.assigned_to; prior_due:=t.due_at;
  select * into actor from public.profiles where id=auth.uid() and active=true;
  if actor.id is null then raise exception 'active_actor_required' using errcode='42501'; end if;
  update public.tasks set assigned_to=p_assigned_to,due_at=p_due_at,priority=p_priority::public.severity_level,updated_at=now()
    where id=t.id returning * into t;
  if t.workflow_task_id is not null then
    update public.workflow_tasks set assigned_to=t.assigned_to,due_at=t.due_at,priority=t.priority::text,updated_at=now()
      where id=t.workflow_task_id;
  end if;
  insert into public.audit_logs(actor_id,actor_role,garden_id,entity_type,entity_id,action,before_data,after_data)
  values(actor.id,actor.role,t.garden_id,'tasks',t.id,'task_assignment_or_due_changed',
    jsonb_build_object('assigned_to',prior_assignee,'due_at',prior_due),
    jsonb_build_object('assigned_to',t.assigned_to,'due_at',t.due_at,'priority',t.priority));
  if t.assigned_to is not null and t.assigned_to is distinct from prior_assignee then
    insert into public.notifications(garden_id,recipient_id,title,body,entity_type,entity_id,channel,status)
    values(t.garden_id,t.assigned_to,'משימה הוקצתה לך',t.title,'task',t.id,'in_app','pending');
  end if;
  return t;
end; $$;

CREATE FUNCTION public.validate_classroom_assignment_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare room_garden uuid; subject_garden uuid; relation_garden uuid;
begin
  select garden_id into room_garden from public.classrooms where id=new.classroom_id;
  if tg_table_name='child_classroom_assignments' then
    select garden_id into subject_garden from public.children where id=new.child_id;
    if new.enrollment_id is not null then select garden_id into relation_garden from public.child_kindergarten_enrollments where id=new.enrollment_id and child_id=new.child_id; end if;
  else
    select garden_id into subject_garden from public.staff where id=new.staff_id;
    if new.employment_id is not null then select garden_id into relation_garden from public.staff_kindergarten_employments where id=new.employment_id and staff_id=new.staff_id and status='active'; end if;
  end if;
  if room_garden is null or subject_garden is null or room_garden<>new.garden_id or subject_garden<>new.garden_id or (case when tg_table_name='child_classroom_assignments' then new.enrollment_id is not null else new.employment_id is not null end and relation_garden is distinct from new.garden_id) then
    raise exception 'cross_garden_classroom_assignment' using errcode='23514';
  end if;
  return new;
end $$;

CREATE FUNCTION public.validate_classroom_reservation_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare room_garden uuid; child_garden uuid; enrollment_garden uuid; request_garden uuid;
begin
  select garden_id into room_garden from public.classrooms where id=new.classroom_id;
  if new.child_id is not null then select garden_id into child_garden from public.children where id=new.child_id; end if;
  if new.enrollment_id is not null then select garden_id into enrollment_garden from public.child_kindergarten_enrollments where id=new.enrollment_id and (new.child_id is null or child_id=new.child_id); end if;
  if new.enrollment_request_id is not null then select garden_id into request_garden from public.kindergarten_enrollment_requests where id=new.enrollment_request_id; end if;
  if room_garden is null or room_garden<>new.garden_id
    or (new.child_id is not null and child_garden is distinct from new.garden_id)
    or (new.enrollment_id is not null and enrollment_garden is distinct from new.garden_id)
    or (new.enrollment_request_id is not null and request_garden is distinct from new.garden_id) then
    raise exception 'cross_garden_seat_reservation' using errcode='42501';
  end if;
  return new;
end $$;

CREATE FUNCTION public.validate_garden_teaching_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor_role text; actor_active boolean; garden_owner uuid; garden_manager uuid; garden_ownership text;
begin
  select role::text, active into actor_role, actor_active from public.profiles where id = new.profile_id;
  select owner_profile_id, manager_id, ownership_type into garden_owner, garden_manager, garden_ownership from public.gardens where id = new.garden_id;
  if new.status = 'active' and actor_active is not true then raise exception 'teaching_assignment_requires_active_profile' using errcode = '23514'; end if;
  if new.assignment_kind = 'owner_teacher' and new.status = 'active'
    and (actor_role <> 'owner' or garden_owner is distinct from new.profile_id or garden_ownership <> 'teacher_is_owner') then
    raise exception 'owner_teacher_identity_mismatch' using errcode = '23514';
  end if;
  if new.assignment_kind = 'operator_teacher' and new.status = 'active'
    and (actor_role not in ('manager','owner') or garden_manager is distinct from new.profile_id or garden_ownership <> 'teacher_only') then
    raise exception 'operator_teacher_identity_mismatch' using errcode = '23514';
  end if;
  if new.assignment_kind = 'delegated_teacher' and new.status = 'active' and not exists (
    select 1 from public.staff s join public.staff_kindergarten_employments e
      on e.staff_id=s.id and e.profile_id=s.profile_id and e.garden_id=s.garden_id and e.status='active'
    where s.id=new.staff_id and s.profile_id=new.profile_id and s.garden_id=new.garden_id
      and s.approved_to_work is true and s.onboarding_status='active' and actor_role='staff'
  ) then raise exception 'delegated_teacher_requires_active_staff_employment' using errcode = '23514'; end if;
  if new.access_scope - array['children','attendance','journal','communication'] <> '{}'::jsonb then
    raise exception 'teaching_assignment_scope_not_allowed' using errcode = '23514';
  end if;
  if exists (select 1 from jsonb_each(new.access_scope) entry where jsonb_typeof(entry.value) <> 'boolean') then
    raise exception 'teaching_assignment_scope_must_be_boolean' using errcode = '23514';
  end if;
  new.updated_at := now(); return new;
end $$;

CREATE TABLE public.account_security_locks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid,
    lock_reason text NOT NULL,
    lock_status text DEFAULT 'active'::text NOT NULL,
    failed_attempt_count integer DEFAULT 0 NOT NULL,
    locked_at timestamp with time zone DEFAULT now() NOT NULL,
    unlock_at timestamp with time zone,
    unlocked_at timestamp with time zone,
    unlocked_by uuid,
    admin_notes text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_lock_status_check CHECK ((lock_status = ANY (ARRAY['active'::text, 'expired'::text, 'admin_unlocked'::text, 'auto_unlocked'::text, 'cancelled'::text])))
);

COMMENT ON TABLE public.account_security_locks IS 'Temporary account lockout and admin recovery readiness.';

CREATE TABLE public.accounting_export_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    batch_key text NOT NULL,
    export_type text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    period_start date,
    period_end date,
    invoice_count integer DEFAULT 0 NOT NULL,
    payment_count integer DEFAULT 0 NOT NULL,
    total_amount numeric(12,2) DEFAULT 0 NOT NULL,
    file_url text,
    error_message text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT accounting_export_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT accounting_export_type_check CHECK ((export_type = ANY (ARRAY['invoices'::text, 'payments'::text, 'receipts'::text, 'refunds'::text, 'full_bookkeeping'::text])))
);

CREATE TABLE public.ai_alerts (
