);

COMMENT ON TABLE public.ai_assistant_messages IS 'Auditable AI assistant prompts and deterministic responses. No automatic actions are executed.';

CREATE TABLE public.ai_assistant_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    role text NOT NULL,
    session_title text DEFAULT 'עוזר גן בטוח'::text NOT NULL,
    context_scope jsonb DEFAULT '{}'::jsonb NOT NULL,
