    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_assistant_sessions_permission_mode_check CHECK ((permission_mode = ANY (ARRAY['role_scoped'::text, 'admin_global'::text, 'garden_scoped'::text, 'parent_child_scoped'::text, 'staff_scoped'::text, 'inspector_assignment_scoped'::text]))),
    CONSTRAINT ai_assistant_sessions_provider_mode_check CHECK ((provider_mode = ANY (ARRAY['rules_based'::text, 'external_ai_ready'::text, 'external_ai_active'::text]))),
    CONSTRAINT ai_assistant_sessions_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'network_manager'::text, 'owner'::text, 'manager'::text, 'parent'::text, 'staff'::text, 'inspector'::text]))),
    CONSTRAINT ai_assistant_sessions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text, 'archived'::text])))
);

COMMENT ON TABLE public.ai_assistant_sessions IS 'Role-scoped AI assistant sessions. Context is limited by user permissions.';

