    observer_recommendation text,
    ground_truth_outcome text,
    ground_truth_reviewed_by uuid,
    ground_truth_reviewed_at timestamp with time zone,
    human_review_required boolean DEFAULT true NOT NULL,
    model_name text,
    model_version text,
    model_provider text DEFAULT 'local_mock'::text NOT NULL,
    model_mode text DEFAULT 'shadow'::text NOT NULL,
    confidence_threshold numeric(5,4),
    processing_latency_ms integer,
    gateway_latency_ms integer,
    CONSTRAINT ai_camera_events_detector_mode_check CHECK ((detector_mode = ANY (ARRAY['mock'::text, 'local_shadow'::text, 'shadow'::text, 'future_real'::text]))),
    CONSTRAINT ai_camera_events_review_outcome_check CHECK (((review_outcome IS NULL) OR (review_outcome = ANY (ARRAY['false_positive'::text, 'valid_detection'::text, 'needs_more_data'::text])))),
    CONSTRAINT ai_camera_events_review_priority_check CHECK (((review_priority >= 1) AND (review_priority <= 4))),
    CONSTRAINT ai_camera_events_safety_category_check CHECK (((safety_category IS NULL) OR (safety_category = ANY (ARRAY['distress'::text, 'violence'::text, 'supervision'::text, 'crowding'::text, 'fall'::text, 'emergency'::text, 'camera'::text, 'pickup'::text, 'general'::text])))),
    CONSTRAINT ai_camera_events_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'low'::text, 'medium'::text, 'high'::text, 'urgent'::text, 'critical'::text]))),
    CONSTRAINT ai_camera_events_status_check CHECK ((status = ANY (ARRAY['open'::text, 'reviewing'::text, 'confirmed'::text, 'dismissed'::text, 'escalated'::text]))),
    CONSTRAINT ai_camera_events_type_check CHECK ((event_type = ANY (ARRAY['person_detected'::text, 'unauthorized_person'::text, 'child_missing_from_area'::text, 'restricted_area_entry'::text, 'fall_suspected'::text, 'crowding_suspected'::text, 'gate_or_door_open'::text, 'pickup_mismatch'::text, 'staff_behavior_concern'::text, 'distress_suspected'::text, 'violence_indicator'::text, 'aggressive_behavior_indicator'::text, 'prolonged_crying_indicator'::text, 'child_left_alone_indicator'::text, 'staff_absence_indicator'::text, 'unusual_crowding'::text, 'emergency_behavior_indicator'::text, 'audio_anomaly'::text, 'keyword_detected'::text, 'camera_tampering'::text, 'camera_offline'::text, 'camera_frozen_suspected'::text, 'motion_detected'::text, 'no_motion_too_long'::text, 'multiple_persons_detected'::text, 'restricted_area_occupancy'::text, 'camera_obstruction_suspected'::text])))
);

COMMENT ON TABLE public.ai_camera_events IS 'AI Digital Observer event readiness table. Events are suspected/indicator records and require human review before escalation.';

COMMENT ON COLUMN public.ai_camera_events.clip_url IS 'Future secure event clip URL. Do not expose without signed access control.';

COMMENT ON COLUMN public.ai_camera_events.snapshot_url IS 'Future secure snapshot URL. Do not expose without signed access control.';

COMMENT ON COLUMN public.ai_camera_events.shadow_mode IS 'True for local pilot detections. Shadow events are review-only and never parent-visible by default.';

COMMENT ON COLUMN public.ai_camera_events.review_outcome IS 'Human review outcome for false-positive learning: false_positive, valid_detection or needs_more_data.';

COMMENT ON COLUMN public.ai_camera_events.safety_category IS 'Safety incident category for review queues and kindergarten-level trend analysis only.';

COMMENT ON COLUMN public.ai_camera_events.review_priority IS '1 critical review first, 4 low priority. Human review required.';

COMMENT ON COLUMN public.ai_camera_events.evidence_timeline IS 'Private future evidence timeline. No public access.';

COMMENT ON COLUMN public.ai_camera_events.safety_score_impact IS 'Kindergarten-level readiness only. Never child scoring.';

COMMENT ON COLUMN public.ai_camera_events.observer_site_id IS 'Generic site link for future standalone Digital Observer product. Kindergarten_id remains for Gan Batuach compatibility.';

COMMENT ON COLUMN public.ai_camera_events.watch_request_id IS 'Optional link to the custom watch request that produced a reviewed/shadow event.';

CREATE TABLE public.ai_capabilities (
