    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    capacity_limit integer,
    CONSTRAINT classrooms_age_bounds_check CHECK ((((min_age_months IS NULL) OR (min_age_months >= 0)) AND ((max_age_months IS NULL) OR (max_age_months >= COALESCE(min_age_months, 0))))),
    CONSTRAINT classrooms_capacity_limit_check CHECK (((capacity_limit IS NULL) OR (capacity_limit > 0))),
    CONSTRAINT classrooms_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT classrooms_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'archived'::text])))
);

COMMENT ON TABLE public.classrooms IS 'Canonical operational Classroom; age-group category is classification, not identity or legal policy.';

COMMENT ON COLUMN public.classrooms.capacity_limit IS 'Configured operational capacity; it is not a legal staffing-ratio assertion.';

