    CONSTRAINT commercial_launch_readiness_status_check CHECK ((status = ANY (ARRAY['not_ready'::text, 'preparing'::text, 'commercial_ready_with_gaps'::text, 'commercial_ready'::text, 'active_sales'::text])))
);

