);

COMMENT ON TABLE public.digital_observer_calibration_samples IS 'Reviewed structured calibration metadata. Raw media is referenced under retention policy, never copied automatically.';

CREATE TABLE public.digital_observer_camera_automation_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
    camera_source_id uuid NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    allowed_actions text[] DEFAULT '{}'::text[] NOT NULL,
    lighting_event_types text[] DEFAULT ARRAY['person_detected'::text, 'person_entered'::text, 'vehicle_entered'::text] NOT NULL,
    siren_event_types text[] DEFAULT ARRAY['person_entered'::text, 'vehicle_entered'::text] NOT NULL,
    minimum_confidence numeric(5,4) DEFAULT 0.9000 NOT NULL,
    siren_minimum_confidence numeric(5,4) DEFAULT 0.9500 NOT NULL,
    siren_duration_ms integer DEFAULT 1000 NOT NULL,
    active_from time without time zone DEFAULT '22:00:00'::time without time zone NOT NULL,
    active_until time without time zone DEFAULT '06:00:00'::time without time zone NOT NULL,
    lighting_cooldown_seconds integer DEFAULT 30 NOT NULL,
    siren_cooldown_seconds integer DEFAULT 300 NOT NULL,
    siren_hourly_limit integer DEFAULT 3 NOT NULL,
    approved_by uuid NOT NULL,
    approved_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT digital_guard_camera_policy_actions_check CHECK (((allowed_actions <@ ARRAY['lighting'::text, 'siren'::text]) AND ((array_length(allowed_actions, 1) >= 1) AND (array_length(allowed_actions, 1) <= 2)))),
    CONSTRAINT digital_guard_camera_policy_events_check CHECK (((lighting_event_types <@ ARRAY['person_detected'::text, 'person_entered'::text, 'vehicle_entered'::text]) AND (siren_event_types <@ ARRAY['person_entered'::text, 'vehicle_entered'::text]))),
    CONSTRAINT digital_guard_camera_policy_limits_check CHECK ((((lighting_cooldown_seconds >= 10) AND (lighting_cooldown_seconds <= 3600)) AND ((siren_cooldown_seconds >= 60) AND (siren_cooldown_seconds <= 3600)) AND ((siren_hourly_limit >= 1) AND (siren_hourly_limit <= 6)))),
    CONSTRAINT digital_guard_camera_policy_siren_check CHECK ((siren_duration_ms = 1000)),
    CONSTRAINT digital_guard_camera_policy_threshold_check CHECK ((((minimum_confidence >= 0.5) AND (minimum_confidence <= (1)::numeric)) AND ((siren_minimum_confidence >= 0.9) AND (siren_minimum_confidence <= (1)::numeric)) AND (siren_minimum_confidence >= minimum_confidence)))
);

