COMMENT ON TABLE public.digital_observer_domain_separation_reviews IS 'Future domain and product separation review for Digital Observer.';

CREATE TABLE public.digital_observer_event_clips (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
    camera_source_id uuid,
    signal_id uuid,
    title text NOT NULL,
    clip_status text DEFAULT 'readiness'::text NOT NULL,
    storage_bucket text,
    storage_path text,
    snapshot_storage_path text,
    captured_at timestamp with time zone,
    duration_seconds integer,
    retention_hours integer DEFAULT 24 NOT NULL,
    delete_after timestamp with time zone,
    downloadable boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    media_status text DEFAULT 'missing'::text NOT NULL,
    media_missing_reason text,
    retry_count integer DEFAULT 0 NOT NULL,
    window_seconds_before integer DEFAULT 0 NOT NULL,
    window_seconds_after integer DEFAULT 0 NOT NULL,
    last_media_attempt_at timestamp with time zone,
    storage_backend_id text,
    storage_backend_class text,
    clip_object_id text,
    thumbnail_object_id text,
    clip_sha256 text,
    thumbnail_sha256 text,
    storage_state text DEFAULT 'LEGACY_COMPATIBILITY'::text NOT NULL,
    legal_hold boolean DEFAULT false NOT NULL,
    retention_policy_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT digital_observer_event_clips_integrity_check CHECK ((((clip_sha256 IS NULL) OR (clip_sha256 ~ '^[a-f0-9]{64}$'::text)) AND ((thumbnail_sha256 IS NULL) OR (thumbnail_sha256 ~ '^[a-f0-9]{64}$'::text)))),
    CONSTRAINT digital_observer_event_clips_media_status_check CHECK ((media_status = ANY (ARRAY['missing'::text, 'queued'::text, 'capturing'::text, 'available'::text, 'failed'::text, 'expired'::text]))),
    CONSTRAINT digital_observer_event_clips_retention_check CHECK ((retention_hours = ANY (ARRAY[1, 6, 24, 48]))),
    CONSTRAINT digital_observer_event_clips_retry_check CHECK (((retry_count >= 0) AND (retry_count <= 5))),
    CONSTRAINT digital_observer_event_clips_status_check CHECK ((clip_status = ANY (ARRAY['readiness'::text, 'processing'::text, 'available'::text, 'expired'::text, 'failed'::text, 'deleted'::text]))),
    CONSTRAINT digital_observer_event_clips_storage_backend_class_check CHECK (((storage_backend_class IS NULL) OR (storage_backend_class = ANY (ARRAY['CLOUD_OBJECT_STORAGE'::text, 'LOCAL_NAS'::text, 'ENTERPRISE_OBJECT_STORAGE'::text, 'CUSTOMER_MANAGED_STORAGE'::text])))),
    CONSTRAINT digital_observer_event_clips_storage_guard CHECK (((clip_status <> 'available'::text) OR ((storage_bucket IS NOT NULL) AND (storage_path IS NOT NULL)))),
    CONSTRAINT digital_observer_event_clips_storage_state_check CHECK ((storage_state = ANY (ARRAY['LEGACY_COMPATIBILITY'::text, 'PENDING_UPLOAD'::text, 'AVAILABLE'::text, 'COPYING'::text, 'VERIFYING'::text, 'MIGRATED'::text, 'FAILED'::text, 'DELETED'::text]))),
    CONSTRAINT digital_observer_event_clips_window_check CHECK ((((window_seconds_before >= 0) AND (window_seconds_before <= 15)) AND ((window_seconds_after >= 0) AND (window_seconds_after <= 15))))
);

COMMENT ON TABLE public.digital_observer_event_clips IS 'Event clip metadata with a Digital Observer product maximum retention of 48 hours.';

COMMENT ON COLUMN public.digital_observer_event_clips.media_status IS 'Event media lifecycle. Review UI treats missing thumbnail/clip/source as a technical fault, not a reviewable event.';

COMMENT ON COLUMN public.digital_observer_event_clips.media_missing_reason IS 'Precise non-secret reason media evidence is unavailable.';

COMMENT ON COLUMN public.digital_observer_event_clips.window_seconds_before IS 'Requested local read-only capture window before the event timestamp.';

COMMENT ON COLUMN public.digital_observer_event_clips.window_seconds_after IS 'Requested local read-only capture window after the event timestamp.';

COMMENT ON COLUMN public.digital_observer_event_clips.legal_hold IS 'A true value blocks retention deletion. Full legal case management is outside PUSH 34.';

CREATE TABLE public.digital_observer_extraction_cost_estimates (
