    payment_provider_monthly_cost numeric(12,2) DEFAULT 0 NOT NULL,
    monitoring_logging_monthly_cost numeric(12,2) DEFAULT 0 NOT NULL,
    support_monthly_cost numeric(12,2) DEFAULT 0 NOT NULL,
    estimated_total_monthly_cost numeric(12,2) DEFAULT 0 NOT NULL,
    cost_notes text,
    status text DEFAULT 'draft'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.digital_observer_extraction_cost_estimates IS 'Cost estimate scenarios for keeping inside Gan Batuach, separate Vercel, separate Supabase and full repo split.';

