    CONSTRAINT digital_observer_extraction_risk_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT digital_observer_extraction_risk_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'mitigated'::text, 'accepted_risk'::text, 'blocked'::text, 'deferred'::text])))
);

COMMENT ON TABLE public.digital_observer_extraction_risks IS 'Risk register for future Digital Observer infrastructure extraction.';

CREATE TABLE public.digital_observer_extraction_timeline_estimates (
