CREATE TABLE public.digital_observer_feedback_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
    incident_id uuid NOT NULL,
    target_type text DEFAULT 'INCIDENT'::text NOT NULL,
    target_id uuid NOT NULL,
    camera_source_id uuid,
    label text NOT NULL,
    actor_id uuid NOT NULL,
    actor_role text NOT NULL,
    reason_code text,
    note text,
    previous_feedback_id uuid,
    revision_number integer NOT NULL,
    feedback_version text DEFAULT 'do-feedback-v1'::text NOT NULL,
    source text DEFAULT 'PRODUCT_UI'::text NOT NULL,
    environment text DEFAULT 'PRODUCTION'::text NOT NULL,
    incident_provenance text NOT NULL,
    idempotency_key text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT digital_observer_feedback_environment_check CHECK ((environment = ANY (ARRAY['PRODUCTION'::text, 'TEST'::text, 'CALIBRATION_FIXTURE'::text]))),
    CONSTRAINT digital_observer_feedback_label_check CHECK ((label = ANY (ARRAY['TRUE_SECURITY_EVENT'::text, 'TRUE_EXPECTED_ACTIVITY'::text, 'FALSE_DETECTION'::text, 'FALSE_CORRELATION'::text, 'FALSE_SPATIAL_EVENT'::text, 'UNCERTAIN'::text, 'OTHER'::text]))),
    CONSTRAINT digital_observer_feedback_note_check CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT digital_observer_feedback_provenance_check CHECK (((environment <> 'PRODUCTION'::text) OR (incident_provenance = 'REAL_CAMERA_AI'::text))),
    CONSTRAINT digital_observer_feedback_reason_check CHECK (((reason_code IS NULL) OR (char_length(reason_code) <= 80))),
    CONSTRAINT digital_observer_feedback_revision_check CHECK ((revision_number > 0)),
    CONSTRAINT digital_observer_feedback_source_check CHECK ((source = ANY (ARRAY['PRODUCT_UI'::text, 'PRODUCT_API'::text, 'INTERNAL_ADMIN'::text]))),
    CONSTRAINT digital_observer_feedback_target_check CHECK ((target_type = ANY (ARRAY['INCIDENT'::text, 'EVENT'::text, 'VERIFICATION'::text, 'DECISION'::text, 'EVIDENCE'::text])))
);

COMMENT ON TABLE public.digital_observer_feedback_revisions IS 'Immutable, attributable raw Digital Observer feedback history. A correction creates a new revision.';

