    CONSTRAINT digital_observer_followup_templates_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ready_for_review'::text, 'approved'::text, 'disabled'::text])))
);

COMMENT ON TABLE public.digital_observer_followup_templates IS 'Provider-ready follow-up templates for Digital Observer leads. Real sending remains provider-mode gated.';

CREATE TABLE public.digital_observer_identity_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
    camera_source_id uuid,
    assigned_known_person_id uuid,
    candidate_status text DEFAULT 'observing'::text NOT NULL,
    suggested_label text,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    observation_count integer DEFAULT 1 NOT NULL,
    average_confidence numeric(5,4),
    preview_available boolean DEFAULT false NOT NULL,
    sample_storage_bucket text,
    sample_storage_path text,
    cluster_reference text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT digital_observer_identity_candidate_confidence_check CHECK (((average_confidence IS NULL) OR ((average_confidence >= (0)::numeric) AND (average_confidence <= (1)::numeric)))),
    CONSTRAINT digital_observer_identity_candidate_count_check CHECK ((observation_count > 0)),
    CONSTRAINT digital_observer_identity_candidate_preview_guard CHECK (((preview_available = false) OR ((sample_storage_bucket IS NOT NULL) AND (sample_storage_path IS NOT NULL)))),
    CONSTRAINT digital_observer_identity_candidate_status_check CHECK ((candidate_status = ANY (ARRAY['observing'::text, 'ready_for_review'::text, 'known'::text, 'unknown'::text, 'dismissed'::text, 'blocked'::text])))
);

COMMENT ON TABLE public.digital_observer_identity_candidates IS 'Server-ingested frequent-person candidates. Raw crops and cluster references are never granted to browser roles.';

CREATE TABLE public.digital_observer_incident_verifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
    incident_id uuid NOT NULL,
    risk_evaluation_id uuid NOT NULL,
    status text NOT NULL,
    classification text NOT NULL,
    verification_confidence numeric(5,4) NOT NULL,
    final_decision_confidence numeric(5,4) NOT NULL,
    confirmed_signals jsonb DEFAULT '[]'::jsonb NOT NULL,
    contradictory_signals jsonb DEFAULT '[]'::jsonb NOT NULL,
    verification_reasons text[] DEFAULT '{}'::text[] NOT NULL,
    required_followup text NOT NULL,
    final_decision text NOT NULL,
    fast_path boolean DEFAULT false NOT NULL,
    metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    verification_version text NOT NULL,
    final_decision_version text NOT NULL,
    input_fingerprint text NOT NULL,
    previous_verification_id uuid,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT digital_observer_verification_classification_check CHECK ((classification = ANY (ARRAY['TRUE_SECURITY_EVENT'::text, 'TRUE_EXPECTED_ACTIVITY'::text, 'FALSE_DETECTION'::text, 'FALSE_CORRELATION'::text, 'OTHER_UNKNOWN'::text]))),
    CONSTRAINT digital_observer_verification_confidence_check CHECK ((((verification_confidence >= (0)::numeric) AND (verification_confidence <= (1)::numeric)) AND ((final_decision_confidence >= (0)::numeric) AND (final_decision_confidence <= (1)::numeric)))),
    CONSTRAINT digital_observer_verification_decision_check CHECK ((final_decision = ANY (ARRAY['IGNORE'::text, 'LOG_ONLY'::text, 'PRESERVE_EVIDENCE'::text, 'VERIFY'::text, 'NOTIFY_IN_APP'::text, 'ESCALATION_CANDIDATE'::text]))),
    CONSTRAINT digital_observer_verification_fingerprint_check CHECK ((length(input_fingerprint) = 64)),
    CONSTRAINT digital_observer_verification_followup_check CHECK ((required_followup = ANY (ARRAY['NONE'::text, 'VERIFY'::text, 'PRESERVE_EVIDENCE'::text, 'HUMAN_REVIEW'::text]))),
    CONSTRAINT digital_observer_verification_status_check CHECK ((status = ANY (ARRAY['UNVERIFIED'::text, 'LIKELY'::text, 'CONFIRMED'::text, 'UNCERTAIN'::text, 'REJECTED_FALSE_POSITIVE'::text, 'RESOLVED'::text])))
);

COMMENT ON TABLE public.digital_observer_incident_verifications IS 'Immutable deterministic verification history downstream of canonical Incident and Risk; no LLM and no external action execution.';

COMMENT ON COLUMN public.digital_observer_incident_verifications.classification IS 'Separates a true expected activity from a false detector/correlation result.';

COMMENT ON COLUMN public.digital_observer_incident_verifications.verification_confidence IS 'Confidence that the factual incident is corroborated; distinct from detector confidence and Risk.';

COMMENT ON COLUMN public.digital_observer_incident_verifications.final_decision_confidence IS 'Confidence in the policy-bounded final Decision after Risk and Verification.';

