    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid NOT NULL,
    enrollment_request_id uuid NOT NULL,
    evidence_kind text NOT NULL,
    provider_mode text NOT NULL,
    provider_event_id text,
    idempotency_key text NOT NULL,
    status text NOT NULL,
    manual_method text,
    amount numeric(10,2) NOT NULL,
    currency text DEFAULT 'ILS'::text NOT NULL,
    covered_from date NOT NULL,
    covered_until date NOT NULL,
    reference text,
    note text,
    confirmed_at timestamp with time zone,
    recorded_by uuid,
    reconciliation_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT enrollment_payment_covered_period_check CHECK ((covered_until >= covered_from)),
    CONSTRAINT enrollment_payment_evidence_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT enrollment_payment_evidence_currency_check CHECK ((currency = 'ILS'::text)),
    CONSTRAINT enrollment_payment_evidence_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['electronic'::text, 'manual_arrangement'::text]))),
    CONSTRAINT enrollment_payment_evidence_manual_method_check CHECK (((manual_method IS NULL) OR (manual_method = ANY (ARRAY['bank_transfer'::text, 'standing_order'::text, 'checks'::text])))),
    CONSTRAINT enrollment_payment_evidence_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'failed'::text, 'cancelled'::text, 'reconciliation_required'::text]))),
    CONSTRAINT enrollment_payment_kind_check CHECK ((((evidence_kind = 'manual_arrangement'::text) AND (manual_method IS NOT NULL) AND (provider_event_id IS NULL) AND (provider_mode = 'manual'::text)) OR ((evidence_kind = 'electronic'::text) AND (manual_method IS NULL) AND (provider_event_id IS NOT NULL) AND (provider_mode <> 'manual'::text))))
);

COMMENT ON TABLE public.enrollment_payment_evidence IS 'GB-M16 activation evidence for Parent-to-Garden tuition only; it is separate from Gan Batuach platform subscription billing.';

