    CONSTRAINT final_production_readiness_scores_company_readiness_score_check CHECK (((company_readiness_score >= 0) AND (company_readiness_score <= 100))),
    CONSTRAINT final_production_readiness_scores_digital_observer_score_check CHECK (((digital_observer_score >= 0) AND (digital_observer_score <= 100))),
