    CONSTRAINT final_regulatory_score_range_check CHECK ((((regulatory_readiness_score >= 0) AND (regulatory_readiness_score <= 100)) AND ((privacy_readiness_score >= 0) AND (privacy_readiness_score <= 100)) AND ((security_readiness_score >= 0) AND (security_readiness_score <= 100)) AND ((camera_compliance_score >= 0) AND (camera_compliance_score <= 100)) AND ((ai_governance_score >= 0) AND (ai_governance_score <= 100)) AND ((iso_readiness_score >= 0) AND (iso_readiness_score <= 100)) AND ((launch_readiness_score >= 0) AND (launch_readiness_score <= 100)) AND ((final_readiness_score >= 0) AND (final_readiness_score <= 100))))
);

