    CONSTRAINT gardens_approval_flow_status_check CHECK ((approval_flow_status = ANY (ARRAY['registration_pending'::text, 'admin_approved'::text, 'lead_submitted'::text, 'lead_review'::text, 'lead_approved'::text, 'credentials_sent'::text, 'activation_in_progress'::text, 'payment_pending'::text, 'onboarding_in_progress'::text, 'onboarding_submitted'::text, 'correction_required'::text, 'pending_final_approval'::text, 'active'::text, 'suspended'::text, 'archived'::text]))),
    CONSTRAINT gardens_bootstrap_assignment_after_activation_check CHECK (((bootstrap_inspector_id IS NULL) OR ((status)::text = 'active'::text) OR (inspector_id IS NULL))),
    CONSTRAINT gardens_bootstrap_assignment_status_check CHECK ((bootstrap_assignment_status = ANY (ARRAY['pending'::text, 'assigned'::text, 'admin_reassignment_required'::text]))),
    CONSTRAINT gardens_children_capacity_check CHECK ((children_capacity >= 0)),
    CONSTRAINT gardens_current_children_count_check CHECK ((current_children_count >= 0)),
    CONSTRAINT gardens_enrollment_availability_check CHECK ((enrollment_availability = ANY (ARRAY['accepting'::text, 'paused'::text, 'closed'::text, 'waitlist_only'::text]))),
    CONSTRAINT gardens_final_approval_status_check CHECK ((final_approval_status = ANY (ARRAY['admin_approved'::text, 'activation_in_progress'::text, 'payment_pending'::text, 'onboarding_in_progress'::text, 'onboarding_submitted'::text, 'correction_required'::text, 'pending_final_approval'::text, 'active'::text, 'suspended'::text, 'archived'::text]))),
    CONSTRAINT gardens_ownership_type_check CHECK ((ownership_type = ANY (ARRAY['teacher_is_owner'::text, 'separate_owner'::text, 'teacher_only'::text, 'owner_only'::text]))),
    CONSTRAINT gardens_staff_count_check CHECK ((staff_count >= 0)),
    CONSTRAINT gardens_tuition_due_day_check CHECK (((tuition_due_day >= 1) AND (tuition_due_day <= 31)))
);

