    CONSTRAINT iso_certification_execution_certification_decision_check CHECK ((certification_decision = ANY (ARRAY['not_started'::text, 'pending'::text, 'certified'::text, 'rejected'::text, 'deferred'::text, 'surveillance_required'::text]))),
