    CONSTRAINT iso_certification_execution_stage_2_audit_readiness_check CHECK ((stage_2_audit_readiness = ANY (ARRAY['not_ready'::text, 'preparing'::text, 'ready'::text, 'completed'::text, 'blocked'::text])))
);

