CREATE TABLE public.kindergarten_rating_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    garden_id uuid NOT NULL,
    overall_score integer DEFAULT 0 NOT NULL,
    safety_score integer DEFAULT 0 NOT NULL,
    compliance_score integer DEFAULT 0 NOT NULL,
    inspection_score integer DEFAULT 0 NOT NULL,
    parent_satisfaction_score integer DEFAULT 0 NOT NULL,
    observer_score integer DEFAULT 0 NOT NULL,
    rating_band text DEFAULT 'new'::text NOT NULL,
    trend text DEFAULT 'stable'::text NOT NULL,
    public_score integer,
    public_badge text,
    public_summary text,
    public_display_enabled boolean DEFAULT false NOT NULL,
    explanation jsonb DEFAULT '{}'::jsonb NOT NULL,
    improvement_recommendations jsonb DEFAULT '[]'::jsonb NOT NULL,
    data_sources jsonb DEFAULT '{}'::jsonb NOT NULL,
