    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT kindergarten_rating_band_check CHECK ((rating_band = ANY (ARRAY['excellent'::text, 'strong'::text, 'stable'::text, 'needs_attention'::text, 'critical'::text, 'new'::text]))),
    CONSTRAINT kindergarten_rating_scores_check CHECK ((((overall_score >= 0) AND (overall_score <= 100)) AND ((safety_score >= 0) AND (safety_score <= 100)) AND ((compliance_score >= 0) AND (compliance_score <= 100)) AND ((inspection_score >= 0) AND (inspection_score <= 100)) AND ((parent_satisfaction_score >= 0) AND (parent_satisfaction_score <= 100)) AND ((observer_score >= 0) AND (observer_score <= 100)) AND ((public_score IS NULL) OR ((public_score >= 0) AND (public_score <= 100))))),
    CONSTRAINT kindergarten_rating_trend_check CHECK ((trend = ANY (ARRAY['improving'::text, 'stable'::text, 'declining'::text, 'new'::text])))
);

