);

CREATE TABLE public.kindergarten_risk_profiles (
    kindergarten_id uuid NOT NULL,
    attendance_score integer DEFAULT 0 NOT NULL,
    pickup_score integer DEFAULT 0 NOT NULL,
    safety_score integer DEFAULT 0 NOT NULL,
    supervision_score integer DEFAULT 0 NOT NULL,
    camera_coverage_score integer DEFAULT 0 NOT NULL,
    overall_score integer DEFAULT 0 NOT NULL,
    risk_status text DEFAULT 'mock_baseline'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    calculated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    id uuid DEFAULT gen_random_uuid(),
    garden_id uuid NOT NULL,
    overall_risk_score integer DEFAULT 0 NOT NULL,
    safety_risk integer DEFAULT 0 NOT NULL,
    compliance_risk integer DEFAULT 0 NOT NULL,
    operational_risk integer DEFAULT 0 NOT NULL,
    staffing_risk integer DEFAULT 0 NOT NULL,
    observer_risk integer DEFAULT 0 NOT NULL,
    risk_trend text DEFAULT 'stable'::text NOT NULL,
    risk_level text DEFAULT 'low'::text NOT NULL,
    predicted_risk_level text DEFAULT 'low'::text NOT NULL,
    prediction_summary text,
    explanation jsonb DEFAULT '{}'::jsonb NOT NULL,
    top_contributors jsonb DEFAULT '[]'::jsonb NOT NULL,
    advisory_only boolean DEFAULT true NOT NULL,
    human_review_required boolean DEFAULT true NOT NULL,
    parent_visible boolean DEFAULT false NOT NULL,
    CONSTRAINT kindergarten_predicted_risk_level_check CHECK ((predicted_risk_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT kindergarten_risk_level_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT kindergarten_risk_scores_check CHECK ((((overall_risk_score >= 0) AND (overall_risk_score <= 100)) AND ((safety_risk >= 0) AND (safety_risk <= 100)) AND ((compliance_risk >= 0) AND (compliance_risk <= 100)) AND ((operational_risk >= 0) AND (operational_risk <= 100)) AND ((staffing_risk >= 0) AND (staffing_risk <= 100)) AND ((observer_risk >= 0) AND (observer_risk <= 100)) AND ((COALESCE(attendance_score, 0) >= 0) AND (COALESCE(attendance_score, 0) <= 100)) AND ((COALESCE(pickup_score, 0) >= 0) AND (COALESCE(pickup_score, 0) <= 100)) AND ((COALESCE(safety_score, 0) >= 0) AND (COALESCE(safety_score, 0) <= 100)) AND ((COALESCE(supervision_score, 0) >= 0) AND (COALESCE(supervision_score, 0) <= 100)) AND ((COALESCE(camera_coverage_score, 0) >= 0) AND (COALESCE(camera_coverage_score, 0) <= 100)) AND ((COALESCE(overall_score, 0) >= 0) AND (COALESCE(overall_score, 0) <= 100)))),
    CONSTRAINT kindergarten_risk_status_check CHECK ((risk_status = ANY (ARRAY['mock_baseline'::text, 'needs_configuration'::text, 'baseline_ready'::text, 'review_required'::text]))),
    CONSTRAINT kindergarten_risk_trend_check CHECK ((risk_trend = ANY (ARRAY['rising'::text, 'stable'::text, 'declining'::text, 'new'::text])))
);

COMMENT ON TABLE public.kindergarten_risk_profiles IS 'Advisory internal risk profile. Not parent visible and not an enforcement mechanism.';

COMMENT ON COLUMN public.kindergarten_risk_profiles.parent_visible IS 'Must remain false. Parents do not see predictive risk scores.';

