    CONSTRAINT legal_review_documents_reviewer_check CHECK ((external_reviewer_type = ANY (ARRAY['legal_counsel'::text, 'privacy_lawyer'::text, 'iso_consultant'::text, 'camera_compliance_expert'::text, 'external_auditor'::text, 'accounting_payment_reviewer'::text, 'regulator'::text]))),
    CONSTRAINT legal_review_documents_risk_check CHECK ((risk_level = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT legal_review_documents_status_check CHECK ((status = ANY (ARRAY['draft_for_legal_review'::text, 'ready_for_external_review'::text, 'under_review'::text, 'needs_changes'::text, 'approved'::text, 'approved_with_conditions'::text, 'blocked'::text, 'missing'::text])))
);

