    CONSTRAINT legal_review_external_review_check CHECK ((required_external_review = ANY (ARRAY['legal_counsel'::text, 'privacy_lawyer'::text, 'iso_consultant'::text, 'penetration_tester'::text, 'cloud_security_reviewer'::text, 'accounting_payment_reviewer'::text, 'camera_compliance_expert'::text, 'external_auditor'::text, 'regulator'::text, 'none'::text]))),
