    CONSTRAINT legal_review_status_check CHECK ((current_status = ANY (ARRAY['open'::text, 'in_progress'::text, 'requires_external_review'::text, 'not_started'::text, 'sent_to_reviewer'::text, 'under_review'::text, 'changes_requested'::text, 'needs_changes'::text, 'needs_review'::text, 'requested'::text, 'draft_for_legal_review'::text, 'fixed'::text, 're_review'::text, 'approved'::text, 'approved_with_conditions'::text, 'rejected'::text, 'blocked'::text, 'closed'::text, 'accepted_risk'::text])))
);

