    staff_application_id uuid,
    CONSTRAINT management_invitations_fingerprint_check CHECK ((length(recipient_fingerprint) = 64)),
    CONSTRAINT management_invitations_hash_check CHECK ((length(token_hash) = 64)),
    CONSTRAINT management_invitations_recipient_check CHECK (((recipient_email IS NOT NULL) OR (recipient_phone IS NOT NULL))),
    CONSTRAINT management_invitations_role_check CHECK ((intended_role = ANY (ARRAY['parent'::text, 'staff'::text, 'inspector'::text, 'kindergarten_manager'::text, 'kindergarten_owner'::text]))),
    CONSTRAINT management_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'delivered'::text, 'processing'::text, 'accepted'::text, 'rejected'::text, 'revoked'::text, 'expired'::text, 'superseded'::text]))),
    CONSTRAINT management_invitations_type_check CHECK ((invitation_type = ANY (ARRAY['parent_guardian'::text, 'staff'::text, 'inspector'::text, 'garden_management'::text])))
);

COMMENT ON COLUMN public.management_invitations.token_hash IS 'SHA-256 digest only. Plain invitation tokens must never be persisted or logged.';

COMMENT ON COLUMN public.management_invitations.status IS 'processing is an optimistic lock while an authenticated recipient acceptance is activated.';

