    CONSTRAINT mobile_check_category_check CHECK ((category = ANY (ARRAY['push'::text, 'deep_links'::text, 'security'::text, 'offline'::text, 'camera'::text, 'store_assets'::text, 'privacy'::text, 'analytics'::text, 'crash_monitoring'::text, 'role_experience'::text]))),
    CONSTRAINT mobile_check_platform_check CHECK ((platform = ANY (ARRAY['ios'::text, 'android'::text, 'web_pwa'::text, 'all'::text]))),
    CONSTRAINT mobile_check_score_check CHECK (((readiness_score >= 0) AND (readiness_score <= 100))),
    CONSTRAINT mobile_check_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'prepared'::text, 'ready'::text, 'blocked'::text, 'needs_review'::text, 'not_applicable'::text])))
);

