CREATE TABLE public.mobile_release_readiness_scores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_key text NOT NULL,
    ios_readiness integer DEFAULT 0 NOT NULL,
    android_readiness integer DEFAULT 0 NOT NULL,
    build_readiness integer DEFAULT 0 NOT NULL,
    push_readiness integer DEFAULT 0 NOT NULL,
    privacy_label_readiness integer DEFAULT 0 NOT NULL,
    store_metadata_readiness integer DEFAULT 0 NOT NULL,
    screenshot_readiness integer DEFAULT 0 NOT NULL,
    overall_readiness integer DEFAULT 0 NOT NULL,
    release_status text DEFAULT 'preparing'::text NOT NULL,
    release_blockers jsonb DEFAULT '[]'::jsonb NOT NULL,
    notes text,
    calculated_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mobile_release_score_check CHECK ((((ios_readiness >= 0) AND (ios_readiness <= 100)) AND ((android_readiness >= 0) AND (android_readiness <= 100)) AND ((build_readiness >= 0) AND (build_readiness <= 100)) AND ((push_readiness >= 0) AND (push_readiness <= 100)) AND ((privacy_label_readiness >= 0) AND (privacy_label_readiness <= 100)) AND ((store_metadata_readiness >= 0) AND (store_metadata_readiness <= 100)) AND ((screenshot_readiness >= 0) AND (screenshot_readiness <= 100)) AND ((overall_readiness >= 0) AND (overall_readiness <= 100)))),
    CONSTRAINT mobile_release_status_check CHECK ((release_status = ANY (ARRAY['not_ready'::text, 'preparing'::text, 'internal_testing_ready'::text, 'testflight_ready'::text, 'google_internal_ready'::text, 'store_review_ready'::text, 'submitted'::text, 'in_review'::text, 'approved'::text, 'rejected'::text, 'released'::text, 'blocked'::text])))
);

COMMENT ON TABLE public.mobile_release_readiness_scores IS 'App Store and Google Play submission readiness score snapshots. No submission is performed.';

