    CONSTRAINT observer_correlated_event_links_source_check CHECK ((source_type = ANY (ARRAY['observer_intelligence_signal'::text, 'ai_camera_event'::text, 'audio_observer_event'::text, 'safety_incident'::text, 'pickup_event'::text, 'watch_request_event'::text, 'camera_health'::text, 'mock'::text])))
);

COMMENT ON TABLE public.observer_correlated_event_links IS 'Links reviewed/source events into a single timeline. Source links must not imply identity tracking.';

CREATE TABLE public.observer_correlated_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid,
    kindergarten_id uuid,
    correlation_type text NOT NULL,
    severity text DEFAULT 'medium'::text NOT NULL,
    confidence numeric(5,4) DEFAULT 0 NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
