    end_time timestamp with time zone,
    entry_zone_id uuid,
    destination_zone_id uuid,
    involved_camera_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    involved_zone_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    timeline_summary jsonb DEFAULT '[]'::jsonb NOT NULL,
    confidence_factors jsonb DEFAULT '{}'::jsonb NOT NULL,
    review_notes text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    title text,
    summary text,
    opened_at timestamp with time zone,
    last_activity_at timestamp with time zone,
    closed_at timestamp with time zone,
    primary_camera_source_id uuid,
    involved_track_ids text[] DEFAULT '{}'::text[] NOT NULL,
    related_event_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    provenance text,
    correlation_version text,
    created_by_origin text,
    current_risk_score integer,
    peak_risk_score integer,
    current_risk_band text,
    risk_evaluation_confidence numeric(5,4),
    current_decision text,
    risk_updated_at timestamp with time zone,
    latest_risk_evaluation_id uuid,
    current_verification_status text,
    verification_classification text,
    verification_confidence numeric(5,4),
    final_decision text,
    final_decision_confidence numeric(5,4),
    verification_updated_at timestamp with time zone,
    latest_verification_id uuid,
    current_feedback_label text,
    latest_feedback_revision_id uuid,
    feedback_updated_at timestamp with time zone,
    current_ground_truth_label text,
    latest_ground_truth_review_id uuid,
    ground_truth_reviewed_at timestamp with time zone,
    CONSTRAINT observer_correlated_events_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT observer_correlated_events_scope_check CHECK (((observer_site_id IS NOT NULL) OR (kindergarten_id IS NOT NULL))),
    CONSTRAINT observer_correlated_events_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'low'::text, 'medium'::text, 'high'::text, 'urgent'::text, 'critical'::text]))),
    CONSTRAINT observer_correlated_events_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'resolved'::text, 'closed'::text, 'reviewing'::text, 'confirmed'::text, 'dismissed'::text, 'escalated'::text, 'false_positive'::text, 'needs_more_data'::text]))),
    CONSTRAINT observer_correlated_events_type_check CHECK ((correlation_type = ANY (ARRAY['multi_camera_timeline'::text, 'cross_camera_confirmation'::text, 'audio_video_correlation'::text, 'pickup_path_correlation'::text, 'watch_request_correlation'::text, 'safety_event_correlation'::text, 'camera_health_correlation'::text, 'mock_correlation'::text]))),
    CONSTRAINT observer_incident_current_risk_score_check CHECK (((current_risk_score IS NULL) OR ((current_risk_score >= 0) AND (current_risk_score <= 100)))),
    CONSTRAINT observer_incident_decision_check CHECK (((current_decision IS NULL) OR (current_decision = ANY (ARRAY['IGNORE'::text, 'LOG_ONLY'::text, 'PRESERVE_EVIDENCE'::text, 'VERIFY'::text, 'NOTIFY_IN_APP'::text, 'ESCALATION_CANDIDATE'::text])))),
    CONSTRAINT observer_incident_feedback_label_check CHECK (((current_feedback_label IS NULL) OR (current_feedback_label = ANY (ARRAY['TRUE_SECURITY_EVENT'::text, 'TRUE_EXPECTED_ACTIVITY'::text, 'FALSE_DETECTION'::text, 'FALSE_CORRELATION'::text, 'FALSE_SPATIAL_EVENT'::text, 'UNCERTAIN'::text, 'OTHER'::text])))),
    CONSTRAINT observer_incident_final_decision_check CHECK (((final_decision IS NULL) OR (final_decision = ANY (ARRAY['IGNORE'::text, 'LOG_ONLY'::text, 'PRESERVE_EVIDENCE'::text, 'VERIFY'::text, 'NOTIFY_IN_APP'::text, 'ESCALATION_CANDIDATE'::text])))),
    CONSTRAINT observer_incident_final_decision_confidence_check CHECK (((final_decision_confidence IS NULL) OR ((final_decision_confidence >= (0)::numeric) AND (final_decision_confidence <= (1)::numeric)))),
    CONSTRAINT observer_incident_ground_truth_label_check CHECK (((current_ground_truth_label IS NULL) OR (current_ground_truth_label = ANY (ARRAY['TRUE_SECURITY_EVENT'::text, 'TRUE_EXPECTED_ACTIVITY'::text, 'FALSE_DETECTION'::text, 'FALSE_CORRELATION'::text, 'FALSE_SPATIAL_EVENT'::text, 'UNCERTAIN'::text, 'OTHER'::text])))),
    CONSTRAINT observer_incident_peak_risk_score_check CHECK (((peak_risk_score IS NULL) OR ((peak_risk_score >= 0) AND (peak_risk_score <= 100)))),
    CONSTRAINT observer_incident_risk_band_check CHECK (((current_risk_band IS NULL) OR (current_risk_band = ANY (ARRAY['LOW'::text, 'GUARDED'::text, 'ELEVATED'::text, 'HIGH'::text, 'CRITICAL'::text])))),
    CONSTRAINT observer_incident_risk_confidence_check CHECK (((risk_evaluation_confidence IS NULL) OR ((risk_evaluation_confidence >= (0)::numeric) AND (risk_evaluation_confidence <= (1)::numeric)))),
    CONSTRAINT observer_incident_verification_classification_check CHECK (((verification_classification IS NULL) OR (verification_classification = ANY (ARRAY['TRUE_SECURITY_EVENT'::text, 'TRUE_EXPECTED_ACTIVITY'::text, 'FALSE_DETECTION'::text, 'FALSE_CORRELATION'::text, 'OTHER_UNKNOWN'::text])))),
    CONSTRAINT observer_incident_verification_confidence_check CHECK (((verification_confidence IS NULL) OR ((verification_confidence >= (0)::numeric) AND (verification_confidence <= (1)::numeric)))),
    CONSTRAINT observer_incident_verification_status_check CHECK (((current_verification_status IS NULL) OR (current_verification_status = ANY (ARRAY['UNVERIFIED'::text, 'LIKELY'::text, 'CONFIRMED'::text, 'UNCERTAIN'::text, 'REJECTED_FALSE_POSITIVE'::text, 'RESOLVED'::text]))))
);

COMMENT ON TABLE public.observer_correlated_events IS 'Canonical Digital Observer Incident storage for do-track-v1 rows; legacy correlation rows remain compatible.';

COMMENT ON COLUMN public.observer_correlated_events.timeline_summary IS 'Ordered event timeline for human review. No biometric path tracking.';

COMMENT ON COLUMN public.observer_correlated_events.confidence_factors IS 'Mock confidence factors such as camera count and sensor diversity. Human review required.';

