    level text DEFAULT 'info'::text NOT NULL,
    message text NOT NULL,
    failure_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    observer_site_id uuid,
    CONSTRAINT observer_job_logs_level_check CHECK ((level = ANY (ARRAY['info'::text, 'warning'::text, 'error'::text, 'success'::text])))
);

CREATE TABLE public.observer_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    worker_id uuid,
    kindergarten_id uuid,
    camera_id uuid,
    zone_id uuid,
    rule_id uuid,
    job_type text DEFAULT 'mock_detection'::text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority integer DEFAULT 5 NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    max_retries integer DEFAULT 3 NOT NULL,
    cooldown_until timestamp with time zone,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    last_run_at timestamp with time zone,
    failure_reason text,
    result_event_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    observer_site_id uuid,
    CONSTRAINT observer_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text, 'retrying'::text, 'cancelled'::text]))),
    CONSTRAINT observer_jobs_type_check CHECK ((job_type = ANY (ARRAY['mock_detection'::text, 'camera_health_check'::text, 'frame_sample'::text, 'rule_evaluation'::text])))
);

COMMENT ON TABLE public.observer_jobs IS 'AI Observer job queue foundation. Phase 2D uses mock detections only; no real child video processing.';

CREATE TABLE public.observer_managed_device_auth_nonces (
    enrollment_id uuid NOT NULL,
    credential_version integer NOT NULL,
    nonce_hash text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT observer_managed_device_auth_nonces_nonce_hash_check CHECK ((nonce_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT observer_managed_device_nonce_ttl CHECK (((expires_at > observed_at) AND (expires_at <= (observed_at + '00:05:00'::interval))))
);

CREATE TABLE public.observer_managed_device_credentials (
    id uuid NOT NULL,
    enrollment_id uuid NOT NULL,
    credential_version integer NOT NULL,
    algorithm text NOT NULL,
    public_key_spki text NOT NULL,
    credential_state text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    retired_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT observer_managed_device_credentials_algorithm_check CHECK ((algorithm = 'Ed25519'::text)),
    CONSTRAINT observer_managed_device_credentials_credential_state_check CHECK ((credential_state = ANY (ARRAY['PENDING'::text, 'ACTIVE'::text, 'RETIRED'::text, 'REVOKED'::text]))),
    CONSTRAINT observer_managed_device_credentials_credential_version_check CHECK ((credential_version > 0)),
    CONSTRAINT observer_managed_device_credentials_public_key_spki_check CHECK ((((length(public_key_spki) >= 40) AND (length(public_key_spki) <= 256)) AND (public_key_spki ~ '^[A-Za-z0-9_-]+$'::text)))
);

COMMENT ON TABLE public.observer_managed_device_credentials IS 'Public Ed25519 credentials for DO-managed local components. Private keys never leave platform-protected local storage.';

CREATE TABLE public.observer_managed_device_rotations (
    id uuid NOT NULL,
    enrollment_id uuid NOT NULL,
    old_credential_version integer NOT NULL,
    new_credential_version integer NOT NULL,
    challenge_hash text NOT NULL,
    state text DEFAULT 'PENDING'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    CONSTRAINT observer_managed_device_rotation_ttl CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:10:00'::interval)))),
    CONSTRAINT observer_managed_device_rotations_challenge_hash_check CHECK ((challenge_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT observer_managed_device_rotations_state_check CHECK ((state = ANY (ARRAY['PENDING'::text, 'CONFIRMED'::text, 'EXPIRED'::text, 'CANCELLED'::text])))
);

CREATE TABLE public.observer_model_readiness_catalog (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
