    monitoring_hours jsonb DEFAULT '{}'::jsonb NOT NULL,
    event_retention_days integer DEFAULT 30 NOT NULL,
    recording_retention_days integer DEFAULT 0 NOT NULL,
    ai_event_types_enabled jsonb DEFAULT '[]'::jsonb NOT NULL,
    feature_flags jsonb DEFAULT '{}'::jsonb NOT NULL,
    sms_alerts_enabled boolean DEFAULT false NOT NULL,
    whatsapp_alerts_enabled boolean DEFAULT false NOT NULL,
    human_review_required boolean DEFAULT true NOT NULL,
    monthly_price numeric(12,2) DEFAULT 0 NOT NULL,
    annual_price numeric(12,2) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'ILS'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    live_view_enabled boolean DEFAULT true NOT NULL,
    alert_channels jsonb DEFAULT '["in_app"]'::jsonb NOT NULL,
    multi_user_access boolean DEFAULT false NOT NULL,
    advanced_analytics boolean DEFAULT false NOT NULL,
    recording_retention_readiness boolean DEFAULT false NOT NULL,
    package_feature_matrix jsonb DEFAULT '{}'::jsonb NOT NULL,
    payment_provider_mode text DEFAULT 'readiness_only'::text NOT NULL,
    recording_retention_hours integer DEFAULT 0 NOT NULL,
