    CONSTRAINT observer_monitoring_packages_commercial_limits_check CHECK (((COALESCE(site_limit, 0) >= 0) AND (COALESCE(user_limit, 0) >= 0) AND (sms_quota >= 0) AND (voice_call_quota >= 0) AND ((trial_days >= 0) AND (trial_days <= 90)) AND ((annual_discount_percent >= (0)::numeric) AND (annual_discount_percent <= (100)::numeric)))),
    CONSTRAINT observer_monitoring_packages_recording_hours_check CHECK (((recording_retention_hours >= 0) AND (recording_retention_hours <= 48))),
    CONSTRAINT observer_monitoring_packages_type_check CHECK ((package_type = ANY (ARRAY['home'::text, 'business'::text, 'enterprise'::text, 'custom'::text])))
);

COMMENT ON TABLE public.observer_monitoring_packages IS 'Future standalone Digital Observer packages. Not used for Gan Batuach kindergarten subscriptions.';

CREATE TABLE public.observer_monitoring_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid NOT NULL,
