CREATE VIEW public.observer_packages AS
 SELECT id,
    name,
    package_key,
    description,
    package_type,
    camera_limit,
    monitoring_mode,
    monitoring_hours,
    event_retention_days,
    recording_retention_days,
    recording_retention_readiness,
    ai_event_types_enabled,
    live_view_enabled,
    alert_channels,
    multi_user_access,
    advanced_analytics,
    human_review_required,
    monthly_price,
    annual_price,
    currency,
    active,
    sort_order,
    package_feature_matrix,
    metadata,
    created_at,
    updated_at
   FROM public.observer_monitoring_packages;

COMMENT ON VIEW public.observer_packages IS 'Alias view for observer_monitoring_packages, aligned to the Phase 177 observer_packages naming requirement.';

