    CONSTRAINT observer_performance_deployment_check CHECK ((deployment_scope = ANY (ARRAY['shadow'::text, 'test'::text, 'pilot'::text, 'production_candidate'::text]))),
    CONSTRAINT observer_performance_scope_check CHECK ((scope_type = ANY (ARRAY['global'::text, 'site'::text, 'camera'::text, 'zone'::text, 'model'::text, 'deployment'::text]))),
    CONSTRAINT observer_performance_scores_check CHECK ((((precision_score >= (0)::numeric) AND (precision_score <= (1)::numeric)) AND ((recall_score >= (0)::numeric) AND (recall_score <= (1)::numeric)) AND ((false_positive_rate >= (0)::numeric) AND (false_positive_rate <= (1)::numeric)) AND ((false_negative_rate >= (0)::numeric) AND (false_negative_rate <= (1)::numeric)) AND ((confidence_average >= (0)::numeric) AND (confidence_average <= (1)::numeric)) AND ((confidence_stability >= (0)::numeric) AND (confidence_stability <= (1)::numeric)) AND ((maturity_score >= 0) AND (maturity_score <= 100)) AND ((readiness_score >= 0) AND (readiness_score <= 100)))),
    CONSTRAINT observer_performance_training_status_check CHECK ((training_status = ANY (ARRAY['not_ready'::text, 'collecting'::text, 'review_ready'::text, 'candidate'::text, 'blocked'::text])))
);

