CREATE TABLE public.observer_sites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    site_type text DEFAULT 'kindergarten'::text NOT NULL,
    owner_profile_id uuid,
    garden_id uuid,
    address text,
    timezone text DEFAULT 'Asia/Jerusalem'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    monitoring_enabled boolean DEFAULT false NOT NULL,
    camera_limit integer,
    monitoring_hours jsonb DEFAULT '{}'::jsonb NOT NULL,
    event_retention_days integer DEFAULT 30 NOT NULL,
    ai_features jsonb DEFAULT '{}'::jsonb NOT NULL,
    storage_limit_mb integer,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    observer_package_id uuid,
    observer_subscription_status public.observer_site_subscription_status DEFAULT 'trial'::public.observer_site_subscription_status NOT NULL,
    observer_trial_start timestamp with time zone,
    observer_trial_end timestamp with time zone,
    observer_renewal_date date,
    observer_suspended_at timestamp with time zone,
    observer_cancellation_reason text,
    observer_package_override_limits jsonb DEFAULT '{}'::jsonb NOT NULL,
    digital_observer_organization_id uuid,
    city text,
    street text,
    building_number text,
    apartment_number text,
    floor_kind text DEFAULT 'floor'::text NOT NULL,
    floor_number integer,
    postal_code text,
    country_code text DEFAULT 'IL'::text NOT NULL,
    formatted_address text,
    address_provider text,
    address_place_id text,
    latitude numeric(9,6),
    longitude numeric(9,6),
    address_verification_status text DEFAULT 'unverified'::text NOT NULL,
    address_verified_at timestamp with time zone,
    business_handles_children boolean DEFAULT false NOT NULL,
    vision_privacy_mode text DEFAULT 'standard_consent'::text NOT NULL,
    observer_runtime_status text DEFAULT 'setup'::text NOT NULL,
    learning_started_at timestamp with time zone,
    learning_target_days integer DEFAULT 30 NOT NULL,
    engine_mode text DEFAULT 'standard_biometric'::text NOT NULL,
    CONSTRAINT observer_sites_address_verification_check CHECK ((address_verification_status = ANY (ARRAY['unverified'::text, 'suggested'::text, 'verified'::text, 'failed'::text, 'manual_review'::text]))),
    CONSTRAINT observer_sites_coordinates_check CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric)) AND ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))))),
    CONSTRAINT observer_sites_engine_mode_check CHECK ((engine_mode = ANY (ARRAY['standard_biometric'::text, 'kindergarten_skeleton'::text]))),
    CONSTRAINT observer_sites_engine_privacy_consistency_check CHECK ((((engine_mode = 'kindergarten_skeleton'::text) AND (vision_privacy_mode = 'skeleton_only'::text)) OR ((engine_mode = 'standard_biometric'::text) AND (vision_privacy_mode = 'standard_consent'::text)))),
    CONSTRAINT observer_sites_floor_kind_check CHECK ((floor_kind = ANY (ARRAY['ground'::text, 'floor'::text]))),
    CONSTRAINT observer_sites_learning_target_check CHECK (((learning_target_days >= 1) AND (learning_target_days <= 90))),
    CONSTRAINT observer_sites_runtime_status_check CHECK ((observer_runtime_status = ANY (ARRAY['setup'::text, 'connection_testing'::text, 'learning_readiness'::text, 'learning_shadow'::text, 'active'::text, 'paused'::text, 'provider_required'::text, 'suspended'::text]))),
    CONSTRAINT observer_sites_type_check CHECK ((site_type = ANY (ARRAY['kindergarten'::text, 'home'::text, 'office'::text, 'business'::text, 'warehouse'::text, 'store'::text, 'parking_lot'::text, 'school_future'::text, 'municipality_future'::text, 'construction_site_future'::text, 'clinic_future'::text, 'factory_future'::text, 'custom'::text]))),
    CONSTRAINT observer_sites_vision_privacy_mode_check CHECK ((vision_privacy_mode = ANY (ARRAY['standard_consent'::text, 'skeleton_only'::text])))
);

COMMENT ON TABLE public.observer_sites IS 'Generic Digital Observer site abstraction. Kindergarten remains primary, future sites can be homes/offices/businesses/warehouses/stores/parking lots.';

COMMENT ON COLUMN public.observer_sites.monitoring_hours IS 'Future monitoring schedule by site. No billing or monitoring daemon in this phase.';

COMMENT ON COLUMN public.observer_sites.ai_features IS 'Future observer subscription feature flags. Does not enable real AI by itself.';

COMMENT ON COLUMN public.observer_sites.latitude IS 'Verified or suggested site latitude for a future admin map and regional aggregates; never a browser-exposed provider secret.';

COMMENT ON COLUMN public.observer_sites.vision_privacy_mode IS 'Child-focused businesses must use skeleton_only. Homes and other businesses require explicit consent before biometric recognition.';

COMMENT ON COLUMN public.observer_sites.engine_mode IS 'Canonical routing mode: kindergarten_skeleton never loads face/biometric processing; standard_biometric is subject to consent and provider controls.';

CREATE TABLE public.observer_situation_summaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observer_site_id uuid,
    kindergarten_id uuid,
    summary_type text NOT NULL,
    severity text DEFAULT 'info'::text NOT NULL,
    confidence numeric(5,4) DEFAULT 0 NOT NULL,
    title text NOT NULL,
    summary text NOT NULL,
    recommended_actions jsonb DEFAULT '[]'::jsonb NOT NULL,
    related_event_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    dedupe_key text NOT NULL,
    context_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT observer_situation_summaries_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT observer_situation_summaries_scope_check CHECK (((observer_site_id IS NOT NULL) OR (kindergarten_id IS NOT NULL))),
    CONSTRAINT observer_situation_summaries_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'low'::text, 'medium'::text, 'high'::text, 'urgent'::text, 'critical'::text]))),
    CONSTRAINT observer_situation_summaries_status_check CHECK ((status = ANY (ARRAY['open'::text, 'reviewing'::text, 'handled'::text, 'dismissed'::text, 'escalated'::text, 'snoozed'::text]))),
    CONSTRAINT observer_situation_summaries_type_check CHECK ((summary_type = ANY (ARRAY['needs_review_now'::text, 'camera_health_warning'::text, 'unresolved_safety_indicators'::text, 'correlated_event_attention'::text, 'audio_indicator_attention'::text, 'watch_request_attention'::text, 'pickup_verification_attention'::text, 'learning_readiness'::text, 'site_health'::text, 'mock_summary'::text])))
);

COMMENT ON TABLE public.observer_situation_summaries IS 'Unified Digital Observer situation summaries. Advisory only: no automatic accusations, no parent raw AI access, human review required.';

COMMENT ON COLUMN public.observer_situation_summaries.recommended_actions IS 'Careful operational recommendations only. No legal or disciplinary wording.';

COMMENT ON COLUMN public.observer_situation_summaries.related_event_ids IS 'JSON list of related source ids. These ids are for review context, not identity tracking.';

COMMENT ON COLUMN public.observer_situation_summaries.context_snapshot IS 'Context used for safer interpretation: routines, zones, learning maturity, camera health and recent reviewed signals.';

