    CONSTRAINT penetration_test_execution_environment_check CHECK ((environment = ANY (ARRAY['staging'::text, 'test'::text, 'sandbox'::text, 'production_approved'::text]))),
    CONSTRAINT penetration_test_execution_remediation_status_check CHECK ((remediation_status = ANY (ARRAY['not_started'::text, 'triage'::text, 'in_progress'::text, 'internal_verification'::text, 'external_retest'::text, 'verified'::text, 'closed'::text, 'blocked'::text]))),
    CONSTRAINT penetration_test_execution_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'scheduled'::text, 'in_progress'::text, 'report_received'::text, 'retest_pending'::text, 'completed'::text, 'blocked'::text, 'cancelled'::text])))
);

