CREATE TABLE public.penetration_test_readiness_score (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_key text NOT NULL,
    readiness_score integer DEFAULT 0 NOT NULL,
    scope_readiness integer DEFAULT 0 NOT NULL,
    test_environment_readiness integer DEFAULT 0 NOT NULL,
    test_user_readiness integer DEFAULT 0 NOT NULL,
    documentation_readiness integer DEFAULT 0 NOT NULL,
    audit_readiness integer DEFAULT 0 NOT NULL,
    remediation_workflow_readiness integer DEFAULT 0 NOT NULL,
    open_findings integer DEFAULT 0 NOT NULL,
    critical_findings integer DEFAULT 0 NOT NULL,
    high_findings integer DEFAULT 0 NOT NULL,
    external_review_status text DEFAULT 'not_started'::text NOT NULL,
    generated_from jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT penetration_test_external_status_check CHECK ((external_review_status = ANY (ARRAY['not_started'::text, 'ready_for_external_tester'::text, 'scheduled'::text, 'in_progress'::text, 'retest_pending'::text, 'completed'::text, 'blocked'::text]))),
    CONSTRAINT penetration_test_score_range_check CHECK ((((readiness_score >= 0) AND (readiness_score <= 100)) AND ((scope_readiness >= 0) AND (scope_readiness <= 100)) AND ((test_environment_readiness >= 0) AND (test_environment_readiness <= 100)) AND ((test_user_readiness >= 0) AND (test_user_readiness <= 100)) AND ((documentation_readiness >= 0) AND (documentation_readiness <= 100)) AND ((audit_readiness >= 0) AND (audit_readiness <= 100)) AND ((remediation_workflow_readiness >= 0) AND (remediation_workflow_readiness <= 100))))
);

COMMENT ON TABLE public.penetration_test_readiness_score IS 'Internal penetration-test readiness score. Not a penetration test result.';

