    CONSTRAINT predictive_risk_signal_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT predictive_risk_signal_type_check CHECK ((signal_type = ANY (ARRAY['repeated_incidents'::text, 'repeated_complaints'::text, 'repeated_compliance_failures'::text, 'repeated_staffing_issues'::text, 'repeated_observer_alerts'::text, 'camera_outage_pattern'::text, 'attendance_anomaly_pattern'::text, 'pickup_anomaly_pattern'::text, 'child_safety_indicator'::text, 'staff_operational_indicator'::text])))
);

