    CONSTRAINT prevention_action_type_check CHECK ((recommendation_type = ANY (ARRAY['schedule_inspection'::text, 'increase_supervision'::text, 'review_staffing'::text, 'complete_compliance_actions'::text, 'review_safety_procedures'::text, 'follow_up_inspection'::text, 'urgent_review'::text, 'compliance_review'::text, 'management_action'::text])))
);

