    CONSTRAINT privacy_by_design_score_check CHECK (((readiness_score >= 0) AND (readiness_score <= 100))),
    CONSTRAINT privacy_by_design_status_check CHECK ((status = ANY (ARRAY['implemented'::text, 'partial'::text, 'missing'::text, 'legal_review_required'::text]))),
    CONSTRAINT privacy_by_design_vertical_check CHECK ((vertical_key = ANY (ARRAY['digital_observer_core'::text, 'gan_batuach'::text, 'school_safe'::text, 'business_observer'::text, 'home_observer'::text, 'municipality_observer'::text])))
);

COMMENT ON TABLE public.privacy_by_design_controls IS 'Privacy-by-design control readiness across data minimization, purpose, access and retention.';

