    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT privacy_execution_action_check CHECK ((action_type = ANY (ARRAY['export'::text, 'correct'::text, 'delete'::text, 'anonymize'::text, 'redact'::text, 'revoke_access'::text, 'revoke_token'::text, 'preserve_audit'::text, 'notify_user'::text]))),
    CONSTRAINT privacy_execution_status_check CHECK ((status = ANY (ARRAY['pending_review'::text, 'approved'::text, 'processing'::text, 'completed'::text, 'blocked'::text, 'failed'::text, 'cancelled'::text])))
);

COMMENT ON TABLE public.privacy_execution_actions IS 'Admin-reviewed privacy execution actions. No automatic deletion without scope and legal-hold checks.';

