    notes text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT privacy_scope_action_check CHECK ((action_recommendation = ANY (ARRAY['export'::text, 'correct'::text, 'delete'::text, 'anonymize'::text, 'retain'::text, 'review'::text, 'exclude'::text])))
);

COMMENT ON TABLE public.privacy_request_scope_items IS 'Calculated subject-scope items for access, export, correction, deletion and anonymization requests.';

CREATE TABLE public.privacy_rights_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_key text NOT NULL,
    requester_profile_id uuid,
    garden_id uuid,
    request_type text NOT NULL,
    data_subject_type text NOT NULL,
    data_subject_id uuid,
    status text DEFAULT 'received'::text NOT NULL,
    due_at timestamp with time zone,
    completed_at timestamp with time zone,
    response_summary text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    requested_by uuid,
    subject_user_id uuid,
    subject_type text,
    child_id uuid,
    request_reason text,
    reviewer_id uuid,
    decision_reason text,
    scope_calculated_at timestamp with time zone,
    legal_hold_checked_at timestamp with time zone,
    execution_started_at timestamp with time zone,
    execution_status text DEFAULT 'not_started'::text NOT NULL,
    anonymized_subject_id text,
    export_package_path text,
    retention_conflicts jsonb DEFAULT '[]'::jsonb NOT NULL,
    legal_hold_conflicts jsonb DEFAULT '[]'::jsonb NOT NULL,
    notification_status text DEFAULT 'pending'::text NOT NULL,
    CONSTRAINT privacy_request_execution_status_check CHECK ((execution_status = ANY (ARRAY['not_started'::text, 'scoped'::text, 'blocked'::text, 'ready'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'manual_review'::text]))),
    CONSTRAINT privacy_request_notification_status_check CHECK ((notification_status = ANY (ARRAY['pending'::text, 'queued'::text, 'sent'::text, 'failed'::text, 'not_required'::text]))),
    CONSTRAINT privacy_rights_request_type_check CHECK ((request_type = ANY (ARRAY['access'::text, 'correction'::text, 'deletion'::text, 'export'::text, 'restriction'::text, 'objection'::text, 'anonymization'::text]))),
    CONSTRAINT privacy_rights_status_check CHECK ((status = ANY (ARRAY['received'::text, 'validating'::text, 'in_progress'::text, 'waiting_approval'::text, 'completed'::text, 'rejected'::text, 'cancelled'::text, 'submitted'::text, 'under_review'::text, 'approved'::text, 'processing'::text, 'blocked_by_legal_hold'::text]))),
    CONSTRAINT privacy_rights_subject_type_check CHECK ((data_subject_type = ANY (ARRAY['child'::text, 'parent'::text, 'staff'::text, 'manager'::text, 'inspector'::text, 'garden'::text])))
);

COMMENT ON TABLE public.privacy_rights_requests IS 'Privacy rights request workflow for access, correction, deletion and export readiness.';

CREATE VIEW public.privacy_requests AS
 SELECT id,
    request_key,
    requester_profile_id,
    requested_by,
    subject_user_id,
    COALESCE(subject_type, data_subject_type) AS subject_type,
    garden_id,
    child_id,
    request_type,
    status,
    request_reason,
    reviewer_id,
    decision_reason,
    completed_at,
    due_at,
    response_summary,
    scope_calculated_at,
    legal_hold_checked_at,
    execution_status,
    anonymized_subject_id,
    export_package_path,
    retention_conflicts,
    legal_hold_conflicts,
    notification_status,
    metadata,
    created_at,
    updated_at
   FROM public.privacy_rights_requests;

