    communication_log_id uuid,
    template_id uuid,
    recipient_profile_id uuid,
    kindergarten_id uuid,
    event_type public.sms_event_type NOT NULL,
    recipient_phone text,
    masked_phone text,
    message_preview text,
    status public.sms_delivery_status DEFAULT 'queued'::public.sms_delivery_status NOT NULL,
    provider text DEFAULT 'mock_sms'::text NOT NULL,
    provider_message_id text,
    provider_reference text,
    variables jsonb DEFAULT '{}'::jsonb NOT NULL,
    failure_reason text,
    retry_attempts integer DEFAULT 0 NOT NULL,
    max_retry_attempts integer DEFAULT 3 NOT NULL,
    next_retry_at timestamp with time zone,
    queued_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    failed_at timestamp with time zone,
    dead_letter_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text
);

CREATE TABLE public.sms_opt_ins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    phone_e164 text NOT NULL,
    opted_in boolean DEFAULT false NOT NULL,
    opt_in_source text DEFAULT 'not_collected'::text NOT NULL,
    consent_text text,
    consented_at timestamp with time zone,
    revoked_at timestamp with time zone,
    last_verified_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.sms_provider_configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text DEFAULT 'mock_sms'::text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    mode text DEFAULT 'mock'::text NOT NULL,
    sender_id text,
    api_key_configured boolean DEFAULT false NOT NULL,
    webhook_configured boolean DEFAULT false NOT NULL,
    last_health_status text DEFAULT 'not_configured'::text NOT NULL,
    last_health_checked_at timestamp with time zone,
    last_error text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.sms_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_key text NOT NULL,
    template_name text NOT NULL,
    category public.sms_template_category DEFAULT 'utility'::public.sms_template_category NOT NULL,
    language text DEFAULT 'he'::text NOT NULL,
    status public.sms_template_status DEFAULT 'draft'::public.sms_template_status NOT NULL,
    event_type public.sms_event_type NOT NULL,
    variables jsonb DEFAULT '[]'::jsonb NOT NULL,
    body_template text NOT NULL,
    provider text DEFAULT 'mock_sms'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.staff (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid,
    garden_id uuid NOT NULL,
    full_name text NOT NULL,
    role_title text NOT NULL,
    identity_number text,
    phone text,
    email text,
    address text,
    class_group text,
    start_date date,
    background_check_status public.document_status DEFAULT 'missing'::public.document_status NOT NULL,
    police_clearance_status public.document_status DEFAULT 'missing'::public.document_status NOT NULL,
    approved_to_work boolean DEFAULT false NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    profile_photo_url text,
    sexual_offense_clearance_url text,
    criminal_clearance_url text,
    onboarding_status text DEFAULT 'profile_incomplete'::text NOT NULL,
    manager_approved_at timestamp with time zone,
    inspector_verified_at timestamp with time zone,
    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text,
    invited_by uuid,
    activated_by uuid,
    invited_at timestamp with time zone,
    account_created_at timestamp with time zone,
    onboarding_completed_at timestamp with time zone,
    activated_at timestamp with time zone,
    correction_note text,
    verification_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    policy_acknowledged boolean DEFAULT false NOT NULL,
    role_assignment_confirmed boolean DEFAULT false NOT NULL,
    police_sex_offender_clearance_status text DEFAULT 'missing'::text NOT NULL,
    police_sex_offender_clearance_expires_at date,
    first_aid_certification_status text DEFAULT 'missing'::text NOT NULL,
    first_aid_certification_expires_at date,
    safe_conduct_training_status text DEFAULT 'missing'::text NOT NULL,
    safe_conduct_training_expires_at date,
    mandatory_permit_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    identity_number_encrypted text,
    identity_number_hash text,
    address_encrypted text,
    emergency_contact_encrypted text,
    encryption_version text,
    CONSTRAINT staff_onboarding_status_check CHECK ((onboarding_status = ANY (ARRAY['invited'::text, 'account_created'::text, 'profile_incomplete'::text, 'pending_verification'::text, 'correction_required'::text, 'active'::text, 'suspended'::text])))
);

CREATE TABLE public.staff_absence_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    absence_type text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reason text,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_absence_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT staff_absence_type_check CHECK ((absence_type = ANY (ARRAY['vacation'::text, 'sickness'::text, 'emergency'::text, 'approved_leave'::text])))
);

CREATE TABLE public.staff_candidate_profiles (
    profile_id uuid NOT NULL,
    full_name text,
    phone text,
    email text,
    identity_number_hash text,
    profile_photo_url text,
    date_of_birth date,
    previous_kindergarten_experience boolean,
    previous_kindergarten_name text,
    work_experience text,
    document_status jsonb DEFAULT '{}'::jsonb NOT NULL,
    duplicate_flags jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'profile_incomplete'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    city text,
    professional_role text,
    qualification_keys text[] DEFAULT '{}'::text[] NOT NULL,
    availability jsonb DEFAULT '{}'::jsonb NOT NULL,
    preferred_age_groups text[] DEFAULT '{}'::text[] NOT NULL,
    employment_preference text,
    professional_summary text,
    profile_completeness jsonb DEFAULT '{}'::jsonb NOT NULL,
    matching_paused boolean DEFAULT false NOT NULL,
    CONSTRAINT staff_candidate_profiles_status_check CHECK ((status = ANY (ARRAY['registered'::text, 'profile_incomplete'::text, 'pending_affiliation'::text, 'pending_approval'::text, 'active'::text, 'rejected'::text, 'suspended'::text])))
);

CREATE TABLE public.staff_certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    certificate_type text NOT NULL,
    file_url text,
