    created_at timestamp with time zone DEFAULT now() NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text
);

CREATE TABLE public.staff_job_applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_candidate_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    opening_id uuid,
    requested_role text,
    status text DEFAULT 'submitted'::text NOT NULL,
    manager_decision text,
    decision_reason text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    activated_at timestamp with time zone,
    activated_staff_id uuid,
    duplicate_flags jsonb DEFAULT '[]'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    classroom_id uuid,
    invitation_id uuid,
    employment_id uuid,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    information_request text,
    candidate_response text,
    requirement_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    accepted_at timestamp with time zone,
    withdrawn_at timestamp with time zone,
    CONSTRAINT staff_job_applications_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'under_review'::text, 'information_required'::text, 'resubmitted'::text, 'approved'::text, 'awaiting_candidate_acceptance'::text, 'accepted'::text, 'rejected'::text, 'withdrawn'::text, 'cancelled'::text, 'employed'::text])))
);

COMMENT ON TABLE public.staff_job_applications IS 'Self-service staff applications. Does not grant staff access until manager approval.';

