);

CREATE TABLE public.staff_location_samples (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    profile_id uuid,
    garden_id uuid NOT NULL,
    work_zone_id uuid,
    gps_lat numeric(10,7) NOT NULL,
    gps_lng numeric(10,7) NOT NULL,
    gps_accuracy_meters numeric(10,2),
    distance_meters numeric(10,2),
    inside_geofence boolean DEFAULT false NOT NULL,
    network_reliable boolean DEFAULT true NOT NULL,
    sample_source text DEFAULT 'mobile_browser'::text NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT staff_location_samples_source_check CHECK ((sample_source = ANY (ARRAY['mobile_browser'::text, 'web_browser'::text, 'offline_sync'::text, 'manager_review'::text, 'system'::text])))
);

COMMENT ON TABLE public.staff_location_samples IS 'GPS location samples for automatic staff attendance. Samples are used to start/close shifts after 30 minutes of continuous presence or absence.';

CREATE TABLE public.staff_onboarding_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    profile_id uuid,
    garden_id uuid,
    status text DEFAULT 'profile_incomplete'::text NOT NULL,
    progress_percent integer DEFAULT 0 NOT NULL,
    completed_steps text[] DEFAULT '{}'::text[] NOT NULL,
    missing_items text[] DEFAULT '{}'::text[] NOT NULL,
    invited_by uuid,
    activated_by uuid,
    invited_at timestamp with time zone,
    account_created_at timestamp with time zone,
    submitted_at timestamp with time zone,
    activated_at timestamp with time zone,
    correction_note text,
    verification_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_onboarding_records_progress_percent_check CHECK (((progress_percent >= 0) AND (progress_percent <= 100))),
    CONSTRAINT staff_onboarding_records_status_check CHECK ((status = ANY (ARRAY['invited'::text, 'account_created'::text, 'profile_incomplete'::text, 'pending_verification'::text, 'correction_required'::text, 'active'::text, 'suspended'::text])))
);

