    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.staff_work_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    weekday integer NOT NULL,
    planned_start time without time zone NOT NULL,
    planned_end time without time zone NOT NULL,
    recurring boolean DEFAULT true NOT NULL,
    temporary_replacement_staff_id uuid,
    active_from date DEFAULT CURRENT_DATE NOT NULL,
    active_until date,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_work_schedules_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'replaced'::text, 'archived'::text]))),
    CONSTRAINT staff_work_schedules_weekday_check CHECK (((weekday >= 0) AND (weekday <= 6)))
);

CREATE TABLE public.staff_workforce_anomalies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid,
    garden_id uuid NOT NULL,
    shift_id uuid,
    anomaly_type text NOT NULL,
    severity text DEFAULT 'medium'::text NOT NULL,
    status text DEFAULT 'requires_review'::text NOT NULL,
    details text,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_workforce_anomaly_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT staff_workforce_anomaly_status_check CHECK ((status = ANY (ARRAY['requires_review'::text, 'reviewing'::text, 'confirmed'::text, 'dismissed'::text, 'resolved'::text]))),
    CONSTRAINT staff_workforce_anomaly_type_check CHECK ((anomaly_type = ANY (ARRAY['impossible_movement'::text, 'gps_failure'::text, 'outside_garden'::text, 'suspicious_pattern'::text, 'missing_shift'::text, 'late_arrival'::text, 'early_departure'::text])))
);

CREATE TABLE public.staff_workforce_audit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid,
    garden_id uuid,
    actor_profile_id uuid,
    event_type text NOT NULL,
    entity_type text,
    entity_id uuid,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_workforce_audit_type_check CHECK ((event_type = ANY (ARRAY['location_sample'::text, 'auto_shift_started'::text, 'auto_shift_closed'::text, 'attendance_requires_review'::text, 'schedule_changed'::text, 'task_completed'::text, 'compliance_action'::text, 'manager_intervention'::text, 'absence_requested'::text, 'absence_reviewed'::text])))
);

CREATE TABLE public.staff_workforce_scores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    staff_id uuid NOT NULL,
    garden_id uuid NOT NULL,
    score_date date DEFAULT CURRENT_DATE NOT NULL,
    readiness_score integer DEFAULT 0 NOT NULL,
    attendance_score integer DEFAULT 0 NOT NULL,
    document_score integer DEFAULT 0 NOT NULL,
    training_score integer DEFAULT 0 NOT NULL,
    compliance_score integer DEFAULT 0 NOT NULL,
    inspection_score integer DEFAULT 0 NOT NULL,
    explanation text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_workforce_scores_range_check CHECK ((((readiness_score >= 0) AND (readiness_score <= 100)) AND ((attendance_score >= 0) AND (attendance_score <= 100)) AND ((document_score >= 0) AND (document_score <= 100)) AND ((training_score >= 0) AND (training_score <= 100)) AND ((compliance_score >= 0) AND (compliance_score <= 100)) AND ((inspection_score >= 0) AND (inspection_score <= 100))))
);

CREATE TABLE public.staffing_policy_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    policy_version_id uuid NOT NULL,
    rule_key text NOT NULL,
    age_group_key text,
    min_age_months integer,
    max_age_months integer,
    child_count_from integer DEFAULT 1 NOT NULL,
    child_count_until integer,
    children_per_staff numeric(8,3) NOT NULL,
    minimum_staff integer DEFAULT 1 NOT NULL,
    staff_qualification_key text,
    notes text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staffing_policy_rule_age_check CHECK ((((min_age_months IS NULL) OR (min_age_months >= 0)) AND ((max_age_months IS NULL) OR (max_age_months >= COALESCE(min_age_months, 0))))),
    CONSTRAINT staffing_policy_rule_count_check CHECK (((child_count_from >= 0) AND ((child_count_until IS NULL) OR (child_count_until >= child_count_from)))),
    CONSTRAINT staffing_policy_rule_ratio_check CHECK (((children_per_staff > (0)::numeric) AND (minimum_staff >= 0)))
);

CREATE TABLE public.staffing_policy_sets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    policy_key text NOT NULL,
    name text NOT NULL,
    jurisdiction text DEFAULT 'IL'::text NOT NULL,
    program_type text,
    description text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staffing_policy_key_check CHECK (((length(btrim(policy_key)) >= 3) AND (length(btrim(policy_key)) <= 100)))
);

CREATE TABLE public.stream_health_checks (
