    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text
);

CREATE TABLE public.subprocessor_register (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider_key text NOT NULL,
    provider_name text NOT NULL,
    service_purpose text NOT NULL,
    data_processed jsonb DEFAULT '[]'::jsonb NOT NULL,
    country text DEFAULT 'review_required'::text NOT NULL,
    privacy_review_status text DEFAULT 'needs_review'::text NOT NULL,
    dpa_status text DEFAULT 'not_started'::text NOT NULL,
    security_review_status text DEFAULT 'needs_review'::text NOT NULL,
    risk_rating text DEFAULT 'medium'::text NOT NULL,
    contract_status text DEFAULT 'not_started'::text NOT NULL,
    notes text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subprocessor_contract_status_check CHECK ((contract_status = ANY (ARRAY['not_started'::text, 'under_review'::text, 'signed'::text, 'expired'::text, 'blocked'::text]))),
    CONSTRAINT subprocessor_dpa_status_check CHECK ((dpa_status = ANY (ARRAY['not_started'::text, 'requested'::text, 'under_review'::text, 'signed'::text, 'not_required'::text, 'blocked'::text]))),
    CONSTRAINT subprocessor_review_status_check CHECK ((privacy_review_status = ANY (ARRAY['not_started'::text, 'needs_review'::text, 'under_review'::text, 'approved'::text, 'approved_with_conditions'::text, 'rejected'::text]))),
    CONSTRAINT subprocessor_risk_rating_check CHECK ((risk_rating = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT subprocessor_security_status_check CHECK ((security_review_status = ANY (ARRAY['not_started'::text, 'needs_review'::text, 'under_review'::text, 'approved'::text, 'approved_with_conditions'::text, 'rejected'::text])))
);

COMMENT ON TABLE public.subprocessor_register IS 'Subprocessor register for external privacy and DPA review.';

CREATE TABLE public.subscription_checkout_sessions (
