    payment_method text,
    amount numeric(12,2) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'ILS'::text NOT NULL,
    billing_status public.billing_record_status DEFAULT 'open'::public.billing_record_status NOT NULL,
    paid_at timestamp with time zone,
    failed_at timestamp with time zone,
    failure_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    demo_batch_id text,
    payment_gateway_key text,
    gateway_status text DEFAULT 'not_sent'::text NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    next_retry_at timestamp with time zone,
    token_reference text,
    card_brand text,
    card_last4 text,
    wallet_type text,
    processor_fee_amount numeric(12,2) DEFAULT 0 NOT NULL,
    net_amount numeric(12,2),
    CONSTRAINT subscription_payments_gateway_status_check CHECK ((gateway_status = ANY (ARRAY['not_sent'::text, 'queued'::text, 'authorized'::text, 'captured'::text, 'failed'::text, 'retry_scheduled'::text, 'refunded'::text, 'cancelled'::text])))
);

CREATE TABLE public.subscription_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    plan_type public.subscription_plan_type DEFAULT 'monthly'::public.subscription_plan_type NOT NULL,
    price_amount numeric(12,2) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'ILS'::text NOT NULL,
    duration_days integer,
    trial_days integer DEFAULT 0 NOT NULL,
    active_users_limit integer,
    active_children_limit integer,
    camera_limit integer,
    storage_limit_mb integer,
    enabled_features jsonb DEFAULT '{}'::jsonb NOT NULL,
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
