CREATE VIEW public.unsafe_gardens WITH (security_invoker='true') AS
 SELECT g.id,
    g.name,
    g.city,
    g.address,
    g.gps_lat,
    g.gps_lng,
    g.framework_type,
    g.ages,
    g.children_capacity,
    g.current_children_count,
    g.staff_count,
    g.owner_name,
    g.phone,
    g.email,
    g.status,
    g.safe_status,
    g.inspector_id,
    g.manager_id,
    g.public_profile_enabled,
    g.eligible_for_safe_status,
    g.last_inspection_score,
    g.last_inspection_at,
    g.next_inspection_at,
    g.created_at,
    g.updated_at,
    COALESCE(open_violations.count, 0) AS open_violations_count
   FROM (public.gardens g
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS count
           FROM public.violations v
          WHERE ((v.garden_id = g.id) AND (v.status <> 'done'::public.task_status))) open_violations ON (true))
  WHERE ((g.safe_status = ANY (ARRAY['requires_fix'::public.safe_status, 'not_compliant'::public.safe_status])) OR (COALESCE(g.last_inspection_score, (10)::numeric) < (8)::numeric));

