    review_confidence numeric(5,4),
    learning_confidence numeric(5,4),
    correlation_confidence numeric(5,4),
    combined_confidence numeric(5,4) DEFAULT 0 NOT NULL,
    bounding_boxes jsonb DEFAULT '[]'::jsonb NOT NULL,
    object_labels jsonb DEFAULT '[]'::jsonb NOT NULL,
    recommended_action text,
    shadow_mode boolean DEFAULT true NOT NULL,
    requires_human_review boolean DEFAULT true NOT NULL,
    calibration_mode boolean DEFAULT true NOT NULL,
    parent_visible boolean DEFAULT false NOT NULL,
    sanitized_provider_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vision_detection_category_check CHECK ((detection_category = ANY (ARRAY['person_detected'::text, 'multiple_persons_detected'::text, 'occupancy'::text, 'restricted_area_presence'::text, 'unusual_activity'::text, 'object_presence'::text, 'obstruction_detection'::text, 'camera_blocked'::text, 'camera_frozen'::text, 'camera_offline'::text]))),
    CONSTRAINT vision_detection_confidence_check CHECK ((((model_confidence >= (0)::numeric) AND (model_confidence <= (1)::numeric)) AND ((COALESCE(review_confidence, (0)::numeric) >= (0)::numeric) AND (COALESCE(review_confidence, (0)::numeric) <= (1)::numeric)) AND ((COALESCE(learning_confidence, (0)::numeric) >= (0)::numeric) AND (COALESCE(learning_confidence, (0)::numeric) <= (1)::numeric)) AND ((COALESCE(correlation_confidence, (0)::numeric) >= (0)::numeric) AND (COALESCE(correlation_confidence, (0)::numeric) <= (1)::numeric)) AND ((combined_confidence >= (0)::numeric) AND (combined_confidence <= (1)::numeric)))),
    CONSTRAINT vision_detection_scope_check CHECK (((kindergarten_id IS NOT NULL) OR (observer_site_id IS NOT NULL)))
);

COMMENT ON TABLE public.vision_detection_results IS 'Sanitized computer-vision detection results for human review and calibration.';

